window.XZ=window.XZ||{};(window.XZ.bank=window.XZ.bank||{})["病理学"]=[["1988-N17",14,"第3节 中枢神经系统感染性疾病","病毒性疾病概述",1988,17,"A","","下列传染病中，哪一种是人畜共患的",[["A","流脑"],["B","乙型脑炎"],["C","伤寒"],["D","霍乱"],["E","病毒性肝炎"]],"B","人畜共患病是一种传统的提法，指人类与人类饲养的畜禽之间自然传播和感染的疾病。流行性乙型脑炎（B对）是一种以蚊类作为传播媒介的人畜共患病，人和多种动物（家畜、家禽等）感染乙型脑炎病毒后都可成为乙型脑炎的传染源。流脑（流行性脑脊髓膜炎）（A错）、伤寒（C错）和霍乱（D错）均不是人畜共患病。病毒性肝炎（E错）中仅有戊型肝炎为人畜共患病。","","N"],["1988-N18",16,"","",1988,18,"A","","出血热继发感染易发生于",[["A","发热期至低血压休克期间"],["B","低血压休克期到少尿期间"],["C","少尿期至多尿期间"],["D","多尿期至恢复期间"],["E","发热期至少尿期间"]],"C","肾综合征出血热（HFRS）（十版病理学P353）是汉坦病毒引起的一种由鼠类传播给人的自然疫源性急性传染病，主要表现为发热、休克、充血、出血和急性肾衰竭，根据病程可分为发热期、低血压休克期、少尿期、多尿期和恢复期。继发感染是HFRS常见的并发症之一，严重的继发感染可危及生命，继发感染可发生于病程各期，以少尿期和多尿期（C对）最为常见。","","N"],["1988-N66",16,"第3节 伤寒","伤寒临床病理联系",1988,66,"A","","男性，发热月余，在当地按伤寒治疗,热退一周，入院前又开始发热体温39.5℃，均在肋下1厘米，压能（±）白细胞计数1200/立方毫米，尿蛋白（＋＋），“H”1：30，“O”1：640，SGPT300单位，HbsAg（－）此时宜用",[["A","输液加红霉素"],["B","激素加氯霉素"],["C","复方新诺明加保肝药"],["D","氨基青霉素"],["E","氯霉素加保肝药"]],"B","根据患者临床表现及相关检查，怀疑伤寒，尿蛋白（++）可能有肾功能损害，故用激素，氯霉素是大多数伤寒敏感的（B对）。","","N"],["1988-N72",16,"第3节 伤寒","伤寒肠道病变概述",1988,72,"B","","可发生肠道肉芽肿",[["A","伤寒"],["B","菌痢"],["C","阿米巴痢疾"],["D","钩虫病"],["E","乙脑"]],"A","伤寒是以巨噬细胞增生为特征的急性增生性炎，增生活跃时巨噬细胞的胞浆内吞噬有伤寒杆菌、红细胞和细胞碎片，这种巨噬细胞称为伤寒细胞，伤寒细胞常聚集成团，形成小结节，称为伤寒肉芽肿（A对）。阿米巴痢疾慢性期可发生肠道肉芽组织增生，形成阿米巴肿，而不会发生肠道肉芽肿（C错）。菌痢（十版病理学P351）（B错）、钩虫病（D错）和乙脑（十版病理学P312）（E错）均不会形成肉芽肿。","","N"],["1988-N73",16,"第3节 伤寒","伤寒其他病变",1988,73,"B","","缓解期可发生肠道出血",[["A","伤寒"],["B","菌痢"],["C","阿米巴痢疾"],["D","钩虫病"],["E","乙脑"]],"A","九版病理学未明确说明。","","N"],["1988-N115",16,"第4节 细菌性痢疾","中毒性细菌性痢疾",1988,115,"X","","中毒型细菌性痢疾脑型的表现特点是",[["A","突然高热、嗜睡、反复惊厥"],["B","脑膜刺激征明显"],["C","后期有血压下降，昏迷，瞳孔大小不一，呼吸浅深不均，节律不齐"],["D","脑脊液呈浆液性脑膜炎改变"]],"ABCD","中毒型细菌性痢疾是细菌性痢疾的一种临床病理分型，其特征是起病急骤，严重的全身中毒症状，但肠道病变和症状轻微，多见于2～7岁儿童。中毒型细菌性痢疾又可分为休克型、脑型和混合型。其中，脑型因脑缺氧、水肿而发生反复惊厥、嗜睡、突然高热（A对）和呼吸衰竭。由于颅压增高，脑疝形成，脑膜受激可发生明显的脑膜刺激征（B对）。病变早期有嗜睡、呕吐等症状，后期很快出现昏迷，血压降低，瞳孔大小不一，对光反射消失，呼吸深浅不匀、节律不齐等症状（C对）。脑水肿时毛细血管通透性增加，因此脑脊液可呈浆液性脑膜炎改变（D对）。","","N"],["1988-N118",11,"第1节 肾小球疾病","慢性肾小球肾炎病理变化",1988,118,"X","","慢性肾炎的主要病理类型有",[["A","系膜增生性肾炎"],["B","膜性肾病"],["C","局灶性肾小球硬化"],["D","膜增生性肾炎"]],"ABCD","慢性肾小球肾炎由不同类型的肾炎发展形成。系膜增生性肾炎（A对）、膜性肾病（膜性肾小球肾炎）（B对）、局灶性肾小球硬化（C对）、膜增生性肾炎（D对）均可发展为慢性肾炎。","","N"],["1988-N119",7,"第2节 高血压病","脑病变",1988,119,"X","","关于高血压性脑出血正确的是",[["A","内囊附近出血最多见"],["B","脑干出血以脑桥最多见"],["C","病因以高血压和动脉硬化多见"],["D","脑室积血多为脑实质出血破入脑室所致"]],"BCD","高血压脑出血最常见于基底节区域，尤其以豆状核区最多见（A错）（十版病理学P153），因为供应该区域的豆纹动脉从大脑中动脉呈直角分支，直接受到大脑中动脉压力较高的血流冲击和牵引，致豆纹动脉易破裂出血。脑干自下而上由延髓、脑桥、中脑三部分组成，最常见的是脑桥出血（B对），中脑出血少见，延髓出血罕见。高血压性脑出血的原因在于脑血管的细小动脉硬化使血管壁变脆，当血压突然升高时引起破裂性出血（C对）。脑室积血多为脑实质出血破入脑室所致（D对）。","","N"],["1989-N60",0,"第3节 细胞可逆性损伤","脂肪变的机制",1989,60,"A","","在下列引起肝脏脂肪变性的原因中，哪一项是错误的",[["A","四氯化碳中毒"],["B","缺氧"],["C","食用过多脂肪"],["D","饥饿"],["E","败血症"]],"C","食入过多脂肪（C对）时，过多的游离脂肪酸经由血液入肝，引起肝脏脂肪变性。四氯化碳中毒（A对）、缺氧（B对）、饥饿（D对）时，肝细胞中脂蛋白、载脂蛋白合成减少，细胞输出脂肪受阻而堆积于细胞内，引起肝脏脂肪变性。败血症（E对）属于感染因素，损伤肝功能，肝细胞中脂蛋白、载脂蛋白合成减少，细胞输出脂肪受阻而堆积于细胞内从而引起肝脏脂肪变性。故本题没有正确答案，但给出的参考答案为C。","","N"],["1989-N61",0,"第4节 细胞不可逆性损伤（细胞死亡）","坏死的结局",1989,61,"A","","坏死组织本身的结局下列哪一项是错误",[["A","溶解吸收"],["B","分离排出"],["C","机化"],["D","化生"],["E","包裹钙化"]],"D","坏死组织及周围中性粒细胞释放水解酶，使坏死组织溶解液化，由淋巴管或血管吸收（A对），不能吸收的碎片则由巨噬细胞吞噬清除。坏死灶较大不易被完全溶解吸收时，表皮黏膜的坏死物可被分离排出（B对），形成组织缺损。新生肉芽组织逐渐长入并取代坏死组织、血栓、脓液、异物，此为机化（C对）。坏死组织和细胞碎片若未被及时吸收清除，则日后易吸引钙盐和其他矿物质沉积，引起营养不良性钙化（E对）。而化生是一种分化成熟的细胞类型被另一种分化成熟的细胞类型所取代的过程，属于适应的一种方式（D错，为本题正确答案）。","","N"],["1989-N62",2,"第1节 充血和淤血","肺淤血",1989,62,"A","","肺淤血时，痰中出现胞浆含有含铁血黄素的巨噬细胞称为",[["A","大单核细胞"],["B","尘细胞"],["C","组织细胞"],["D","心力衰竭细胞"],["E","异物巨噬细胞"]],"D","慢性肺淤血时，毛细血管通透性增高，红细胞漏出，漏出的红细胞被巨噬细胞吞噬，血红蛋白被溶酶体酶分解，析出含铁血黄素并堆积在巨噬细胞内，这种细胞称含铁血黄素细胞。由于肺淤血常由左心衰引起，故此种细胞又被称为心力衰竭细胞（D对）。尘细胞是吞噬灰尘后的肺巨噬细胞，见于尘肺（十版病理学P182）（B错）。异物巨噬细胞见于异物性肉芽肿中（十版病理学P76）（E错）。","","N"],["1989-N63",3,"第1节 炎症概述","炎症的局部表现",1989,63,"A","","急性炎症时组织肿胀的主要原因是",[["A","组织增生"],["B","动脉扩张"],["C","静脉阻塞"],["D","富有蛋白的液体进入组织内"]],"D","炎症的局部表现包括：红、肿、热、痛和功能障碍。炎症时，由于局部血管通透性增高，局部组织血管内的液体成分、纤维素等蛋白质和各种炎细胞渗出，导致局部组织肿胀（D对）。渗出液的形成对机体具有积极意义，但渗出液过多时有压迫和阻塞的作用。","","N"],["1989-N64",5,"第4节 肿瘤的生长和扩散","血行转移",1989,64,"A","","血道转移的确切根据是",[["A","恶性瘤细胞侵入静脉"],["B","恶性瘤细胞侵入动脉"],["C","血液中发现肿瘤细胞"],["D","瘤细胞栓塞于远隔器官"],["E","在远隔器官形成同一类型肿瘤"]],"E","血道转移的定义为癌细胞侵入血管后，随血流到达远隔器官，形成转移瘤（为同一类型的肿瘤）。经血道转移的瘤细胞可经静脉或动脉入血（静脉压力低，经静脉入血更常见）。然而，进入血流的肿瘤细胞或栓塞于远隔器官肿瘤细胞，均可能被被机体免疫防御体系所清除而不能继续生长形成转移瘤。只有在远隔器官形成同一类型肿瘤才能作为血道转移的确切依据（E对）。","","N"],["1989-N65",7,"第4节 风湿病","风湿性心内膜炎",1989,65,"A","","反复发作的风湿病主要引起",[["A","关节强直，功能障碍"],["B","皮下结节相融合"],["C","缩窄性心包炎"],["D","慢性心瓣膜病"],["E","因舞蹈病导致脑功能障碍"]],"D","风湿病最常累及心脏、关节和血管等处，以心脏病变最为严重，表现为风湿性心内膜炎、风湿性心肌炎和风湿性心外膜炎，其中又以风湿性心内膜炎为最主要病变，风湿反复发作引起纤维组织增生，导致瓣膜增厚、变硬、蜷曲、短缩、瓣膜间相互粘连、腱索增粗、短缩，最后形成慢性心瓣膜病（D对）。风湿性关节炎主要为关节滑膜的浆液性炎症（虽然关节腔也有纤维蛋白渗出），急性期后，炎症渗出物易被完全吸收，一般不留后遗症，不会导致关节强直和功能障碍（A错）。皮下结节相融合（B错）、缩窄性心包炎（C错）和舞蹈病（小舞蹈病）（E错）均可见于反复发作的风湿病，但非主要表现。","","N"],["1989-N66",8,"第1节 呼吸道和肺炎症性疾病","大叶性肺炎的病理变化及临床病理联系",1989,66,"A","","大叶性肺炎是属于",[["A","化脓性炎症"],["B","浆液性炎症"],["C","增生性炎症"],["D","出血性炎症"],["E","纤维素性炎症"]],"E","大叶性肺炎是主要由肺炎球菌引起的肺泡内纤维素性炎症（E对）。镜下表现为肺泡腔内大量纤维素渗出，相邻肺泡纤维素丝经肺泡间孔互相连接。化脓性炎症（A错）见于小叶性肺炎（十版病理学P174）。浆液性炎症（B错）可见于大叶性肺炎的充血水肿期（但大叶性肺炎主要为纤维性炎症）。增生性炎症（C错）可见于肺结节病（九版内科学P93）。出血性炎症（D错）可见于肺出血肾炎综合征（Goodpasture syndrome）（十版病理学P255）。","","N"],["1989-N67",8,"第1节 呼吸道和肺炎症性疾病","红色肝样变期",1989,67,"A","","肺炎球菌肺炎的基本病理改变，主要为",[["A","肺间质充血、水肿、炎症浸润"],["B","肺泡内浆液及细胞浸润性实变"],["C","肺泡壁破裂、坏死、溃疡"],["D","并发肺气肿"],["E","并发支气管扩张"]],"B","肺炎球菌肺炎即大叶性肺炎，大叶性肺炎典型的自然发展过程包括充血水肿期、红色肝样变期、灰色肝样变期和溶解消散期。充血水肿期有大量浆液性渗出，红色肝样变期（大量红细胞和少量中性粒细胞、巨噬细胞浸润，呈暗红色，质实如肝）和灰色肝样变期（大量中性粒细胞浸润，呈灰白色，质实如肝）表现为细胞浸润性实变（B对）。肺间质充血、水肿、炎症浸润（A错）见于病毒性肺炎（十版病理学P175）和支原体肺炎（十版病理学P176）。肺泡壁破裂、坏死、溃疡（C错），并发肺气肿（D错），及并发支气管扩张（E错）均见于小叶性肺炎。","","N"],["1989-N68",9,"第7节 酒精性肝病和非酒精性脂肪性肝病","酒精性肝硬化",1989,68,"A","","肝细胞出现透明小体见于",[["A","胆汁性肝硬变"],["B","门脉性肝硬变"],["C","酒精性肝硬变"],["D","坏死后性肝硬变"],["E","淤血性肝硬变"]],"C","酒精性肝病（脂肪肝、酒精性肝炎和酒精性肝硬化）（C对）时，一些肝细胞中可出现均质的嗜酸性的透明小体，称之为酒精透明小体（即Mallory小体，属玻璃样变性），主要由属于中丝蛋白的前角蛋白组成。","","N"],["1989-N69",10,"第3节 髓系肿瘤","急性髓系白血病的病理变化",1989,69,"A","","急性、慢性（急性变）粒细胞性白血病时，在骨内、骨膜下或其他器官内，血细胞形成瘤结，外观呈某种颜色，可称为",[["A","白色瘤"],["B","黄色瘤"],["C","绿色瘤"],["D","棕色瘤"],["E","黑色瘤"]],"C","绿色瘤（C对）又称粒细胞性肉瘤，是指急性（AML）、慢性（急性变）粒细胞性白血病时，幼稚粒细胞在骨内、骨膜下或其他器官内形成的局限性实体性肿瘤，因其外观呈绿色（肿瘤组织含有原卟啉或绿色过氧化物酶），肿块呈圆形隆起似瘤而得名。","","N"],["1989-N95",7,"第4节 风湿病","风湿性心内膜炎",1989,95,"B","","风湿性心内膜炎",[["A","主要位于二尖瓣心室面"],["B","主要位于主动脉瓣动脉面"],["C","主要位于二尖瓣心房面或主动脉瓣心室面"],["D","主要位于腱索上"],["E","主要位于乳头肌顶部"]],"C","风湿性心内膜炎病变主要侵犯心瓣膜，其中二尖瓣最常受累，其次为二尖瓣和主动脉瓣同时受累。由于二尖瓣心房面和主动脉瓣心室面直接受到瓣膜开、关时的摩擦及高速血流的冲击，心内膜细胞容易发生变性坏死，故风湿性心内膜炎最易发生于此二处（C对）。","","N"],["1989-N96",7,"第5节 感染性心内膜炎","心脏",1989,96,"B","","亚急性细菌性心内膜炎",[["A","赘生物主要位于二尖瓣心室面"],["B","主要位于主动脉瓣动脉面"],["C","主要位于二尖瓣心房面或主动脉瓣心室面"],["D","主要位于腱索上"],["E","主要位于乳头肌顶部"]],"C","亚急性细菌性心内膜炎常侵犯已有病变的心瓣膜，多在风湿性心内膜炎的基础上发生，故病变的主要部位与风湿性心内膜炎相同（风湿性心内膜炎的病变部位主要位于二尖瓣心房面和主动脉瓣心室面，见1989N95B）（C对）。","","N"],["1989-N101",11,"第1节 肾小球疾病","急性肾炎综合征",1989,101,"C","","急性肾炎可并发",[["A","高血压脑病"],["B","肺水肿"],["C","两者皆有"],["D","两者皆无"]],"C","急性肾炎又称急性弥漫性增生性肾小球肾炎，主要表现为急性肾炎综合征，即明显的血尿、轻至中度蛋白尿，水肿（B对）和高血压。急性肾炎引起高血压时可并发高血压脑病（A对）。本题AB均对，正确答案为C。","","N"],["1989-N102",11,"第1节 肾小球疾病","肾病综合征",1989,102,"C","","肾病综合征可并发",[["A","高血压脑病"],["B","肺水肿"],["C","两者皆有"],["D","两者皆无"]],"B","肾病综合征的主要表现为大量蛋白尿、明显水肿、低白蛋白血症、高脂血症和脂尿（十版病理学P262），其中低白蛋白血症可引起肺水肿（B对）。肾病综合征无高血压表现，因此不会引起高血压脑病（A错）。","","N"],["1989-N111",8,"第2节 慢性阻塞性肺疾病","腺泡中央型肺气肿",1989,111,"C","","小叶中央型肺气肿",[["A","呼吸性支气管呈囊状扩张"],["B","肺泡管、肺泡囊和肺泡扩张"],["C","二者均有"],["D","二者均无"]],"A","肺泡性肺气肿病变发生在肺腺泡内，根据发生的部位和范围可分为：腺泡中央型肺气肿、腺泡周围型肺气肿和全肺泡型肺气肿。腺泡中央型肺气肿又称小叶中央型肺气肿，其病变特点是位于肺腺泡中央的呼吸性细支气管呈囊状扩张（A对），而肺泡管和肺泡囊和肺泡扩张不明显（B错）。","","N"],["1989-N112",8,"第2节 慢性阻塞性肺疾病","全腺泡型肺气肿",1989,112,"C","","全小叶型肺气肿",[["A","呼吸性支气管呈囊状扩张"],["B","肺泡管、肺泡囊和肺泡扩张"],["C","二者均有"],["D","二者均无"]],"C","肺泡性肺气肿病变发生在肺腺泡内，根据发生的部位和范围可分为：腺泡中央型肺气肿、腺泡周围型肺气肿和全腺泡型肺气肿。全腺泡型肺气肿又称全小叶型肺气肿，其病变特点是呼吸性细支气管、肺泡管、肺泡囊和肺泡扩张（C对）。","","N"],["1989-N155",1,"第2节 纤维性修复","肉芽组织的成分及形态",1989,155,"X","","肉芽组织中包括下列哪些成分",[["A","纤维母细胞"],["B","肌纤维母细胞"],["C","血管内皮细胞"],["D","表皮细胞"]],"ABC","肉芽组织由新生薄壁的毛细血管（C对）以及增生的成纤维细胞（即纤维母细胞）（A对）构成，其中部分成纤维细胞的胞质中含有肌细丝，此种细胞除有成纤维细胞的功能外，尚有平滑肌细胞的收缩功能，因此称其为肌成纤维细胞（B对）。肉芽组织中不含表皮细胞（D错）。","","N"],["1989-N156",2,"第5节 梗死","出血性梗死",1989,156,"X","","肺梗死常为出血性梗死，其原因是",[["A","双重血液循环"],["B","组织疏松"],["C","淤血"],["D","动脉呈树枝状分布"]],"ABC","严重淤血是肺梗死的重要先决条件，因为在肺淤血的情况下，肺静脉和毛细血管压升高，影响了肺动脉分支阻塞后建立有效的肺动脉和支气管动脉的侧支循环，导致梗死发生（C对）。肺组织疏松，梗死初期疏松的组织间隙内可容纳多量漏出的血液，当组织坏死吸收水分而膨胀时，也不能把漏出的血液挤出梗死灶外，因而梗死灶为出血性（B对）。肺的双重血液循环在肺部未淤血时，能够防止肺梗死的发生（肺动脉和支气管动脉同时供血，当肺动脉分支阻塞时，支气管动脉的血液仍可维持肺组织存活）。但在严重肺淤血时，双重血液循环也不能阻止肺梗死的发生，肺动脉分支阻塞时，支气管动脉的血流仍可进入梗死区，造成出血性梗死（A对）。动脉呈树枝状分布只影响肺梗死的形状，不决定梗死的类型（D错）。","","N"],["1989-N158",12,"第7节 乳腺疾病","乳腺癌病理变化",1989,158,"X","","乳腺癌的发生与下列哪些因素可能有关",[["A","雌激素紊乱"],["B","不孕或少乳"],["C","纤维囊性乳腺病"],["D","乳腺创伤"]],"ABC","乳腺癌的发病机制尚未完全阐明，长期研究表明，雌激素紊乱（A对）以及不孕或少乳（B对）可能都与乳腺癌的发生有关。纤维囊性乳腺病（C对）即乳腺纤维囊性变，分为非增生型和增生型两种，增生型有恶变潜能，与乳腺癌的发生有关。乳腺创伤（D错）可引起乳腺的脂肪坏死（P23），与乳腺癌无关。","","N"],["1989-N159",14,"第3节 中枢神经系统感染性疾病","脑脓肿",1989,159,"X","","小脑与大脑颞叶的脓肿最多来自",[["A","慢性脓胸"],["B","慢性中耳炎"],["C","鼻窦炎"],["D","乳突炎"]],"BD","脑脓肿的发生部位和数目与感染途径有关。小脑与大脑颞叶的脓肿多是耳源性，如慢性化脓性中耳炎（B对）、乳突炎（D对）等。慢性脓胸（A错）引起的脓肿多见于大脑中动脉供应区、额叶和顶叶等。鼻窦炎（C错）引起的脓肿多见于额叶。","","N"],["1989-N160",16,"第10节 寄生虫病","肠阿米巴病病理变化概述",1989,160,"X","","肠阿米巴病溃疡的特点是",[["A","纵向"],["B","横向"],["C","地图形"],["D","烧瓶形，口小底大"]],"D","肠阿米巴病急性期，由于黏膜下层组织疏松，阿米巴向四周蔓延，坏死组织液化脱落后可形成烧瓶形，口小底大（D对）的溃疡。纵向（A错）溃疡是指溃疡长轴与肠的长轴平行，见于肠伤寒（十版病理学P350）。横向（B错）溃疡是指溃疡长轴与肠的长轴垂直，见于肠结核（十版病理学P348）。地图形（C错）溃疡是指大小不等、形状不一的浅溃疡，见于急性细菌性痢疾（十版病理学P351）。","","N"],["1990-N3",9,"第6节 病毒性肝炎","甲型肝炎病理改变特点",1990,3,"A","","一般不发展为肝硬化的肝炎是",[["A","甲型肝炎"],["B","乙型肝炎"],["C","非甲非乙型肝炎"],["D","药物性肝炎"],["E","以上都不是"]],"A","甲型肝炎病毒一般为急性起病，大多数可痊愈，不导致慢性肝炎，也不会慢性迁延为肝硬化（A对）。我国肝硬化的主要原因为病毒性肝炎，尤其是乙型（B错）和丙型病毒性肝炎（C错）与肝硬化的发生有密切关系。非甲非乙型肝炎如丙型肝炎也可以导致肝硬化（C错）。药物性肝炎可以模拟急慢性病毒或自身免疫性肝炎的特征，引起肝硬化（D错）。","","N"],["1990-N61",9,"第12节 消化系统常见肿瘤","中晚期胃癌的浸润型",1990,61,"A","","下列哪一种癌在胃幽门部一般不会出现",[["A","腺癌"],["B","鳞状细胞癌"],["C","硬癌"],["D","胶样癌"],["E","髓样癌"]],"B","WHO近年将胃癌分为（八版内科学P376）：腺癌（包括乳头状腺癌、管状腺癌、黏液腺癌、印戒细胞癌和混合型腺癌）、腺鳞癌、鳞状细胞癌、类癌、未分化癌以及未分类癌。其中鳞状细胞癌（B对）主要发生于胃贲门部，一般不会在幽门部出现。","","N"],["1990-N62",2,"第5节 梗死","贫血性梗死",1990,62,"A","","下述哪些器官发生的梗死属于贫血性梗死",[["A","心、肺、肠"],["B","心、脾、肠"],["C","心、脾、肾"],["D","心、肾、肺"],["E","心、肾、肠"]],"C","根据梗死灶内含血量的多少，可将梗死分为两种类型：贫血性梗死和出血性梗死。贫血性梗死发生于组织结构较致密、侧支循环不充分的实质器官，如脾、肾、心和脑组织（C对）。而出血性梗死发生于组织结构疏松、双重血供或吻合支丰富的器官，如肺和肠（ABDE错）。","","N"],["1990-N63",0,"第1节 适应","化生的概念",1990,63,"A","","从一种类型的成熟细胞或组织转变成另一种细胞或组织，这种过程称为",[["A","间变"],["B","发育不良"],["C","增生"],["D","化生"]],"D","化生是指一种分化成熟的细胞类型被另一种分化成熟的细胞类型所取代的过程（D对）。间变是指肿瘤组织和细胞成熟程度和分化程度极低的现象，具有间变特征的肿瘤，称为间变性肿瘤（十版病理学P93）（A错）。增生是组织细胞有丝分裂活跃而致组织或器官内细胞数目增多现象（十版病理学P8）（C错）。","","N"],["1990-N64",10,"第2节 淋巴组织肿瘤","经典型霍奇金淋巴瘤的概述",1990,64,"A","","按预后的好坏，经典型何杰金氏病四型的排列顺序应为",[["A","混合细胞型－淋巴细胞消减型－结节硬化型－淋巴细胞为主型"],["B","淋巴细胞消减型－混合细胞型－结节硬化型－淋巴细胞为主型"],["C","淋巴细胞为主型－结节硬化型－淋巴细胞消减型－混合细胞型"],["D","淋巴细胞为主型－结节硬化型－混合细胞型－淋巴细胞消减型"],["E","淋巴细胞消减型－淋巴细胞为主型－结节硬化型－混合细胞型"]],"D","经典型何杰金氏病（现称霍奇金淋巴瘤）的四种分型按预后从好到坏的排列顺序为：淋巴细胞为主型－结节硬化型－混合细胞型－淋巴细胞消减型（D对）。总结：淋巴细胞越多，预后越好。随着现代放疗和化疗技术的进步，CHL各亚型的预后差别已不很明显了（十版病理学P241）。","","N"],["1990-N65",9,"第3节 消化性溃疡病","消化性溃疡病的病理变化",1990,65,"A","","消化性溃疡最好发于",[["A","胃小弯近幽门部"],["B","十二指肠球部"],["C","胃与十二指肠球部"],["D","胃体部"],["E","十二指肠下段"]],"B","消化性溃疡是以胃或十二指肠黏膜形成慢性溃疡为特征的一种常见病变：①胃溃疡多位于胃小弯侧，愈近幽门愈多见，尤多见于胃窦部，少见于胃底及大弯侧；②十二指肠溃疡多发生于球部。其中，十二指肠溃疡病较胃溃疡多见，所以，消化性溃疡最好发于十二指肠球部（B对）。","","N"],["1990-N67",3,"第3节 慢性炎症","一般慢性炎症的特点",1990,67,"A","","在慢性炎症组织中哪种细胞最多见",[["A","中性白细胞"],["B","嗜酸性白细胞"],["C","淋巴细胞"],["D","肥大细胞"],["E","嗜碱性白细胞"]],"C","五种细胞中，中性白细胞主要见于急性炎症（A错）。其余四种细胞见于慢性炎症，其中最常见的是淋巴细胞（C对）：淋巴细胞在各类慢性炎症中普遍存在；嗜碱性白细胞（E错）和肥大细胞（D错）主要见于过敏反应性炎症；嗜酸性白细胞主要见于过敏反应性炎症和寄生虫感染性炎症（B错）。","","N"],["1990-N68",11,"第1节 肾小球疾病","急性弥漫性增生性肾小球肾炎病理变化",1990,68,"A","","绝大多数能治愈的肾炎是",[["A","急性弥漫性增生性肾小球肾炎"],["B","膜性增生性肾小球肾炎"],["C","新月体性肾小球肾炎"],["D","膜性肾小球肾炎"],["E","慢性肾盂肾炎"]],"A","急性弥漫性增生性肾小球肾炎（急性肾炎）（A对）多见于儿童，多数患儿的肾脏病变可逐渐消退，绝大多数患者能被治愈。膜性增生性肾小球肾炎（B错）常为慢性进展性，预后较差（十版病理学P258）。新月体性肾小球肾炎（急进型肾炎）（C错）预后较差，如不及时治疗，患者往往在数周至数月死于急性肾衰竭（十版病理学P255）。膜性肾小球肾炎（D错）常为慢性进展性，多数患者的症状可持续存在，约40%发展为肾功能不全，不到10%的患者于10年内死亡或肾衰竭（八版病理学P269）。慢性肾盂肾炎（E错）是慢性肾衰竭的常见原因之一，预后多不佳（十版病理学P264）。","","N"],["1990-N69",5,"第8节 常见肿瘤举例","间叶组织恶性肿瘤",1990,69,"A","","光镜下区分癌与肉瘤的主要依据是",[["A","病理性核分裂象的多少"],["B","细胞异型性的大小"],["C","组织来源的不同"],["D","实质与间质分界是否明显"],["E","细胞膜是否清楚"]],"C","组织来源是光镜上区分癌和肉瘤的主要依据（C对），癌为上皮组织的恶性肿瘤，肉瘤为间叶组织的恶性肿瘤。","","N"],["1990-N85",5,"第4节 肿瘤的生长和扩散","血行转移",1990,85,"B","","直肠癌转移到肝是",[["A","血行转移"],["B","直接蔓延"],["C","淋巴转移"],["D","种植转移"],["E","胃肠道管腔内转移"]],"A","直肠癌的转移途径包括淋巴道转移、血道转移和种植性转移。直肠癌转移到肝，由门静脉系统介导，为典型的血道转移（血行转移）（A对）。","","N"],["1990-N86",5,"第4节 肿瘤的生长和扩散","种植性转移",1990,86,"B","","胃癌转移到盆腔是",[["A","血行转移"],["B","直接蔓延"],["C","淋巴转移"],["D","种植转移"]],"D","胃癌的转移途径包括淋巴道转移、血道转移和种植性转移。胃癌特别是胃黏液癌癌细胞浸润至胃浆膜表面时可脱落至腹腔，种植于腹腔及盆腔器官的浆膜上，此为种植转移（D对）。","","N"],["1990-N95",8,"第2节 慢性阻塞性肺疾病","肺气肿的病理变化",1990,95,"B","","慢性阻塞性肺气肿的发生主要由于",[["A","支气管腺体肥大增生，黏膜上皮杯状细胞增多"],["B","急、慢性细支气管炎及细支气管周围炎"],["C","支气管壁因炎症而遭破坏"],["D","细支气管壁及肺泡隔弹力纤维支架破坏和细支气管的不完全阻塞"],["E","肺组织过度纤维化"]],"D","正常时细支气管和肺泡隔上的弹力纤维具有支撑作用，并通过回缩力排出末梢肺组织内的残余气体。长期的慢性炎症（慢性支气管炎），一方面破坏了大量的弹力纤维（D对），使细支气管和肺泡的回缩力减弱，一方面被破坏的细支气管管壁发生纤维化致管壁增厚、管腔变窄，使呼吸受阻（D对），最终使细支气管和肺泡长期处于高张力状态，弹性降低，残气量增多，导致肺气肿的发生。","","N"],["1990-N96",8,"第4节 支气管扩张症","支气管扩张症的病理变化",1990,96,"B","","支气管扩张症引起肺源性心脏病的原因是由于",[["A","支气管腺体肥大增生，黏膜上皮杯状细胞增多"],["B","急、慢性细支气管炎及细支气管周围炎"],["C","支气管壁因炎症而遭破坏"],["D","细支气管壁及肺泡隔弹力纤维支架破坏和细支气管的不完全阻塞"],["E","肺组织过度纤维化"]],"E","慢性肺源性心脏病是支气管扩张症的并发症之一。支气管扩张症晚期肺发生广泛性纤维化，肺毛细血管床减少，导致肺动脉循环阻力增加，肺动脉高压，最终引起慢性肺源性心脏病（E对）。","","N"],["1990-N111",7,"第1节 动脉粥样硬化","主动脉粥样硬化",1990,111,"C","","升主动脉粥样硬化",[["A","主动脉瓣口狭窄"],["B","左心室壁肥厚"],["C","二者均有"],["D","二者均无"]],"C","升主动脉粥样硬化可累及主动脉瓣，导致瓣膜纤维化和钙化，可引起主动脉瓣口狭窄（A对），左心室收缩期血液排出受阻，左心室为维持正常的心输出量而发生代偿性肥厚（B对）。本题AB均对，正确答案为C。","","N"],["1990-N112",7,"第7节 心肌病","肥厚型心肌病的病理变化",1990,112,"C","","肥厚性阻塞性心肌病",[["A","主动脉瓣口狭窄"],["B","左心室壁肥厚"],["C","二者均有"],["D","二者均无"]],"B","肥厚性心肌病左心室壁肥厚（B对）、主动脉瓣下的心内膜局限性增厚，造成左心室流出道狭窄，肥厚性心肌病因此又称“特发性肥厚性主动脉瓣下狭窄”。故肥厚性阻塞性心肌病为主动脉瓣下狭窄，而非主动脉瓣口狭窄（A错）。","","N"],["1990-N155",15,"第2节 骨的代谢性疾病","儿童佝偻病和成人骨软化症",1990,155,"X","","佝偻病时长骨骨端肿胀，其主要病变是",[["A","软骨细胞增生、肥大"],["B","软骨基质钙化"],["C","骨样组织堆积"],["D","骨质新生"]],"AC","佝偻病时软骨组织和骨组织钙化不全（缺乏维生素D，使钙、磷代谢紊乱造成），软骨细胞和成骨细胞代偿性增生，软骨细胞增生、肥大（A对）及骨样组织堆积（C对），导致长骨骨端肿胀。","","N"],["1990-N156",14,"第3节 中枢神经系统感染性疾病","脑膜炎概述",1990,156,"X","","关于流行脑脊髓膜炎下列哪些项是正确的",[["A","急性化脓性炎"],["B","葡萄球菌所致"],["C","冬春两季多见"],["D","通过消化道感染"]],"AC","流行性脑脊髓膜炎是一种由脑膜炎双球菌（B错）感染所致的急性化脓性炎症（A对）。患者或带菌者鼻咽分泌物中的细菌通过咳嗽、喷嚏等借飞沫传播，经呼吸道（D错）侵入人体。其多在冬春两季（C对）引起流行，因此称为流行性脑膜炎。","","N"],["1990-N157",2,"第3节 血栓形成","白色血栓",1990,157,"X","","白色血栓一般由哪些成分构成",[["A","血小板"],["B","白血球"],["C","纤维素"],["D","红血球"]],"ABCD","白色血栓镜下主要由血小板（A 对）及少量纤维蛋白（C 对）构成，其组成成分中也会有少量白细胞（B ）和红细胞（D ）。考虑到本题目出题时间，原答案为ABCD，但根据最新教材观点，应选择AC。","","N"],["1990-N158",1,"第2节 纤维性修复","肉芽组织的作用及结局",1990,158,"X","","肉芽组织变为瘢痕组织所见到的变化是",[["A","胶原纤维数量增多"],["B","组织内水分减少"],["C","毛细血管床减少"],["D","成纤维细胞减少"]],"ABCD","肉芽组织成熟过程中，组织内水分减少（B对），毛细血管（C对）和成纤维细胞（D对）的数量逐渐减少，胶原纤维逐渐增多（A对）并成为其主要成分，最终形成瘢痕组织。","","N"],["1990-N159",12,"第7节 乳腺疾病","乳腺癌淋巴道转移",1990,159,"X","","乳腺癌可转移到",[["A","腋窝淋巴结"],["B","锁骨下淋巴结"],["C","胸骨旁淋巴结"],["D","纵隔淋巴结"]],"ABCD","乳腺癌的转移途径有直接蔓延、淋巴道转移和血道转移，其中淋巴道转移是乳腺癌最常见的转移途径。淋巴道转移时，经乳房外侧淋巴管可依次侵入同侧腋窝淋巴结（A对）、锁骨下淋巴结（B对）和锁骨上淋巴结；经乳房内侧淋巴管可侵入纵隔淋巴结（D对）和胸骨旁淋巴结（C对）。","","N"],["1990-N160",12,"第3节 滋养层细胞疾病","葡萄胎病理变化",1990,160,"X","","阴道蓝紫色结节可见于",[["A","子宫颈癌"],["B","恶性葡萄胎"],["C","子宫体瘤"],["D","绒毛膜上皮瘤"]],"BD","恶性葡萄胎（B对）和绒毛膜上皮瘤（D对）的癌结节可经宫旁静脉逆行转移至阴道前壁及穹窿（八版妇产科学P339），造成阴道组织出血坏死，呈现蓝紫色或紫红色结节。","","N"],["1991-N32",10,"第3节 髓系肿瘤","慢性髓系白血病病理变化",1991,32,"A","","Ph染色体主要出现在哪种白血病",[["A","急性淋巴细胞性白血病"],["B","慢性淋巴细胞性白血病"],["C","急性粒细胞性白血病"],["D","慢性粒细胞性白血病"],["E","单核细胞性白血病"]],"D","Ph染色体主要出现在CML（慢性粒细胞白血病）（D对）中，该染色体因t（9；22）（q34；q11）易位（22号染色体的长臂易位到9号染色体）而形成，这种易位使９号染色体长臂上的ABL原癌基因与22号染色体上的BCR基因序列发生拼接，形成BCR-ABL1融合基因。","","N"],["1991-N33",9,"第12节 消化系统常见肿瘤","早期胃癌的凹陷型",1991,33,"A","","早期胃癌最常见的类型是",[["A","隆起型"],["B","表浅隆起型"],["C","表浅平坦型"],["D","表浅凹陷型"],["E","凹陷型"]],"E","早期胃癌大体分为以下三种类型：隆起型、表浅型和凹陷型，其中凹陷型最多见（E对）。表浅隆起型（B错）、表浅平坦型（C错）、表浅凹陷型（D错）均属于表浅型。","","N"],["1991-N34",8,"第5节 肺尘埃沉着病","硅结节的形成",1991,34,"A","","下述哪一项不符合硅肺的病理变化",[["A","易并发肺结核"],["B","可引起肺间质纤维化"],["C","早期硅结节在肺实质内"],["D","硅结节中央可发生坏死"],["E","硅结节由呈同心环状胶原纤维组成"]],"C","硅肺的基本病变是硅结节的形成和肺组织（肺间质）的弥漫性纤维化（B对）。硅结节为境界清楚的圆形或椭圆形结节，硅结节形成的早期阶段是由吞噬硅尘的巨细胞聚集形成的细胞性结节，随病程进展，结节发生纤维化而形成纤维性结节，结节内胶原纤维呈同心环状排列（E对）。相邻的硅结节可以融合形成大的结节状病灶，其中央常因缺血、缺氧发生坏死（D对），形成硅肺性空洞。早期硅肺硅结节主要局限于肺门淋巴结，肺组织内硅结节数量较少（C错，为本题正确答案）。由于病变组织对结核杆菌的防御能力降低，硅肺患者易并发结核病，称硅肺结核病（A对）。","","N"],["1991-N35",11,"第1节 肾小球疾病","膜性肾小球病病理变化",1991,35,"A","","膜性肾小球肾炎的肾脏呈",[["A","大白肾"],["B","大红肾"],["C","蚤咬肾"],["D","固缩肾"],["E","无明显改变"]],"A","膜性肾小球肾炎又称膜性肾病，是引起肾病综合征的常见原因之一。肉眼观察可见双肾肿大，颜色苍白，有“大白肾”（A对）之称。大红肾也叫蚤咬肾（BC错），是急性弥漫性增生性肾小球肾炎（急性肾炎）的肉眼表现（十版病理学P254）。固缩肾包括原发性颗粒性固缩肾（十版病理学P152）、继发性颗粒性固缩肾（十版病理学P260）和动脉粥样硬化性固缩肾（十版病理学P148）等，分别见于高血压肾病、慢性肾小球肾炎和动脉粥样硬化症（D错）。","","N"],["1991-N36",16,"第3节 伤寒","溃疡期",1991,36,"A","","肠伤寒所形成的溃疡为",[["A","环形溃疡"],["B","烧瓶口状溃疡"],["C","地图状溃疡"],["D","溃疡长轴与肠轴平行"],["E","火山口状溃疡"]],"D","肠伤寒所形成的溃疡多呈圆形或椭圆形，长轴与肠轴平行（D对）。环形溃疡（A错）为肠结核的病理特点（十版病理学P348）。烧瓶口状溃疡（B错）是肠阿米巴病的病理特点（十版病理学P358）。地图状溃疡（C错）是急性细菌性痢疾的病理特点（十版病理学P351）。火山口状溃疡（E错）是胃癌的病理特点（十版病理学P216）。","","N"],["1991-N61",3,"第3节 慢性炎症","肉芽肿的组成成分和形态特点",1991,61,"A","","肉芽肿性炎时，下述哪种细胞是主要成分",[["A","多核巨细胞"],["B","泡沫细胞"],["C","上皮样细胞"],["D","伤寒细胞"],["E","骨骼肌细胞"]],"C","肉芽肿性炎是一种特殊类型的慢性炎症，其主要细胞成分包括巨噬细胞及其衍生而来的上皮样细胞（C对）和多核巨细胞（A对）。泡沫细胞（十版病理学P142）是动脉粥样硬化斑块内出现的特征性病理细胞（B错）。伤寒细胞（十版病理学P350）为伤寒肉芽肿的特征性细胞（D错），吞噬有伤寒杆菌、红细胞和细胞碎片。故本题的正确答案应为AC，但给出的参考答案仅为C。","","N"],["1991-N62",1,"第1节 再生","神经组织的再生",1991,62,"A","","下述各种细胞中，哪种再生能力最强",[["A","神经细胞"],["B","心肌细胞"],["C","软骨细胞"],["D","神经胶质细胞"],["E","骨骼肌细胞"]],"D","根据细胞再生能力的不同，分为不稳定细胞、稳定细胞和永久性细胞三类细胞。其中，不稳定细胞再生能力最强，稳定细胞再生能力次之，永久性细胞无再生能力。神经细胞（A错）、心肌细胞（B错）和骨骼肌细胞（E错）均属于永久性细胞，无再生能力；神经胶质细胞属于稳定细胞，在生理情况下增殖不明显，但受到损伤刺激时可表现出较强的再生能力（D对）。软骨细胞也属于稳定细胞，但软骨细胞的再生能力较弱（但有再生能力）（C错），软骨组织缺损较大时需要由纤维组织参与修补。","","N"],["1991-N63",0,"第4节 细胞不可逆性损伤（细胞死亡）","纤维素样坏死",1991,63,"A","","下述哪种病变不是纤维素样变性",[["A","恶性高血压时肾脏入球小动脉壁的灶、片状红染物质"],["B","动脉粥样斑块表面纤维组织帽内的灶、片状红染物质"],["C","风湿结节内灶、片状红染物质"],["D","急性坏死性肾炎毛细血管球内的灶、片状红染物质"],["E","结节性多动脉炎的动脉壁内灶、片状红染物质"]],"B","纤维素样变性即纤维素样坏死，因坏死物质与纤维素染色性质相似而得名，是结缔组织及小血管壁常见的坏死形式，常见于某些变态反应性疾病，如风湿病（C错）、结节性多动脉炎（E错）、新月体性肾小球肾炎（急性坏死性肾炎）（D错）以及急进性高血压（恶性高血压）（A错）和胃溃疡底部小血管等。动脉粥样斑块（十版病理学P16）属于纤维结缔组织的玻璃样变，而非纤维素坏死（B对）。","","N"],["1991-N64",5,"第10节 肿瘤的分子基础","获得侵袭和转移能力",1991,64,"A","","下述哪条是恶性肿瘤的主要诊断依据",[["A","肿瘤边界不清"],["B","肿瘤切除后复发"],["C","肿瘤发生转移"],["D","肿瘤出血坏死"],["E","肿瘤突然生长迅速"]],"C","边界不清（A）、切除后复发（B）、发生转移（C）、出血坏死（D）、突然生长迅速（E）等都是恶性肿瘤的特点，但发生转移是最具特征性的改变，是恶性肿瘤的主要诊断依据（C对）。","","N"],["1991-N65",5,"第1节 肿瘤的概念","概念",1991,65,"A","","下述哪一项不符合肿瘤性增生",[["A","增生过程需致癌因素持续存在"],["B","相对无止境生长"],["C","细胞分化成熟能力下降"],["D","细胞分裂能力加强"],["E","常形成肿块"]],"A","肿瘤性增生为细胞的异常增殖过程，常表现为机体局部的异常肿块（E对）。肿瘤性增生细胞分裂能力加强（D对），失去控制，能够相对无止境生长（B对），并且具有相对自主性，增生过程不需要致癌因素持续存在（A错，为本题正确答案）。肿瘤细胞的形态、代谢和功能均有异常，不同程度地失去了分化成熟的能力（C对）。","","N"],["1991-N78",7,"第1节 动脉粥样硬化","基本病理变化",1991,78,"A","","下述哪种成分是粥样斑块所不具备的",[["A","泡沫细胞"],["B","无细胞的不定形物质"],["C","苏丹Ⅲ染色阳性物质"],["D","纤维组织"],["E","中性白细胞"]],"E","粥瘤斑块亦称粥瘤，由纤维斑块深层细胞的坏死发展而来，是动脉粥样硬化（AS）的典型病变。光镜下，在纤维帽（D对）之下含有大量无细胞的不定形物质（B对）、胆固醇结晶（针状空隙）、钙盐沉积，斑块底部和边缘出现肉芽组织，少量淋巴细胞和泡沫细胞（A对），中膜因斑块压迫、SMC萎缩、弹力纤维破坏而变薄。无论是在泡沫细胞内还是胞外不定形坏死崩解产物中都存在脂质成分，使苏丹Ⅲ染色呈阳性（C对）。动脉粥样硬化是一种慢性炎症过程（十版病理学P143），不出现急性炎症细胞中性白细胞（E错，为本题正确答案）。","","N"],["1991-N79",7,"第4节 风湿病","风湿病的基本病理变化",1991,79,"A","","在风湿病中最具有病理诊断意义的病变是",[["A","心肌变性、坏死"],["B","心外膜纤维素性渗出"],["C","心瓣膜疣状赘生物"],["D","肌纤维的纤维素样变性"],["E","风湿小结"]],"E","风湿病的增生期在变质渗出的基础上，在心肌间质、心内膜下和皮下结缔组织中形成特征性的肉芽肿病变，称为Aschoff小体或风湿小结（E对），为对风湿病最有诊断意义的病变。心肌变性坏死（A）、心外膜纤维素性渗出（B）及心瓣膜疣状赘生物（C）均可在风湿病时出现，但不具有特异性，不能作为风湿病的病理诊断依据。纤维素样变性是结缔组织及小血管壁常见的坏死形式，不常发生在肌纤维，D选项本身不够严谨。","","N"],["1991-N83",0,"第3节 细胞可逆性损伤","脂褐素",1991,83,"B","","老年萎缩心脏的心肌细胞内的色素颗粒",[["A","含铁血黄素"],["B","胆色素"],["C","脂褐素"],["D","黑色素"],["E","钙盐沉积"]],"C","脂褐素是细胞内未被彻底消化的富含磷脂的膜包被细胞器残体，常见于萎缩的细胞中，如老年萎缩心脏的心肌细胞中（C对）。","","N"],["1991-N84",2,"第1节 充血和淤血","肺淤血",1991,84,"B","","心力衰竭细胞的色素颗粒",[["A","含铁血黄素"],["B","胆色素"],["C","脂褐素"],["D","黑色素"],["E","钙盐沉积"]],"A","心力衰竭细胞是指左心衰时在肺泡腔内可见的含有含铁血黄素颗粒（A对）的巨噬细胞。胆色素（B错）是体内铁卟啉化合物的分解代谢产物，主要存在于胆汁之中。脂褐素（C错）是细胞氧化后的产物，常见于心肌细胞和肝细胞等萎缩细胞的胞质内。黑色素（D错）主要存在于人体皮肤中的黑色素细胞内。钙盐沉积（E错）见于病理性钙化。","","N"],["1991-N103",16,"第3节 伤寒","伤寒病理变化概述",1991,103,"C","","伤寒",[["A","渗出性炎"],["B","增生性炎"],["C","两者皆有"],["D","两者皆无"]],"B","伤寒杆菌引起的炎症是以巨噬细胞增生为特征的急性增生性炎（B对），增生活跃时巨噬细胞的胞浆内吞噬有伤寒杆菌、红细胞和细胞碎片，这种巨噬细胞称为伤寒细胞，伤寒细胞常聚集成团，形成小结节，称为伤寒肉芽肿（伤寒小结），是具有病理诊断价值的特征性病变。","","N"],["1991-N104",16,"第2节 结核病","肺结核病概述",1991,104,"C","","结核病",[["A","渗出性炎"],["B","增生性炎"],["C","两者皆有"],["D","两者皆无"]],"C","结核病是由结核分枝杆菌感染引起的传染性疾病，其基本病理变化有三种：以渗出（A对）为主的病变（变态反应较强）、以增生（B对）为主的病变（变态反应较弱）和以坏死为主的病变（变态反应强）。本题AB均对，正确答案为C。","","N"],["1991-N105",12,"第1节 子宫颈疾病","子宫颈鳞状上皮内病变",1991,105,"C","","子宫颈原位癌可发生",[["A","血道转移"],["B","淋巴道转移"],["C","两者皆有"],["D","两者皆无"]],"D","子宫颈原位癌是指异型增生的细胞累及子宫颈黏膜上皮全层，但病变局限于上皮层内，未突破基膜的癌。因此不存在血道（A错）或淋巴道转移（B错）。本题AB均错，正确答案为D。","","N"],["1991-N106",9,"第12节 消化系统常见肿瘤","胃癌的转移",1991,106,"C","","早期胃癌可发生",[["A","血道转移"],["B","淋巴道转移"],["C","两者皆有"],["D","两者皆无"]],"B","早期胃癌是指癌组织浸润仅限于黏膜层或黏膜下层，可无淋巴道的转移，也可发生淋巴道的转移（B对），但无血道转移（A错），血道转移多发生在胃癌晚期。","","N"],["1991-N127",9,"第8节 肝硬化","镜下",1991,127,"X","","肝硬化时，假小叶具有的特点有",[["A","假小叶内肝细胞索排列尚正常"],["B","假小叶内可无中央静脉"],["C","假小叶内中央静脉偏位或有两个以上的中央静脉"],["D","假小叶内可见到汇管区"]],"BCD","假小叶是指由广泛增生的纤维组织分割原来的肝小叶并包绕成大小不等的圆形或类圆形的肝细胞团，是肝硬化的特征性病变。假小叶具有如下特点：①肝细胞排列紊乱（A错），可有变性、坏死及再生的肝细胞；②中央静脉常缺如（B对），偏位或有两个以上（C对）；③有时可见汇管区也被包于内（D对）。","","N"],["1991-N128",7,"第7节 心肌病","克山病",1991,128,"X","","克山病的病理变化有",[["A","右室心肌变性坏死"],["B","20％病人可有附壁血栓"],["C","心壁常增厚"],["D","心肌变性呈灶状分布"]],"ABD","克山病是一种地方性心肌病，可能与缺乏硒等微量元素有关，干扰和破坏了心肌代谢而引起心肌细胞损伤，其病变以心肌成批出现多灶性变性和坏死（二版八年制病理学P211）（AD对），机化和瘢痕形成为特点。约20%的病例在心室肉柱间或左、右心耳内可见附壁血栓形成（B对）。克山病由于心肌严重变性坏死，心腔扩大，心室壁变薄（C错）。","","N"],["1991-N129",5,"第12节 肿瘤与遗传","遗传性肿瘤综合征举例",1991,129,"X","","遗传性肿瘤有",[["A","视网膜母细胞瘤"],["B","大肠腺瘤"],["C","神经纤维瘤病"],["D","肾母细胞瘤"]],"ACD","视网膜母细胞瘤（A对）和神经纤维瘤病（C对）均为常染色体显性遗传的遗传性肿瘤。部分肾母细胞瘤（1%～2.4%）为常染色体显性遗传的遗传性肿瘤（D对）。部分大肠腺瘤（家族性腺瘤性息肉病）为常染色体显性遗传的遗传性肿瘤（B）。本题给出的参考答案为ACD，若认为D选项正确，则B选项也应为正确答案。","","N"],["1991-N130",2,"第3节 血栓形成","广泛性出血",1991,130,"X","","DIC发生的原因包括",[["A","广泛的组织损伤"],["B","广泛的血管内皮损伤"],["C","大量的胰蛋白酶进入血液"],["D","大量的红细胞破坏"]],"ABCD","DIC即弥散性血管内凝血。广泛的组织损伤时，大量组织因子释放入血液，启动外源性凝血途径，导致DIC的发生（A对）。血管内皮损伤时，内皮胶原及组织因子暴露于血液，分别启动内源性凝血途径和外源性凝血途径，导致DIC的发生（B对）。胰蛋白酶能不经过内源性或外源性凝血过程，直接激活凝血酶原，导致DIC的发生（C对）。大量的红细胞破坏时，大量促凝物质进入血液，导致DIC的发生（D对）。","","N"],["1991-N131",3,"第2节 急性炎症","细胞释放的炎症介质",1991,131,"X","","炎性介质包括",[["A","前列腺素"],["B","激肽"],["C","组织胺"],["D","C₃ₐ、C₅ₐ"]],"ABCD","炎性介质可以来自细胞也可来自血浆。细胞释放的炎性介质有：花生四烯酸代谢产物（前列腺素、白细胞三烯和脂质素）（A对）、血管活性胺（组胺和5-羟色胺）（C对）、血小板激活因子、细胞因子、活性氧和一氧化氮、白细胞溶酶体酶、神经肽等；血浆中存在的炎性介质有：缓激肽（激肽的一种）（B对）、补体（D对）、凝血酶、纤维蛋白多肽等。","","N"],["1991-N132",10,"第2节 淋巴组织肿瘤","镜下改变",1991,132,"X","","何杰金氏病的R-S细胞的特点是",[["A","多核或双核的瘤巨细胞"],["B","胞浆丰富，嗜酸性"],["C","核大而呈空泡状，核仁明显，其周围有透明晕"],["D","常见核分裂象"]],"AC","何杰金氏病（现称霍奇金淋巴瘤）的R-S细胞是一种直径15-45μm的多核或双核瘤巨细胞（A对），胞浆丰富，略嗜酸或嗜碱性（B错），核圆形或椭圆形，核膜厚，核大而呈空泡状，核仁明显，周围有透明晕（C对）。R-S细胞无核分裂象（D错）。","","N"],["1991-N151",11,"第1节 肾小球疾病","膜增生性肾小球肾炎病理变化",1991,151,"X","","膜性增生性肾小球肾炎时，肾小球有如下改变",[["A","脏层上皮细胞足突融合"],["B","浸银染色基底膜呈梳状"],["C","肾小球小叶中心硬化"],["D","血管间质细胞增生"]],"CD","膜性增生性肾小球肾炎的病理改变为系膜细胞（即血管间质细胞，属于肾小球细胞）（D对）和系膜基质弥漫重度增生，可插入肾小球基底膜和内皮细胞之间（九版内科学P473），使基底膜呈双轨状（B错）。膜性增生性肾小球肾炎发展到晚期，可出现肾小球小叶中心硬化（C对）。脏层上皮细胞足突融合（消失）（A错）为微小病变性肾小球病（脂性肾病）（十版病理学P259）、膜性肾小球病（十版病理学P256）和局灶性节段性肾小球硬化（十版病理学P259）的病变特点。","","N"],["1992-N27",16,"第4节 细菌性痢疾","细菌性痢疾概述",1992,27,"A","","假膜性肠炎的主要渗出物是",[["A","浆液"],["B","纤维素"],["C","中性白细胞"],["D","淋巴细胞"],["E","单核细胞"]],"B","假膜性肠炎的主要渗出物是纤维素（B对）。浆液（A错）为浆液性炎（十版病理学P72）的主要渗出物。中性白细胞（C错）为化脓性炎（P77）的主要渗出物。单核细胞（E错）和淋巴细胞（D错）为慢性炎症（十版病理学P75）的主要渗出物。","","N"],["1992-N28",2,"第4节 栓塞","体循环动脉栓塞",1992,28,"A","","大脑中动脉血栓栓塞，栓子可能来源于",[["A","髂静脉"],["B","肝静脉"],["C","右心房"],["D","左心室"],["E","股动脉"]],"D","在循环血液中出现的不溶于血液的异常物质，随血流运行阻塞血管腔的现象称为栓塞（十版病理学P50），阻塞血管的异常物质称为栓子，栓子的运行方向一般与血流方向一致，最终停留在口径与其相当的血管并阻断血流。来自左心的栓子（D对），随动脉血流运行，依次经左心房、左心室、主动脉弓、颈总动脉、颈内动脉，进入大脑中动脉，造成大脑中动脉血栓栓塞。","","N"],["1992-N29",5,"第4节 肿瘤的生长和扩散","淋巴道转移",1992,29,"A","","淋巴结癌转移时，癌细胞首先出现在",[["A","副皮质区"],["B","边缘窦"],["C","淋巴滤泡内"],["D","淋巴结门"],["E","髓窦"]],"B","淋巴道转移是恶性肿瘤发生转移的重要途径。肿瘤细胞侵入淋巴管，随淋巴流到达局部淋巴结，肿瘤细胞首先聚集于边缘窦（B对），之后继续增殖，最终累及整个淋巴结。","","N"],["1992-N30",3,"第2节 急性炎症","化脓性炎",1992,30,"A","","下述疾病中，哪一种不是化脓性炎",[["A","急性蜂窝织炎性阑尾炎"],["B","肾盂肾炎"],["C","皮肤疖肿"],["D","急性细菌性心内膜炎"],["E","肾小球肾炎"]],"E","化脓性炎以中性粒细胞渗出，并伴有不同程度的组织坏死和脓液形成为特点。化脓性炎多由化脓菌（如葡萄球菌、链球菌、脑膜炎双球菌或大肠杆菌等）感染所致，也可由组织坏死继发感染产生，急性蜂窝织性阑尾炎（A错）、肾盂肾炎（B错）、皮肤疖肿（C错）及急性细菌性心内膜炎（D错）均为化脓性炎。肾小球肾炎为变态反应性炎症，无化脓菌感染，不属于化脓性炎（E对）。","","N"],["1992-N31",14,"第3节 中枢神经系统感染性疾病","暴发型脑膜脑炎",1992,31,"A","","有关急性暴发性流脑的论述中，哪项是不正确的",[["A","起病急、进展快、死亡率高"],["B","脑膜病变重"],["C","常伴中毒性休克和DIC"],["D","由脑膜炎双球菌释放的大量内毒素所致"],["E","常伴肾上腺皮质出血和功能衰竭"]],"B","急性暴发性流脑是指少数起病急骤，进展较快的流脑病例，死亡率较高（A对）。根据其临床病理特点可分为两型：暴发型脑膜炎双球菌败血症和暴发性脑膜脑炎。暴发型脑膜炎双球菌败血症主要表现为败血症性休克，脑膜的炎症病变较轻（B错，为本题正确答案），短期内即出现皮肤、黏膜的广泛性出血和瘀斑及周围循环衰竭等严重临床表现，过去认为是因严重感染致肾上腺皮质出血及急性肾上腺功能衰竭所致（E对），现在认为其发生机制是由于脑膜炎双球菌败血症时，大量内毒素释放（D对）到血液中引起中毒性休克和DIC（弥散性血管内凝血）（C对），两者相互影响，使病情进一步恶化。","","N"],["1992-N32",7,"第4节 风湿病","风湿性心肌炎",1992,32,"A","","下列描述中，哪一项是错误的",[["A","风湿性心内膜炎最常累及二尖瓣和主动脉瓣"],["B","疣状心内膜炎赘生物不易脱落"],["C","风湿性心肌炎可导致心肌纤维化"],["D","风湿性心外膜炎可导致心包粘连"],["E","风湿性关节炎不会导致关节畸形"]],"C","风湿性心内膜炎病变主要侵犯心瓣膜，最常累及二尖瓣和主动脉瓣（A对）。病变瓣膜表面（特别是瓣膜闭锁缘上）形成单行排列、直径为1～2mm的疣状赘生物，赘生物呈灰白色半透明状，附着牢固，不易脱落（B对）。风湿性心肌炎反复发作时，心肌间质中的Achoff小体逐渐纤维化，形成梭形小瘢痕，可导致心肌纤维化（心肌纤维化的病因之一就包括了风湿性心脏病）（C对）。风湿性心外膜炎渗出的大量纤维素如不能被溶解吸收，则发生机化，使心外膜脏层和壁层互相粘连（即心包粘连）（D对），形成缩窄性心外膜炎。风湿性关节炎主要为关节滑膜的浆液性炎症（虽然关节腔也有纤维蛋白渗出），急性期后，炎症渗出物易被完全吸收，一般不留后遗症，不会导致关节畸形（导致关节畸形的是P80类风湿性关节炎）（E对）。故本题各选项均对，无正确答案，但给出的参考答案为C。","","N"],["1992-N33",9,"第6节 病毒性肝炎","病毒性肝炎的临床病理类型",1992,33,"A","","下述关于各型肝炎肝细胞坏死程度的描述中，哪项是错误的",[["A","慢性活动性肝炎——碎片状及灶状坏死"],["B","急性重型肝炎——片状坏死"],["C","慢性持续性肝炎——灶状坏死"],["D","急性普通型肝炎——点状坏死"],["E","亚急性重型肝炎——灶状及桥状坏死"]],"C","肝炎的临床病理类型包括：急性（普通型）肝炎、慢性（普通型）肝炎（旧版教材将其分成持续性、活动性两型，新版教材又将其分成轻度、中度、重度三型）、急性重型肝炎、亚急性重型肝炎等。肝细胞的坏死类型包括：溶解性坏死、点状坏死、灶状坏死（病理学未提及灶状坏死概念，可参见八版传染病学P26，灶状坏死比点状坏死略大，有时二者并不作区分而合称点灶状坏死）、碎片状坏死、桥接坏死、大片坏死等。临床病理类型与坏死类型的对应关系是考研的重点也是难点，现总结如下：急性肝炎——点状坏死（D对）；轻度慢性肝炎——点状坏死，轻度碎片状坏死；中度慢性肝炎——桥接坏死，中度碎片状坏死；重度慢性肝炎——大范围桥接坏死，重度碎片状坏死；急性重型肝炎——大片坏死（B对）；亚急性重型肝炎——亚大块坏死（E错）；慢性持续性肝炎——点状坏死（C错）；慢性活动性肝炎——灶状坏死、碎片状坏死（A对）。故C选项和E选项均错误，但本题给出的参考答案仅为C。","","N"],["1992-N34",16,"第3节 伤寒","伤寒概述",1992,34,"A","","下列疾病好发部位描述中错误的是",[["A","慢性胃溃疡——胃窦及移行部"],["B","十二指肠溃疡——十二指肠起始部"],["C","伤寒——回肠上段"],["D","细菌性痢疾——大肠下段"],["E","阿米巴痢疾——结肠上段"]],"C","伤寒肠道病变的好发部位为回肠末端（C错，为本题正确答案）。慢性胃溃疡（十版病理学P198）多位于胃小弯侧，愈近幽门愈多见，尤多见于胃窦及移行部（A对）。十二指肠溃疡（十版病理学P198）多发生于球部，即十二指肠起始部（B对）。细菌性痢疾（十版病理学P351）多发生于乙状结肠和直肠，即大肠下段（D对）。阿米巴痢疾（十版病理学P358）主要见于盲肠和升结肠，即结肠上段（E对）。","","N"],["1992-N35",8,"第1节 呼吸道和肺炎症性疾病","病毒性肺炎的病理变化",1992,35,"A","","病毒性肺炎的主要诊断依据是",[["A","间质性肺炎"],["B","淋巴细胞、单核细胞为主的炎细胞浸润"],["C","上皮细胞内病毒包涵体"],["D","肺泡上皮细胞增生"],["E","肺泡内透明膜形成"]],"C","病毒包涵体是病毒在增殖的过程中，使寄主细胞形成的一种蛋白质性质的病变结构，在光学显微镜下可见，多为圆形或椭圆形，约红细胞大小。检见病毒包涵体是病理组织学诊断病毒性肺炎的重要依据（C对）。间质性肺炎（A错），淋巴细胞、单核细胞为主的炎细胞浸润（B错），肺泡上皮细胞增生（D错）和肺泡内透明膜形成（E错）均为病毒性肺炎的病理变化，但也均可见于支原体肺炎（十版病理学P176），不是病毒性肺炎的主要诊断依据。","","N"],["1992-N36",10,"第2节 淋巴组织肿瘤","蕈样肉芽肿病的病理改变",1992,36,"A","","下述蕈样霉菌病的病理变化中，哪一项是错误的",[["A","可见脑回样肿瘤细胞"],["B","可见鲍氏小脓肿"],["C","发生在皮肤"],["D","可扩散到淋巴结和内脏"],["E","由B细胞发生"]],"E","蕈样霉菌病是一种由T细胞发生的淋巴瘤（E错，为本题正确答案），原发于皮肤（C对），随着病程发展，可由皮肤向外扩散，累及淋巴结和内脏器官（D对）。蕈样霉菌病的病理表现：光镜下可见折叠状或脑回样细胞核的肿瘤细胞（A对），真皮内瘤细胞常侵入表皮，在表皮内聚集成堆，形成Pautrier微脓肿（鲍氏小脓肿）（B对）。","","N"],["1992-N38",9,"第6节 病毒性肝炎","病毒性肝炎的概述",1992,38,"A","","下列疾病描述中，哪项是不正确的",[["A","传染性肝炎——增殖性炎"],["B","细菌性痢疾——纤维素性炎"],["C","阿米巴痢疾——坏死性炎"],["D","伤寒——急性增生性炎"],["E","乙型脑炎——变质性炎"]],"A","传染性肝炎是由一组肝炎病毒引起的以肝实质细胞变性坏死为主要病变的传染病，故为变质性炎（A错，为本题正确答案）。细菌性痢疾是由痢疾杆菌所引起的一种纤维素性炎症（B对），以大量纤维素渗出形成假膜为特征。阿米巴痢疾的基本病变为液化坏死性结肠炎，以形成烧瓶状溃疡为病变特点，为坏死性炎（C对）。伤寒杆菌引起的炎症是以巨噬细胞增生为特征的急性增生性炎（D对），所形成的伤寒肉芽肿是其特征性病变。乙脑的病变特点是神经细胞变性、坏死，进而形成具有一定特征性的镂空筛网状软化灶及胶质细胞增生和血管周围炎细胞浸润，为变质性炎（E对）。","","N"],["1992-N91",8,"第8节 呼吸系统常见肿瘤","EB病毒",1992,91,"B","","鼻咽癌",[["A","EB病毒"],["B","乳头瘤病毒"],["C","乙型肝炎病毒"],["D","HTLV病毒"],["E","疱疹病毒"]],"A","EB病毒（A对）与鼻咽癌的关系密切，其主要证据为瘤细胞内存在EBV-DNA和核抗原。此外EB病毒还可导致Burkitt淋巴瘤。乳头瘤病毒（B错）与宫颈癌的发生有关（十版病理学P122）。乙型肝炎病毒（C错）主要与乙肝有关。HTLV病毒（D错）全称人类T细胞白血病病毒，可导致白血病（十版病理学P122）。疱疹病毒（E错）系指一大类感染人体后能够引起蔓延性皮疹的病毒，值得注意的是，EB病毒属于疱疹病毒的一种。","","N"],["1992-N92",12,"第1节 子宫颈疾病","子宫颈鳞状上皮内病变",1992,92,"B","","宫颈癌",[["A","EB病毒"],["B","乳头瘤病毒"],["C","乙型肝炎病毒"],["D","HTLV病毒"],["E","疱疹病毒"]],"B","人乳头瘤病毒（HPV）（B对）感染是宫颈癌致病的主要因素之一。EB病毒（A错）主要与Burkitt淋巴瘤（十版病理学P233）和鼻咽癌（十版病理学P187）的发病有关。乙型肝炎病毒（C错）主要与乙肝发病有关（十版病理学P203）。人类嗜T细胞病毒（HTLV）（D错）是一种人类逆转录病毒（十版病理学P122），有Ⅰ型和Ⅱ型之分，分别与T细胞白血病和毛细胞白血病的发病有关。疱疹病毒（E错）共有120余种（EB病毒即为疱疹病毒的一种），与许多疾病的发病有关，但与宫颈癌无关。","","N"],["1992-N103",9,"第8节 肝硬化","门脉高压症的概述(1)",1992,103,"B","","肝炎后肝硬变所致",[["A","门静脉高压症的主要阻塞部位在窦前"],["B","门静脉高压症的主要阻塞部位在窦后"],["C","门静脉高压症的主要阻塞部位在窦旁"],["D","门静脉高压症的主要阻塞部位在肝前"],["E","门静脉高压症的主要阻塞部位在肝后"]],"B","答案解析：门静脉血流阻力增加，常是门静脉高压症的始动因素。按阻力增加的部位，可将门静脉高压症分为肝前、肝内和肝后三型。肝内型门静脉高压症又可分为窦前性、窦性和窦后性。肝炎性肝硬化时，肝血窦闭塞或窦周纤维化，门静脉循环受阻，为窦性阻塞（而非窦旁阻塞）（C错）；增生的纤维束和再生的肝细胞结节压迫小叶下静脉，使肝窦内血液流出受阻，进而影响门静脉血流入肝血窦，为窦后性阻塞（B对）。","","N"],["1992-N104",9,"第8节 肝硬化","门脉高压症的概述(1)",1992,104,"B","","血吸虫肝硬变所致",[["A","门静脉高压症的主要阻塞部位在窦前"],["B","门静脉高压症的主要阻塞部位在窦后"],["C","门静脉高压症的主要阻塞部位在窦旁"],["D","门静脉高压症的主要阻塞部位在肝前"],["E","门静脉高压症的主要阻塞部位在肝后"]],"A","门静脉血流阻力增加，常是门静脉高压症的始动因素。按阻力增加的部位，可将门静脉高压症分为肝前、肝内和肝后三型。肝内型门静脉高压症的机制主要包括窦性阻塞、窦后性阻塞和窦前性分流三种类型：窦性阻塞指肝内广泛结缔组织增生，肝血窦闭塞或窦周纤维化，使门静脉循环受阻；窦后性阻塞指假小叶压迫小叶下静脉，使肝窦内血流流出受阻；窦前性分流指肝内肝动脉小分支与门静脉小支在汇入肝窦前形成异常吻合，使高压力的动脉血流入门静脉内。血吸虫肝硬变时由于虫卵在肝内大量沉积，引起门静脉干支系统纤维化，即所谓干线型肝硬化（十版病理学P363），虫卵阻塞处常有许多小血管增生，沟通阻塞的两端，使肝内肝动脉小分支与门静脉小支在汇入肝窦前形成异常吻合，使高压力的动脉血流入门静脉内，形成窦前性门脉高压（A对）。","","N"],["1992-N109",9,"","",1992,109,"C","","胃癌可引起",[["A","穿孔"],["B","出血"],["C","两者皆有"],["D","两者皆无"]],"C","胃癌的并发症（八版内科学P377）有：1.出血（B对），多呈呕血或黑粪；2.幽门或贲门梗阻，出现进食困难、呕吐、腹胀等；3.穿孔（A对）。本题AB均对，正确答案为C。","","N"],["1992-N110",16,"第4节 细菌性痢疾","细菌性痢疾病理变化概述",1992,110,"C","","细菌性痢疾可引起",[["A","穿孔"],["B","出血"],["C","两者皆有"],["D","两者皆无"]],"D","细菌性痢疾少见肠出血（B错），肠穿孔（A错）等并发症。本题AB均可出现，正确答案应为C，参考答案为D。本题题干改为“细菌性痢疾较常引起”可能更为严谨。","","N"],["1992-N111",7,"第2节 高血压病","内脏病变期",1992,111,"C","","高血压病",[["A","脑出血"],["B","肾固缩"],["C","两者皆有"],["D","两者皆无"]],"C","高血压时，脑血管的细小动脉硬化使血管壁变脆，当血压突然升高时引起破裂性出血，亦可由于血管壁弹性下降，局部膨出形成小动脉瘤和微小动脉瘤，当血压突然升高时，致小动脉瘤和微小动脉瘤破裂出血（A对）。高血压时，肾入球小动脉玻璃样变和肌型小动脉硬化，管壁增厚，管腔狭窄，致病变区的肾小球缺血发生纤维化、硬化或玻璃样变，相应的肾小管因缺血而萎缩，间质纤维组织增生。肉眼观，双侧肾脏对称性缩小，质地变硬，肾表面凹凸不平，呈细颗粒状，称为原发性颗粒性固缩肾（B对）。本题AB均对，正确答案为C。","","N"],["1992-N112",7,"第1节 动脉粥样硬化","主要动脉的病理变化",1992,112,"C","","动脉粥样硬化症",[["A","脑出血"],["B","肾固缩"],["C","两者皆有"],["D","两者皆无"]],"C","动脉粥样硬化病变发生脑血管时，可形成动脉瘤，患者血压突然升高时，可致动脉瘤破裂引起脑出血（A对）。动脉粥样硬化病变发生在肾血管时，可因斑块合并血栓形成引起肾组织梗死，梗死灶机化后遗留较大凹陷瘢痕，多个瘢痕可使肾脏缩小，称为AS性固缩肾（B对）。本题AB均对，正确答案为C。","","N"],["1992-N141",2,"第3节 血栓形成","血流状态异常",1992,141,"X","","心室壁瘤时，血栓形成的主要原因在于",[["A","心室内膜粗糙"],["B","血液浓缩"],["C","涡流形成"],["D","心源性休克"]],"AC","血栓的形成有三个要素：血管内皮损伤、血流状态的改变和血液凝固性增加。心肌梗死后梗死区域出现室壁扩张、变薄、心肌全层坏死，坏死心肌由瘢痕组织代替，病变区薄层的心室壁向外膨出，形成室壁瘤。血液在该处常形成涡流（血流状态改变）（C对），同时由于该处心室内膜粗糙（血管内皮损伤）（A对），极易形成附壁血栓。","","N"],["1992-N142",7,"第1节 动脉粥样硬化","颈动脉及脑动脉粥样硬化",1992,142,"X","","脑动脉粥样硬化时，脑组织可发生",[["A","萎缩"],["B","软化"],["C","梗死"],["D","出血"]],"ABCD","脑动脉粥样硬化时，由于脑动脉管腔狭窄，脑组织长期供血不足而发生脑萎缩（A对）。由于斑块处常继发血栓形成致管腔阻塞，引起脑梗死（脑软化）（BC对）。脑动脉粥样硬化常形成动脉瘤，患者血压突然升高时，可致动脉瘤破裂引起脑出血（D对）。","","N"],["1992-N143",14,"第3节 中枢神经系统感染性疾病","病毒性疾病病理变化概述",1992,143,"X","","乙型脑炎的病理变化主要表现为",[["A","神经细胞的变性、坏死"],["B","筛状软化灶形成"],["C","淋巴细胞套袖状浸润"],["D","病变以小脑、延脑、脑桥为最严重"]],"ABC","乙型脑炎的病变以大脑皮质、基底核和视丘最为严重（D错）。镜下通常可见：1.血管改变和炎症反应，浸润的炎细胞以淋巴细胞、单核细胞和浆细胞为主，其中淋巴细胞可围绕血管呈套袖状浸润（C对）；2.神经细胞变性、坏死（A对）；3.筛状软化灶形成（B对）；4.胶质细胞增生。","","N"],["1992-N144",8,"第4节 支气管扩张症","支气管扩张症的病理变化",1992,144,"X","","支气管扩张症的主要发病基础是",[["A","支气管慢性感染"],["B","支气管阻塞性通气障碍"],["C","支气管肿瘤压迫"],["D","支气管壁平滑肌和弹力组织遭受破坏"]],"AD","支气管扩张症多继发于支气管的慢性感染（A对），因反复感染，特别是化脓性炎症常导致支气管壁平滑肌和弹力组织遭受破坏（D对）；同时受支气管壁外周肺组织慢性炎症所形成的纤维瘢痕组织的牵拉及咳嗽时支气管腔内压的增加，最终导致支气管壁持久性扩张。","","N"],["1992-N145",10,"第2节 淋巴组织肿瘤","WHO关于淋巴组织肿瘤的分类",1992,145,"X","","B细胞恶性淋巴瘤可以有",[["A","伯基特氏淋巴瘤"],["B","浆细胞样淋巴细胞淋巴瘤"],["C","小细胞淋巴瘤"],["D","滤泡中心细胞淋巴瘤"]],"ABCD","B细胞恶性淋巴瘤即B细胞起源的淋巴瘤（淋巴瘤均为恶性）。伯基特氏淋巴瘤（Burkitt）（A对）、浆细胞样淋巴细胞淋巴瘤（B对）、小细胞淋巴瘤（C对）和滤泡中心细胞淋巴瘤（D对）均为B细胞起源的淋巴瘤。","","N"],["1993-N29",16,"第4节 细菌性痢疾","中毒性细菌性痢疾",1993,29,"A","","下述哪项有关中毒性痢疾的描述是不正确的",[["A","儿童多见"],["B","肠道症状轻"],["C","多由毒力强的痢疾杆菌引起"],["D","全身症状明显"],["E","患者对细菌毒素反应强烈"]],"C","中毒性痢疾是细菌性痢疾的一种临床病理类型，多由毒力较低的福氏或宋内氏痢疾杆菌引起（C错，为本题正确答案），儿童多见（A对）。患者对细菌毒素反应强烈（E对），全身症状明显（D对），但肠道症状轻微（B对），发病后数小时即可出现中毒性休克或呼吸衰竭而死亡。","","N"],["1993-N30",9,"第12节 消化系统常见肿瘤","结直肠癌的分期与预后",1993,30,"A","","早期大肠癌是",[["A","局限于黏膜层及黏膜下层的癌"],["B","侵及黏膜下层的癌"],["C","侵及浅肌层的癌"],["D","无淋巴结转移的癌"],["E","直径小于2cm的癌"]],"B","大肠壁由内至外依次可分为黏膜层、黏膜下层、肌层和浆膜层共四层，早期大肠癌的癌组织浸润仅局限于黏膜层及黏膜下层，未侵及肌层（C错），无论有无淋巴结转移（D错）。早期大肠癌的判定与病灶直径大小（E错）无关。且根据十版（P220）WHO肿瘤分类对大肠癌的定义，大肠肿瘤组织只有侵犯黏膜肌层到达黏膜下层才称为癌。只要不超过黏膜肌层，就不称为癌，而称为上皮内瘤变（A错B对）。","","N"],["1993-N31",9,"第8节 肝硬化","病毒性肝炎",1993,31,"A","","我国门脉性肝硬变最常见的原因是",[["A","慢性酒精中毒"],["B","营养不良"],["C","胆道阻塞"],["D","血吸虫病"],["E","病毒性肝炎"]],"E","门脉性肝硬化的病因及发病机制尚未完全清楚，有很多因素均可引起肝细胞的损害进而发展为肝硬化，这些因素有：①病毒性肝炎：是我国肝硬化的主要原因（E对），尤其是乙型和丙型病毒性肝炎与肝硬化的发展有密切关系。②慢性酒精中毒：长期酗酒是引起肝硬化的一个重要因素，在欧美国家尤为突出，由于酒精在肝内代谢产生乙醛有直接毒害作用，使肝细胞发生脂肪变性而逐渐进展为肝硬化（A错）。③营养不良：长期缺乏蛋氨酸和胆碱类物质时使肝合成磷脂障碍而发生脂肪变性而逐渐进展为肝硬化（C错）。④有毒物质的损害。","","N"],["1993-N32",8,"第1节 呼吸道和肺炎症性疾病","大叶性肺炎的病理变化及临床病理联系",1993,32,"A","","下述哪项描述不符合大叶性肺炎",[["A","多由肺炎球菌引起"],["B","属浆液性炎"],["C","可继发肺脓肿"],["D","肺泡炎症为主"],["E","可继发肺肉质变"]],"B","大叶性肺炎是主要由肺炎球菌（A对）引起的发生于肺泡（D对）的纤维素性炎症（B错，为本题正确答案）。大叶性肺炎时，若病灶中中性粒细胞渗出过少，则释放的蛋白酶量不足以溶解渗出物中的纤维素，大量未能被溶解吸收的纤维素即被肉芽组织取代而机化，称肺肉质变（E对）。若病原菌毒力强大或机体抵抗力低下，由金黄色葡萄球菌和肺炎链球菌混合感染时，易并发肺脓肿（C对）。","","N"],["1993-N33",5,"第12节 肿瘤与遗传","遗传性肿瘤综合征概念",1993,33,"A","","下列哪项描述不符合遗传性肿瘤的特点",[["A","发病年龄较轻"],["B","常为多发性肿瘤"],["C","第一次突变发生在生殖细胞"],["D","男性多于女性"],["E","家族史阳性"]],"D","遗传性肿瘤多有家族史（E对），为常染色体遗传，与性别无关（D错，为本题正确答案）。肿瘤的遗传性可用两次打击假说（十版病理学P113）来解释，两次打击假说认为遗传性肿瘤家族连续传递时，已经携带了一个生殖细胞系的突变（即第一次突变发生在生殖细胞）（C对），此时若在体细胞内再发生一次体细胞突变，即产生肿瘤，这种事件较易发生，所以发病年龄较轻（A对）。遗传性肿瘤呈多发性（B对），常累及双侧器官。","","N"],["1993-N34",7,"第4节 风湿病","风湿性心内膜炎",1993,34,"A","","慢性风湿性瓣膜病常见的联合瓣膜损害是",[["A","二尖瓣与三尖瓣"],["B","二尖瓣与主动脉瓣"],["C","主动脉瓣与肺动脉瓣"],["D","主动脉瓣与三尖瓣"],["E","二尖瓣与肺动脉瓣"]],"B","慢性风湿性瓣膜病（慢性风湿性心脏病）最常损害的单瓣膜是二尖瓣，最常损害的联合瓣膜是二尖瓣和主动脉瓣（B对）。","","N"],["1993-N35",3,"第3节 慢性炎症","肉芽肿性炎的常见类型",1993,35,"A","","下述炎症中哪种不属肉芽肿性炎",[["A","麻风"],["B","真菌感染"],["C","手术缝线慢性炎症反应"],["D","粟粒性结核病"],["E","阿米巴病"]],"E","肉芽肿性炎以炎症局部巨噬细胞及其衍生细胞增生形成境界清楚的结节状病灶（即肉芽肿）为特征，是一种特殊类型的慢性炎症。肉芽肿性炎的常见类型有感染性肉芽肿、异物性肉芽肿和原因不明的肉芽肿。麻风（A对）、真菌感染（B对）、粟粒性结核病（D对）均为感染性肉芽肿。手术缝线慢性炎症反应为异物性肉芽肿（C对）。阿米巴病为组织溶解液化为主的变质性炎，不属于肉芽肿性炎（E错，为本题正确答案）。","","N"],["1993-N36",2,"第3节 血栓形成","混合血栓",1993,36,"A","","混合性血栓可见于",[["A","静脉内柱状血栓尾部"],["B","毛细血管内血栓"],["C","风湿性心内膜炎瓣膜闭锁缘疣状血栓"],["D","动脉血栓头部"],["E","心室附壁血栓"]],"E","血栓类型可分为四种：白色血栓、混合血栓、红色血栓和透明血栓。静脉内柱状血栓头部为白色血栓，体部为混合血栓，尾部为红色血栓（A错）。毛细血管内为透明血栓（B错）。风湿性心内膜炎瓣膜闭锁缘为白色血栓（C错）。动脉血栓整体（包括头部）均为白色血栓（D错）。心室附壁血栓为混合血栓（E对）。","","N"],["1993-N37",0,"第3节 细胞可逆性损伤","脂肪变的机制",1993,37,"A","","下述肝脂肪变性的原因描述中，哪项是错误的",[["A","化学毒物使脂蛋白合成障碍，导致肝脂肪变性"],["B","糖尿病时，脂肪酸入肝过多，导致肝脂肪变性"],["C","缺氧时可导致肝脂肪变性"],["D","食入脂肪过多导致肝脂肪变性"],["E","白喉杆菌外毒素影响脂肪酸代谢导致肝脂肪变性"]],"D","化学毒物（A对）和缺氧（C对）均使脂蛋白合成障碍，导致肝脂肪变性。糖尿病时，葡萄糖代谢受阻，脂肪动员增加，使血液中游离脂肪酸含量增高，进入肝脏的游离脂肪酸增多，导致肝脏脂肪变性（B对）。食入脂肪过多时，血液中游离脂肪酸含量增高，进入肝脏的游离脂肪酸增多，导致肝脏脂肪变性（D对）。白喉外毒素能干扰脂肪酸的氧化利用过程，使脂肪酸相对增多，导致肝脏脂肪变性（E对）。故本题没有正确答案，但给出的参考答案为D。","","N"],["1993-N38",10,"第3节 髓系肿瘤","慢性髓系白血病病理变化",1993,38,"A","","慢性粒细胞白血病时，肝内白血病细胞浸润的部位是",[["A","集中在被膜下"],["B","集中在中央静脉周围"],["C","集中在汇管区内"],["D","弥散在肝窦内"],["E","集中在小叶下静脉周围"]],"D","慢性粒细胞性白血病（CML）时，瘤细胞多沿肝窦（D对）呈弥漫性浸润。慢性淋巴细胞性白血病（CLL）时，瘤细胞浸润汇管区及其周围。急性粒细胞白血病（AML）时，瘤细胞主要在淋巴结的副皮质区及窦内浸润，在脾脏红髓及肝窦内浸润（十版病理学P244）。急性淋巴细胞性白血病（ALL）时，瘤细胞浸润肝血窦及汇管区。","","N"],["1993-N39",7,"第1节 动脉粥样硬化","主动脉粥样硬化",1993,39,"A","","下述哪项关于动脉粥样硬化症的叙述是错误的",[["A","粥样硬化易发生在主动脉前壁"],["B","冠状动脉左前降支易受累"],["C","大脑中动脉易受累"],["D","可引起肾固缩"],["E","下肢动脉比上肢动脉易受累"]],"A","动脉粥样硬化症的粥肿易发生于主动脉后壁（A错，为本题正确答案）。冠状动脉粥样硬化是冠状动脉最常见的疾病，根据病变检出率和统计结果，以左冠状动脉前降支发生率为最高（B对）。颈动脉及脑动脉粥样硬化，最常见于颈内动脉起始部、基底动脉、大脑中动脉（C对）和Willis环。肾动脉粥样硬化可因斑块合并血栓形成使肾组织梗死，梗死灶机化后遗留较大凹陷瘢痕，多个瘢痕可使肾脏缩小，称为AS性肾固缩（D对）。四肢动脉粥样硬化以下肢动脉更易受累（E对），常发生在髂动脉、股动脉和前后胫动脉。","","N"],["1993-N40",9,"第12节 消化系统常见肿瘤","中晚期胃癌的溃疡型",1993,40,"A","","中晚期胃癌最多见的肉眼类型是",[["A","溃疡型"],["B","皮革胃"],["C","息肉型"],["D","局限浸润型"],["E","胶样癌"]],"A","中晚期胃癌肉眼形态可分三型：息肉型（蕈伞型）（C错）、溃疡型和浸润型（包括局限浸润型和弥漫浸润型）（D错），其中溃疡型最多见（A对）。胶样癌（九版病理学P231）的肉眼形态可是以上三型中的任何一种（E错）。皮革胃（十版病理学P217）又称革囊胃，为弥漫浸润型胃癌（B错）。","","N"],["1993-N89",8,"第8节 呼吸系统常见肿瘤","腺癌",1993,89,"B","","肺泡细胞癌",[["A","中央型多见"],["B","周围型多见"],["C","弥漫型多见"],["D","由嗜银细胞发生"],["E","由上皮化生恶变而来"]],"C","肺泡细胞癌又称细支气管肺泡癌，其生长特点为癌细胞沿肺泡壁、肺泡管壁，有时也沿细支气管壁呈弥漫性浸润生长（鳞屑状生长），属于弥漫型肺癌（C对）。","","N"],["1993-N90",8,"第8节 呼吸系统常见肿瘤","神经内分泌癌",1993,90,"B","","肺小细胞癌",[["A","中央型多见"],["B","周围型多见"],["C","弥漫型多见"],["D","由嗜银细胞发生"],["E","由上皮化生恶变而来"]],"D","小细胞癌又称小细胞神经内分泌癌，肺癌中恶性程度最高的一型，生长迅速，转移早，多为中央型（A对BC错），常发生于大支气管。电镜下66%～90%病例的癌细胞胞质中可见神经分泌颗粒，故认为其起源于支气管黏膜上皮的Kulchitsky细胞（嗜银细胞）（D对）。故本题答案为AD，但给出的参考答案仅为D。","","N"],["1993-N91",1,"第1节 再生","神经组织的再生",1993,91,"B","","创伤神经纤维瘤",[["A","肥大"],["B","增生"],["C","再生"],["D","化生"],["E","机化"]],"C","创伤性神经纤维瘤为神经纤维再生（C对）的结果。肥大（A错）、增生（B错）、化生（D错）为细胞和组织适应的类型。机化指肉芽组织的形成过程（E错）。","","N"],["1993-N92",0,"第1节 适应","鳞状上皮的化生",1993,92,"B","","支气管内出现鳞状上皮",[["A","肥大"],["B","增生"],["C","再生"],["D","化生"],["E","机化"]],"D","化生是一种分化成熟的细胞类型被另一种分化成熟的细胞类型取代的过程，支气管正常被覆假复层纤毛柱状上皮细胞，受到吸烟等外界刺激时，可被鳞状上皮细胞取代，此为化生过程（D对）。","","N"],["1993-N115",11,"第3节 肾和膀胱常见肿瘤","尿路上皮肿瘤病理变化",1993,115,"C","","膀胱可以发生",[["A","鳞状细胞癌"],["B","腺癌"],["C","两者皆有"],["D","两者皆无"]],"C","绝大多数膀胱癌起源于尿路移行上皮，为移行细胞癌，但也可为鳞状细胞癌（A对）、腺癌（B对）和肉瘤。本题AB均对，正确答案为C。","","N"],["1993-N116",9,"第12节 消化系统常见肿瘤","概述",1993,116,"C","","食管可以发生",[["A","鳞状细胞癌"],["B","腺癌"],["C","两者皆有"],["D","两者皆无"]],"C","食管癌是食管黏膜上皮或腺体发生的恶性肿瘤，绝大多数为鳞状细胞癌（A对），少数可为腺癌（B对）。本题AB均对，正确答案为C。","","N"],["1993-N117",3,"第2节 急性炎症","趋化作用",1993,117,"C","","C₅ₐ",[["A","血管通透性增加"],["B","白细胞趋化作用"],["C","两者皆有"],["D","两者皆无"]],"C","C₅ₐ对中性粒细胞、嗜酸性粒细胞、嗜碱性粒细胞和单核细胞均有趋化作用（B对）。C₅ₐ也能通过刺激肥大细胞释放组胺，使血管通透性增加（A对）。本题AB均对，正确答案为C。","","N"],["1993-N118",3,"第2节 急性炎症","内皮细胞收缩",1993,118,"C","","缓激肽",[["A","血管通透性增加"],["B","中性白细胞趋化作用"],["C","两者皆有"],["D","两者皆无"]],"A","缓激肽是一种血管活性肽，由激肽原酶作用于血浆中的激肽原而产生。缓激肽作用于内皮细胞受体，可使内皮细胞收缩，血管通透性增加（A对）。缓激肽不具有趋化作用（B错）。","","N"],["1993-N140",11,"第2节 肾小管间质性肾炎","肾盂肾炎类型概述",1993,140,"X","","肾盂肾炎的病变有如下特点",[["A","病变主要存在于肾间质"],["B","由细菌直接感染引起"],["C","以渗出性炎为主要病变"],["D","病变可呈局灶性分布"]],"ABCD","肾盂肾炎的病变主要存在于肾盂、肾间质（A对）和肾小管，是由细菌直接感染引起的（B对）。肾盂肾炎分为急性和慢性两类，二者均属于化脓性渗出性炎症（C对）。急性肾盂肾炎的病变呈局灶性分布（D对）。","","N"],["1993-N141",5,"第1节 肿瘤的概念","概念",1993,141,"X","","肿瘤性增生的腺上皮细胞具有如下特点",[["A","分化成熟能力下降"],["B","可具有一定代偿功能"],["C","相对无止境生长"],["D","可具有分泌功能"]],"ACD","肿瘤性增生的腺上皮细胞不同程度地失去分化成熟的能力（A对），能相对无止境的生长（C对）。肿瘤性增生的腺上皮细胞仍具有分泌功能（D对），如分泌浆液、黏液甚至激素，但是腺癌无正常的腺体结构，失去了代偿功能（B错）。","","N"],["1993-N142",9,"第12节 消化系统常见肿瘤","肝细胞癌的病因",1993,142,"X","","下列哪些因素与肝癌发生关系密切",[["A","黄曲霉污染的食物"],["B","坏死后的肝硬变"],["C","华支睾吸虫胆道感染"],["D","肝细胞不典型增生"]],"ABCD","与肝癌发生关系密切的因素有：1.肝炎病毒（乙型肝炎病毒最多见）；2.肝硬化，我国肝癌最常合并坏死后的肝硬变（B对）；3.酒精；4.真菌及其毒素，例如黄曲霉污染的食物（A对）。华支睾吸虫主要寄生于肝内胆管，重度感染者可导致胆管细胞癌（C对）等病变。肝细胞不典型增生（D对）为肝癌的癌前病变，最终会发展为肝癌。","","N"],["1993-N143",16,"第2节 结核病","原发性肺结核病",1993,143,"X","","原发性肺结核病的病变特点是",[["A","成人多见"],["B","原发灶多位于肺尖部"],["C","肺内形成空洞多见"],["D","由肺内原发灶、淋巴管炎、肺门淋巴结结核构成"]],"D","原发性肺结核病是指初次感染结核杆菌所引起的肺结核病，其病变特点是原发综合征的形成，而原发综合征由肺内原发灶、淋巴管炎、肺门淋巴结结核构成（D对）。此病多见于儿童（A错），青年和成人亦可见，原发灶多位于肺上叶下部或下叶上部（B错）。肺内形成空洞（C错）多见于空洞型肺结核（继发性肺结核的一种类型）。原X型题为不定项选择题，有1~4个正确答案。","","N"],["1993-N144",0,"第4节 细胞不可逆性损伤（细胞死亡）","湿性坏疽",1993,144,"X","","湿性坏疽可发生于",[["A","小肠"],["B","肺"],["C","下肢"],["D","脾"],["E","上皮细胞"]],"ABC","湿性坏疽多发生于与外界相通的内脏，如肺（B对）、肠（A对）、子宫、阑尾及胆囊等，也可发生于动脉阻塞及静脉回流受阻的肢体（C对）。脾为组织结构较致密、侧支循环不充分的实质器官，多发生凝固性坏死（D错）。湿性坏疽一般发生在组织或器官，很少发生在某种特定类型的细胞上（E错）。","","N"],["1994-N33",0,"第4节 细胞不可逆性损伤（细胞死亡）","纤维素样坏死",1994,33,"A","","结节性动脉周围炎的血管壁坏死是",[["A","液化性坏死"],["B","纤维素样坏死"],["C","干酪性坏死"],["D","脂肪坏死"],["E","固缩坏死"]],"B","由于酶的分解作用或蛋白质变性所占地位的不同，坏死组织会出现不同的形态学变化，通常分为凝固性坏死、液化性坏死和纤维素样坏死三个基本类型。此外，还有干酪样坏死、脂肪坏死和坏疽等一些特殊类型的坏死。纤维素样坏死主要见于某些变态反应性疾病，如风湿病、结节性多动脉炎（B对）、新月体性肾小球肾炎，以及急进性高血压和胃溃疡底部小血管等。液化性坏死（A错）常见于含脂质多（脑、脊髓、乳房）和蛋白酶多（如胰腺）的组织。干酪样坏死（C错）主要见于结核病病灶内。脂肪坏死主要见于急性胰腺炎和乳房创伤时。固缩坏死（E错）旧指凋亡，多见于单个细胞的生理性死亡过程。","","N"],["1994-N34",1,"第1节 再生","永久性细胞",1994,34,"A","","下述哪种细胞属于永久性细胞",[["A","造血细胞"],["B","表皮细胞"],["C","肝细胞"],["D","心肌细胞"],["E","肾小管细胞"]],"D","按再生能力的强弱可将人体细胞分为不稳定细胞、稳定细胞、永久性细胞三类。不稳定细胞又称持续分裂细胞，这类细胞总是都在进行新老更替，具有应对损伤的强大再生修复能力，如表皮细胞（B错）、呼吸道和消化道黏膜被覆细胞、男性及女性生殖器官管腔的被覆细胞、淋巴及造血细胞（A错）、间皮细胞等。稳定细胞又称静止细胞，这类细胞在生理情况下增殖现象并不明显，但当受到损伤时，会表现出较强的再生能力，如肝（C错）、胰、涎腺、内分泌腺、汗腺、皮脂腺和肾小管的上皮细胞（E错）等。永久性细胞又称非分裂细胞，这类细胞再生能力极弱，无论在生理情况下还是在受到损伤刺激的情况下，均不具有再生能力，如神经细胞、骨骼肌细胞及心肌细胞（D对）等。","","N"],["1994-N35",3,"第2节 急性炎症","白细胞激活",1994,35,"A","","下述哪项不符合单核巨噬细胞的特点",[["A","细胞表面有Fc受体"],["B","细胞表面有C3b受体"],["C","细胞表面有抗原识别受体"],["D","处理传递抗原信息"],["E","免疫监视功能"]],"C","单核-巨噬细胞是机体重要的免疫细胞（包括骨髓中的前单核细胞、外周血中的单核细胞、及组织内的巨噬细胞），具有抗感染、抗肿瘤和免疫调节等重要作用。单核-巨噬细胞表面有Fc受体（A对）和C3b受体（B对），可介导单核-巨噬细胞吞噬病原微生物（病原微生物被抗体IgG的Fc段和补体C3b包裹），发挥抗感染作用。单核-巨噬细胞亦具有识别、杀伤并清除体内突变细胞，防止肿瘤发生的功能，此为单核-巨噬细胞的免疫监视功能（E对）。单核-巨噬细胞还能摄取、加工处理抗原，并将处理过的抗原呈递给T、B淋巴细胞（D对），发挥免疫调节功能。抗原识别受体指T细胞、B细胞表面的T细胞受体和B细胞受体，前者可特异性识别抗原肽-MHC分子复合物，后者可特异性识别抗原的B细胞表位。单核巨噬细胞表面无抗原识别受体（C错，为本题正确答案）。","","N"],["1994-N36",8,"第9节 胸膜疾病","良性及浸润前间皮肿瘤",1994,36,"A","","下述哪种肿瘤是良性肿瘤",[["A","淋巴瘤"],["B","黑色素瘤"],["C","尤文氏瘤"],["D","骨髓瘤"],["E","间皮瘤"]],"E","淋巴瘤（十版病理学P226）为原发于淋巴结和结外淋巴组织的恶性肿瘤（A错）。黑色素瘤（十版病理学P108）为皮肤、黏膜及内脏黑色素细胞产生的恶性肿瘤（B错），又称恶性黑色素瘤。尤文氏瘤（二版八年制病理学P439）又称Ewing肉瘤或骨尤文肉瘤，为起源于骨髓间充质细胞的恶性肿瘤（C错）。骨髓瘤又称浆细胞骨髓瘤（十版病理学P235）或多发性骨髓瘤，为起源于骨髓中浆细胞的恶性肿瘤（D错）。间皮瘤好发于胸膜和腹膜，有良性和恶性之分，并且恶性者更为常见，故E选项也是错误的。本题应无正确答案，但给出的参考答案为E。在历年西医综合真题中，良恶性肿瘤的鉴别反复出现，现将常考的良恶性肿瘤归纳如下——良性肿瘤：骨母细胞瘤、软骨母细胞瘤、脂肪母细胞瘤、肌母细胞瘤、葡萄胎、血管瘤、神经鞘瘤、纤维腺瘤、多形性腺瘤；恶性肿瘤：淋巴瘤（A错）、白血病、黑色素瘤（B错）、视网膜母细胞瘤、神经母细胞瘤、肾母细胞瘤、肝母细胞瘤、绒毛膜癌、无性细胞瘤、精原细胞瘤、骨髓瘤（D错）、尤文氏瘤（C错）。","","N"],["1994-N37",5,"第9节 癌前病变和原位癌","大肠腺瘤",1994,37,"A","","下述哪个病变是癌前病变",[["A","大肠腺瘤"],["B","皮下脂肪瘤"],["C","皮肤纤维瘤"],["D","子宫平滑肌瘤"],["E","乳腺纤维腺瘤"]],"A","某些疾病虽然本身不是恶性肿瘤，但具有发展为恶性肿瘤的潜能，这些疾病或病变称为癌前疾病或癌前病变。如大肠腺瘤（A对）、乳腺纤维囊性病、慢性胃炎与肠上皮化生、慢性溃疡性结肠炎、皮肤慢性溃疡、黏膜白斑等。皮下脂肪瘤（十版病理学P105）（B错）、皮肤纤维瘤（C错）、子宫平滑肌瘤（十版病理学P273）（D错）、乳腺纤维腺瘤（十版病理学P285）（E错）均为良性肿瘤。","","N"],["1994-N38",9,"第6节 病毒性肝炎","乙型肝炎病毒改变特点",1994,38,"A","","慢性肝炎时出现的毛玻璃细胞，在电镜下的主要变化是",[["A","光面内质网大量增生"],["B","粗面内质网大量增生"],["C","线粒体大量增生"],["D","高尔基器肥大增生"],["E","溶酶体数目增多"]],"A","毛玻璃样细胞是乙型肝炎一种特殊的形态学特征，HE染色光镜下，可见部分肝细胞胞质内充满嗜酸性细颗粒物质，胞质不透明似毛玻璃样，电镜下见细胞质滑面内质网（光面内质网）增生（A对），此为HBsAg颗粒沉积。","","N"],["1994-N39",10,"第2节 淋巴组织肿瘤","霍奇金淋巴瘤的病理诊断",1994,39,"A","","何杰金氏病最重要的具有诊断意义的病变是",[["A","小核裂细胞"],["B","大核裂细胞"],["C","陷窝细胞"],["D","何杰金氏细胞"],["E","R-S细胞"]],"E","何杰金氏病（霍奇金淋巴瘤）的肿瘤细胞包括典型的R-S细胞及其变异型细胞，典型的R-S细胞（E对）对何杰金氏病具有诊断意义。陷窝细胞（十版病理学P241）只对结节硬化型何杰金氏病具有诊断意义（C错）。何杰金氏细胞（霍奇金细胞）（十版病理学P239）是一种与R-S细胞形态特征相似，但只有单核的瘤巨细胞，对何杰金氏病的诊断意义不大（D错）。小核裂细胞（中心细胞）（A错）和大核裂细胞（B错）均见于滤泡性淋巴瘤。","","N"],["1994-N40",11,"第1节 肾小球疾病","微小病变性肾小球病病理变化",1994,40,"A","","脂性肾病的病理学特点是",[["A","嗜银染色显示毛细血管基底膜上形成许多钉状突起"],["B","肾小球囊脏层上皮细胞足突消失"],["C","系膜细胞增生"],["D","系膜基质增生"],["E","内皮细胞增生"]],"B","脂性肾病即微小病变性肾小球肾炎，其病变特点是肾小球囊脏层上皮细胞足突消失（B对）。嗜银染色显示毛细血管基底膜上形成许多钉状突起（A错）为膜性肾病的病理学特点（十版病理学P256）。系膜细胞增生（C错）可见于急性肾炎（十版病理学P254）、系膜增生性肾炎（十版病理学P258）、膜增生性肾炎（十版病理学P256）、IgA肾病（十版病理学P259）。内皮细胞增生（E错）可见于急性肾炎。系膜基质增生（D错）可见于膜增生性肾炎（十版病理学P256）和系膜增生性肾炎。","","N"],["1994-N41",12,"第5节 前列腺疾病","前列腺癌病理变化",1994,41,"A","","前列腺癌患者血清中增高的物质是",[["A","酸性磷酸酶"],["B","碱性磷酸酶"],["C","甲胎蛋白"],["D","癌胚抗原"],["E","CA₁₉₋₉"]],"A","前列腺癌患者血清中增高的物质主要包括血清酸性磷酸酶（ACP）（A对）和血清前列腺特异性抗原（PSA）。血清中大部分碱性磷酸酶来源于肝脏与骨骼，血清碱性磷酸酶（B错）增高见于各种肝胆系统疾病和骨骼疾病（九版诊断学P363）。甲胎蛋白（C错）增高主要见于肝细胞癌和生殖腺胚胎肿瘤等（九版诊断学P416）。癌胚抗原（CEA）（D错）（九版诊断学P417）是一个广谱性肿瘤标记物，其增高可见于结、直肠癌、胰腺癌、乳腺癌、胃癌、肺癌、甲状腺癌等多种恶性肿瘤。CA19-9（E错）（九版诊断学P419）增高主要见于胰腺癌。注：酸性磷酸酶（ACP）是在酸性条件下能催化磷酸基转移反应的酶，主要存在于细胞的溶酶体中，正常男性血清中有1/3～1/2来自前列腺。前列腺癌，特别是发生转移时，ACP可显著升高，因此ACP水平常用于诊断前列腺癌，但由于其不稳定，检测困难，目前已被PSA所取代（九版诊断学P417）。","","N"],["1994-N42",16,"第2节 结核病","继发性肺结核病概述",1994,42,"A","","下面哪一项是继发性肺结核病所不具备的",[["A","肺尖部最常受累"],["B","可形成纤维性空洞"],["C","病程长，时好时坏"],["D","新旧病变交错"],["E","淋巴道播散为主"]],"E","继发性肺结核的病理特点有：①病变最先并最常见于肺尖部（A对），因此病变呈上旧下新、上重下轻的特点；②病程长，病变复杂，随着机体免疫反应和变态反应的消长，新旧病灶交错（D对），临床症状时好时坏（C对）；③以气道播散为主（E错，为本题正确答案），多局限于肺内。纤维性空洞可见于慢性纤维空洞型肺结核，后者为继发性肺结核的常见类型（B对）。","","N"],["1994-N43",12,"第7节 乳腺疾病","非特殊型浸润性癌",1994,43,"A","","最常见的乳腺癌的病理学类型是",[["A","导管内癌"],["B","浸润性导管癌"],["C","小叶原位癌"],["D","髓样癌"],["E","浸润性小叶癌"]],"B","乳腺癌按照组织形态可分为非浸润性癌和浸润性癌两类。非浸润性癌包括导管内原位癌（A）和小叶原位癌（C），浸润性癌包括浸润性导管癌（B）、浸润性小叶癌（E）和特殊类型癌，所有类型中最常见的是浸润性导管癌（B对）。髓样癌（D）是特殊类型癌的一种。","","N"],["1994-N44",13,"第2节 甲状腺疾病","髓样癌",1994,44,"A","","下述哪种甲状腺肿瘤是由APUD细胞发生的",[["A","乳头状腺癌"],["B","滤泡腺癌"],["C","髓样癌"],["D","梭形细胞癌"],["E","巨细胞癌"]],"C","APUD细胞（九版病理学P311）是指一系列能吸取胺的前身，使之脱羧基并转变为胺类物质（APUD）的内分泌细胞。髓样癌（C对）是由滤泡旁降钙素分泌细胞（即甲状腺C细胞，属于APUD细胞）发生的甲状腺肿瘤。","","N"],["1994-N45",16,"第10节 寄生虫病","肠阿米巴病病理变化概述",1994,45,"A","","肠阿米巴病所形成的肠溃疡呈",[["A","火山口状"],["B","烧瓶口状"],["C","椭圆形，长轴与肠长轴平行"],["D","环形"],["E","匐行形"]],"B","肠阿米巴病所形成的肠溃疡呈口小底大的烧瓶口状（B对）。火山口状（A错）是癌性溃疡的特点（十版病理学P216）。椭圆形，长轴与肠长轴平行（C错）是肠伤寒溃疡的特点（十版病理学P350）。环形（D错）是肠结核溃疡的特点（十版病理学P348）。匐行形（E错）是克罗恩病溃疡的特点。","","N"],["1994-N46",16,"第10节 寄生虫病","急性虫卵结节",1994,46,"A","","血吸虫卵引起的急性虫卵结节内浸润的细胞为",[["A","大量浆细胞"],["B","大量肥大细胞"],["C","大量淋巴细胞"],["D","大量嗜酸性粒细胞"],["E","大量巨噬细胞"]],"D","血吸虫卵引起的急性虫卵结节在镜下可见：结节中央有1～2个成熟虫卵，其周围浸润着大量嗜酸性粒细胞（D对），状似脓肿，故也称为嗜酸性脓肿。","","N"],["1994-N103",0,"第4节 细胞不可逆性损伤（细胞死亡）","凋亡的概念",1994,103,"B","","体内细胞的生理死亡",[["A","凝固性坏死"],["B","固缩坏死"],["C","干酪性坏死"],["D","坏疽"],["E","液化性坏死"]],"B","固缩坏死为凋亡的旧称，多见于单个细胞的生理性死亡过程（B对）。凝固性坏死（A错）、干酪性坏死（C错）、坏疽（D错）和液化性坏死（E错）均为坏死的类型，为细胞病理性死亡过程。","","N"],["1994-N104",0,"第4节 细胞不可逆性损伤（细胞死亡）","凝固性坏死",1994,104,"B","","脾梗死",[["A","凝固性坏死"],["B","固缩坏死"],["C","干酪性坏死"],["D","坏疽"],["E","液化性坏死"]],"A","蛋白质变性凝固且溶酶体酶水解作用较弱时，坏死区呈灰黄、干燥、质实状态，称为凝固性坏死，多见于心、肝、肾和脾（A对）等实质器官。干酪性坏死（C错）是坏死更为彻底的特殊类型凝固性坏死，常见于结核病。坏疽（D错）是指局部组织大块坏死并继发腐败菌感染的坏死类型，分为干性、湿性和气性等类型：干性坏疽常见于动脉阻塞但静脉回流尚畅通的四肢末端；湿性坏疽见于与外界相通的内脏，如肺、肠、子宫、阑尾及胆囊等，也可发生于动脉阻塞及静脉回流受阻的四肢；气性坏疽常见于深达肌肉的开放性创伤。液化性坏死（E错）指细胞组织发生溶解液化的坏死类型，常见于脑、脊髓、胰腺及乳房等处。固缩（B错）坏死旧指凋亡，多见于单个细胞的生理性死亡过程。","","N"],["1994-N125",8,"第1节 呼吸道和肺炎症性疾病","病毒性肺炎的病理变化",1994,125,"C","","麻疹病毒",[["A","核内病毒包涵体"],["B","胞浆内病毒包涵体"],["C","两者皆有"],["D","两者皆无"]],"C","病毒包涵体是病毒在增殖的过程中，使寄主细胞形成的一种蛋白质性质的病变结构，在光学显微镜下可见，多为圆形或椭圆形，约红细胞大小。病毒包涵体在细胞内出现的位置因感染病毒的种类不同而已。腺病毒、单纯疱疹病毒和巨细胞病毒的病毒包涵体位于核内；呼吸道合胞病毒的病毒包涵体位于胞浆内；麻疹病毒（C对）的病毒包涵体在核内和胞浆（胞质）内均可见到。","","N"],["1994-N126",8,"第1节 呼吸道和肺炎症性疾病","病毒性肺炎的病理变化",1994,126,"C","","腺病毒",[["A","核内病毒包涵体"],["B","胞浆内病毒包涵体"],["C","两者皆有"],["D","两者皆无"]],"A","病毒包涵体是病毒在增殖的过程中，使寄主细胞形成的一种蛋白质性质的病变结构，在光学显微镜下可见，多为圆形或椭圆形，约红细胞大小。病毒包涵体在细胞内出现的位置因感染病毒的种类不同而异。腺病毒（A对）、单纯疱疹病毒和巨细胞病毒的病毒包涵体位于核内并呈嗜碱性；呼吸道合胞病毒的病毒包涵体位于胞浆内；麻疹病毒的病毒包涵体在核内和胞浆（胞质）内均可见到。","","N"],["1994-N127",9,"第12节 消化系统常见肿瘤","早期胃癌的概述",1994,127,"C","","早期胃癌",[["A","蕈伞型"],["B","缩窄型"],["C","两者皆有"],["D","两者皆无"]],"D","早期胃癌大体分为以下三种类型：隆起型、表浅型和凹陷型。蕈伞型（A错）为中晚期胃癌（进展型胃癌）的类型（十版病理学P217）。缩窄型（B错）为中晚期食管癌的类型（十版病理学P216）。本题AB均错，正确答案为D。","","N"],["1994-N128",9,"第12节 消化系统常见肿瘤","中晚期癌",1994,128,"C","","食管癌",[["A","蕈伞型"],["B","缩窄型"],["C","两者皆有"],["D","两者皆无"]],"C","中晚期食管癌根据肉眼形态可分为四型：髓质型、蕈伞型（A对）、溃疡型和缩窄型（B对）。本题AB均对，正确答案为C。","","N"],["1994-N147",8,"第6节 慢性肺源性心脏病","心脏病变",1994,147,"X","","慢性肺源性心脏病时，心肺的病理变化可以有",[["A","肺肌型小动脉纤维样坏死"],["B","心肌纤维溶解、纤维化"],["C","弥漫性阻塞性肺气肿"],["D","肺纤维化"]],"BCD","弥漫性阻塞性肺气肿（C对）和肺纤维化（D对）均为慢性肺源性心脏病的病因，弥漫性阻塞性肺气肿和肺纤维化均可引起肺循环阻力增加，肺动脉压升高，导致慢性肺源性心脏病的发生。慢性肺源性心脏病除原有肺疾病所表现的多种肺部病变外，肺内的主要病变是肺小动脉的变化，包括无肌型细动脉肌化及肌型小动脉中膜增生、肥厚，内膜下出现纵行平滑肌束等，但不包括肌型小动脉纤维样坏死（P157肺肌型小动脉纤维样坏死可见于风湿性动脉炎）（A错）。慢性肺源性心脏病时，心肌缺氧，导致心肌纤维溶解和纤维性增生（B对）。","","N"],["1994-N148",8,"第1节 呼吸道和肺炎症性疾病","大叶性肺炎的病理变化及临床病理联系",1994,148,"X","","大叶性肺炎的病理特点有",[["A","肺泡的纤维素性炎"],["B","支气管常受累"],["C","可合并中毒性休克"],["D","可合并肺脓肿"]],"ACD","大叶性肺炎是主要由肺炎球菌引起的以肺泡内弥漫性纤维素渗出为主的炎症（A对）。大叶性肺炎时，若病原菌毒力强大或机体抵抗力低下，由金黄色葡萄球菌和肺炎链球菌混合感染时，易合并肺脓肿（D对）。大叶性肺炎的重症病例，可合并中毒性休克（C对），表现为严重的全身中毒症状和微循环衰竭。支气管受累是小叶性肺炎（十版病理学P174）的病变特点（B错）。","","N"],["1994-N149",3,"第2节 急性炎症","血管通透性增加",1994,149,"X","","炎症时血管通透性增高是由于",[["A","内皮细胞间连接缝隙增大"],["B","内皮细胞的变性坏死"],["C","内皮细胞吞饮增加"],["D","基底膜受损"]],"ABCD","在炎症过程中，引起血管通透性增加的机制有：①内皮细胞收缩，内皮间隙增大，使血管通透性增高（A对）；②内皮细胞损伤后变性坏死（B对）或基底膜受损（D对），使血管通透性增高；③内皮细胞吞饮增加，细胞的穿胞作用增强，使血管通透性增加（C对）；④新生毛细血管增多，新生毛细血管内皮细胞连接不健全，使血管通透性增加。","","N"],["1994-N150",5,"第11节 环境致瘤因素","真菌毒素",1994,150,"X","","黄曲霉毒素致癌的特点是",[["A","致癌性强"],["B","化学性不稳定，加热易分解"],["C","主要诱发胃癌"],["D","霉变的花生及谷物中含量高"]],"AD","黄曲霉毒素广泛存在于霉变食品中，以霉变的花生、玉米及谷类含量最多（D对）。黄曲霉毒素是目前发现的最强化学致癌物之一（A对），主要诱发肝细胞癌（C错）。黄曲霉毒素化学性质稳定，加热不易分解（B错），煮熟后食入仍有致癌作用。","","N"],["1995-N32",8,"第2节 慢性阻塞性肺疾病","全腺泡型肺气肿",1995,32,"A","","下述哪种慢性肺疾患与α₁-抗胰蛋白酶缺乏有关",[["A","肺出血肾炎综合征"],["B","全小叶性肺气肿"],["C","支气管扩张症"],["D","慢性支气管炎"],["E","肺间质纤维化"]],"B","α₁抗胰蛋白酶缺乏是全小叶性肺气肿（全腺泡型肺气肿）（B对）的发病机制之一：α₁-抗胰蛋白酶广泛存在于组织和体液中，对包括弹性蛋白酶在内的多种蛋白水解酶有抑制作用。α₁抗胰蛋白酶缺乏时，中性粒细胞和巨噬细胞分泌的弹性蛋白酶数量增多、活性增强，破坏了肺组织的结构，使呼吸性细支气管、肺泡管、肺泡囊和肺泡的回缩力均减弱，促进全腺泡型肺气肿的发生。α₁抗胰蛋白酶严重缺乏是支气管扩张症（C）的发病机制之一（九版内科学P36），故C选项也可认为正确，但给出的参考答案仅为B。","","N"],["1995-N33",0,"第1节 适应","化生的概念",1995,33,"A","","化生是指",[["A","细胞体积增大"],["B","细胞数量增多"],["C","细胞大小、形态不一致"],["D","一种分化组织代替另一种分化组织"],["E","细胞体积缩小"]],"D","细胞体积增大见于肥大（十版病理学P7）（A错）。细胞数量增多见于肥大和增生（十版病理学P7-P8）（B错）。细胞大小、形态不一致见于细胞恶变（十版病理学P92）（C错）。化生是指一种分化成熟的细胞类型被另一种分化成熟的细胞类型所取代的过程（D对）。细胞体积缩小见于萎缩（十版病理学P5）（E错）。","","N"],["1995-N34",6,"第2节 儿童疾病","良性肿瘤和肿瘤样病变",1995,34,"A","","误位于异常部位的分化正常的组织叫",[["A","错构瘤"],["B","迷离瘤"],["C","绿色瘤"],["D","畸胎瘤"],["E","尤文瘤"]],"B","迷离瘤（二版八年制病理学P128）指分化正常的组织误位于异常部位而形成的包块（B对）。错构瘤（二版八年制病理学P128）是由与所在器官相同的组织构成，但结构紊乱比例失常而形成的包块（A错）。绿色瘤（十版病理学P244）为急性髓系白血病时发生的粒细胞肉瘤（C错）。畸胎瘤（十版病理学P280）是一种常见的卵巢生殖细胞肿瘤（D错）。尤文瘤（二版八年制病理学P439）又称Ewing肉瘤或骨尤文肉瘤，为起源于骨髓间充质细胞的恶性肿瘤（E错）。","","N"],["1995-N35",5,"第3节 肿瘤的命名与分类","肿瘤的分类",1995,35,"A","","下述肿瘤中，哪一种是良性肿瘤",[["A","白血病"],["B","神经母细胞瘤"],["C","葡萄胎"],["D","无性细胞瘤"],["E","骨髓瘤"]],"C","白血病（十版病理学P243）为发生于骨髓造血干细胞的恶性肿瘤（A错）。神经母细胞瘤（十版病理学P324）为发生于交感神经节和肾上腺髓质的恶性肿瘤（B错）。葡萄胎（十版病理学P274）为发生于胎盘绒毛的良性肿瘤（C对）。无性细胞瘤（十版病理学P281）为发生于卵巢原始生殖细胞的恶性肿瘤（D错）。骨髓瘤（十版病理学P235）为起源于骨髓中浆细胞的恶性肿瘤（E错）。在历年西医综合真题中，良恶性肿瘤的鉴别反复出现，现将常考的良恶性肿瘤归纳如下——良性肿瘤：骨母细胞瘤、软骨母细胞瘤、脂肪母细胞瘤、肌母细胞瘤、葡萄胎（C对）、血管瘤、神经鞘瘤、纤维腺瘤、多形性腺瘤；恶性肿瘤：淋巴瘤、白血病（A错）、黑色素瘤、视网膜母细胞瘤、神经母细胞瘤（B错）、肾母细胞瘤、肝母细胞瘤、绒毛膜癌、无性细胞瘤（D错）、精原细胞瘤、骨髓瘤（E错）、尤文氏瘤。","","N"],["1995-N36",16,"第3节 伤寒","伤寒病理变化概述",1995,36,"A","","伤寒杆菌感染的特征性反应细胞是",[["A","中性粒细胞"],["B","嗜酸性粒细胞"],["C","单核细胞"],["D","多核巨细胞"],["E","淋巴细胞"]],"C","伤寒杆菌引起的炎症是以单核-巨噬细胞（C对）增生为特征的急性增生性炎。中性粒细胞（A错）为急性炎症的特征性反应细胞。嗜酸性粒细胞（B错）为寄生虫感染时的特征性反应细胞（十版病理学P362）。多核巨细胞（十版病理学P75）（D错）为慢性肉芽肿性炎症的特征性反应细胞。淋巴细胞（E错）为慢性炎症的特征性反应细胞（十版病理学P75）。","","N"],["1995-N37",3,"第2节 急性炎症","白细胞渗出",1995,37,"A","","下述关于急性炎症时白细胞渗出的描述中，哪项是错误的",[["A","在炎症反应中，中性粒细胞进入边流、附壁"],["B","内皮细胞收缩，使中性粒细胞从间隙游出血管"],["C","中性粒细胞通过伸出巨大伪足，逐渐从内皮细胞间隙游出血管"],["D","在趋化因子的作用下，中性粒细胞到达炎症部位"],["E","补体C3、C5是重要的炎性因子"]],"B","白细胞通过血管壁游出血管外的过程称为白细胞渗出。白细胞渗出是炎症反应最重要的特征，其过程包括：白细胞的边集和滚动、黏附和游出、在组织中游走等阶段（A对），并在补体C3、C5等炎性因子（趋化因子）（E对）的作用下到达炎症部位，在局部发挥重要的防御作用（D对）。白细胞穿过血管壁进入周围组织的过程称为白细胞游出，白细胞游出主要是由于炎性灶产生的化学趋化因子介导的，这些趋化因子作用于粘附于血管内皮的白细胞，刺激白细胞伸出巨大伪足，以阿米巴运动的主动方式，逐渐从内皮细胞间隙游出血管（C对），在这一过程中内皮细胞收缩并不起主导作用（B错，为本题正确答案）。","","N"],["1995-N38",9,"第6节 病毒性肝炎","纤维化",1995,38,"A","","下述哪项关于纤维素渗出的描述是错误的",[["A","可引起纤维组织机化"],["B","可发生在大叶性肺炎"],["C","可见于绒毛心"],["D","可见于细菌性痢疾"],["E","可见于病毒性肝炎"]],"E","纤维素性炎是以纤维蛋白原渗出为主的炎症，继而形成纤维蛋白，即纤维素。多由某些细菌毒素或毒物引起，易发生于黏膜、浆膜和肺组织。常见的纤维素性炎有：白喉、大叶性肺炎（B对）、绒毛心（C对）、细菌性痢疾（D对）等。少量纤维素可被吸收，如纤维素渗出过多时，可引起纤维素吸收不良，发生机化（A对）。病毒性肝炎通过免疫反应致病，属于以变质为主的炎症，无纤维素渗出（E错，为本题正确答案）。","","N"],["1995-N39",5,"第11节 环境致瘤因素","物理致瘤因素",1995,39,"A","","下述哪项关于放射性致癌的描述是错误的",[["A","组织损伤的程度与放射剂量有关"],["B","RNA是放射损伤的主要物质"],["C","细胞具有修复放射损伤的能力"],["D","放射性治疗史与癌发生有关"],["E","职业性放射暴露与癌发生有关"]],"B","放射性损伤的主要物质是DNA，而非RNA（B错，为本题正确答案）。正常人，这种DNA损伤通过核苷酸切除修复机制（九版生物化学P254）进行修复（C对），着色性干皮病患者由于先天缺乏修复DNA所需的酶，不能修复紫外线导致的DNA损伤，对日照敏感，在幼年即发生皮肤病。放射性损伤的组织损伤程度与放射剂量呈正相关。放射性治疗史（D对）、职业性放射暴露（E对）均可增加患癌几率。","","N"],["1995-N40",9,"第12节 消化系统常见肿瘤","概述",1995,40,"A","","下述有关食管癌的描述中，哪项是错误的",[["A","食管上段最常见"],["B","鳞状细胞癌多见"],["C","可见原位癌"],["D","亚硝胺与食管癌发生有关"],["E","可以多中心发生"]],"A","食管癌好发于三个生理性狭窄部，以中段最多见，其次为下段，上段最少见（A错，为本题正确答案）。食管癌的组织学类型中约95%以上为鳞状细胞癌（B对），腺癌次之。食物中的亚硝酸盐在消化道内可转变成亚硝胺，后者有强烈的致癌作用，与食管癌发生有关（D对）。早期食管癌多为原位癌（C对）或黏膜内癌，未侵犯肌层，无论是否存在局部淋巴结转移，可以多中心性发生（E对）。","","N"],["1995-N41",16,"第10节 寄生虫病","血吸虫病概述",1995,41,"A","","下述有关日本血吸虫病的描述中，哪项是错误的",[["A","急性虫卵结节可引起脓肿形成和积脓"],["B","虫卵随粪便排出体外"],["C","可引起肝硬化"],["D","钉螺是中间宿主"],["E","肺、脑可发生虫卵结节"]],"A","日本血吸虫病最主要的病变是虫卵沉着形成结节，虫卵主要沉着于乙状结肠、直肠和肝，也可见于肺和脑（E对）等处。虫卵沉着于肝时可引起窦前性肝硬化（C对）。虫卵结节周围有大量嗜酸性粒细胞浸润，称为嗜酸性脓肿，其状似脓肿但并非真正的脓肿（A错，为本题正确答案）。肠壁内的虫卵成熟后可破坏肠黏膜进入肠腔，并随粪便排出体外（B对）。排出的虫卵入水后，孵出毛蚴，毛蚴可进入中间宿主钉螺（D对）内发育成尾蚴。","","N"],["1995-N42",0,"第4节 细胞不可逆性损伤（细胞死亡）","液化性坏死",1995,42,"A","","液化性坏死常见于",[["A","脑"],["B","心脏"],["C","肾脏"],["D","脾脏"],["E","小肠"]],"A","由于酶的分解作用或蛋白质变性所占地位的不同，坏死组织会出现不同的形态学变化，通常分为凝固性坏死、液化性坏死和纤维素样坏死三个基本类型。此外，还有干酪样坏死、脂肪坏死和坏疽等一些特殊类型的坏死。液化性坏死常见于脑（A对）、脊髓、胰腺及乳房等组织。心脏（B错）、肾脏（C错）、脾脏（D错）等器官常发生凝固性坏死。小肠易发生湿性坏疽（E错）。","","N"],["1995-N43",10,"第2节 淋巴组织肿瘤","伯基特淋巴瘤概述",1995,43,"A","","下述哪个是B淋巴细胞来源的恶性淋巴瘤",[["A","多发性骨髓瘤"],["B","何杰金病"],["C","蕈样霉菌病"],["D","伯基特淋巴瘤"],["E","恶性组织细胞增生症"]],"D","多发性骨髓瘤（浆细胞骨髓瘤）（A对）、伯基特淋巴瘤（Burkitt淋巴瘤）（D对）均为B淋巴细胞来源的恶性淋巴瘤。何杰金病（现称霍奇金淋巴瘤）绝大多数是B细胞来源的，但也有少数是T细胞来源的（九版内科学 P584）（B错）。蕈样霉菌病（十版病理学P238）（C错）是一种T细胞来源的淋巴瘤。有文献称恶性组织细胞增生症（E错）的瘤细胞表达T淋巴细胞的标记，因此将该病列入T细胞淋巴瘤的范畴。本题答案应为AD，但参考答案仅为D。","","N"],["1995-N44",13,"第2节 甲状腺疾病","未分化癌",1995,44,"A","","下述哪种甲状腺癌的分化最差",[["A","乳头状腺癌"],["B","滤泡腺癌"],["C","巨细胞癌"],["D","嗜酸性细胞腺癌"],["E","髓样癌"]],"C","甲状腺癌可分为乳头状癌、滤泡癌、髓样癌和未分化癌四种类型，其中未分化癌又可分为小细胞型、梭型细胞型、巨细胞型和混合细胞型。以上各种类型中，乳头状癌（A错）分化最好，滤泡癌（B错）和髓样癌（E错）分化较好，未分化癌分化最差（C对）。嗜酸性细胞腺癌属于滤泡癌的特殊类型，分化较好（D错）。","","N"],["1995-N45",12,"第7节 乳腺疾病","非特殊型浸润性癌",1995,45,"A","","下述哪种乳腺癌最常见",[["A","浸润性小叶癌"],["B","浸润性导管癌"],["C","髓样癌"],["D","黏液癌"],["E","小管癌"]],"B","乳腺癌按照组织形态可分为非浸润性癌和浸润性癌两类。非浸润性癌包括导管内原位癌和小叶原位癌，浸润性癌包括浸润性导管癌（B）、浸润性小叶癌（A）和特殊类型癌，所有类型中最常见的是浸润性导管癌（B对）。髓样癌（C）、黏液癌（D）、小管癌（E）均属于特殊类型癌。","","N"],["1995-N103",0,"第4节 细胞不可逆性损伤（细胞死亡）","纤维素样坏死",1995,103,"B","","结节性多动脉炎",[["A","淀粉样变性"],["B","纤维素样变性"],["C","玻璃样变性"],["D","黏液变性"],["E","脂肪变性"]],"B","结节性多动脉炎是一种累及中、小动脉全层的坏死性血管炎，坏死的类型为纤维素样坏死，旧称纤维素样变性（B对）。而淀粉样变性（A错）、玻璃样变性（C错）、黏液变性（D错）和脂肪变性（E错）均为变性（可逆性损伤）的类型。","","N"],["1995-N104",0,"第3节 细胞可逆性损伤","脂肪变的病理变化",1995,104,"B","","四氯化碳中毒",[["A","淀粉样变性"],["B","纤维素样变性"],["C","玻璃样变性"],["D","黏液变性"],["E","脂肪变性"]],"E","四氯化碳中毒影响脂蛋白合成，使细胞输出脂肪受阻，而发生脂肪变性（E对）。","","N"],["1995-N125",8,"第1节 呼吸道和肺炎症性疾病","大叶性肺炎的病理变化及临床病理联系",1995,125,"C","","大叶性肺炎",[["A","肺泡炎"],["B","细支气管炎"],["C","两者皆有"],["D","两者皆无"]],"A","大叶性肺炎是主要由肺炎球菌引起的以肺泡（A对）内弥漫性纤维素渗出为主的炎症，一般不累及支气管（B错），即使偶尔累及，其炎症病变一般很轻微，炎症消退后，一般不留痕迹。","","N"],["1995-N126",2,"第1节 充血和淤血","肺淤血",1995,126,"C","","肺淤血",[["A","肺泡炎"],["B","细支气管炎"],["C","两者皆有"],["D","两者皆无"]],"D","肺淤血多由左心衰引起，由于左心腔内压力升高，阻碍肺静脉回流，造成肺淤血。肺淤血时肺泡间隔增宽、毛细血管扩张充盈，肺泡内可有蛋白性液体、红细胞漏出，并可出现心力衰竭细胞，但这些都是“淤血”的表现，不是“炎症”的表现（D对）。","","N"],["1995-N127",0,"第4节 细胞不可逆性损伤（细胞死亡）","凝固性坏死",1995,127,"C","","病毒性肝炎",[["A","凝固性坏死"],["B","液化性坏死"],["C","两者皆有"],["D","两者皆无"]],"C","病毒性肝炎最常见的病变为细胞水肿，严重的细胞水肿可发展为溶解性坏死（十版病理学P203），溶解性坏死即属于液化性坏死（B对）。肝属于实质器官，病毒性肝炎也可出现凝固性坏死（A对）。本题AB均对，正确答案为C。","","N"],["1995-N128",0,"第4节 细胞不可逆性损伤（细胞死亡）","凝固性坏死",1995,128,"C","","脾梗死",[["A","凝固性坏死"],["B","液化性坏死"],["C","两者皆有"],["D","两者皆无"]],"A","蛋白质变性凝固且溶酶体酶水解作用较弱时，坏死区呈灰黄、干燥、质实状态，称为凝固性坏死，多见于心、肝、肾和脾（A对）等实质器官。由于坏死组织中可凝固的蛋白质少，或坏死细胞自身及浸润的中性粒细胞等释放大量水解酶，或组织富含水分和磷脂，则细胞组织坏死后易发生溶解液化，称为液化性坏死，多见于脑、脊髓、胰腺及乳房等处（B错）。","","N"],["1995-N147",3,"第1节 炎症概述","渗出",1995,147,"X","","渗出液的特点是",[["A","蛋白含量高"],["B","比重低"],["C","细胞成分多"],["D","液体清亮"]],"AC","炎症反应时，炎症局部组织血管内的液体、纤维素等蛋白质和各种炎细胞通过血管壁渗出，所渗出的成分即为渗出液。渗出液需要与漏出液进行区分，后者一般因血液循环障碍引起，为非炎性液体。渗出液与漏出液相比，其蛋白含量高（A对），细胞成分多（C对），液体比重高（B错），外观浑浊（D错），易自凝。","","N"],["1995-N148",9,"第3节 消化性溃疡病","穿孔",1995,148,"X","","下列哪些疾病可合并穿孔",[["A","伤寒"],["B","胃癌"],["C","细菌性痢疾"],["D","十二指肠溃疡"]],"ABD","细菌性痢疾形成的溃疡为大小不等、形状不一的地图状溃疡，溃疡较浅，肠穿孔少见（C错）。肠伤寒溃疡一般深及黏膜下层，坏死严重者可深达肌层及浆膜层，甚至穿孔（A对）。胃癌形成的恶性溃疡也可引起胃穿孔（八版内科学P377）（B对）。十二指肠溃疡因肠壁较薄易发生穿孔（D对），胃肠内容物漏入腹腔可引起腹膜炎。","","N"],["1995-N149",2,"第1节 充血和淤血","肝淤血",1995,149,"X","","慢性肝淤血可见的病理变化有",[["A","肝细胞萎缩变性"],["B","肝细胞内淤胆"],["C","肝脏纤维组织增生"],["D","细胞异型增生"]],"AC","慢性肝淤血时，肝细胞缺氧，以小叶中央区为甚，严重时发生萎缩（A对），甚至坏死消失。肝细胞坏死消失后，肝内网状纤维塌陷并胶原化，肝窦旁的贮脂细胞增生，合成胶原纤维增多，加上汇管区纤维结缔组织的增生，致使整个肝脏的间质纤维组织增多（C对），形成淤血性肝硬化。肝细胞内淤胆的原因很多，包括病毒性肝炎或其他肝炎、药物中毒性、酒精性肝病等，但不包括慢性肝淤血（B错）。枯否氏细胞（Kupffer细胞）为位于肝血窦内的巨噬细胞，是肝脏防御系统的主要成员，异型增生为癌前病变，慢性肝淤血时不可见（D错）。","","N"],["1995-N150",14,"第3节 中枢神经系统感染性疾病","脑膜炎症期",1995,150,"X","","流脑的病理变化有",[["A","筛状软化灶"],["B","血管周围淋巴细胞套状浸润"],["C","蛛网膜下腔大量炎细胞渗出"],["D","脑底部病变最显著"]],"C","流脑是脑膜炎双球菌感染所致的化脓性炎症，其病理变化有：镜下可见蛛网膜下腔增宽，大量炎细胞渗出（C对）。流脑病变主要侵及软脑膜、蛛网膜和脑脊液，呈弥漫分布，无显著部位差异（D错）。筛状软化灶（A 错）和血管周围淋巴细胞套状浸润（B 错）均为流行性乙型脑炎的病理变化（十版病理学P312）。","","N"],["1996-N33",9,"第2节 胃炎","慢性萎缩性胃炎",1996,33,"A","","慢性萎缩性胃炎最具特征的病理变化是",[["A","黏膜变薄、腺体减少"],["B","假幽门腺化生"],["C","肠上皮化生"],["D","腺体异型增生"],["E","胃酸减少"]],"A","慢性萎缩性胃炎以胃黏膜萎缩变薄，黏膜腺体减少或消失并伴有肠上皮化生，固有层内多量淋巴细胞、浆细胞浸润为特点，其中胃黏膜萎缩变薄，黏膜腺体减少或消失（A对）为慢性萎缩性胃炎最具特征的病理变化，而肠上皮化生为伴随变化，也可出现在胃溃疡等其他疾病，不具有特征性（C错）。假幽门腺化生为胃体部或胃底部的腺体壁细胞和主细胞消失，被类似幽门腺的黏液分泌细胞所取代，为腺上皮化生的一种，较少见，是慢性萎缩性胃炎的病理变化，但也可在胃溃疡中出现，不具有特征性（B错）。当慢性胃炎进一步发展，胃上皮或化生的肠上皮再生过程中，可发生腺体异型增生，此为胃癌的癌前病变（D错）。胃酸减少是由于腺体萎缩、壁细胞和主细胞减少所导致的，可见于胃炎、胃溃疡、胃癌等各种疾病，不具有特征性（E错）。","","N"],["1996-N34",11,"第2节 肾小管间质性肾炎","慢性肾盂肾炎病理变化",1996,34,"A","","慢性肾盂肾炎的描述中，哪项是正确的",[["A","双肾弥漫受累"],["B","间质化脓性炎"],["C","肾周围组织不受累"],["D","不引起肾功能不全"],["E","血源性感染占多数"]],"B","慢性肾盂肾炎是一种慢性间质化脓性炎（B对）。双肾弥漫受累（A错）是慢性肾小球肾炎的病理特征，而慢性肾盂肾炎的特征是病变为一侧或双侧肾脏体积缩小，出现不规则瘢痕。慢性肾盂肾炎常累及肾小管、肾间质等，严重时可累及肾周围组织（C错）。慢性肾盂肾炎发展到晚期，肾组织破坏严重，可出现氮质血症和尿毒症等肾功能不全的表现（D错）。肾盂肾炎多由细菌感染引起，包括下行性（血源性）感染和上行性感染两条途径，其中上行性感染占多数（E错）。","","N"],["1996-N35",9,"第12节 消化系统常见肿瘤","结直肠癌的分期与预后",1996,35,"A","","在我国大肠癌的病理分期中，哪一期是指侵入深肌层，未穿出肌层的大肠癌",[["A","A₁"],["B","A₂"],["C","A₃"],["D","B"],["E","C"]],"C","本题年份较早，参照旧版病理学课本可知，我国大肠癌协作组曾将大肠癌A期分为局限于黏膜下层（A₁）、浅肌层（A₂）和深肌层（A₃）三类，可见侵入深肌层，但未穿出肌层的大肠癌为A₃期（C对）。在十版病理学的最新分期中，侵入肌层（不区分浅肌层和深肌层），但未穿出肌层的大肠癌为B₁期或C₁期。","","N"],["1996-N36",0,"第4节 细胞不可逆性损伤（细胞死亡）","机化与包裹",1996,36,"A","","下述哪种病理过程叫机化",[["A","坏死灶周围钙盐沉积"],["B","死骨周围纤维增生"],["C","坏死物排出空腔形成"],["D","坏死灶由肉芽组织取代"],["E","坏死缺损由周围组织修补"]],"D","坏死的结局有溶解吸收、分离排出、机化与包裹、钙化等。小的坏死灶可被溶解吸收；位于体表和与外界相通脏器的较大的坏死灶可分离排出体内，形成的组织缺损按发生的部位、深浅分为糜烂、溃疡、窦道、瘘管和空腔（C错）。既不能溶解吸收，又不能分离排出则由肉芽组织长入坏死区，代替坏死组织而发生机化（D对）。如果坏死组织太大，肉芽组织难以向中心部完全长入，则由周围增生的肉芽组织将其包围称为包裹。坏死组织和细胞碎片若未被及时吸收清除，则日后易吸引钙盐（A错）和其他矿物质沉积，引起营养不良性钙化。","","N"],["1996-N37",1,"第1节 再生","软骨组织和骨组织的再生",1996,37,"A","","下述描述中，哪种属于完全再生",[["A","动脉吻合口愈合"],["B","骨折愈合再建"],["C","剖腹手术切口愈合"],["D","肠吻合口愈合"],["E","胃溃疡愈合"]],"B","组织的损伤修复的过程可以概括为两种不同的形式：①由损伤周围的同种细胞来修复，称为再生，如果完全恢复原组织的结构及功能，则称为完全再生；②由纤维结缔组织来修复，称为纤维性修复，以后形成瘢痕，故也称瘢痕修复。骨组织（细胞）属于稳定细胞，但再生能力较强，骨折经过良好复位后，几个月内便可完全愈合，恢复正常结构和功能，为完全再生（B对）。平滑肌细胞也属于稳定细胞，但再生能力较弱，受损时一般会出现瘢痕修复，故动脉（血管平滑肌）吻合口愈合（A错）、肠（消化道平滑肌）吻合口愈合（D错）、胃（消化道平滑肌）溃疡愈合（E错）均不属于完全再生。剖腹手术伤口处皮肤的愈合过程中有肉芽组织生成，形成瘢痕修复，故剖腹手术切口愈合不属于完全再生（C错）。","","N"],["1996-N38",2,"第3节 血栓形成","血栓形成对机体的影响",1996,38,"A","","下述有关血栓的描述中，哪项是错误的",[["A","纤维素血栓易溶解吸收"],["B","可形成静脉石"],["C","再通可恢复正常循环"],["D","可阻塞动脉、静脉"],["E","可继发于血管炎"]],"C","纤维素血栓又称透明血栓或微血栓，主要发生在DIC的微循环内，由于血栓微小，易被溶解吸收（A对）。血栓较大，未能软化又未完全机化时，可发生钙盐沉着，形成静脉石（B对）。再通时只能使被阻塞的血管部分地重建血流，并不能恢复正常循环（C错，为本题正确答案）。血栓对机体的重要影响之一就是阻塞动脉或静脉血管，形成动脉血栓或静脉血栓（D对）。血管炎时血管内皮细胞受损，容易继发血栓形成（E对）。","","N"],["1996-N39",3,"第2节 急性炎症","吞噬作用",1996,39,"A","","下述哪种物质与吞噬细胞对细菌的杀伤降解无直接关系",[["A","阳离子蛋白"],["B","乳铁蛋白"],["C","髓过氧化物酶"],["D","酸性水解酶"],["E","调理素"]],"E","调理素是指一类通过包裹微生物而增强吞噬细胞吞噬功能的血清蛋白质，调理素包裹微生物而增强吞噬作用的过程称为调理素化，可明显提高白细胞的吞噬作用，但对吞噬细胞对细菌的杀伤降解不起直接作用（E对）。吞噬细胞包括中性粒细胞和巨噬细胞。其中，中性粒细胞胞质内含有嗜天青颗粒和特异性颗粒：嗜天青颗粒含有酸性水解酶（D错）、中性蛋白酶、髓过氧化物酶（C错）、阳离子蛋白（A错）、溶菌酶和磷脂酶A₂，特异性颗粒含溶菌酶、磷脂酶A₂、乳铁蛋白（B错）及碱性磷酸酶等。这些蛋白或酶类均直接参与了吞噬细胞对细菌的杀伤降解作用。","","N"],["1996-N40",5,"第10节 肿瘤的分子基础","获得侵袭和转移能力",1996,40,"A","","下述哪项是恶性肿瘤最具特征的变化",[["A","出血坏死"],["B","浸润"],["C","转移"],["D","细胞多形性"],["E","生长迅速"]],"C","出血坏死（A）、浸润（B）、转移（C）、细胞多形性（D）、生长迅速（E）等都是恶性肿瘤的特点，但转移是最具特征性的改变（C对）。","","N"],["1996-N41",7,"第2节 高血压病","脑病变",1996,41,"A","","下述有关高血压脑病变的描述中，哪项是不正确的",[["A","脑内可有小软化灶形成"],["B","脑内可有微小动脉瘤形成"],["C","脑出血是常见的致死原因"],["D","基底节、内囊是出血的常见部位"],["E","脑动脉栓塞多见"]],"E","高血压时，脑细小动脉硬化，使脑组织缺血坏死，形成小软化灶（A对）。严重病例细小动脉壁可发生纤维素样坏死，并发血栓形成和微动脉瘤（B对）。脑出血是高血压最严重的并发症，也是常见的致死原因（C对），常发生于基底节、内囊（D对），其次为大脑白质、脑桥和小脑。脑动脉栓塞（体循环栓塞）的栓子多来源于左心室（十版病理学P50），常见于亚急性感染性心内膜炎（心瓣膜上的赘生物）、二尖瓣狭窄（左心房附壁血栓）、心肌梗死（心内膜附壁血栓）等疾病（E错，为本题正确答案）。","","N"],["1996-N42",7,"第1节 动脉粥样硬化","动脉粥样硬化的危险因素",1996,42,"A","","下述哪项不属于动脉粥样硬化症的危险因素",[["A","高胆固醇血症"],["B","甲状腺功能亢进"],["C","糖尿病"],["D","吸烟"],["E","高血压病"]],"B","低密度脂蛋白（LDL）是引起动脉粥样硬化（AS）的主要因素，与极低密度脂蛋白（VLDL）共同称为致AS性的脂蛋白，而高密度脂蛋白（HDL）对AS则有预防作用。胆固醇血症时LDL水平升高（LDL是血液中胆固醇的主要载体），促进AS的发生（A对）。甲状腺功能亢进时血胆固醇含量低于正常（九版生理学P378），LDL水平降低，降低了发生动脉粥样硬化症的风险（B错，为本题正确答案）。糖尿病患者血中甘油三酯（TG）及极低密度脂蛋白（VLDL）水平明显升高，高密度脂蛋白（HDL）水平降低，而且高血糖可使LDL氧化，促进血液单核细胞迁入内膜及转化为泡沫细胞，促进AS的发生（C对）。吸烟可使LDL易于氧化，ox-LDL可促进血液单核细胞迁入内膜并转化为泡沫细胞，促使AS发生（D对）。高血压时血流对血管壁的机械性压力和冲击引起血管内皮损伤，使内膜对脂质的通透性增加，脂质因渗入内膜，可促进AS发生（E对）。","","N"],["1996-N43",7,"第7节 心肌病","克山病",1996,43,"A","","下述哪种疾病属于原发性心肌病",[["A","克山病"],["B","冠心病"],["C","孤立性心肌炎"],["D","风湿性心脏病"],["E","高血压性心脏病"]],"A","广义上的心肌病包括原发性心肌病和继发性心肌病两种（狭义上的心肌病仅指原发性心肌病），原发性心肌病为发病原因不明的代谢性心肌病变，如扩张性心肌病、肥厚性心肌病、限制性心肌病等，继发性心肌病又称“特异性心肌病”，指继发于冠心病（B错）、高血压性心脏病（E错）、甲状腺机能亢进、风湿性心脏病（D错）等明确发病原因的心肌改变。七版及更早版本的病理学教材将克山病也列入了原发性心肌病的分类，故本题给出的参考答案为A。从八版病理学教材开始，已明确表明克山病被列入特异性心肌病即继发性心肌病的分类，按照最新病理学教材的说法，本题已无正确答案。另：孤立性心肌炎属于心肌炎，不属于心肌病（C错）。","","N"],["1996-N44",8,"第5节 肺尘埃沉着病","肺硅沉着病的病因及发病机制",1996,44,"A","","下述哪项有关肺疾病的描述是正确的",[["A","硅肺主要由小于5μm的硅尘颗粒引起"],["B","支原体主要引起小叶性肺炎"],["C","α₁-抗胰蛋白酶缺乏是肺气肿的常见原因"],["D","支气管腔扩大称为支气管扩张症"],["E","支气管肺炎常作为独立疾病发生"]],"A","硅尘颗粒的大小是硅肺致病的一个决定因素，一般认为硅尘颗粒＞5µm者经过上呼吸道时易附着于黏膜表面，大多被黏液-纤毛排送系统清除出体外；而＜5µm（A对）者则可被吸入肺内直达肺泡并被聚集于肺泡间隔或支气管周围的巨噬细胞吞噬，形成早期硅肺的细胞性结节。支原体主要引起间质性肺炎，小叶性肺炎主要由化脓性细菌引起（B错）。（先天性）α₁-抗胰蛋白酶缺乏是肺气肿的原因之一（引起全腺泡型肺气肿），但不是常见原因（C错）。支气管扩张是指小支气管管腔持久性扩张，并伴管壁纤维增厚的慢性呼吸道疾病，两者缺一不可（D错）。支气管肺炎即小叶性肺炎，一般不作为独立疾病发生，多为某些疾病的并发症（E错）。","","N"],["1996-N45",16,"第2节 结核病","肺结核病概述",1996,45,"A","","下述有关肺结核的描述，哪项是错误的",[["A","结核病是一种慢性传染病"],["B","结核病属Ⅲ型变态反应"],["C","肺外器官结核病多由血源播散引起"],["D","钙化的干酪坏死灶内仍有结核杆菌"],["E","肺空洞性结核病属开放性结核病"]],"B","结核病是由结核分枝杆菌感染引起的慢性传染病（A对），属于Ⅳ型变态反应（B错，为本题正确答案）。肺外器官结核病是指发生在肺部以外各部位的结核病，通常由肺部病变经血源播散引起（C对），如肠结核、结核性腹膜炎、结核性脑膜炎等。钙化的干酪坏死灶内仍有少量结核杆菌残留（D对），此表现在临床虽然定义为痊愈，但当机体抵抗力降低时仍可复发。肺空洞性（慢性纤维空洞性）结核病又称开放性肺结核（十版病理学P346）（E对），此型的病变空洞与支气管相通，成为结核病的传染源。","","N"],["1996-N46",11,"第1节 肾小球疾病","微小病变性肾小球病病理变化",1996,46,"A","","轻微病变性肾小球肾炎的主要病理变化是",[["A","肾小球毛细血管壁增厚"],["B","脏层上皮细胞足突消失"],["C","系膜细胞及基质增生"],["D","壁层上皮细胞增生"],["E","内皮细胞增生"]],"B","轻微病变性肾小球肾炎的主要病理变化是脏层上皮细胞足突消失（B对）。肾小球毛细血管壁增厚（A错）是膜性肾小球病的主要病理变化（十版病理学P256）。系膜细胞及基质增生（C错）是系膜增生性肾炎的主要病理变化（十版病理学P258）。壁层上皮细胞增生（D错）是急进性（新月体性）肾小球肾炎的主要病理变化（十版病理学P255）。内皮细胞增生（E错）是急性肾炎的主要病理变化（十版病理学P254）。","","N"],["1996-N101",2,"第4节 栓塞","脂肪栓塞",1996,101,"B","","股骨干骨折",[["A","血栓栓塞"],["B","脂肪栓塞"],["C","空气栓塞"],["D","羊水栓塞"],["E","肿瘤栓塞"]],"B","股骨干骨折时，骨髓内脂肪细胞破裂并释出脂滴，脂滴由破裂的骨髓血管窦状隙进入血液循环引起脂肪栓塞（B对）。","","N"],["1996-N102",2,"第4节 栓塞","减压病",1996,102,"B","","沉箱病",[["A","血栓栓塞"],["B","脂肪栓塞"],["C","氮气栓塞"],["D","羊水栓塞"],["E","肿瘤栓塞"]],"C","根据十版病理学P52的分类，气体栓塞包括空气栓塞和减压病两种。空气栓塞指因静脉破裂导致大量空气（含氮气、氧气、二氧化碳等）进入血液循环形成的气体阻塞；而减压病即沉箱病，指人从高气压环境急速转到低气压环境的减压过程中，原来溶于血液、组织的气体，包括氮气、氧气、二氧化碳等游离形成气泡，氧气和二氧化碳可再溶于体液被吸收，但氮气在体液内溶解迟缓，而形成的气体栓塞，故沉箱病为氮气栓塞（C对）。","","N"],["1996-N103",4,"","",1996,103,"B","","慢性肉芽肿病",[["A","调理素缺乏"],["B","脱颗粒障碍"],["C","H₂O₂产生障碍"],["D","B淋巴细胞缺陷"],["E","T淋巴细胞缺陷"]],"C","慢性肉芽肿病是一种致死性遗传性粒细胞功能缺陷病，由于粒细胞内的过氧化氢（H₂O₂）产生障碍（C对），导致其杀菌力缺陷而致病。","","N"],["1996-N104",4,"第2节 免疫缺陷病","原发性免疫缺陷病",1996,104,"B","","DiGeorge综合征",[["A","调理素缺乏"],["B","脱颗粒障碍"],["C","H₂O₂产生障碍"],["D","B淋巴细胞缺陷"],["E","T淋巴细胞缺陷"]],"E","DiGeorge综合征即先天性胸腺发育不良综合征，是一种以T淋巴细胞缺陷（E对）为主的原发性免疫缺陷病。患者胚胎期第三、第四咽囊发育障碍，导致胸腺（T细胞的成熟部位）缺如或发育不全，使外周血成熟T细胞数量显著减少。","","N"],["1996-N125",8,"第8节 呼吸系统常见肿瘤","神经内分泌癌",1996,125,"C","","肺小细胞癌",[["A","内分泌紊乱"],["B","浸润转移"],["C","两者皆有"],["D","两者皆无"]],"C","小细胞癌又称小细胞神经内分泌癌，为肺癌中恶性程度最高的一型，向肺实质浸润生长，生长迅速，转移早（B对）。其可分泌5-羟色胺而引起内分泌紊乱（类癌综合征）（十版病理学P192），导致支气管痉挛、阵发性心动过速、水样腹泻和皮肤潮红等（A对）。本题AB均对，正确答案为C。","","N"],["1996-N126",13,"第2节 甲状腺疾病","髓样癌",1996,126,"C","","甲状腺髓样癌",[["A","内分泌紊乱"],["B","浸润转移"],["C","两者皆有"],["D","两者皆无"]],"C","甲状腺髓样癌是由滤泡旁降钙素分泌细胞（C细胞）发生的恶性肿瘤，属于APUD瘤，90%的甲状腺髓样癌会分泌降钙素，产生严重腹泻和低钙血症，有的还同时分泌其他多种激素和物质，可导致内分泌紊乱（A对）。甲状腺髓样癌中度恶性，可发生浸润转移（B对）。本题AB均对，正确答案为C。","","N"],["1996-N131",11,"第1节 肾小球疾病","微小病变性肾小球病病理变化",1996,131,"C","","微小病变型肾病患者",[["A","肾小球毛细血管基膜网孔加大"],["B","肾小球毛细血管基膜负电荷减少"],["C","两者均有"],["D","两者均无"]],"B","肾小球滤过膜的结构主要有三层：毛细血管内皮细胞、肾小球基膜和肾小球脏层上皮细胞。肾小球滤过膜的屏障包括机械屏障和电荷屏障，其中，机械屏障主要由滤过膜结构的滤孔大小来决定，由于内皮细胞窗孔>肾小球脏层上皮细胞间隙>肾小球基膜网孔，基膜的网孔孔径最小，在机械屏障中起主要作用。电荷屏障是指滤过膜各层均含有许多带负电荷的物质，而血浆蛋白也带负电荷，电荷排斥原理可以阻止血浆蛋白进入到尿液中。微小病变型肾病患者的肾小球脏层上皮细胞损伤，足突消失，但基膜正常，因此，肾小球毛细血管基膜网孔孔径无变化（A错）。基膜的成分主要由脏层上皮细胞合成（八版病理学P259），脏层上皮细胞损伤，基膜合成减少，基膜负电荷亦减少（B对）。","","N"],["1996-N132",11,"第2节 肾小管间质性肾炎","肾盂肾炎类型概述",1996,132,"C","","肾盂肾炎",[["A","肾小球毛细血管基膜筛孔加大"],["B","肾小球毛细血管基膜负电荷减少"],["C","两者均有"],["D","两者均无"]],"D","肾盂肾炎主要侵犯肾盂、肾间质以及肾小管，一般不累及肾小球，而毛细血管基膜筛孔大小及基膜负电荷多少均与肾小球滤过屏障有关，因此，肾盂肾炎既无毛细血管基膜孔筛加大（A错），也无基膜负电荷减少（B错）。本题AB均错，正确答案为D。","","N"],["1996-N147",3,"第2节 急性炎症","纤维蛋白性炎",1996,147,"X","","下列哪些疾病属纤维素性炎",[["A","风湿性关节炎"],["B","流行性脑膜炎"],["C","大叶性肺炎"],["D","细菌性痢疾"]],"CD","根据炎症的基本病变性质进行分类，可分为变质性炎、渗出性炎和增生性炎。任何炎症都在一定程度上包含变质、渗出、增生这三种基本病变，但往往以一种病变为主，以变质为主时称为变质性炎，以渗出为主时称为渗出性炎，以增生为主时称为增生性炎。渗出性炎还可以根据渗出物的主要成分和病变特点，进一步分为浆液性炎、纤维素性炎、化脓性炎、出血性炎等。纤维素性炎是以渗出物中含有大量纤维蛋白（纤维素）为特征的炎症，易发生于黏膜、浆膜和肺组织，常见的纤维素性炎有大叶性肺炎（C对）、细菌性痢疾（D对）、白喉、风湿性心包炎等。风湿性关节炎主要为浆液性炎（虽然也有纤维蛋白渗出）（A错）。流行性脑膜炎为化脓性炎（B错）。","","N"],["1996-N148",1,"第2节 纤维性修复","肉芽组织的作用及结局",1996,148,"X","","肉芽组织具有如下功能",[["A","机化"],["B","修复"],["C","吞噬搬运"],["D","抗感染"]],"ABD","肉芽组织在组织损伤修复的过程中有重要的作用。肉芽组织可以修复（B对）组织的缺损，其包含的巨噬细胞、中性粒细胞等炎症细胞能够吞噬搬运（C对）细菌和组织碎片，发挥有抗感染（D对）保护创面的作用。肉芽组织的形成过程即为机化（A对）。本题的正确答案应为ABCD，但给出的参考答案仅为ABD。","","N"],["1996-N149",7,"第1节 动脉粥样硬化","继发性病变",1996,149,"X","","动脉粥样硬化斑块可发生",[["A","出血"],["B","溃疡"],["C","血栓形成"],["D","动脉瘤"]],"ABCD","出血、溃疡、血栓形成和动脉瘤均为动脉粥样硬化斑块基础上继发的病变。斑块内新生的血管破裂导致出血（A对）。斑块表面的纤维帽破裂遗留粥瘤样溃疡（B对）。溃疡形成后，胶原暴露，促进血栓形成（C对）。严重的粥样斑块底部的中膜平滑肌可发生不同程度的萎缩和弹性下降，在血管内压力的作用下，动脉壁局限性扩张，形成动脉瘤（D对）。","","N"],["1996-N150",9,"第8节 肝硬化","镜下",1996,150,"X","","肝硬化的病理组织学变化有",[["A","假小叶形成"],["B","纤维组织增生"],["C","肝细胞弥漫大片坏死"],["D","淋巴细胞浸润"]],"ABD","肝硬化时，纤维组织增生（B对），分割原来的肝小叶并包绕成大小不等的圆形或类圆形的肝细胞团，形成假小叶（A对）。包绕假小叶的纤维间隔内可有少量淋巴细胞（D对）和单核细胞浸润。肝细胞弥漫性大片坏死为急性重型肝炎的病理学特点（C错）。","","N"],["1997-N33",0,"第4节 细胞不可逆性损伤（细胞死亡）","坏疽",1997,33,"A","","下列哪个脏器不发生坏疽",[["A","肺"],["B","下肢"],["C","阑尾"],["D","小肠"],["E","脑"]],"E","坏疽是指局部组织大块坏死并继发腐败菌感染的坏死类型，分为干性、湿性和气性等类型：干性坏疽常见于动脉阻塞但静脉回流尚畅通的四肢末端（B错）；湿性坏疽见于与外界相通的内脏，如肺（A错）、肠（D错）、子宫、阑尾（C错）及胆囊等，也可发生于动脉阻塞及静脉回流受阻的四肢（B错）；气性坏疽常见于深达肌肉的开放性创伤。脑组织多发生液化性坏死，而不发生坏疽（E对）。","","N"],["1997-N34",2,"第3节 血栓形成","混合血栓",1997,34,"A","","混合性血栓可见于",[["A","静脉内柱状血栓的尾部"],["B","毛细血管内血栓"],["C","急性风湿性心内膜炎的疣状血栓"],["D","动脉血栓头部"],["E","心室内附壁血栓"]],"E","血栓类型可分为四种：白色血栓、混合血栓、红色血栓和透明血栓。静脉内柱状血栓头部为白色血栓，体部为混合血栓，尾部为红色血栓（A错）。毛细血管内血栓为透明血栓（B错）。急性风湿性心内膜炎的疣状血栓为白色血栓（C错）。动脉血栓整体（包括头部）均为白色血栓（D错）。心室内附壁血栓为混合血栓（E对）。","","N"],["1997-N35",3,"第2节 急性炎症","蜂窝织炎",1997,35,"A","","在急性蜂窝织炎组织中，浸润的炎细胞是",[["A","浆细胞"],["B","淋巴细胞"],["C","嗜酸性粒细胞"],["D","中性粒细胞"],["E","巨噬细胞"]],"D","急性蜂窝织炎为化脓性炎症，表现为炎症病变组织内大量中性粒细胞（D对）弥漫性浸润。","","N"],["1997-N36",3,"第2节 急性炎症","炎症介质在炎症过程中的作用",1997,36,"A","","关于炎症介质的描述，哪项是不正确的",[["A","凝血系统在炎症中具有重要功能"],["B","C3、C5是重要的炎症介质"],["C","缓激肽可使血管通透性增加"],["D","花生四烯酸代谢产物可导致发热、疼痛"],["E","组胺具有阳性趋化作用"]],"E","炎症的血管反应和白细胞反应都是通过一系列化学因子的作用实现的。参与和介导炎症反应的化学因子称为化学介质或炎症介质。炎症介质可来自细胞和血浆。①血浆中存在着三种相互关联的系统，即激肽系统、补体系统（C3、C5均为补体成分）（B对）、凝血系统/纤维蛋白溶解系统（A对），是重要的炎症介质。缓激肽可使细动脉扩张、血管通透性增加、支气管平滑肌收缩，并可引起疼痛（C对）。②细胞释放的炎症介质有：血管活性胺、花生四烯酸代谢产物、血小板激活因子、细胞因子、活性氧和一氧化氮、白细胞溶酶体酶、神经肽等。花生四烯酸代谢产物前列腺素可引起发热和疼痛（D对）。血管活性胺中的组胺可使细动脉扩张和细静脉通透性增加，但不具有趋化作用（E错，为本题正确答案）。","","N"],["1997-N37",7,"第2节 高血压病","肾脏病变",1997,37,"A","","在下列描述中，哪一项不符合高血压的病理变化",[["A","细小动脉硬化"],["B","左心室肥大"],["C","肾脏大瘢痕性萎缩"],["D","脑出血"],["E","视乳头水肿、出血"]],"C","良性高血压按病变的发展分为三期：1.功能紊乱期：此期为高血压的早期阶段。全身细小动脉间歇性痉挛收缩、血压升高，因动脉无器质性病变，痉挛缓解后血压可恢复正常。2.动脉病变期：细小动脉硬化（A对），是高血压病的主要病变特征，表现为细小动脉玻璃样变。3.内脏病变期：①心脏病变：主要为左心室肥大（B对），是对持续性血压升高，心肌工作负荷增加的一种适应性反应；②肾脏病变：肉眼观，双侧肾脏对称性缩小，质地变硬，肾表面凹凸不平，呈细颗粒状，称原发性颗粒性固缩肾（而肾脏大瘢痕性萎缩是由动脉粥样硬化肾动脉粥样硬化引起，称为AS性固缩肾）（C错，为本题正确答案）；③脑病变：包括脑水肿或高血压脑病、脑软化、脑出血（D对）等；⑷视网膜病变：视网膜中央动脉发生细动脉硬化，严重者视盘（视乳头）水肿，视网膜出血（E对），视力减退。","","N"],["1997-N38",9,"第6节 病毒性肝炎","亚急性重型肝炎的病理变化",1997,38,"A","","最常引起肝硬化的肝炎类型是",[["A","急性重型肝炎和慢性活动性肝炎"],["B","急性重型肝炎和亚急性重型肝炎"],["C","亚急性重型肝炎和慢性活动性肝炎"],["D","亚急性重型肝炎和慢性持续性肝炎"],["E","慢性活动性肝炎和慢性持续性肝炎"]],"C","亚急性重型肝炎肝细胞坏死后有肝细胞结节状再生，形成假小叶，多数病例常继续发展而转变为坏死后性肝硬化。慢性活动性肝炎（旧版教材将慢性肝炎分为慢性迁延性肝炎和慢性活动性肝炎两型，（八版病理学P198）将慢性肝炎分为轻度、中度、重度三型，慢性活动性肝炎中、重度慢性肝炎）桥接性坏死时有肝细胞结节状再生，可形成假小叶，晚期逐渐转变为肝硬化。故本题正确答案为C。","","N"],["1997-N39",5,"第3节 肿瘤的命名与分类","肿瘤的分类",1997,39,"A","","下列哪种肿瘤是恶性肿瘤",[["A","畸胎瘤"],["B","错构瘤"],["C","精原细胞瘤"],["D","多形性腺瘤"],["E","纤维腺瘤"]],"C","畸胎瘤有良性畸胎瘤和恶性畸胎瘤之分，因此，畸胎瘤本身不代表良性或恶性（A错）。错构瘤是由与所在器官相同的组织构成，但结构紊乱比例失常而形成的包块，不属于肿瘤（B错）。精原细胞瘤（十版病理学P281）为发生于睾丸原始生殖细胞的恶性肿瘤（C对）。多形性腺瘤又称腮腺混合瘤，是一种含有腮腺组织、黏液和软骨样组织的良性肿瘤（D错）。纤维腺瘤为多发于乳腺（十版病理学P285）的由上皮和间叶组织构成的良性肿瘤（E错）。在历年西医综合真题中，良恶性肿瘤的鉴别反复出现，现将常考的良恶性肿瘤归纳如下——良性肿瘤：骨母细胞瘤、软骨母细胞瘤、脂肪母细胞瘤、肌母细胞瘤、葡萄胎、血管瘤、神经鞘瘤、纤维腺瘤（E错）、多形性腺瘤（D错）；恶性肿瘤：淋巴瘤、白血病、黑色素瘤、视网膜母细胞瘤、神经母细胞瘤、肾母细胞瘤、肝母细胞瘤、绒毛膜癌、无性细胞瘤、精原细胞瘤（C对）、骨髓瘤、尤文氏瘤。","","N"],["1997-N40",5,"第8节 常见肿瘤举例","腺癌",1997,40,"A","","诊断腺癌时，下列指标中哪项最重要",[["A","肿瘤出血坏死明显"],["B","肿瘤呈浸润性生长"],["C","肿瘤细胞异型性明显"],["D","肿瘤发生于实体腺"],["E","恶性肿瘤细胞呈腺样排列"]],"E","腺癌是发生于腺上皮的恶性肿瘤，腺癌癌细胞形成大小不等、形状不一、排列不规则的腺体或腺样结构（E对）。肿瘤出血坏死明显（A错）、肿瘤呈浸润性生长（B错）、肿瘤细胞异型性明显（C错）均为恶性肿瘤的特点，不具有特异性。腺癌不一定发生于实体腺，胃肠道、肺等非腺体器官也可以发生腺癌（D错）。","","N"],["1997-N41",9,"第12节 消化系统常见肿瘤","早期癌",1997,41,"A","","下列哪一项有关早期食管癌的叙述是不正确的",[["A","常无明显临床症状"],["B","可以是黏膜内癌"],["C","可以是黏膜下癌"],["D","可以是原位癌"],["E","可以侵及浅肌层"]],"E","消化道管壁由内至外依次可分为黏膜层、黏膜下层、肌层和浆膜层共四层，黏膜层又可分为黏膜上皮层（含基底膜）、黏膜固有层和黏膜肌层三个部分。肿瘤局限在黏膜上皮层时（未突破基底膜），为原位癌；肿瘤突破黏膜上皮层基底膜，但未突破黏膜肌层时，为黏膜内癌；肿瘤突破黏膜肌层到达黏膜下层，但未侵及肌层为黏膜下癌。以上原位癌（D对）、黏膜内癌（B对）、黏膜下癌（C对）均属于早期癌。浸及浅肌层的癌（E错，为本题正确答案）为中晚期癌。食管癌、胃癌和大肠癌均适用以上界定方式。早期食管癌常无明显临床症状（A对）。","","N"],["1997-N42",11,"第1节 肾小球疾病","肾病综合征",1997,42,"A","","肾病综合征不伴有",[["A","蛋白尿"],["B","水肿"],["C","血尿"],["D","低蛋白血症"],["E","高脂血症"]],"C","蛋白尿（尿蛋白含量≧3.5g/d）（A对）、水肿（B对）、低白蛋白血症（D对）及高脂血症（E对）均为肾病综合征的主要表现。血尿（C错，为本题正确答案）是肾炎综合征的典型症状（十版病理学P262）。","","N"],["1997-N43",11,"第1节 肾小球疾病","急进性肾小球肾炎病理变化",1997,43,"A","","急进性肾小球肾炎的病变特点是",[["A","肾小球系膜细胞大量增生"],["B","肾小球内皮细胞大量增生"],["C","肾球囊壁层上皮细胞显著增生"],["D","毛细血管基底膜多量钉状突起"],["E","毛细血管壁增厚呈车轨状或分层状"]],"C","急进性肾小球肾炎又称新月体性肾小球肾炎，其病变特点是肾小球囊壁层上皮细胞显著增生（C对），形成新月体。肾小球系膜细胞（A错）和内皮细胞（B错）大量增生是急性弥漫性增生性肾小球肾炎（急性肾炎）的病变特点（十版病理学P254）。毛细血管基底膜多量钉状突起（D错）是膜性肾小球病的病变特点（十版病理学P256）。毛细血管壁增厚呈车轨状或分层状（E错）是膜增生性肾小球肾炎的病变特点（十版病理学P258）。","","N"],["1997-N44",10,"第2节 淋巴组织肿瘤","霍奇金淋巴瘤的病理诊断",1997,44,"A","","何杰金病具有诊断意义的细胞主要是",[["A","何杰金细胞"],["B","陷窝细胞"],["C","多形性细胞"],["D","R-S细胞"],["E","未分化细胞"]],"D","何杰金病（霍奇金淋巴瘤）的肿瘤细胞包括典型的R-S细胞及其变异型细胞，其中典型的R-S细胞（D对）对霍奇金淋巴瘤具有诊断意义。陷窝细胞（十版病理学P241）只对结节硬化型何杰金氏病具有诊断意义（B错）。何杰金细胞（霍奇金细胞）（十版病理学P239）是一种与R-S细胞形态特征相似，但只有单核的瘤巨细胞，对何杰金病的诊断意义不大（A错）。多形性细胞（多形性瘤细胞）（C错）主要见于淋巴细胞减少型何杰金病（十版病理学P241），但也可见于非何杰金病中的浆细胞骨髓瘤（十版病理学P236）。细胞的分化程度与肿瘤的良、恶性有关，与肿瘤的特异性诊断无关（E错）。","","N"],["1997-N45",8,"第2节 慢性阻塞性肺疾病","全腺泡型肺气肿",1997,45,"A","","遗传性α₁-抗胰蛋白酶缺乏与下列哪种肺气肿的发生关系密切",[["A","小叶中央型肺气肿"],["B","间质性肺气肿"],["C","全腺泡型肺气肿"],["D","肺大泡"],["E","瘢痕旁肺气肿"]],"C","α₁抗胰蛋白酶缺乏是全腺泡型肺气肿（C对）的发病机制之一：α₁-抗胰蛋白酶广泛存在于组织和体液中，对包括弹性蛋白酶在内的多种蛋白水解酶有抑制作用。α₁抗胰蛋白酶缺乏时，中性粒细胞和巨噬细胞分泌的弹性蛋白酶数量增多、活性增强，破坏了肺组织的结构，使呼吸性细支气管、肺泡管、肺泡囊和肺泡的回缩力均减弱，促进全腺泡型肺气肿的发生。","","N"],["1997-N46",0,"第1节 适应","间叶组织的化生",1997,46,"A","","骨化性肌炎，在肌肉组织内出现骨组织，称为",[["A","萎缩"],["B","增生"],["C","化生"],["D","肥大"],["E","变性"]],"C","一种分化成熟的细胞类型被另一种分化成熟的细胞类型所取代的过程为化生，化生常发生于同源性细胞之间，即上皮细胞之间或间叶细胞之间。骨化性肌炎时在肌肉组织内出现骨组织，为成纤维细胞化生为成骨细胞（C对）。萎缩是已发育正常的细胞、组织或器官的体积缩小（A错）。增生是细胞有丝分裂活跃而致组织或器官内细胞数量增多的现象（B错）。肥大是由于功能增加，合成代谢旺盛，使细胞、组织或器官体积增大（D错）。变性是指细胞的可逆性损伤（而化生属于细胞的适应）（E错）。","","N"],["1997-N101",8,"第8节 呼吸系统常见肿瘤","腺癌",1997,101,"B","","肺腺癌",[["A","中央型多见"],["B","周围型多见"],["C","弥漫型多见"],["D","常具有内分泌功能"],["E","肿瘤呈胶冻状"]],"B","肺癌按组织学（十版病理学P190）可分为鳞状细胞癌、腺癌、腺鳞癌、小细胞癌、大细胞癌、肉瘤样癌、类癌和唾液腺癌8个基本类型，按肿瘤在肺内分布部位（十版病理学P190）可分为中央型、周围型和弥漫型三个主要类型。肺腺癌通常发生于通常发生于较小的支气管上皮，65%为周围型肺癌（B对AC错）。具有内分泌功能的肺癌多为小细胞癌（D错），是肺癌中恶性程度最高的一型。肿瘤呈胶冻状（E错）为腺癌中黏液癌（十版病理学P104）的特点，好发于胃和大肠。","","N"],["1997-N102",8,"第8节 呼吸系统常见肿瘤","鳞状细胞癌",1997,102,"B","","肺鳞癌",[["A","中央型多见"],["B","周围型多见"],["C","弥漫型多见"],["D","常具有内分泌功能"],["E","肿瘤呈胶冻状"]],"A","肺癌按组织学（十版病理学P190）可分为鳞状细胞癌、腺癌、腺鳞癌、小细胞癌、大细胞癌、肉瘤样癌、类癌和唾液腺癌8个基本类型，按肿瘤在肺内分布部位（十版病理学P190）可分为中央型、周围型和弥漫型三个主要类型。鳞状细胞癌为肺癌中最常见的类型之一，其中80%～85%为中央型肺癌（A对BC错）。具有内分泌功能的肺癌多为小细胞癌（D错），是肺癌中恶性程度最高的一型。肿瘤呈胶冻状（E错）为腺癌中黏液癌（十版病理学P104）的特点，好发于胃和大肠。","","N"],["1997-N103",7,"第1节 动脉粥样硬化","脂纹",1997,103,"B","","动脉粥样硬化症可见",[["A","阿绍夫细胞"],["B","陷窝细胞"],["C","类上皮细胞"],["D","泡沫细胞"],["E","噬神经细胞现象"]],"D","泡沫细胞（D对）是动脉粥样硬化斑块内出现的特征性病理细胞，主要来源于血液单核细胞与血管中膜平滑肌细胞。阿绍夫细胞（十版病理学P155）（A错）又称风湿细胞，为风湿病时巨噬细胞吞噬纤维素样坏死物质转变而来，是风湿病的特征性病理细胞。陷窝细胞（十版病理学P239）（B错）见于霍奇金淋巴瘤，为R-S细胞的特殊类型。类上皮细胞又称上皮样细胞，为肉芽肿的主要细胞成分之一（十版病理学P76）（C错）。噬神经细胞现象（十版病理学P307）（E错）是指坏死的神经元被增生的小胶质细胞或血源性巨噬细胞吞噬的现象，可见于乙型脑炎。","","N"],["1997-N104",14,"第3节 中枢神经系统感染性疾病","神经细胞变性坏死",1997,104,"B","","乙型脑炎可见",[["A","阿绍夫细胞"],["B","陷窝细胞"],["C","类上皮细胞"],["D","泡沫细胞"],["E","噬神经细胞现象"]],"E","乙型脑炎病毒在神经细胞内增殖，可引起神经细胞变性坏死，神经细胞死亡后，被小胶质细胞或血源性巨噬细胞包围吞噬的现象称为噬神经细胞现象（E对）。小胶质细胞或巨噬细胞在吞噬细胞和组织碎片后，细胞浆中出现小脂滴，HE染色呈空泡状，称为泡沫细胞（D对）或格子细胞，苏丹Ⅲ染色呈阳性反应。阿绍夫细胞（A错）又称风湿细胞，见于风湿病（十版病理学P155）。陷窝细胞（B错）见于结节硬化型霍奇金淋巴瘤（十版病理学P241）。类上皮细胞（C错）又称上皮样细胞，见于慢性肉芽肿性炎（十版病理学P76）。故DE均正确，原参考答案为E。","","N"],["1997-N125",9,"第6节 病毒性肝炎","大块及亚大块坏死",1997,125,"C","","慢性持续性肝炎",[["A","肝细胞灶状坏死"],["B","肝细胞碎片状坏死"],["C","两者均有"],["D","两者均无"]],"D","五版以前的教材将慢性肝炎分为慢性持续性肝炎（慢性迁延性肝炎）和慢性活动性肝炎，新版教材（八版病理学P198）已将慢性肝炎重新分类，分为轻度慢性肝炎、中度慢性肝炎和重度慢性肝炎。慢性持续性肝炎以汇管区淋巴细胞浸润，肝细胞损伤较轻为主要病理特点，仅存在点状坏死。灶状坏死（A错）和肝细胞碎片状坏死（B错）均见于慢性活动性肝炎。本题AB均错，正确答案为D。","","N"],["1997-N126",9,"第6节 病毒性肝炎","急性重型肝炎的病理变化",1997,126,"C","","急性重型肝炎",[["A","肝细胞灶状坏死"],["B","肝细胞碎片状坏死"],["C","两者均有"],["D","两者均无"]],"D","急性重型肝炎镜下表现为肝细胞坏死广泛而严重，肝细胞索解离，肝细胞溶解，出现弥漫性大片坏死（D对）。肝细胞灶状坏死（A错）和肝细胞碎片坏死（B错）均见于慢性肝炎。本题AB均错，正确答案为D。","","N"],["1997-N147",5,"第11节 环境致瘤因素","亚硝胺类物质",1997,147,"X","","亚硝胺致癌作用有以下特点",[["A","致癌性强"],["B","对称的亚硝胺常引起食管癌"],["C","不对称的亚硝胺常引起肝癌"],["D","在胃内酸性环境合成"]],"AD","亚硝胺类物质可在许多实验动物诱发各器官的肿瘤，致癌性强（A对）。肉类食品的保存剂与着色剂可含有亚硝酸盐，亚硝酸盐也可由细菌分解硝酸盐产生，在胃内酸性环境下，亚硝酸盐与来自食物的二级胺合成亚硝胺（D对）。亚硝胺类物质致癌作用与其化学结构有关，如不对称的亚硝胺常引起食管癌（B错），对称的亚硝胺常引起肝癌（C错）。","","N"],["1997-N148",10,"第2节 淋巴组织肿瘤","伯基特淋巴瘤概述",1997,148,"X","","伯基特淋巴瘤的特点是",[["A","多见于非洲儿童"],["B","一般不累及外周淋巴结"],["C","由小无裂细胞恶变而来"],["D","伴有组织细胞反应性增生"]],"ABCD","伯基特淋巴瘤（Burkitt淋巴瘤）是B细胞起源的高度侵袭性肿瘤。多见于非洲儿童（A对），常发生于淋巴结外的器官和组织，最常累及颌骨，一般不累及外周淋巴结（颈淋巴结）（B对）和脾脏。Burkitt淋巴瘤由小无裂细胞恶变而来（C对），恶性程度高，常伴有组织细胞反应性增生（D对）。","","N"],["1997-N149",9,"第6节 病毒性肝炎","病毒性肝炎的基本病理变化",1997,149,"X","","病毒性肝炎中常见的肝细胞变化有",[["A","胞浆疏松化"],["B","气球样变"],["C","嗜酸性坏死"],["D","溶解坏死"]],"ABCD","病毒性肝炎属于以变质为主的炎症，其病变主要包括：（一）肝细胞变性：①细胞水肿，光镜下见肝细胞明显肿大，胞质疏松呈网状、半透明，称为胞质疏松化（A对），进一步发展，肝细胞体积更加肿大，由多角形变为圆球形，胞质几乎完全透明，称气球样变（B对）；②嗜酸性变。（二）肝细胞坏死与凋亡：①溶解性坏死，由严重的细胞水肿发展而来（D对）；②凋亡，以往曾认为是嗜酸性坏死，实质属细胞凋亡，由嗜酸性变发展而来，胞质进一步浓缩，核也浓缩消失，最终形成深红色浓染的圆形小体，称为嗜酸性小体（凋亡小体）（C对）。（三）炎细胞浸润。（四）再生。（五）纤维化。","","N"],["1997-N150",16,"第2节 结核病","结核病发病机制",1997,150,"X","","下列关于结核杆菌的描述中，哪些是正确的",[["A","多糖类参与免疫反应"],["B","脂类与细菌毒力有关"],["C","蛋白与蜡质D结合使机体产生变态反应"],["D","分泌外毒素，引起组织坏死和全身中毒症状"]],"ABC","结核杆菌不产生内、外毒素（D错），其致病性与其菌体和细胞壁内某些成分诱发机体产生迟发型变态反应有关。结核分枝杆菌菌体成分复杂，包括类脂质（属于脂类）、蛋白质和多糖类。脂类与细菌毒力有关（B对），可引起组织坏死、干酪液化和空洞发生。菌体蛋白可与脂类物质蜡质D结合（二版八年制病理学P452）使机体产生变态反应（C对）。多糖类与血清反应等免疫应答有关（A对）。","","N"],["1998-N33",0,"第1节 适应","鳞状上皮的化生",1998,33,"A","","下列哪种肿瘤与化生有关",[["A","甲状腺滤泡腺癌"],["B","卵巢畸胎癌"],["C","肺鳞状细胞癌"],["D","子宫内膜腺癌"],["E","肾细胞癌"]],"C","判断肿瘤是否与化生有关，只需看发生肿瘤组织的细胞类型是否在原正常组织存在，若原来存在，则不是化生，若不存在，则是化生。呼吸道黏膜正常为假复层纤毛柱状上皮，当受到有害因素的作用时（如吸烟），可发生鳞状上皮化生，若有害因素持续存在，最终可发展为肺鳞癌（C对）。甲状腺滤泡腺癌（A错）、卵巢畸胎癌（B错）、子宫内膜腺癌（D错）、肾细胞癌（E错）均是由原来的细胞直接恶变所致，与化生无关。","","N"],["1998-N34",0,"第4节 细胞不可逆性损伤（细胞死亡）","坏死的基本病变",1998,34,"A","","下列有关坏死的描述中，哪项不正确",[["A","核缩、核碎、核溶是细胞坏死的主要形态改变"],["B","干酪样坏死常由结核杆菌引起"],["C","胰腺坏死常为液化性坏死"],["D","固缩坏死只见于细胞的生理性死亡"],["E","湿性坏疽是坏死组织经腐败菌作用的结果"]],"D","细胞核的变化是细胞坏死的主要形态学标志，主要有三种形式：核固缩、核碎裂和核溶解（A对）。干酪样坏死多见于结核病灶中，由结核杆菌引起（B对）。胰腺坏死时，释放大量胰酶，引起酶解性组织坏死，常为液化性坏死（C对）。固缩坏死即凋亡，主要见于细胞的生理性死亡，但也见于某些病理过程中（如病毒性肝炎）（D错，为本题正确答案）。坏疽分为干性、湿性和气性，湿性和气性坏疽是坏死组织经腐败菌作用的结果（E对）。","","N"],["1998-N35",2,"第3节 血栓形成","白色血栓",1998,35,"A","","下述血栓中，哪种是白色血栓",[["A","疣状心内膜炎的瓣膜赘生物"],["B","心房纤颤时心耳内球状血栓"],["C","心肌梗死时的附壁血栓"],["D","微循环内的微血栓"],["E","下肢深静脉的延续性血栓"]],"A","血栓类型可分为四种：白色血栓、混合血栓、红色血栓和透明血栓。疣状心内膜炎（风湿性心内膜炎）的瓣膜赘生物属于白色血栓（A对）。心房纤颤时心耳内球状血栓（B错）、心肌梗死时的附壁血栓（C错）均属于混合血栓。微循环内的微血栓属于透明血栓（D错）。下肢深静脉的延续性血栓（E错）的头部为白色血栓，体部为混合血栓，尾部为红色血栓。","","N"],["1998-N36",16,"第2节 结核病","肺结核病概述",1998,36,"A","","下列哪种炎症属Ⅳ型免疫反应",[["A","风湿性心内膜炎"],["B","支气管哮喘"],["C","病毒性肝炎"],["D","肺出血肾炎综合征"],["E","肺结核病"]],"E","变态反应分为Ⅰ、Ⅱ、Ⅲ、Ⅳ共四型，其中Ⅳ型变态反应又称迟发型变态反应，肺结核病（E对）属于此型变态反应。支气管哮喘（B错）属于Ⅰ型变态反应，即速发型变态反应。病毒性肝炎（C错）可见Ⅲ型变态反应，即免疫复合物型变态反应，此为肝细胞免疫病理损伤机制之一。风湿性心内膜炎（A错）、肺出血肾炎综合征（D错）均属于Ⅱ型变态反应，即细胞毒性变态反应。","","N"],["1998-N37",3,"第2节 急性炎症","趋化作用",1998,37,"A","","下列哪种炎症介质不具有阳性趋化作用",[["A","白细胞三烯B₄"],["B","C5a"],["C","TNF"],["D","IL-8"],["E","缓激肽"]],"E","阳性趋化作用（一般简称趋化作用）是指白细胞被趋化因子吸引，朝趋化因子所在处游走的现象（与之对应的是阴性趋化作用，指白细胞不被吸引甚至被排斥的现象）。由十版病理学P71表4-3可知白细胞三烯B4（LTB₄）（A错）、C5a（B错）、TNF （C错）和IL-8（D错）均具有阳性趋化作用。而缓激肽可使血管通透性增加，具有致痛作用，但无阳性趋化作用（E对）。","","N"],["1998-N38",5,"第10节 肿瘤的分子基础","肿瘤发生和演进的分子机制",1998,38,"A","","下列哪项关于恶性肿瘤发生发展的叙述是错误的",[["A","癌症是一种基因病"],["B","多种因素起作用"],["C","常为多阶段演进过程"],["D","单个基因改变即可引起细胞恶性转化"],["E","既有癌基因改变，又有肿瘤抑制基因改变"]],"D","癌症是一类由多基因改变（A对）（D错，为本题正确答案）引起，有多种因素在作用（遗传因素、环境因素等）（B对），历经多阶段演进过程（C对）的细胞异常增生性疾病。癌症发生时的多基因改变既有癌基因改变（原癌基因激活），又有肿瘤抑制基因改变（肿瘤抑制基因的灭活或丢失）（E对），还有凋亡调节基因和DNA修复基因功能紊乱等。","","N"],["1998-N39",12,"第7节 乳腺疾病","导管原位癌",1998,39,"A","","下述哪种是原位癌",[["A","小肝癌"],["B","胃黏膜内癌"],["C","大肠黏膜下癌"],["D","早期食管瘤"],["E","乳腺导管内癌"]],"E","原位癌（十版病理学P109）是指累及上皮全层但未突破基底膜向下浸润的癌。乳腺导管内癌（E对）癌细胞局限于扩张的导管内，未突破基底膜，属于原位癌，因此又称乳腺导管内原位癌。小肝癌（十版病理学P221）指单个癌结节最大直径＜3cm或两个癌结节合计最大直径＜3cm的原发性肝癌，与癌组织的浸润程度无关（A错）。胃黏膜内癌（B错）、大肠黏膜下癌（C错）、早期食管瘤（D错）均属于消化道早期癌。注：早期癌是指癌症的早期阶段，对于消化道肿瘤而言，早期癌包括原位癌、黏膜内癌和黏膜下癌。对于大肠癌而言，肿瘤组织只有到达黏膜下层才称为癌，按照最新观点，其原位癌归为上皮内瘤变。","","N"],["1998-N40",9,"第12节 消化系统常见肿瘤","概述",1998,40,"A","","食管脱落细胞学检查时，下述哪项支持食管癌的诊断",[["A","出现大量鳞状上皮细胞"],["B","出现中性粒细胞"],["C","出现大量腺上皮细胞"],["D","出现核大、深染、核仁明显的细胞"],["E","出现大量红细胞"]],"D","正常食道黏膜层被覆鳞状上皮，黏膜下层含食管腺，食管脱落细胞学检查时，即使是正常食道也可出现大量鳞状上皮细胞（A错）和腺上皮细胞（C错）。出现中性粒细胞（B错）提示炎症，出现大量红细胞（E错）提示出血，二者均与癌变无必然联系。核大、深染、核仁明显为肿瘤细胞的异型性表现，支持食管癌诊断（D对）。","","N"],["1998-N41",7,"第4节 风湿病","风湿病的各器官病变",1998,41,"A","","下述有关风湿病的描述，哪项是错误的",[["A","可引起缩窄性心包炎"],["B","风湿性关节炎为纤维素性炎"],["C","风湿性肉芽肿具有诊断意义"],["D","Aschoff细胞可能为巨噬细胞源性"],["E","Aschoff小体内淋巴细胞主要是T细胞"]],"B","风湿病累及心外膜时发生风湿性心外膜炎，风湿性心外膜炎渗出的大量纤维素如不能被溶解吸收，则发生机化，使心外膜脏层和壁层互相粘连，形成缩窄性心外膜炎（缩窄性心包炎）（A对）。风湿性关节炎主要为关节滑膜的浆液性炎症（虽然关节腔也有纤维蛋白渗出）（二版八年制病理学P202）（B错，为本题正确答案），故急性期后，炎症渗出物易被完全吸收，一般不留后遗症。风湿性肉芽肿即Aschoff小体对风湿病具有诊断意义（C对）。Aschoff细胞由增生的巨噬细胞吞噬纤维素样坏死物质转变而来（D对）。Aschoff小体内除风湿细胞外，还含有少量淋巴细胞和浆细胞，其中淋巴细胞主要是T淋巴细胞（E对）。","","N"],["1998-N42",7,"第6节 心瓣膜病","二尖瓣狭窄",1998,42,"A","","下列哪种疾病一般不引起左室壁心肌坏死",[["A","克山病"],["B","冠状动脉粥样硬化"],["C","二尖瓣狭窄"],["D","柯萨奇病毒性心肌炎"],["E","白喉性心肌炎"]],"C","克山病（A错）、冠状动脉粥样硬化（B错）、柯萨奇病毒性心肌炎（D错）、白喉性心肌炎（E错）均可引起左室壁心肌细胞发生变性坏死。二尖瓣狭窄会导致左心房及右心室代偿性肥大，一般不影响左心室，更不会引起左室壁心肌坏死（C对）。","","N"],["1998-N43",9,"第8节 肝硬化","镜下",1998,43,"A","","下述有关假小叶的描述中，哪项不正确",[["A","体积大小不等"],["B","肝细胞索排列紊乱"],["C","中央静脉偏位或缺如"],["D","可见汇管区"],["E","肝细胞异型性显著"]],"E","假小叶是指由广泛增生的纤维组织分割原来的肝小叶并包绕成大小不等（A对）的圆形或类圆形的肝细胞团，是肝硬化的特征性病变。假小叶具有如下特点：①肝细胞排列紊乱（B对），可有变性、坏死及再生的肝细胞；②中央静脉常缺如，偏位或有两个以上（C对）；③有时可见汇管区也被包于内（D对）。肝细胞异型性显著是肝细胞癌的病理表现（十版病理学P221）（E错，为本题正确答案）。","","N"],["1998-N44",9,"第6节 病毒性肝炎","乙型肝炎病毒（HBV）",1998,44,"A","","导致肝硬化的DNA病毒是",[["A","HAV"],["B","HBV"],["C","HCV"],["D","HDV"],["E","HEV"]],"B","病毒性肝炎是我国肝硬化的主要原因，尤其是乙型和丙型病毒性肝炎与肝硬化的发展有密切关系，二者分别因感染HBV（乙型肝炎病毒）和HCV（丙型肝炎病毒）引起，其中HBV为DNA病毒（B对），HCV为RNA病毒（C错）。HAV（A错）、HDV（D错）、HEV（E错）较少引起肝硬化，且均为RNA病毒。","","N"],["1998-N45",10,"第3节 髓系肿瘤","慢性髓系白血病临床表现",1998,45,"A","","下述描述中，哪项不符合慢性粒细胞白血病",[["A","约90％出现Ph¹染色体"],["B","周围血白细胞数量明显增高"],["C","骨髓内大量原始粒细胞"],["D","脾明显肿大"],["E","肝肿大"]],"C","慢性粒细胞白血病（CML）骨髓增生以粒细胞为主，粒红比例明显增高，其中中性中幼、晚幼及杆状核粒细胞明显增多，而原始细胞＜10%。骨髓内出现大量原始粒细胞为急性粒细胞白血病或慢性粒细胞白血病急性变的特点，而不是慢性粒细胞白血病（CML）的特点（C错，为本题正确答案）。CML时，约90％会出现Ph¹染色体（A对），周围血白细胞数量明显升高（B对），常超过20×10⁹/L，甚至可高达100×10⁹/L以上，脾脏明显肿大（D对）是常见的临床表现，肝肿大（E对）可出现，但肿大一般不明显。","","N"],["1998-N46",11,"第1节 肾小球疾病","急性弥漫性增生性肾小球肾炎病理变化",1998,46,"A","","下列描述中，哪一项符合弥漫性毛细血管内增生性肾小球肾炎",[["A","系膜细胞和内皮细胞增生"],["B","系膜细胞和基质增生"],["C","壁层上皮细胞增生"],["D","毛细血管壁呈车轨状"],["E","毛细血管壁增厚显著"]],"A","急性弥漫性增生性肾小球肾炎（临床简称急性肾炎）的病变特点是系膜细胞和毛细血管内皮细胞增生（A对），伴中性粒细胞和巨噬细胞浸润。系膜细胞和基质增生（B错）为系膜增生性肾小球肾炎的病理特点（十版病理学P258）。壁层上皮细胞增生（C错）为急进性肾炎（新月体性肾小球肾炎）的病理特点（十版病理学P256）。毛细血管壁呈车轨状（D错）为膜增生性肾小球肾炎（系膜毛细血管性肾小球肾炎）的病理特点（十版病理学P258）。毛细血管壁显著增厚（E错）为膜性肾小球病的病理特点（十版病理学P256）。","","N"],["1998-N99",5,"第4节 肿瘤的生长和扩散","侵袭性生长",1998,99,"B","","肝血管瘤",[["A","血道转移"],["B","淋巴道转移"],["C","浸润性生长"],["D","膨胀性生长"],["E","外生性生长"]],"C","血管瘤是良性肿瘤，但与一般的良性肿瘤不同，血管瘤无被膜，界限不清，呈浸润性生长（C对）。","","N"],["1998-N100",5,"第4节 肿瘤的生长和扩散","外生性生长",1998,100,"B","","胫骨骨软骨瘤",[["A","血道转移"],["B","淋巴道转移"],["C","浸润性生长"],["D","膨胀性生长"],["E","外生性生长"]],"E","骨软骨瘤是一种常见的、软骨源性的良性肿瘤，骨软骨瘤位于骨表面，为骨性突起物，呈外生性生长（E对）。发生血道转移（A错）和淋巴道转移（B错）是恶性肿瘤的特点。浸润性生长（C错）也是恶性肿瘤的特点。膨胀性生长（D错）为实质器官的良性肿瘤的生长方式。","","N"],["1998-N101",9,"第6节 病毒性肝炎","乙型肝炎病毒改变特点",1998,101,"B","","慢性乙型肝炎时可见",[["A","毛玻璃样细胞"],["B","上皮样细胞"],["C","伤寒细胞"],["D","Anitschkow细胞"],["E","R-S细胞"]],"A","慢性乙型肝炎的形态学特征是毛玻璃样细胞（A对）：乙型肝炎病毒感染时，在HE染色光镜下，可见部分肝细胞胞质内充满嗜酸性细颗粒物质，胞质不透明似毛玻璃样，此为毛玻璃样细胞。伤寒细胞（十版病理学P350）为吞噬有伤寒杆菌、红细胞和细胞碎片的巨噬细胞（C错），是伤寒肉芽肿的特征性细胞。Anitschkow细胞（D错）即Aschoff细胞，为风湿性肉芽肿的特征性细胞（十版病理学P155）。R-S细胞（十版病理学P239）为霍奇金淋巴瘤的特征性肿瘤细胞（E错）。","","N"],["1998-N102",7,"第4节 风湿病","风湿性心肌炎",1998,102,"B","","风湿性心肌炎时可见",[["A","毛玻璃样细胞"],["B","上皮样细胞"],["C","伤寒细胞"],["D","Anitschkow细胞"],["E","R-S细胞"]],"D","Anitschkow细胞即Aschoff细胞（Anitschkow和Aschoff分别为两位病理学家的名字，严格来说Anitschkow细胞与Aschoff细胞并不是同一种细胞，按照文献的解释，Aschoff细胞又名Aschoff巨细胞，由Anitschkow细胞融合而形成，类似P76上皮样细胞与多核巨细胞的关系，但十版病理学教材P155似乎将Aschoff细胞和Aschoff巨细胞当成了两种不同的细胞，而将Aschoff细胞和Anitschkow细胞当成了同一种细胞，此处不必深究），在风湿性心肌炎时可见（D对）。毛玻璃样细胞（十版病理学P205）见于乙型肝炎表面抗原携带者和慢性肝炎患者（A错），因胞质内充满嗜酸性细颗粒物质，胞质不透明似毛玻璃样而得名。上皮样细胞（十版病理学P76）为肉芽肿的主要细胞成分之一（B错），由巨噬细胞衍生而来，因细胞形态与上皮细胞相似而得名。伤寒细胞（十版病理学P350）为吞噬有伤寒杆菌、红细胞和细胞碎片的巨噬细胞（C错），是伤寒肉芽肿的特征性细胞。R-S细胞（十版病理学P239）为霍奇金淋巴瘤的特征性肿瘤细胞（E错）。","","N"],["1998-N127",14,"第3节 中枢神经系统感染性疾病","颅内压增高症状",1998,127,"C","","流行性脑脊髓膜炎",[["A","颅内压增高"],["B","神经细胞变性坏死"],["C","二者皆有"],["D","二者皆无"]],"A","流行性脑脊髓膜炎是脑膜炎双球菌感染所致的化脓性炎症，主要累及软脑膜，很少侵犯脑实质，一般不出现神经细胞变性坏死（B错）。值得注意的是当病情严重时，流行性脑脊髓膜炎可发展为脑膜脑炎，后者可累及邻近脑膜的脑实质，使神经细胞变性坏死。流行性脑脊髓膜炎的临床病理表现主要为脑膜刺激症状、颅内压增高症状（A对）以及脑脊液的改变。","","N"],["1998-N128",14,"第3节 中枢神经系统感染性疾病","神经细胞变性坏死",1998,128,"C","","流行性乙型脑炎",[["A","颅内压增高"],["B","神经细胞变性坏死"],["C","二者皆有"],["D","二者皆无"]],"C","流行性乙型脑炎是乙型脑炎病毒引起的变质性炎，病变广泛累及脑实质，可出现血管改变和炎症反应、神经细胞变性坏死（B对）、软化灶形成和胶质细胞增生。同时由于脑实质血管高度扩张充血、血管壁通透性增加，可发生脑水肿，导致颅内压增高（A对）。本题AB均对，正确答案为C。","","N"],["1998-N147",8,"第6节 慢性肺源性心脏病","慢性肺性心脏病的病因和发病机制",1998,147,"X","","下述哪些疾病可导致慢性肺源性心脏病",[["A","慢性阻塞性肺气肿"],["B","三期硅肺"],["C","慢性空洞性肺结核"],["D","肺动脉反复血栓栓塞"]],"ABCD","慢性阻塞性肺气肿（A对）、三期硅肺（B对）、慢性空洞性肺结核（C对）、肺动脉反复血栓栓塞（D对）均可引起肺循环阻力增加，肺动脉压升高，导致慢性肺源性心脏病的发生。","","N"],["1998-N148",9,"第12节 消化系统常见肿瘤","早期癌",1998,148,"X","","早期食管癌包括",[["A","原位癌"],["B","黏膜内癌"],["C","黏膜下癌"],["D","浸润肌层的癌"]],"ABC","消化道管壁由内至外依次可分为黏膜层、黏膜下层、肌层和浆膜层共四层，黏膜层又可分为黏膜上皮层（含基底膜）、黏膜固有层和黏膜肌层三个部分。肿瘤局限在黏膜上皮层时（未突破基底膜），为原位癌；肿瘤突破黏膜上皮层基底膜，但未突破黏膜肌层时，为黏膜内癌；肿瘤突破黏膜肌层到达黏膜下层，但未侵及肌层为黏膜下癌。以上原位癌（A对）、黏膜内癌（B对）、黏膜下癌（C对）均属于早期癌。浸润肌层的癌（D错）为中晚期癌。食管癌、胃癌和大肠癌均适用以上界定方式。","","N"],["1998-N149",9,"第8节 肝硬化","门脉高压症",1998,149,"X","","肝硬化时，门静脉高压症形成的原因有",[["A","小叶下静脉受压"],["B","肝动脉与门静脉异常吻合支形成"],["C","中央静脉及肝静脉窦受压"],["D","肝静脉阻塞"]],"ABC","肝硬化时，门静脉高压症形成的原因包括小叶下静脉受压（窦后性阻塞）（A对）、肝内肝动脉小分支与门静脉小分支异常吻合支形成（窦前性）（B对）、中央静脉及肝静脉窦受压（窦性阻塞）（C对）等。肝静脉阻塞为肝后型门静脉高压症形成的原因，而不是肝硬化（肝内型）门静脉高压形成的原因（D错）。","","N"],["1998-N150",9,"第12节 消化系统常见肿瘤","肝细胞癌的病理变化概述",1998,150,"X","","下述有关肝细胞癌的描述，哪些是正确的",[["A","常经血道转移"],["B","常与周围肝组织分界明显"],["C","可呈腺管样结构"],["D","可呈团块状结构"]],"ACD","肝细胞癌常沿门静脉分支（经血道）（A对）于肝内转移，常呈浸润性生长，与周围肝组织分界不清（B错），分化高者癌细胞类似于肝细胞，分泌胆汁，癌细胞排列呈巢状（D对）。腺管样结构为胆管细胞癌的特点，而不是肝细胞癌的特点（C错）。故根据最新版本教材，本题正确答案应为AD，但当年官方给出的参考答案为ACD。","","N"],["1999-N33",11,"第1节 肾小球疾病","急性弥漫性增生性肾小球肾炎病理变化",1999,33,"A","","弥漫性膜性增生性肾小球肾炎的病理特点是",[["A","肾小球囊壁层细胞增生"],["B","肾小球内新月体形成"],["C","系膜细胞和内皮细胞增生"],["D","毛细血管壁呈车轨状"],["E","毛细血管内皮细胞增生"]],"D","膜性增生性肾小球肾炎的病理改变为系膜细胞和系膜基质弥漫重度增生，可插入肾小球基底膜和内皮细胞之间（九版内科学P473），使毛细血管壁呈双轨状（D对）。肾小球囊壁层细胞增生（A错）和肾小球内新月体形成（B错）为急进性肾小球肾炎的病变特征（十版病理学P255）。系膜细胞和毛细血管内皮细胞增生（CE错）为急性肾炎的病理特点（十版病理学P254），虽然可以出现在弥漫性膜性增生性肾小球肾炎，但不是其主要病理特点。","","N"],["1999-N34",9,"第12节 消化系统常见肿瘤","结直肠癌的分期与预后",1999,34,"A","","关于大肠癌的描述，下列哪项是正确的",[["A","盲肠癌最多见"],["B","类癌由腺瘤癌变而来"],["C","少数癌瘤产生CEA"],["D","Dukes D期有远隔器官转移"],["E","未分化癌多见"]],"D","大肠癌中以直肠癌最多见（50%），其次为乙状结肠癌、盲肠癌（A错）及升结肠癌等。消化道类癌（P312）来源于嗜银细胞（嗜铬细胞），而不是由腺瘤癌变而来（B错）。大肠癌的血清学检测中，多数癌瘤可产生CEA（癌胚抗原）（C错），其主要用于预测直肠癌的预后和监测复发（八版内科学P396）。大肠癌按癌变扩散范围及有无淋巴结转移可分为A、B₁、B₂、C₁、C₂、D期，称为Dukes分期，其中Dukes D期有远隔器官转移（D对）。大肠癌的组织学分型以腺癌最常见，未分化癌少见（E错）。","","N"],["1999-N35",16,"第10节 寄生虫病","血吸虫病概述",1999,35,"A","","关于血吸虫病的描述，下列哪项是正确的",[["A","晚期急性虫卵结节出现多量类上皮细胞"],["B","慢性虫卵结节的虫卵内毛蚴仍存活"],["C","急性虫卵结节内大量中性粒细胞浸润"],["D","慢性虫卵结节内大量淋巴细胞浸润"],["E","肺脏内无虫卵结节形成"]],"A","血吸虫病成熟虫卵可在肠、肝、肺（E错）等组织内沉着，形成虫卵结节。虫卵结节按发展过程可分为急性虫卵结节和慢性虫卵结节两种类型。急性虫卵结节镜下可见结节中央常有1～2个成熟虫卵，虫卵周围可见颗粒状坏死物质及大量嗜酸性粒细胞浸润（C错），急性虫卵结节发展至晚期，肉芽组织逐渐形成，并出现围绕结节呈放射状排列的类上皮细胞层（A对）。急性虫卵结节经10余天后，卵内毛蚴死亡（B错），逐渐转变为慢性虫卵结节。慢性虫卵结节内可有淋巴细胞浸润，但无大量浸润（D错）。","","N"],["1999-N36",13,"第2节 甲状腺疾病","乳头状癌",1999,36,"A","","甲状腺癌中，下列哪一种最常见",[["A","滤泡性腺癌"],["B","乳头状腺癌"],["C","髓样癌"],["D","梭形细胞癌"],["E","巨细胞癌"]],"B","乳头状腺癌（B对）是甲状腺癌中最常见的类型，约占60%，多见于青少年女性。滤泡性腺癌（A错）也较常见，仅次于甲状腺乳头状癌居第二位，多见于40岁以上的女性。髓样癌（C错）约占甲状腺癌的5%～10%，40～60岁高发。梭型细胞癌（D错）和巨型细胞癌（E错）都属于未分化癌（十版病理学P298），较少见，多见于50岁以上的女性。","","N"],["1999-N37",16,"第3节 伤寒","伤寒肠道病变概述",1999,37,"A","","关于伤寒的描述，下列哪项是正确的",[["A","结肠形成多发性不规则溃疡"],["B","盲肠形成多发性烧瓶状溃疡"],["C","回肠形成多数环形溃疡"],["D","回肠形成鹅口疮样溃疡"],["E","回肠形成多数圆形或椭圆形溃疡"]],"E","伤寒肠道病变常见于回肠末端淋巴组织，其溃疡多为圆形或椭圆形（E对），长轴与肠腔的长轴平行。结肠形成的多发性不规则溃疡（A错）又称地图状溃疡，是急性细菌性痢疾的特征（十版病理学P351）。盲肠形成多发性烧瓶状溃疡（B错）是阿米巴肠病的特征（十版病理学P358）。回肠形成多数环形溃疡（C错）是肠结核的特征（十版病理学P348）。回肠形成鹅口疮样溃疡（D错）见于早期克罗恩病（晚期克罗恩病可见裂隙状溃疡）。","","N"],["1999-N38",10,"第2节 淋巴组织肿瘤","结节硬化型",1999,38,"A","","下述哪项符合结节硬化型何杰金病",[["A","淋巴结结构保留"],["B","淋巴细胞大量增生"],["C","多种细胞混合增生，少数R-S细胞"],["D","淋巴细胞显著减少，较多R-S细胞"],["E","纤维组织增生，多数陷窝细胞和R-S细胞"]],"E","结节硬化型何杰金病（霍奇金淋巴瘤）的组织学特点是纤维组织增生（“硬化”的原因），分隔病变淋巴结为大小不等的结节，淋巴结结构被破坏（A错）。其肿瘤细胞多为陷窝细胞，典型的R-S细胞少见（E错）。淋巴细胞大量增生（B错）见于富于淋巴细胞型何杰金病（十版病理学P241）。多种细胞混合增生（C错）见于混合细胞型何杰金病（十版病理学P241），但此型的R-S细胞多见。淋巴细胞显著减少，较多R-S细胞（D错）见于淋巴细胞减少型何杰金病（十版病理学P241）。严格来说本题无正确答案，但给出的参考答案为E。","","N"],["1999-N39",10,"第2节 淋巴组织肿瘤","T细胞淋巴瘤的概述",1999,39,"A","","下列哪种是T细胞淋巴瘤",[["A","Burkitt淋巴瘤"],["B","滤泡性淋巴瘤"],["C","免疫母细胞淋巴瘤"],["D","滤泡中心细胞型淋巴瘤"],["E","曲折核淋巴细胞型淋巴瘤"]],"E","曲折核淋巴细胞型淋巴瘤（E对）是T细胞来源肿瘤。Burkitt淋巴瘤（A错）、滤泡性淋巴瘤（B错）和滤泡中心细胞型淋巴瘤（D错）均是B细胞来源的肿瘤（请参阅P229 表12-1）。免疫母细胞淋巴瘤（C错）可为B细胞、T细胞或NK细胞来源。","","N"],["1999-N40",9,"第12节 消化系统常见肿瘤","中晚期胃癌（进展期胃癌）的概述",1999,40,"A","","下述哪项支持胃的恶性溃疡",[["A","溃疡呈圆形，椭圆形"],["B","边缘整齐，不隆起"],["C","底部较平坦"],["D","火山口状，底部凹凸不平"],["E","皱襞向溃疡集中"]],"D","胃的恶性溃疡呈皿状或火山口状，底部凹凸不平（D对），边缘不整齐，隆起，黏膜皱襞中断。外形呈圆形或椭圆形（A错），边缘整齐，不隆起（B错），底部较平坦（C错）及黏膜皱襞向溃疡集中（E错）等均为胃良性溃疡的特征。","","N"],["1999-N41",9,"第8节 肝硬化","镜下",1999,41,"A","","下述哪项支持门脉性肝硬变",[["A","结节大小相仿，纤维分隔薄而均匀"],["B","结节大小不等，纤维分隔厚薄不均"],["C","肝脏呈细颗粒状，深绿色"],["D","树枝状纤维组织将肝脏分割为粗大结节"],["E","肝内散在多个大结节"]],"A","我国根据发病的病因、病变特点以及临床表现将肝硬化主要分为常见的三种类型即门脉性肝硬化、坏死后性肝硬化、胆汁性肝硬化。门脉性肝硬化肝脏表面和切面呈弥漫全肝的小结节，结节大小相仿，切面可见圆形或类圆形岛屿状结构，其大小与表面的结节一致，周围有灰白色纤维组织条索或间隔包绕（A对）。结节大小不等，纤维分隔厚薄不均见于坏死后性肝硬化（十版病理学P210）（B错）。肝脏呈细颗粒状，深绿色见于胆汁性肝硬化（十版病理学P210）（C错）。树枝状纤维组织将肝脏分割为粗大结节见于血吸虫性肝硬化（十版病理学P363）（D错）。肝内散在多个大结节见于多结节型肝癌（十版病理学P221）（E错）。","","N"],["1999-N42",8,"第5节 肺尘埃沉着病","硅结节的形成",1999,42,"A","","硅肺的特征病变是",[["A","类上皮肉芽肿"],["B","胸膜呈斑状增厚"],["C","硅肺空洞"],["D","硅结节"],["E","肺间质纤维化"]],"D","硅肺沉着病，简称硅肺，曾称矽肺，是长期吸入游离二氧化硅粉尘沉积于肺组织所引起的一种常见职业病。硅肺的基本病变是硅结节（D对）的形成和肺组织的弥漫性纤维化。硅结节属于异物性肉芽肿，异物性肉芽肿含巨噬细胞、异物巨细胞、淋巴细胞和成纤维细胞等（十版病理学P76），但不含类上皮细胞（A错），不属于类上皮肉芽肿（感染性肉芽肿属于类上皮肉芽肿）。胸膜呈斑状增厚（B错）、硅肺空洞（C错）、肺间质纤维化（E错）为硅肺的病变，但并不属于特征性病变。","","N"],["1999-N43",8,"第8节 呼吸系统常见肿瘤","肺癌的病理变化",1999,43,"A","","下列肺癌的描述中，哪项正确",[["A","腺癌最多见"],["B","小细胞癌多呈弥漫型"],["C","鳞状细胞癌多有吸烟史"],["D","周围型多为鳞癌"],["E","细支气管肺泡细胞癌多为中央型"]],"AC","肺癌按组织学可分为鳞状细胞癌、腺癌、腺鳞癌、小细胞癌、大细胞癌、肉瘤样癌、类癌和唾液腺癌8个基本类型，按发生部位可分为中央型、周围型和弥漫型。病理学认为鳞状细胞癌为肺癌中最常见的类型（A错），约占肺癌手术切除标本的60%以上，其中80%～85%为中央型肺癌（D错）。患者绝大多数为中老年人且大多有吸烟史（C对）。小细胞癌又称小细胞神经内分泌癌，占全部肺癌的10%～20%，是肺癌中恶性程度最高的一型，多为中央型（B错），常发生于大支气管，向肺实质浸润生长，形成巨块。腺癌发生率仅次于鳞癌，女性多见，大多数为周围型。细支气管肺泡癌是高分化腺癌，多为弥漫型（E错）。根据10版内科学P88：腺癌是肺癌最常见的类型。女性多见，主要起源于支气管黏液腺，可发生于细小支气管或中央气道，临床多表现为周围型。A也正确。","","N"],["1999-N44",7,"第7节 心肌病","限制型心肌病的病理变化",1999,44,"A","","下述哪项符合限制性心肌病",[["A","心内膜及心内膜下心肌纤维化"],["B","心肌间质纤维化"],["C","心肌细胞呈旋涡状排列"],["D","心肌细胞变性坏死"],["E","心肌间质内淋巴细胞浸润"]],"A","限制性心肌病以单侧或双侧心室充盈受限和舒张期容量减少为特征，心室充盈受限是由心内膜及心内膜下心肌纤维化（A对）造成的。心肌间质纤维化（十版病理学P161）见于扩张性心肌病（B错）。心肌细胞走行紊乱，呈旋涡状排列见于肥厚性心肌病（C错）。心肌细胞变性坏死（十版病理学P162）是克山病的病理表现（D错）。心肌间质内淋巴细胞浸润可见于病毒性心肌炎（十版病理学P163）、孤立性心肌炎（十版病理学P164）、免疫反应性心肌炎（十版病理学P164）等心肌炎疾病（E错）。","","N"],["1999-N45",5,"第4节 肿瘤的生长和扩散","侵袭性生长",1999,45,"A","","下列哪种肿瘤呈浸润性生长",[["A","脂肪瘤"],["B","畸胎瘤"],["C","带状瘤"],["D","腺瘤"],["E","乳头状瘤"]],"C","一般来说，良性肿瘤多呈膨胀性生长或外生性生长，恶性肿瘤或交界性肿瘤方可多呈浸润性生长（良性肿瘤中的血管瘤也可呈浸润性生长）。脂肪瘤（A错）、腺瘤（D错）、乳头状瘤（E错）项均为良性肿瘤。带状瘤为好发于腹壁肌层和筋膜鞘的纤维瘤，属于交界性肿瘤，该肿瘤生长具有侵袭性（C对）、易复发性和局部破坏性等特点。畸胎瘤根据分化程度的不同，可分为良性畸胎瘤和恶性畸胎瘤，无法确定其生长方式（B错）。","","N"],["1999-N46",5,"第8节 常见肿瘤举例","基底细胞癌",1999,46,"A","","下列哪种肿瘤以局部破坏为主，很少发生转移",[["A","腺癌"],["B","鳞癌"],["C","黑色素瘤"],["D","基底细胞癌"],["E","乳头状腺癌"]],"D","基底细胞癌为来自基底细胞的恶性肿瘤，有浅表型、结节型等组织类型，生长缓慢，表面常形成溃疡，浸润破坏深层组织，但很少发生转移（D对）。腺癌（A错）、鳞癌（B错）、黑色素瘤（C错）、乳头状腺癌（E错）均为恶性程度较高的肿瘤，容易发生转移。","","N"],["1999-N99",0,"第3节 细胞可逆性损伤","细胞内玻璃样变",1999,99,"B","","近曲小管上皮细胞内玻璃样小滴",[["A","光面内质网大量增生"],["B","前角蛋白细丝堆积"],["C","增大的载有蛋白质的溶酶体"],["D","线粒体肿胀、嵴消失"],["E","核内包含物"]],"C","肾小球通透性增高时，大量蛋白滤过进入肾小管，这些蛋白质被近曲小管上皮细胞重吸收，在胞质内与溶酶体融合，形成玻璃样小滴（C对），多见于脂性肾病。光面内质网大量增生为毛玻璃样肝细胞（十版病理学P205）的特点（A错），见于乙肝表面抗原携带者和慢性肝炎患者的肝组织。前角蛋白细丝堆积见于酒精性肝病时肝细胞胞质中细胞中间丝前角蛋白变性（B错）。线粒体肿胀、嵴消失为细胞水肿的病理变化（D错）。","","N"],["1999-N100",0,"第3节 细胞可逆性损伤","细胞内玻璃样变",1999,100,"B","","肝细胞内Mallory小体",[["A","光面内质网大量增生"],["B","前角蛋白细丝堆积"],["C","增大的载有蛋白质的溶酶体"],["D","线粒体肿胀、嵴消失"],["E","核内包含物"]],"B","Mallory小体为酒精性肝病时肝细胞胞质中细胞中间丝前角蛋白变性形成的玻璃样变（B对）。光面内质网大量增生为毛玻璃样肝细胞（十版病理学P205）的特点（A错），见于乙肝表面抗原携带者和慢性肝炎患者的肝组织。增大的载有蛋白质的溶酶体见于近曲小管上皮细胞玻璃样变性（C错）。线粒体肿胀、嵴消失为细胞水肿的病理变化（D错）。","","N"],["1999-N101",11,"第1节 肾小球疾病","急性弥漫性增生性肾小球肾炎病理变化",1999,101,"B","","弥漫性膜性肾小球肾炎",[["A","蚤咬肾"],["B","大白肾"],["C","颗粒性固缩肾"],["D","肾脏多数脓肿"],["E","肾脏多数凹陷瘢痕"]],"B","弥漫性膜性肾小球肾炎（膜性肾病）是引起肾病综合征的常见原因之一，其病理变化为双肾肿大，颜色苍白，呈“大白肾”（B对）。蚤咬肾（A错）见于急性弥漫性增生性肾小球肾炎（急性肾炎）（十版病理学P254）。颗粒性固缩肾包括原发性颗粒性固缩肾和继发性颗粒性固缩肾两种，前者见于高血压肾病（十版病理学P152），后者见于慢性肾小球肾炎（十版病理学P260）（C错）。肾脏多数脓肿（D错）见于肾盂肾炎（十版病理学P263）。肾脏多数凹陷瘢痕（E错）是动脉粥样硬化累及肾动脉的表现，瘢痕可使肾脏缩小，称为动脉粥样硬化（AS）性固缩肾（十版病理学P148）。","","N"],["1999-N102",7,"第1节 动脉粥样硬化","肾动脉粥样硬化",1999,102,"B","","动脉硬化性肾萎缩",[["A","蚤咬肾"],["B","大白肾"],["C","颗粒性固缩肾"],["D","肾脏多发脓肿"],["E","肾脏多数凹陷瘢痕"]],"E","肾动脉粥样硬化时，肾动脉管腔狭窄，斑块处易形成血栓，导致肾组织梗死，梗死灶机化后遗留较大凹陷瘢痕（E对），多个瘢痕可使肾脏缩小，称为肾动脉粥样硬化（AS）性固缩肾。蚤咬肾（十版病理学P254）（A错）见于急性肾小球肾炎。大白肾（十版病理学P256）（B错）见于膜性肾小球病（膜性肾病）。颗粒性固缩肾（C错）可分原发性和继发性，原发性颗粒性固缩肾见于高血压肾病（十版病理学P152），继发性颗粒性固缩肾（十版病理学P260）见于慢性肾小球肾炎。肾脏多发脓肿（D错）见于急性肾盂肾炎（十版病理学P263）。","","N"],["1999-N147",9,"第6节 病毒性肝炎","急性重型肝炎的病理变化",1999,147,"X","","急性重型肝炎的病理特点是",[["A","肝细胞点状坏死"],["B","肝体积明显缩小"],["C","肝质地柔软，呈黄色或红褐色"],["D","肝细胞再生不明显"]],"BCD","急性重型肝炎，起病急骤，病变严重，死亡率高。肉眼观可见肝体积明显缩小（B对），被膜皱缩，质地柔软，切面呈黄色或红褐色（C对），部分区域呈红黄相间的斑纹状，因而又称急性黄色肝萎缩或急性红色肝萎缩。镜下，肝细胞坏死广泛而严重，肝细胞索解离，肝细胞溶解，出现弥漫性大片坏死（A错），溶解坏死的肝细胞很快被清除，仅残留网状支架，数日后网状支架塌陷，残留的肝细胞无明显再生现象（D对）。肝细胞点状坏死为急性普通型肝炎的病理特点。","","N"],["1999-N148",14,"第3节 中枢神经系统感染性疾病","病毒性疾病病理变化概述",1999,148,"X","","流行性乙型脑炎的基本病变有",[["A","神经细胞变性坏死"],["B","蛛网膜下腔大量中性粒细胞渗出"],["C","胶质细胞增生"],["D","主要累及大脑灰质及神经核团"]],"ACD","流行性乙型脑炎是一种由乙型脑炎病毒感染引起的变质性炎，病变广泛累及脑实质，以大脑皮质（灰质）、基底核（由神经核团组成）和视丘最为严重（D对），其基本病变有神经细胞变性坏死（A对），胶质细胞增生（C对）、血管周围炎细胞浸润和软化灶形成。蛛网膜下腔大量中性粒细胞渗出（B错）是流脑的基本病变（十版病理学P310），流行性乙型脑炎主要表现为脑实质血管周围出现淋巴细胞、单核细胞和浆细胞渗出（十版病理学P312）。","","N"],["1999-N149",16,"第2节 结核病","原发性肺结核病",1999,149,"X","","原发性肺结核的基本病变包括",[["A","原发病灶"],["B","肺门淋巴结结核"],["C","血源性结核病"],["D","结核性淋巴管炎"]],"ABD","原发性肺结核的基本病变是原发综合征的形成，而原发综合征由原发病灶（A对）、肺门淋巴结结核（B对）、结核性淋巴管炎（D对）构成。血源性结核病（血行播散型结核病）（九版内科学P67）（C错）是区别于原发性肺结核的另一种肺结核类型。","","N"],["1999-N150",9,"第12节 消化系统常见肿瘤","早期胃癌的概述",1999,150,"X","","早期胃癌包括",[["A","黏膜内癌"],["B","黏膜下癌伴淋巴结转移"],["C","侵及肌层的癌"],["D","侵及浆膜层的癌"]],"AB","消化道管壁由内至外依次可分为黏膜层、黏膜下层、肌层和浆膜层共四层，黏膜层又可分为黏膜上皮层（含基底膜）、黏膜固有层和黏膜肌层三个部分。肿瘤局限在黏膜上皮层时（未突破基底膜），为原位癌；肿瘤突破黏膜上皮层基底膜，但未突破黏膜肌层时，为黏膜内癌；肿瘤突破黏膜肌层到达黏膜下层，但未侵及肌层为黏膜下癌。以上原位癌、黏膜内癌（A对）、黏膜下癌（B对）均属于早期癌，早期胃癌可有（或无）淋巴结转移。累及肌层（C错）和浆膜层（D错）为进展期胃癌（中晚期胃癌）。","","N"],["2000-N33",9,"第6节 病毒性肝炎","乙型肝炎病毒改变特点",2000,33,"A","","下述哪项肝细胞的病理改变与乙型肝炎病毒（HBV）感染有关",[["A","细胞内大量糖原沉积"],["B","核内出现假包涵体"],["C","光面内质网大量增生"],["D","前角蛋白细丝堆集"],["E","粗面内质网增多"]],"C","乙型肝炎特征性的形态学改变为光镜下出现毛玻璃样细胞。HBV进入肝细胞后，在光面内质网内复制，引起光面内质网不同程度的增生（C对E错），增生主要是HBsAg颗粒的沉积。细胞内大量糖原沉积（A错）见于糖原沉积症（八版病理学P204），是一种常染色体隐性遗传病。核内出现假包涵体（胞核不规则内陷成分叶状，内含胞浆和细胞器）见于肝癌细胞（B错）。前角蛋白细丝堆集可成Mallory小体，多见于酒精性肝病（十版病理学P16）（D错），为肝细胞玻璃样的表现。","","N"],["2000-N34",0,"第3节 细胞可逆性损伤","淀粉样变的病理变化",2000,34,"A","","下列哪项关于淀粉样变性的叙述是错误的",[["A","可见于结核病"],["B","可见于骨髓病"],["C","可以是全身性病变"],["D","可以是局灶性病变"],["E","由免疫球蛋白沉积而成"]],"E","淀粉样变是细胞间质内淀粉样蛋白质和黏多糖复合物蓄积，因具有淀粉染色特征而得名。若仅为免疫球蛋白沉积（免疫球蛋白轻链属于淀粉样蛋白质）蓄积，为玻璃样变，如浆细胞胞质粗面内质网中免疫球蛋白蓄积形成Russell小体（E错，为本题正确答案）。","","N"],["2000-N35",0,"第4节 细胞不可逆性损伤（细胞死亡）","凋亡的形态学和生物化学特征",2000,35,"A","","关于固缩性坏死的叙述，哪项是正确的",[["A","固缩性坏死是生理性死亡"],["B","常伴有明显的炎症反应"],["C","凋亡小体是细胞核碎片"],["D","肝细胞碎片状坏死是固缩性坏死"],["E","肝细胞嗜酸性小体是固缩性坏死"]],"E","固缩性坏死为凋亡的旧称，主要见于细胞的生理性死亡，但也见于某些病理过程中（如病毒性肝炎）（A错）。凋亡细胞因其质膜完整，阻止了与其他细胞分子间的识别，故不引起周围炎症反应（B错）。凋亡小体包含细胞核碎片，但也可包含细胞器成分，并且细胞核碎片或细胞器成分是由细胞膜包被的（C错）。肝细胞碎片状坏死（十版病理学P204）是指肝小叶周边部界板肝细胞的灶性坏死和崩解，属于细胞坏死（D错）。肝细胞嗜酸性小体（十版病理学P204）由肝细胞嗜酸性变发展而来，为细胞凋亡（固缩性坏死）的标志，又称凋亡小体（E对）。","","N"],["2000-N36",2,"第4节 栓塞","肺动脉栓塞",2000,36,"A","","关于栓塞的叙述，哪项是正确的",[["A","进入血液的癌细胞均可形成转移癌"],["B","脂肪栓塞均由创伤引起"],["C","羊水栓塞不会引起死亡"],["D","肺动脉血栓栓塞的栓子多来自下肢深静脉"],["E","减压病是氧气栓塞"]],"D","进入血液的癌细胞可被机体的免疫细胞杀死，只有穿出血管在转移器官或组织形成转移灶的才能形成转移癌（A错）。在非创伤性的疾病如糖尿病、酗酒和慢性胰腺炎血脂过高或精神受强烈刺激，过度紧张使呈悬乳状态的血脂不能保持稳定而游离并相互融合形成脂肪滴，也可引起脂肪栓塞（B错）。羊水栓塞是分娩过程中一种罕见严重并发症，死亡率大于80％（C错）。人体从高气压环境迅速进入常压或低气压环境，原来呈溶解状态的气体包括氧气、二氧化碳和氮气迅速游离形成气泡。氧和二氧化碳可再溶于体液内被吸收，但氮气在体液内溶解迟缓，形成很多微气泡或融合成大气泡，引起气体栓塞，即减压病。故减压病是氮气栓塞（E错）。造成肺动脉血栓拴塞的栓子95%以上来自下肢深静脉，来自下肢深静脉的栓子经体循环到达右心房，再经肺循环到达血管较细的肺动脉，造成肺栓塞（D对）。","","N"],["2000-N37",3,"第1节 炎症概述","生物性因子",2000,37,"A","","炎症最常见的原因是",[["A","物理性因子"],["B","化学性因子"],["C","免疫反应"],["D","生物性因子"],["E","机械性因子"]],"D","炎症是具有血管系统的活体组织对各种损伤因子的刺激所发生的以防御性反应为主的基本病理过程。凡是能引起组织和细胞损伤的因子都能引起严重的炎症反应，致炎因子种类繁多可归纳为以下几种：物理性因子、化学性因子、生物性因子、组织坏死、变态反应以及异物等，其中生物性因子为炎症最常见的原因（D对）。","","N"],["2000-N38",3,"第2节 急性炎症","白细胞渗出",2000,38,"A","","下列哪项病理变化最支持炎症的诊断",[["A","细胞变性坏死"],["B","毛细血管扩张充血"],["C","白细胞渗出"],["D","纤维组织增生"],["E","实质细胞增生"]],"C","炎症反应过程中，白细胞参与了一系列复杂的防御过程，其中第一步就是白细胞通过血管壁游出到血管外，即白细胞渗出，这是炎症反应最重要的病理变化（C对）。而细胞变性坏死（A错）、毛细血管扩张充血（B错）、纤维组织增生（D错）及实质细胞增生（E错）均与炎症反应无必然联系（可见于非炎症反应中）。","","N"],["2000-N39",5,"第7节 良性肿瘤与恶性肿瘤的区别","交界性肿瘤概念",2000,39,"A","","交界性肿瘤是指",[["A","既有癌组织、又有肉瘤组织的肿瘤"],["B","既有鳞癌、又有腺癌的肿瘤"],["C","既有上皮组织、又有间叶组织的肿瘤"],["D","介于良性和恶性之间的肿瘤"],["E","以局部浸润为主要特点的低度恶性肿瘤"]],"D","交界性肿瘤是指组织形态和生物学行为介于良恶性肿瘤之间的肿瘤（D对）。既有癌组织、又有肉瘤组织的肿瘤为癌肉瘤（A错）。既有鳞癌、又有腺癌的肿瘤为腺鳞癌（B错）。既有上皮组织，又有间叶组织的肿瘤为良性混合性肿瘤或癌肉瘤（C错）。以局部浸润为主要特点的低度恶性肿瘤为基底细胞癌（E错）。","","N"],["2000-N40",5,"第10节 肿瘤的分子基础","TP53基因",2000,40,"A","","关于p53的叙述，哪项是正确的",[["A","野生型p53蛋白促进细胞生长"],["B","p53基因是肿瘤抑制基因"],["C","p53基因定位于13号染色体"],["D","突变型p53蛋白与生长因子受体同源"],["E","p53基因突变是染色体易位引起的"]],"B","p53基因是肿瘤抑制基因（B对），定位于17号染色体（十版病理学P114）（C错），编码的正常p53蛋白（野生型）能够阻断细胞周期，从而抑制细胞生长（A错）。与生长因子受体同源的是HER2/neu蛋白（与人表皮因子受体同源）等原癌基因表达产物，突变型p53蛋白为抑癌基因p53的表达产物，与生长因子受体无同源性（D错）。p53基因突变多由点突变引起（十版病理学P114）（E错）。","","N"],["2000-N41",7,"第1节 动脉粥样硬化","高脂血症",2000,41,"A","","关于动脉粥样硬化症的描述，哪项是正确的",[["A","主动脉脂纹仅见于中年以上人群"],["B","粥瘤内泡沫细胞均来自单核细胞"],["C","脂纹以主动脉前壁多见"],["D","氧化低密度脂蛋白具有细胞毒性"],["E","粥瘤内胶原由纤维母细胞产生"]],"D","脂纹是动脉粥样硬化的早期病变，脂纹最早可出现于儿童期（二版八年制病理学P183）（A错）。粥瘤内泡沫细胞除来自单核细胞外，还可来自平滑肌细胞（SMC）（B错）。脂纹以主动脉后壁及其分支出口处（C错）多见。氧化低密度脂蛋白（ox-LDL）是最重要的致粥样硬化因子，是损伤内皮细胞和平滑肌细胞的主要因子（即具有细胞毒性）（D对）。粥瘤内胶原由平滑肌细胞（SMC）产生（E错）。","","N"],["2000-N42",7,"第7节 心肌病","心肌病的概念",2000,42,"A","","下列哪项符合原发性心肌病",[["A","炎症性心肌病变"],["B","冠状动脉粥样硬化引起的心肌病变"],["C","原因不明的代谢性心肌病变"],["D","高血压引起的心肌病变"],["E","甲状腺机能亢进引起的心肌病变"]],"C","心肌病是指除冠状动脉粥样硬化（B错）、高血压心脏病（D错）、心脏瓣膜病、先天性心脏病和肺源性心脏病等以外的心肌结构和功能异常为主要表现的一组疾病。广义上的心肌病包括原发性心肌病和继发性心肌病两种（狭义上的心肌病仅指原发性心肌病），原发性心肌病为发病原因不明的代谢性心肌病变（C对），继发性心肌病又称“特异性心肌病”，指继发于炎症（A错）、甲状腺机能亢进（E错）等明确发病原因的心肌改变。","","N"],["2000-N43",8,"第8节 呼吸系统常见肿瘤","神经内分泌癌",2000,43,"A","","下列哪项符合肺小细胞癌",[["A","与吸烟关系不密切"],["B","可伴有异位激素分泌"],["C","起源于化生的上皮细胞"],["D","5年存活率高"],["E","发病率在肺癌中居首位"]],"B","小细胞癌又称小细胞神经内分泌癌，此类型占全部肺癌的10%～20%。患者多为中、老年人，80%以上为男性，且与吸烟密切相关（A错）。这是肺癌中恶性程度最高的一型，生长迅速，转移早，存活期大多不超过一年（D错）。电镜下66%～90%病例的癌细胞胞质中可见神经分泌颗粒，故认为其起源于支气管黏膜上皮的Kulchitsky细胞（C错），是一种可伴有异位激素（由非分泌腺体组织异常分泌的激素）分泌（B对）的神经内分泌肿瘤。在肺癌中发病率居首位是鳞状细胞癌，约占肺癌手术切除标本的60%以上（E错）。","","N"],["2000-N44",10,"第2节 淋巴组织肿瘤","非霍奇金淋巴瘤的概述",2000,44,"A","","关于非霍奇金淋巴瘤的描述，哪项正确",[["A","脑、肝、肾等器官不发生非霍奇金淋巴瘤"],["B","非霍奇金淋巴瘤以T细胞源性多见"],["C","滤泡型及小细胞型非霍奇金淋巴瘤恶性度低"],["D","蕈样霉菌病为B细胞源性"],["E","Burkitt淋巴瘤为T细胞源性"]],"C","非霍奇金淋巴瘤（NHL），以B细胞源性多见（B错），可扩散于全身其他器官组织，如脑、肝、肾等（A错）。滤泡型及小细胞型非霍奇金淋巴瘤属于惰性淋巴瘤，进展缓慢，恶性度低（C对）。蕈样霉菌病是T细胞源性淋巴瘤（D错）。Burkitt淋巴瘤为B细胞源性（E错）。","","N"],["2000-N45",11,"第1节 肾小球疾病","膜增生性肾小球肾炎临床病理联系",2000,45,"A","","下列哪项符合系膜毛细血管性肾小球肾炎",[["A","起病急骤"],["B","常表现急性肾炎综合征"],["C","银染色显示毛细血管壁呈车轨状"],["D","部分病人血清补体升高"],["E","激素和免疫抑制治疗效果明显"]],"C","系膜毛细血管性肾小球肾炎又称膜增生性肾小球肾炎，其特征性病理改变为镜下见基底膜增厚、系膜细胞增生、银染色显示毛细血管壁呈车轨状（C对）。本病常呈慢性进展性（A错），主要表现为肾病综合征（B错）。本病常分为两个类型：Ⅰ型由循环免疫复合物引起，Ⅱ型常出现补体替代途径的异常激活，Ⅱ型中50%～60%的患者的血清C3水平明显下降，C1和C4等补体激活成分水平正常或仅轻微下降（D错）。激素和免疫抑制剂治疗效果常不明显（E错）。","","N"],["2000-N46",16,"第8节 性传播性疾病","梅毒概述",2000,46,"A","","下述哪项关于梅毒的叙述是正确的",[["A","均为性传播"],["B","树胶肿内可见大量类上皮细胞"],["C","树胶肿和血管炎是基本病变"],["D","可导致主动脉瓣狭窄"],["E","骨骼不受累"]],"C","梅毒是由梅毒螺旋体引起的传染病，95%以上经性传播，少数可经输血、接吻、妊娠等传播（A错）。其基本病变是血管炎和树胶样肿（C对）。树胶样肿镜下可见中央凝固性坏死，坏死灶周围肉芽组织中富含淋巴细胞和浆细胞，而上皮样细胞（类上皮细胞）（B错）和朗汉斯巨细胞较少。病变可侵犯主动脉，引起梅毒性主动脉炎、主动脉瓣关闭不全（而非主动脉瓣狭窄）（D错）等。病变亦可侵犯骨骼，鼻骨、长骨、肩胛骨和颅骨最常受累（E错）。","","N"],["2000-N99",7,"第2节 高血压病","细动脉硬化",2000,99,"B","","细动脉硬化",[["A","胶原纤维互相融合，其间伴有多量糖蛋白积聚"],["B","血浆蛋白渗入血管壁"],["C","肾小管上皮吞噬吸收大量血浆蛋白"],["D","前角蛋白成分在肝细胞内聚集"],["E","免疫球蛋白在浆细胞内堆积"]],"B","细小动脉硬化是高血压病的主要病变特征，表现为细小动脉的玻璃样变性。高血压时，细小动脉因长期痉挛，加之血管内皮细胞长期受高血压的刺激，使内皮细胞及基底膜受损，内皮细胞间隙扩大，通透性增强，血浆蛋白渗入血管壁中（B对），使细小动脉发生玻璃样变性，导致细小动脉硬化。胶原纤维互相融合及糖蛋白积聚见于纤维结缔组织玻璃样变（十版病理学P16）（A错）。肾小管上皮细胞吞噬吸收大量血浆蛋白见于肾小管上皮细胞玻璃样变（十版病理学P16）（C错）。前角蛋白成分在肝细胞内聚集见于酒精性肝病时肝细胞玻璃样变（十版病理学P16）（D错）。免疫球蛋白在浆细胞内堆积可形成Russell小体，见于浆细胞玻璃样变（十版病理学P16）（E错）。","","N"],["2000-N100",0,"第3节 细胞可逆性损伤","细胞内玻璃样变",2000,100,"B","","Mallory小体",[["A","胶原纤维互相融合，其间伴有多量糖蛋白积聚"],["B","血浆蛋白渗入血管壁"],["C","肾小管上皮吞噬吸收大量血浆蛋白"],["D","前角蛋白成分在肝细胞内聚集"],["E","免疫球蛋白在浆细胞内堆积"]],"D","Mallory小体是肝细胞玻璃样变，为胞质中细胞中间丝前角蛋白变性（D对），多见于酒精性肝病。胶原纤维互相融合及糖蛋白积聚见于纤维结缔组织玻璃样变（A错）。血浆蛋白渗入血管壁见于动脉粥样硬化（十版病理学P142）或细小动脉硬化（十版病理学P151）（B错）。肾小管上皮细胞吞噬吸收大量血浆蛋白见于肾小管上皮细胞玻璃样变（C错）。免疫球蛋白在浆细胞内堆积可形成Russell小体，见于浆细胞玻璃样变（E错）。","","N"],["2000-N101",16,"第2节 结核病","溃疡型",2000,101,"B","","肠结核",[["A","烧瓶状溃疡"],["B","大小不等、形状不一的浅溃疡"],["C","环形溃疡"],["D","圆形或椭圆形溃疡"],["E","火山口状溃疡"]],"C","肠结核病变沿肠壁淋巴管扩散，而肠壁淋巴管环肠管行走，因此溃疡呈环形（C对），其长轴与肠腔长轴垂直。烧瓶样溃疡（A错）常见于肠阿米巴病（十版病理学P358）。大小不等、形状不一的浅溃疡（B错）又称地图状溃疡，常见于急性细菌性痢疾（十版病理学P351）。圆形或椭圆形溃疡（D错）常见于肠伤寒（十版病理学P350）和胃溃疡（十版病理学P198）。火山口状溃疡（E错）常见于胃癌（十版病理学P216）。","","N"],["2000-N102",16,"第4节 细菌性痢疾","细菌性痢疾病理变化概述",2000,102,"B","","细菌性痢疾",[["A","烧瓶状溃疡"],["B","大小不等、形状不一的浅溃疡"],["C","环形溃疡"],["D","圆形或椭圆形溃疡"],["E","火山口状溃疡"]],"B","细菌性痢疾是由痢疾杆菌引起的一种假膜性炎，当假膜脱落后可形成大小不等、形状不一的浅溃疡（B对），又称地图状溃疡。烧瓶样溃疡（A错）可见于肠阿米巴病（十版病理学P358）。环形溃疡（C错）可见于肠结核（十版病理学P348）。圆形或椭圆形溃疡（D错）可见于肠伤寒（十版病理学P350）。火山口状溃疡（E错）可见于胃癌（十版病理学P216）。","","N"],["2000-N127",9,"第6节 病毒性肝炎","亚急性重型肝炎的病理变化",2000,127,"C","","亚急性重型肝炎",[["A","肝细胞桥接坏死"],["B","肝细胞结节状再生"],["C","二者皆有"],["D","二者皆无"]],"B","亚急性重型肝炎镜下特点为肝细胞的亚大块坏死，由于病程较长可达数周至数月，因而可有肝细胞结节状再生（B对）。肝细胞桥接坏死见于中度及重度慢性肝炎（十版病理学P204）（A错）。","","N"],["2000-N128",9,"第6节 病毒性肝炎","急性（普通型）肝炎的病理变化",2000,128,"C","","急性普通型肝炎",[["A","肝细胞桥接坏死"],["B","肝细胞结节状再生"],["C","二者皆有"],["D","二者皆无"]],"D","急性普通型肝炎肝细胞坏死轻微，仅可见点状坏死（A错），点状坏死的肝细胞能完全再生修复，故无肝细胞结节状再生（B错）。本题AB均错，正确答案为D。","","N"],["2000-N147",8,"第2节 慢性阻塞性肺疾病","肺气肿的病理变化",2000,147,"X","","慢性阻塞性肺气肿的发生与下列哪些因素有关",[["A","小气道的阻塞性通气障碍"],["B","内源性弹性蛋白酶增多"],["C","吸烟"],["D","遗传性α₁-抗胰蛋白酶缺乏"]],"ABCD","慢性阻塞性肺气肿常继发于其他肺阻塞性疾病，其中最常见的是慢性支气管炎。此外，吸烟（C对）、空气污染和肺尘埃沉着病（尘肺）等也是常见的发病原因。其发病机制主要与下列因素有关：1.小气道（小支气管和细支气管）的阻塞性通气障碍（A对），慢性支气管炎时，因慢性炎症使小气道管壁结构遭受破坏及以纤维化为主的增生性改变导致管壁增厚、管腔狭窄；同时黏液性渗出物的增多和黏液栓的形成进一步加剧小气道的通气障碍，使肺排气不畅，残气量过多；2.小气道和肺泡壁弹性降低，正常时细支气管和肺泡壁上的弹力纤维具有支撑作用，并通过回缩力排出末梢肺组织内的残余气体。长期的慢性炎症破坏了大量的弹力纤维（中性粒细胞和巨噬细胞分泌弹性蛋白酶）（B对），使细支气管和肺泡的回缩力减弱；而阻塞性肺通气障碍使细支气管和肺泡长期处于高张力状态，弹性降低，使残气量进一步增多。3.α₁-抗胰蛋白酶水平降低，α₁-抗胰蛋白酶广泛存在于组织和体液中，对包括弹性蛋白酶在内的多种蛋白水解酶有抑制作用。遗传性α₁-抗胰蛋白酶缺乏时（D对），中性粒细胞和巨噬细胞分泌的弹性蛋白酶数量增多、活性增强，破坏了肺组织的结构，使肺泡回缩力减弱。由于上述诸因素的综合作用，使细支气管和肺泡腔残气量不断增多，压力升高，导致细支气管扩张，肺泡最终破裂融合成含气的大囊泡，形成肺气肿。","","N"],["2000-N148",4,"第2节 免疫缺陷病","病因和发病机制",2000,148,"X","","艾滋病的传播途径包括",[["A","经血传播"],["B","性传播"],["C","母婴传播"],["D","粪-口传播"]],"ABC","经血传播（使用被病毒污染的针头、应用含有病毒的血液和血制品）（A对）、性传播（B对）、母婴传播（母体病毒经胎盘或通过哺乳、黏膜接触等方式感染胎儿）（C对）均为艾滋病（AIDS）的传播途径。粪-口传播（消化道传播）（D错）常见于甲型肝炎等疾病（十版病理学P202）。","","N"],["2000-N149",9,"第12节 消化系统常见肿瘤","伴有肠黏膜增生的慢性肠疾病",2000,149,"X","","大肠癌的癌前病变有",[["A","大肠腺瘤性息肉"],["B","家族性息肉病"],["C","溃疡性结肠炎"],["D","绒毛状腺瘤"]],"ABCD","大肠腺瘤性息肉（大肠息肉状腺瘤）（A对）、家族性息肉病（家族性腺瘤性息肉病）（B对）、溃疡性结肠炎（C对）、绒毛状腺瘤（D对）均为伴有肠黏膜增生的慢性肠疾病，与大肠癌的发生密切相关，其中家族性息肉病与遗传因素有关，如不予治疗，将不可避免地出现癌变。","","N"],["2000-N150",4,"","",2000,150,"X","","系统性红斑狼疮的病理特点有",[["A","抗核抗体阳性"],["B","脾小动脉洋葱皮样改变"],["C","心瓣膜细菌性心内膜炎"],["D","肾小球内出现苏木紫小体"]],"ABD","系统性红斑狼疮（SLE）发生的根本原因是免疫耐受的终止和破坏，导致大量自身抗体产生，最主要的是抗核抗体（A对）。SLE的特征性病理变化有脾小动脉周围纤维化，出现洋葱皮样改变（B对），肾小球内出现苏木紫小体（八、九、十版病理学称苏木素小体）（D对）等。SLE可引起非细菌性心内膜炎（Libman-Sacks血栓性心内膜炎）（C错）。","","N"],["2001-N33",0,"第3节 细胞可逆性损伤","脂肪变的病理变化",2001,33,"A","","关于脂肪变性的描述，正确的是",[["A","磷中毒时，脂肪变性首先累及肝小叶中央的细胞"],["B","肝淤血时，脂肪变性首先累及肝小叶周边的肝细胞"],["C","肾远曲小管容易发生脂肪变性"],["D","严重贫血时，心脏乳头肌可呈虎斑状"],["E","心肌脂肪变性常严重影响心脏功能"]],"D","甘油三酯蓄积于非脂肪细胞的细胞质中称为脂肪变，多发生于肝细胞、心肌细胞、肾小管上皮细胞和骨骼肌细胞等，其中以肝细胞的脂肪变最为常见。慢性肝淤血时，肝小叶中央区缺氧较重，因此脂肪变首先累及肝小叶中央的细胞（B错）；磷中毒时，小叶周边带肝细胞对磷中毒更为敏感，故以脂肪变首先累及肝小叶周边的肝细胞（A错）。肾小管上皮细胞也可发生脂肪变，但主要发生于肾近曲小管，严重时才累及肾远曲小管（C错）。严重贫血（缺氧）时可引起心肌细胞脂肪变，常累及左心室内膜下和乳头肌部位，脂肪变心肌呈黄色，与正常心肌的暗红色相间，称虎斑心（D对）。严重的心肌脂肪变性才能影响心脏功能（E错）。","","N"],["2001-N34",2,"第3节 血栓形成","混合血栓",2001,34,"A","","心房纤颤时，左心房内的球形血栓是",[["A","混合性血栓"],["B","白色血栓"],["C","红色血栓"],["D","透明血栓"],["E","延续性血栓"]],"A","发生于心房内的血栓为混合血栓，由于心房的收缩和舒张，混合血栓呈球形（A对）。","","N"],["2001-N35",4,"第2节 免疫缺陷病","淋巴组织的变化",2001,35,"A","","AIDS患者晚期淋巴结的病理变化特点是",[["A","淋巴滤泡增生"],["B","副皮质区增生"],["C","窦组织细胞增生"],["D","淋巴细胞消失殆尽"],["E","副皮质区变窄"]],"D","AIDS（艾滋病）的病理变化过程主要是：早期，淋巴结肿大，淋巴滤泡增生（A错），生发中心活跃。随着病情发展，滤泡外层淋巴细胞减少或消失，副皮质区CD4⁺T细胞进行性减少，小血管增生，生发中心被零落分割。晚期，淋巴结呈现一片荒芜，副皮质区（BE错）及淋巴滤泡消失，淋巴细胞几乎消失殆尽（D对），仅残留少许巨噬细胞和浆细胞。窦组织细胞增生（C错）见于罗道病（Rosai-Dorfman病），后者是一种良性淋巴组织增生性疾病，与AIDS无关。","","N"],["2001-N36",4,"第2节 免疫缺陷病","原发性免疫缺陷病",2001,36,"A","","关于免疫缺陷病的描述，正确的是",[["A","Bruton综合征与X染色体隐性遗传有关"],["B","Di George综合征患者外周血中B细胞减少"],["C","原发性免疫缺陷病较继发性免疫缺陷病多见"],["D","获得性免疫缺陷常引起单一性机会性感染"],["E","慢性肉芽肿病是一种常染色体隐性遗传病"]],"A","Bruton综合征与X染色体隐性遗传有关（A对），多见于男性婴幼儿，以血液循环中B细胞及γ球蛋白缺乏为主要特征。Di George综合征（先天性胸腺发育不良综合征）是一种以T淋巴细胞免疫缺陷为主的原发性免疫缺陷病，患者外周血中成熟T细胞减少（B错）。原发性免疫缺陷病较继发性免疫缺陷病少见（C错）。获得性（继发性）免疫性缺陷常引起多发性机会感染（D错）。慢性肉芽肿病是一种致死性遗传性白细胞功能缺陷病，以皮肤、肺及淋巴结的广泛肉芽肿性损害为主要特征。患者中2/3为X染色体连锁隐性遗传，1/3为常染色体隐性遗传，两性均可发病（E错）。","","N"],["2001-N37",3,"第2节 急性炎症","白细胞黏附",2001,37,"A","","炎症时，内皮细胞与白细胞粘着主要是由于",[["A","血流缓慢"],["B","细胞表面负电荷减少"],["C","细胞表面粘附分子数量增加且亲和性增加"],["D","趋化因子吸引"],["E","内皮细胞损伤"]],"C","白细胞紧紧黏附于内皮细胞是白细胞从血管中游出的前提。该过程是由白细胞表面的整合素与内皮细胞表达的配体介导的。在炎症过程中，内皮细胞、巨噬细胞和成纤维细胞等释放的化学趋化因子，激活附着于内皮细胞的白细胞，白细胞表面的整合素发生构象改变，转变为高亲和力的形式（亲和力增加）。与此同时，内皮细胞被巨噬细胞释放的TNF和IL-1等细胞因子激活，整合素配体表达量增加（粘附分子数量增加）。白细胞表面的整合素与其配体结合后，白细胞的骨架发生改变，导致其紧密黏附于内皮细胞（C对）。血流缓慢（有利于白细胞边集）（A错）、细胞表面负电荷减少（降低内皮细胞与白细胞的相互排斥作用）（B错）均有利于炎症时内皮细胞与白细胞的粘着，但二者并不起主要作用。趋化因子吸引（D错）和内皮细胞损伤（E错）与白细胞游出和在组织中游走有关，与内皮细胞与白细胞粘着无关。","","N"],["2001-N38",5,"","",2001,38,"A","","关于恶性肿瘤的超微结构的叙述，错误的是",[["A","细胞器数目减少"],["B","可见核内陷和怪形核"],["C","可见特异性超微结构"],["D","细胞间连接减少"],["E","核仁数目增多"]],"C","恶性肿瘤细胞根据其分化的程度表现出不同的异型性。总体来说，恶性肿瘤细胞核体积增大，核膜可有内陷或外凸，使核形不规则甚至形成怪形核（B对），核仁明显，体积大，数目增多（E对）。胞浆内的细胞器常有数目减少（A对）、发育不良或形态异常。细胞连接常有减少（D对），有利于肿瘤浸润生长。以上异型性改变是区别良恶性肿瘤的重要标准，但不具有特异性（在良性肿瘤中也可有不同程度的肿瘤异型性）。肿瘤超微结构的异型性未发现有质的差别，仅有量的差别，包括同型性、低分化性和异型性。超微结构是使用电子显微镜观察到的细胞结构，目前尚未发现可区别良恶性肿瘤的特殊超微结构的改变（2版八年制病理学P118）。","","N"],["2001-N39",13,"第2节 甲状腺疾病","髓样癌",2001,39,"A","","甲状腺髓样癌是一种",[["A","交界性肿瘤"],["B","鳞癌"],["C","未分化癌"],["D","迷离瘤"],["E","神经内分泌肿瘤"]],"E","甲状腺髓样癌是由滤泡旁降钙素分泌细胞（即甲状腺C细胞）发生的恶性肿瘤，滤泡旁降钙素分泌细胞属于APUD细胞（神经内分泌细胞）（十版病理学P297），故甲状腺髓样癌是一种神经内分泌肿瘤（E对）。交界性肿瘤（十版病理学P103）（A）是指介于良性和恶性之间的肿瘤。鳞癌（十版病理学P104）（B）是一种发生于上皮组织的恶性肿瘤，多见于有鳞状上皮覆盖或可发生鳞状上皮化生的部位。未分化癌（十版病理学P92）（C）是指缺乏细胞分化特征的恶性肿瘤，可见于甲状腺癌（十版病理学P296）、肺癌（十版病理学P189）、胃癌（十版病理学P216）等。迷离瘤（二版八年制病理学 P128）（D）指分化正常的组织误位于异常部位而形成的包块。","","N"],["2001-N40",7,"第2节 高血压病","恶性高血压",2001,40,"A","","下列符合恶性高血压特征性病理变化的是",[["A","肾入球小动脉玻璃样变性"],["B","肾细动脉壁纤维素样坏死"],["C","肾动脉粥瘤"],["D","肾小球毛细血管内透明血栓"],["E","肾小球纤维化"]],"B","恶性高血压又称急进型高血压，特征性病理变化是增生性小动脉硬化和坏死性细动脉炎（主要累及肾）。前者主要表现为动脉内膜明显增厚，伴有平滑肌细胞增生，胶原纤维增多，致血管壁呈层状洋葱皮样增厚，管腔狭窄。后者主要表现为动脉内膜和中膜发生纤维素样坏死（B对），周围有单核细胞及中性粒细胞浸润。肾入球小动脉玻璃样变性（十版病理学P151）为良性高血压的病理变化（A错）。动脉粥瘤（十版病理学P143）见于动脉粥样硬化时（C错）。肾小球毛细血管内透明血栓（十版病理学P49）的形成见于弥散性血管内凝血（DIC）（D错）。肾小球纤维化见于慢性肾小球肾炎（十版病理学P260）、肾移植慢性排斥反应（十版病理学P89）等肾的慢性炎症反应（E错）。","","N"],["2001-N41",8,"第5节 肺尘埃沉着病","肺硅沉着病的病因及发病机制",2001,41,"A","","关于硅肺的描述，正确的是",[["A","大于5μm的硅尘致病性强"],["B","硅酸导致巨噬细胞自溶"],["C","硅结节内无免疫球蛋白"],["D","纤维性结节是硅肺的早期病变"],["E","胸膜常无病变"]],"B","硅尘颗粒＞5μm者经过上呼吸道时易附着于黏膜表面，大多被黏液-纤毛排送系统清除出体外，故致病性弱（A错）。吸入肺组织的硅尘被巨噬细胞吞入后，SiO₂与水聚合形成硅酸（一种强的成氢键化合物），硅酸可通过各种机制使溶酶体破裂并释放多种溶酶体酶，导致巨噬细胞崩解自溶（B对）。玻璃样变的硅结节内含较多的免疫球蛋白（C错）。硅肺的早期病变是由吞噬硅尘的巨噬细胞聚集形成的细胞性结节（D错）。晚期硅肺纤维化肺组织可达全肺2/3以上，胸膜也可因弥漫性纤维化而广泛增厚（E错），厚度可达1～2cm。","","N"],["2001-N42",9,"第12节 消化系统常见肿瘤","伴有肠黏膜增生的慢性肠疾病",2001,42,"A","","下述疾病中，与大肠癌关系不密切的是",[["A","家族性腺瘤性息肉病"],["B","绒毛状腺瘤"],["C","息肉状腺瘤"],["D","混合型腺瘤"],["E","增生性息肉"]],"E","家族性腺瘤性息肉病（A对）、绒毛状腺瘤（B对）、息肉状腺瘤（C对）和混合型腺瘤（D对）均为伴有肠黏膜增生的慢性肠疾病，与大肠癌的发生密切相关，其中家族性腺瘤性息肉病与遗传因素有关，如不予治疗，将不可避免地出现癌变。增生性息肉（E错，为本题正确答案）发生癌变的可能性小，与大肠癌无关。注：注意区分息肉与息肉病，前者只有少量息肉增生，癌变可能性很小，后者有大量息肉增生，癌变可能性大，为癌前病变。","","N"],["2001-N43",11,"第1节 肾小球疾病","急进性肾小球肾炎病因",2001,43,"A","","肺出血肾炎综合征患者咯血是由于",[["A","肺淤血"],["B","尿毒症引起肺部炎症"],["C","肺内小动脉破裂"],["D","交叉免疫反应引起的肺损害"],["E","肺内空洞"]],"D","肺出血肾炎综合征（Goodpasture综合征）常见于Ⅰ型急进性肾小球肾炎患者，患者之所以有咯血症状，是由于抗GBM抗体（抗肾小球基膜抗体）与肺泡基膜发生交叉免疫反应引起了肺损害（D对）。","","N"],["2001-N44",10,"第2节 淋巴组织肿瘤","伯基特淋巴瘤临床表现",2001,44,"A","","下列描述中，不符合Burkitt淋巴瘤的是",[["A","多累及颈部淋巴结"],["B","B细胞来源"],["C","与EB病毒感染有关"],["D","多见于儿童和青年"],["E","化疗效果较好"]],"A","Burkitt淋巴瘤（BL）常发生于淋巴结外的器官和组织，最常累及颌骨，一般不累及外周淋巴结（颈部淋巴结）（A错，为本题正确答案）和脾脏。BL为B细胞来源（B对）的淋巴瘤，其发生（尤其是非洲地方性BL的发生）多与EB病毒（C对）感染有关，多见于儿童和青少年（D对）。BL属于高度侵袭性淋巴瘤，肿瘤细胞倍增时间短，病情重，但短期、大剂量化疗效果较好（E对），多数儿童和年轻患者可痊愈。","","N"],["2001-N45",16,"第2节 结核病","继发性肺结核病概述",2001,45,"A","","下列描述中，不符合继发性肺结核病的是",[["A","以内源性再感染为主"],["B","以淋巴道和血道播散为主"],["C","以气道播散为主"],["D","多从肺尖开始"],["E","新旧病变交杂"]],"B","继发性肺结核病的发病有两种方式（九版内科学P64）：一种方式是由于受到原发性结核感染时期遗留病灶中的结核杆菌再感染而发病，此为主要发病方式，称为内源性再感染（A对）；另一种方式是由于受到外来结核杆菌的再感染而发病，称为外源性再感染。继发性肺结核的病理特点有：①病变最先并最常见于肺尖部（D对），因此病变呈上旧下新、上重下轻的特点；②病程长，病变复杂，随着机体免疫反应和变态反应的消长，新旧病灶交错（E对），临床症状时好时坏；③以气道播散为主（C对）（B错，为本题正确答案），多局限于肺内。","","N"],["2001-N46",16,"第10节 寄生虫病","虫卵引起的损害概述",2001,46,"A","","血吸虫病时，引起机体严重损害的是",[["A","尾蚴"],["B","童虫"],["C","成虫"],["D","虫卵"],["E","死亡虫体"]],"D","血吸虫病时，引起机体严重损害的是虫卵（D对），虫卵沉着于乙状结肠、直肠和肝等处，形成虫卵结节，造成损害。尾蚴（A错）主要引起尾蚴性皮炎，表现为入侵局部瘙痒的小丘疹，数日后自然消退。童虫（B错）可引起肺组织充血、水肿、点状出血及白细胞浸润，但病变一般轻微而短暂。成虫（C错）对机体的损害作用较轻。","","N"],["2001-N99",5,"第8节 常见肿瘤举例","上皮组织恶性肿瘤",2001,99,"B","","实性癌的组织学表现是",[["A","癌细胞团中央可见角化珠"],["B","癌细胞团漂浮在粘液内"],["C","黏液将癌细胞核推向一侧"],["D","癌细胞呈条索状排列"],["E","癌细胞形成乳头结构"]],"D","实性癌又称单纯癌，属于低分化的腺癌，恶性程度较高，多发生于乳腺，少数可发生于胃及甲状腺，癌细胞呈条索状排列（D对），癌巢内无或很少有腺腔样结构，细胞异型性高，核分裂象多见。","","N"],["2001-N100",5,"第4节 肿瘤的生长和扩散","种植性转移",2001,100,"B","","印戒细胞癌的组织学表现",[["A","癌细胞团中央可见角化珠"],["B","癌细胞团漂浮在粘液内"],["C","黏液将癌细胞核推向一侧"],["D","癌细胞呈条索状排列"],["E","癌细胞形成乳头结构"]],"C","黏液腺癌（黏液癌）的黏液一般分泌至癌细胞外，可形成黏液池使癌细胞团漂浮在黏液内（B错）。但有时黏液会潴留在癌细胞内，将核推向一侧（C对），形成的癌细胞呈印戒状，称为印戒细胞癌。癌细胞团中央可见角化珠（十版病理学P104）见于分化较好的鳞状细胞癌（A错）。癌细胞形成乳头结构（十版病理学P104）为乳头状腺癌（E错）。癌细胞呈条索状排列可见于实性癌（低分化的腺癌，恶性程度较高），如低分化肺腺癌（十版病理学P191）（D错）。","","N"],["2001-N101",9,"第6节 病毒性肝炎","大块及亚大块坏死",2001,101,"B","","急性重型肝炎的病理学特点是",[["A","肝细胞点灶状坏死"],["B","肝细胞碎片状坏死"],["C","肝细胞桥接坏死"],["D","肝细胞亚大片坏死"],["E","肝细胞大片坏死"]],"E","急性重型肝炎起病急骤，镜下表现为肝细胞坏死广泛而严重，肝细胞索解离，肝细胞溶解，出现弥漫性大片坏死（E对）。点灶状坏死（病理学未提及灶状坏死概念，可参见八版传染病学P26，灶状坏死比点状坏死略大，有时二者并不作区分而合称点灶状坏死）常见于急性普通型肝炎（A错）。碎片坏死常见于慢性肝炎（B错）。桥接坏死常见于中、重度慢性肝炎（C错）。亚大片状坏死常见于亚急性重型肝炎（D错）。","","N"],["2001-N102",9,"第6节 病毒性肝炎","点状坏死",2001,102,"B","","急性普通型肝炎的病理学特点是",[["A","肝细胞点灶状坏死"],["B","肝细胞碎片状坏死"],["C","肝细胞桥接坏死"],["D","肝细胞亚大片坏死"],["E","肝细胞大片坏死"]],"A","急性普通型肝炎时肝细胞坏死轻微，肝细胞呈点灶状坏死（病理学未提及灶状坏死概念，可参见八版传染病学P26，灶状坏死比点状坏死略大，有时二者并不作区分而合称点灶状坏死）（A对）。碎片状坏死常见于慢性肝炎（B错）。桥接坏死常见于中、重度慢性肝炎（C错）。亚大片状坏死常见于亚急性重型肝炎（D错）。大片坏死常见于急性重型肝炎和亚急性重型肝炎（E错）。","","N"],["2001-N127",9,"","",2001,127,"C","","胃癌可引起",[["A","出血"],["B","狭窄"],["C","二者都有"],["D","二者都无"]],"C","胃癌的并发症（九版内科学P366）有：1.出血（A对），多呈呕血或黑粪；2.幽门或贲门狭窄（B对），甚至梗阻；3.穿孔。本题AB均对，正确答案为C。","","N"],["2001-N128",9,"第12节 消化系统常见肿瘤","结直肠癌病理变化概述",2001,128,"C","","大肠癌可引起",[["A","出血"],["B","狭窄"],["C","二者都有"],["D","二者都无"]],"C","大肠癌既可因肿瘤坏死脱落引起出血，也可因肿瘤浸润生长引起肠腔狭窄。本题AB均对，正确答案为C。","","N"],["2001-N147",0,"第3节 细胞可逆性损伤","病理性钙化的类型",2001,147,"X","","关于病理性钙化的叙述，正确的是",[["A","HE染色时呈蓝色颗粒状"],["B","营养不良性钙化多见"],["C","转移性钙化多见于肾小管、肺泡和胃黏膜"],["D","营养不良性钙化多见于变性坏死组织、坏死的虫卵等"]],"ABCD","病理性钙化是指骨和牙齿之外的组织中固态钙盐沉积，沉积的钙盐在HE染色时可呈蓝色颗粒状（A对）。病理性钙化有营养不良性钙化和转移性钙化两种形式，以营养不良性钙化多见（B对）。转移性钙化是由于全身钙磷代谢失调而致钙盐沉积于正常组织内，主要见甲状旁腺功能亢进、维生素D摄入过多、肾衰及某些骨肿瘤，多见于肾小管、肺泡和胃黏膜等处（C对）。营养不良性钙化为钙盐沉积于坏死或即将坏死的组织、异物、坏死的虫卵等（D对），见于结核病、血吸虫病、血栓、动脉粥样硬化斑块、心脏瓣膜病变及瘢痕组织。","","N"],["2001-N148",3,"第2节 急性炎症","趋化作用",2001,148,"X","","炎症反应中，具有趋化作用的物质有",[["A","可溶性细菌产物"],["B","C₃ₐ"],["C","白细胞三烯B₄"],["D","IL₈"]],"ABCD","趋化作用是指白细胞被趋化因子吸引，朝趋化因子所在处游走的现象。趋化因子可以是外源性的细菌产物（A对），也可以是内源性的炎性介质，如补体成分（C5a、C3a等）（B对）、白细胞三烯B₄（C对）和IL-8（D对）。","","N"],["2001-N149",3,"第2节 急性炎症","血管通透性增加",2001,149,"X","","炎症时，引起血管通透性增加的因素有",[["A","血管内皮细胞损伤"],["B","新生毛细血管增多"],["C","血管扩张"],["D","内皮细胞间隙加宽"]],"ABD","在炎症过程中，引起血管通透性增加的机制有：①内皮细胞收缩，内皮间隙加宽（D对），使血管通透性增高；②内皮细胞受损（A对）或基底膜受损，使血管通透性增高；③内皮细胞吞饮增加，细胞的穿胞作用增强，使血管通透性增加；④新生毛细血管增多（B对），新生毛细血管内皮细胞连接不健全，使血管通透性增加。血管扩张是急性炎症过程中的血管反应，导致局部血流加快、血流量和能量供应增加，这是炎症局部组织发红和发热的原因，但血管扩张与血管通透性无关（C错）。","","N"],["2001-N150",2,"第3节 血栓形成","心血管内皮细胞损伤",2001,150,"X","","心血管内膜受损时，促进血栓形成的因素有",[["A","内皮下胶原"],["B","组织因子"],["C","纤维连接蛋白"],["D","凝血酶敏感蛋白"]],"ABCD","心血管内膜受损时，暴露内皮下胶原（A对），活化血小板和凝血因子Ⅻ，启动了内源性凝血过程（九版生理学P75）。与此同时，损伤的内皮细胞暴露组织因子（B对），激活凝血因子Ⅶ，启动外源性凝血过程（九版生理学P75）。纤维连接蛋白又称纤连蛋白，广泛分布于人体细胞表面和血浆中，心血管内膜受损时，纤维连接蛋白（C对）能够促进凝血过程中血小板与受损部位的粘附。凝血酶敏感蛋白（D对）最初发现于血小板内，又称血小板反应蛋白，心血管内膜受损时，凝血酶敏感蛋白能够促进凝血过程中血小板与血小板之间的聚集。","","N"],["2002-N33",16,"第4节 细菌性痢疾","急性细菌性痢疾",2002,33,"A","","急性细菌性痢疾的典型肠道病变性质为",[["A","化脓性炎"],["B","卡他性炎"],["C","假膜性炎"],["D","出血性化脓性炎"],["E","蜂窝织炎"]],"C","急性细菌性痢疾是一种以大量纤维素渗出为特征的假膜性肠炎（C对）。急性细菌性痢疾病变初期可见卡他性炎，但卡他性炎缺乏典型性（B错）。化脓性炎（十版病理学P73）（A错）常见于金黄色葡萄球菌、链球菌等化脓菌引起的各种急性炎症。出血性化脓性炎（D错）是指出血性炎与化脓性炎合并存在的情况，可见于流行性出血热、钩端螺旋体病和鼠疫等出血性炎（十版病理学P73）发生化脓性感染时。蜂窝织炎（十版病理学P73）（E错）为溶血性链球菌引起的化脓性炎，常见于急性阑尾炎。","","N"],["2002-N34",16,"第2节 结核病","肠结核病概述",2002,34,"A","","肠结核最好发于",[["A","回盲部"],["B","空肠"],["C","降结肠"],["D","升结肠"],["E","十二指肠"]],"A","肠结核最好发于回盲部（A对），其原因（二版八年制病理学P461）有二：一是肠内容物在回盲部停留时间较长，结核杆菌在此与肠内黏膜接触时间也较长；二是回盲部淋巴组织丰富，而结核杆菌易寄居于淋巴结。","","N"],["2002-N35",4,"第2节 免疫缺陷病","淋巴组织的变化",2002,35,"A","","AIDS病人晚期外周血细胞减少最显著的是",[["A","CD4⁺细胞"],["B","CD8⁺细胞"],["C","CD16⁺细胞"],["D","CD14⁺细胞"],["E","CD56⁺细胞"]],"A","艾滋病（AIDS）是由人类免疫缺陷病毒（HIV）感染引起的继发性免疫缺陷病。CD4分子是HIV进入人体的门户，当HIV感染人体时，CD4⁺T细胞在HIV直接和间接的作用下大量破坏、严重受损，到病程晚期，外周血CD4⁺T（A对）细胞减少显著。","","N"],["2002-N36",4,"","",2002,36,"A","","一般不出现于SLE患者体内的抗体是",[["A","抗核抗体"],["B","抗链球菌抗体"],["C","抗Sm抗体"],["D","抗DNA抗体"],["E","抗组蛋白抗体"]],"B","抗链球菌抗体多存在于与溶血性链球菌感染有关的变态反应性疾病中，如风湿病（十版病理学P154）和急性肾炎（十版病理学P254），而系统性红斑狼疮（SLE）是一种慢性自身免疫病，一般不出现抗链球菌抗体（B错，为本题正确答案）。SLE患者体内含有多种自身抗体，其中抗核抗体（A对）是最主要的，它可分为四类：抗DNA抗体（D对）、抗组蛋白抗体（E对）、抗RNA-非组蛋白抗体（抗Sm抗体）（C对）和抗核仁抗原抗体。","","N"],["2002-N37",11,"第1节 肾小球疾病","微小病变性肾小球病病理变化",2002,37,"A","","引起儿童肾病综合征的最常见肾小球疾病是",[["A","脂性肾病"],["B","新月体性肾炎"],["C","IgA肾病"],["D","节段性肾炎"],["E","弥漫增生型肾炎"]],"A","微小病变性肾小球肾炎又称脂性肾病，是引起儿童肾病综合征最常见的肾小球疾病（A对）。新月体性肾炎（B错）、弥漫增生型肾炎（急性肾炎）（E错）均不引起肾病综合征。IgA肾病（C错）较少引起肾病综合征（八版内科学P486）。（局灶）节段性肾炎（D错）引起肾病综合征，但以青少年多见（九版内科学P472）。","","N"],["2002-N38",7,"第4节 风湿病","风湿病的病因和发病机制",2002,38,"A","","下列有关风湿病的描述，错误的是",[["A","属于变态反应性疾病"],["B","发病与溶血性链球菌感染有关"],["C","以心脏病变的后果最为严重"],["D","风湿性关节炎常导致关节畸形"],["E","皮下结节和环形红斑有助于临床诊断"]],"D","风湿病是一种与A组β溶血链球菌感染有关（B对）的变态反应性疾病（A对）。病变最常累及心脏、关节和血管等处，以心脏病变最为严重（C对）。风湿性关节炎主要为关节滑膜的浆液性炎症（虽然关节腔也有纤维蛋白渗出），急性期后，炎症渗出物易被完全吸收，一般不留后遗症（易留后遗症的是P80类风湿性关节炎）（D错，为本题正确答案）。风湿病的急性期有发热、心脏和关节损害、环形红斑、皮下小结（E对）、舞蹈病等症状和体征，这些症状和体征有助于对风湿病的临床诊断。","","N"],["2002-N39",5,"第9节 癌前病变和原位癌","异型增生和原位癌",2002,39,"A","","原位癌是指",[["A","早期癌"],["B","原发癌"],["C","癌前病变"],["D","未发生转移的癌"],["E","未突破基底膜的癌"]],"E","原位癌指异型增生的细胞在形态和生物学特征上与癌细胞相同，常累及上皮的全层，但未突破基底膜向下浸润（E对）。早期癌（A错）是指癌浸润仅限于黏膜层及黏膜下层者，未侵犯肌层，无论是否存在淋巴结转移，如早期食管癌（十版病理学P215）。原发癌（B错）指原来正常组织和细胞因自身恶变发生的恶性肿瘤（与转移癌对应）。癌前病变（C错）是一些本身不是恶性肿瘤，而有发展成为恶性肿瘤的潜能疾病，如大肠腺瘤、慢性溃疡性结肠炎等。","","N"],["2002-N40",5,"第8节 常见肿瘤举例","软骨瘤",2002,40,"A","","不发生癌的组织是",[["A","皮肤附件"],["B","肾上腺"],["C","子宫内膜"],["D","甲状旁腺"],["E","软骨组织"]],"E","来源于上皮组织的恶性肿瘤统称为癌，间叶组织的恶性肿瘤统称为肉瘤。皮肤附件（A对）、肾上腺（B对）、子宫内膜（C对）、甲状旁腺（D对）均属上皮组织来源，都有可能发生癌，而软骨组织来源于间叶组织，只可能发生肉瘤（E错，为本题正确答案）。","","N"],["2002-N41",5,"第3节 肿瘤的命名与分类","肿瘤的分类",2002,41,"A","","下列肿瘤中，属于良性的是",[["A","淋巴瘤"],["B","黑色素瘤"],["C","神经鞘瘤"],["D","肾母细胞瘤"],["E","精原细胞瘤"]],"C","淋巴瘤（十版病理学P226）为原发于淋巴结和结外淋巴组织的恶性肿瘤（A错）。黑色素瘤（十版病理学P108）为皮肤、黏膜及内脏黑色素细胞产生的恶性肿瘤（B错），又称恶性黑色素瘤。神经鞘瘤（十版病理学P324）为起源于胚胎期神经嵴来源的神经膜细胞或施万细胞的良性肿瘤（C对）。肾母细胞瘤（十版病理学P266）为起源于后肾胚基组织的恶性肿瘤（D错）。精原细胞瘤（十版病理学P281）为发生于睾丸原始生殖细胞的恶性肿瘤（E错）。在历年西医综合真题中，良恶性肿瘤的鉴别反复出现，现将常考的良恶性肿瘤归纳如下——良性肿瘤：骨母细胞瘤、软骨母细胞瘤、脂肪母细胞瘤、肌母细胞瘤、葡萄胎、血管瘤、神经鞘瘤（C对）、纤维腺瘤、多形性腺瘤；恶性肿瘤：淋巴瘤（A错）、白血病、黑色素瘤（B错）、视网膜母细胞瘤、神经母细胞瘤、肾母细胞瘤（D错）、肝母细胞瘤、绒毛膜癌、无性细胞瘤、精原细胞瘤（E错）、骨髓瘤、尤文氏瘤。","","N"],["2002-N42",7,"第4节 风湿病","风湿性心内膜炎",2002,42,"A","","疣状赘生物是指",[["A","心内膜增生物"],["B","心内膜上的新生物"],["C","心瓣膜纤维化"],["D","心瓣膜上的附壁血栓"],["E","心瓣膜钙化"]],"D","风湿性心内膜炎病变初期可在瓣膜上形成由血小板和纤维蛋白构成的疣状赘生物，附着牢固，为白色血栓。本题给出的参考答案为D，但附壁血栓为发生于心腔内、动脉粥样硬化溃疡部位或动脉瘤内的混合血栓，并非白色血栓，故本题并不严谨。","","N"],["2002-N43",2,"第3节 血栓形成","透明血栓",2002,43,"A","","透明血栓最常见于",[["A","小静脉"],["B","小动脉"],["C","中动脉"],["D","大静脉"],["E","毛细血管"]],"E","血栓类型可分为四种：白色血栓、混合血栓、红色血栓和透明血栓。各种类型血栓易发生的部位：①白色血栓：血流较快的心瓣膜、心腔内、动脉内；②混合血栓：血流缓慢的静脉内；③红色血栓：血流缓慢的静脉内；④透明血栓：微循环的毛细血管内（E对）。","","N"],["2002-N44",0,"第1节 适应","萎缩的病理变化",2002,44,"A","","萎缩的心肌细胞内常可出现",[["A","橙色血质"],["B","脂褐素"],["C","疟色素"],["D","含铁血黄素"],["E","黑色素"]],"B","橙色血质化学结构与胆红素相同，由血红蛋白在无氧条件下分解而形成，常见于梗死组织，大出血灶或血肿的中心部，通常见于细胞外，有时可被巨噬细胞吞噬（A错）。脂褐素是细胞内未被彻底消化的富含磷脂的膜包被细胞器残体，常见于萎缩的细胞中比如萎缩的心肌细胞中（B对）。疟色素是由疟原虫侵入红细胞后，将血红蛋白改变为一种黑褐色颗粒，沉积于成熟疟原虫尸体内，后被网状内皮细胞所吞噬，常于肝、脾等器官的网状内皮细胞（C错）。含铁血黄素是由巨噬细胞吞噬、降解红细胞血红蛋白所产生的铁蛋白微粒聚集体，生理、病理情况下均可见（D错）。除黑色素细胞外，黑色素还可聚集于皮肤基底部的角质细胞及真皮的巨噬细胞内，病理情况下还可见于色素痣、黑色素瘤、基底细胞癌等（E错）。","","N"],["2002-N45",0,"第3节 细胞可逆性损伤","玻璃样变的病理变化",2002,45,"A","","不属于玻璃样变的病变是",[["A","Aschoff小体"],["B","Rusell小体"],["C","Councilman小体"],["D","Mallory小体"],["E","Negri小体"]],"A","玻璃样变又称透明变，为细胞内或间质中出现的蛋白质异常蓄积。浆细胞胞质粗面内质网中免疫球蛋白蓄积，形成Rusell小体，为玻璃样变（B对）。酒精性肝病时，肝细胞胞质中细胞中间丝前角蛋白变性，形成Mallory小体，亦为玻璃样变（D对）。Aschoff小体（十版病理学P155）为风湿肉芽肿，由大量风湿细胞和少量淋巴细胞和浆细胞构成，不属于玻璃样变（A错，为本题正确答案）。Councilman小体（十版病理学P204）又称嗜酸性小体或康氏小体，为细胞凋亡过程中的玻璃样变性（即嗜酸性透明变性）（C对），常见于黄热病毒引起的病毒性肝炎。Negri小体（十版病理学P306）又称内基小体，为狂犬病时神经细胞胞质内的嗜酸性病毒包涵体（蛋白质性质的病变结构），属于玻璃样变性（E对）。也有观点认为Councilman小体和Negri小体不属于玻璃样变性，此题答案存在争议。","","N"],["2002-N46",0,"第1节 适应","化生的类型",2002,46,"A","","化生不可能发生于",[["A","肾盂黏膜上皮"],["B","结缔组织"],["C","支气管上皮"],["D","宫颈柱状上皮"],["E","神经纤维"]],"E","化生有多种类型，通常发生在同源性细胞之间，即上皮细胞之间或间叶细胞之间，且化生通常只出现在分裂增殖能力较活跃的细胞类型中 。肾盂黏膜上皮（A错）、支气管上皮（C错）、宫颈柱状上皮（D错）属于上皮组织，为具有很强分裂增殖能力的不稳定细胞（十版病理学P25），结缔组织属于间叶组织（B错），为具有潜在分裂增殖能力的稳定细胞，在有害因素的作用下，以上组织均可发生化生而转变为其他组织类型。神经纤维（神经细胞）既不属于上皮细胞，也不属于间叶细胞，不会发生化生（E对）。","","N"],["2002-N99",8,"第1节 呼吸道和肺炎症性疾病","大叶性肺炎的病理变化及临床病理联系",2002,99,"B","","大叶性肺炎是",[["A","淋巴细胞渗出为主的炎症"],["B","纤维蛋白渗出为主的炎症"],["C","浆液渗出为主的炎症"],["D","单核巨噬细胞渗出为主的炎症"],["E","嗜中性粒细胞渗出为主的炎症"]],"B","大叶性肺炎是以肺泡内纤维蛋白（纤维素）渗出为主的炎症（B对）。","","N"],["2002-N100",8,"第1节 呼吸道和肺炎症性疾病","小叶性肺炎的病理变化",2002,100,"B","","小叶性肺炎是",[["A","淋巴细胞渗出为主的炎症"],["B","纤维蛋白渗出为主的炎症"],["C","浆液渗出为主的炎症"],["D","单核巨噬细胞渗出为主的炎症"],["E","嗜中性粒细胞渗出为主的炎症"]],"E","小叶性肺炎是主要由化脓性菌引起的急性化脓性炎症，以嗜中性粒细胞渗出为主（E对）。","","N"],["2002-N101",9,"第6节 病毒性肝炎","点状坏死",2002,101,"B","","急性普通型肝炎的病变特征是",[["A","肝细胞广泛水样变性、点状坏死"],["B","肝细胞广泛脂肪变性、点状坏死"],["C","肝细胞碎片状坏死"],["D","肝细胞亚大块坏死"],["E","肝细胞大块坏死"]],"A","急性普通型肝炎肝细胞出现广泛的变性，以细胞水肿（水样变性）为主（A对B错），肝细胞坏死轻微，肝小叶内可见点状坏死（A对）和嗜酸性小体。碎片状坏死见于慢性肝炎（C错）。亚大块坏死见于亚急性重型肝炎（D错）。大块坏死见于急性重型肝炎（E错）。","","N"],["2002-N102",9,"第6节 病毒性肝炎","碎片状坏死",2002,102,"B","","慢性活动性肝炎的病变特征是",[["A","肝细胞广泛水样变性、点状坏死"],["B","肝细胞广泛脂肪变性、点状坏死"],["C","肝细胞碎片状坏死"],["D","肝细胞亚大块坏死"],["E","肝细胞大块坏死"]],"C","五版以前的教材将慢性肝炎分为慢性迁延性肝炎和慢性活动性肝炎，慢性迁延性肝炎以汇管区淋巴细胞浸润，肝细胞损伤较轻为主要病理特点，慢性活动性肝炎以肝细胞碎片状坏死为主要特点（C对）。肝细胞广泛水样变性、点状坏死（A错）见于急性普通型肝炎。肝细胞广泛脂肪变性、点状坏死（B错）见于酒精性肝病。亚大片坏死见于亚急性重型肝炎（D错）。大片坏死见于急性重型肝炎和亚急性重型肝炎（E错）。病毒性肝炎临床病理类型与坏死类型的对应关系是考研的难点和重点，现总结如下：肝炎的临床病理类型包括急性（普通型）肝炎、慢性（普通型）肝炎（旧版教材将其分成持续性、活动性两型，新版教材将其分成轻度、中度、重度三型）、急性重型肝炎、亚急性重型肝炎等。肝细胞的坏死类型包括溶解性坏死、点状坏死、灶状坏死（病理学未提及灶状坏死概念，可参见八版传染病学P26，灶状坏死比点状坏死略大，有时二者并不作区分而合称点灶状坏死）、碎片状坏死、桥接坏死、大片坏死等。对应关系：急性肝炎——点状坏死；轻度慢性肝炎——点状坏死，轻度碎片状坏死；中度慢性肝炎——桥接坏死，中度碎片状坏死；重度慢性肝炎——大范围桥接坏死，重度碎片状坏死；急性重型肝炎——大块坏死；亚急性重型肝炎——亚大块坏死；慢性持续性肝炎——点状坏死；慢性活动性肝炎——灶状坏死、碎片状坏死。","","N"],["2002-N127",16,"第2节 结核病","原发性肺结核病",2002,127,"C","","原发性肺结核的常见播散方式是",[["A","淋巴道播散"],["B","血路播散"],["C","二者均有"],["D","二者均无"]],"C","原发性肺结核病常通过血路（B对）或淋巴道（A对）播散到全身。本题AB均对，正确答案为C。","","N"],["2002-N128",16,"第2节 结核病","继发性肺结核病概述",2002,128,"C","","继发性肺结核的常见播散方式是",[["A","淋巴道播散"],["B","血路播散"],["C","二者均有"],["D","二者均无"]],"D","继发性肺结核的常见播散方式是通过支气管播散，淋巴道播散（A错）和血路播散（B错）均常见于原发性肺结核病。本题AB均错，正确答案为D。","","N"],["2002-N135",5,"第4节 肿瘤的生长和扩散","膨胀性生长",2002,135,"C","","良性肿瘤的生长方式多为",[["A","外生性或膨胀性生长"],["B","浸润性生长"],["C","二者均有"],["D","二者均无"]],"A","肿瘤的生长方式主要有三种：膨胀性生长、外生性生长和浸润性生长。良性肿瘤的生长方式多为膨胀性或外生性生长（A对）；恶性肿瘤的生长方式多为浸润性或外生性生长。","","N"],["2002-N136",5,"第4节 肿瘤的生长和扩散","侵袭性生长",2002,136,"C","","恶性肿瘤的生长方式主要为",[["A","外生性或膨胀性生长"],["B","浸润性生长"],["C","二者均有"],["D","二者均无"]],"B","肿瘤的生长方式主要有三种：膨胀性生长、外生性生长和浸润性生长。良性肿瘤的生长方式多为膨胀性或外生性生长；恶性肿瘤的生长方式多为浸润性（B对）或外生性生长。","","N"],["2002-N147",11,"第1节 肾小球疾病","急性肾炎综合征",2002,147,"X","","构成急性肾炎综合征的主要临床表现是",[["A","少尿"],["B","血尿"],["C","氮质血症"],["D","高血压"]],"ABCD","急性肾炎综合征的主要临床表现有明显血尿（B对）、蛋白尿，水肿和高血压（D对），严重者出现氮质血症（C对）。引起急性肾炎综合征的病理类型主要是急性弥漫性肾小球肾炎，起病早期可因肾小球滤过率下降，水、钠潴留而导致尿量减少，少数患者可出现少尿（八版内科学 P470）（A对）。少尿及氮质血症为急性肾炎综合征严重者的临床表现，不属于主要临床表现，AC选项存在争议。","","N"],["2002-N148",14,"第3节 中枢神经系统感染性疾病","脑膜炎病理变化",2002,148,"X","","以化脓性炎为主要表现的疾病有",[["A","急性阑尾炎"],["B","病毒性肝炎"],["C","流行性乙型脑炎"],["D","流行性脑膜炎"]],"AD","急性阑尾炎（A对）和流行性脑脊髓膜炎（D对）均属于细菌感染引起的急性化脓性炎症。病毒性肝炎（B错）和流行性乙型脑炎（C错）均属于病毒感染引起的变质性炎症。","","N"],["2002-N149",5,"第8节 常见肿瘤举例","鳞状细胞癌",2002,149,"X","","鳞癌可发生于",[["A","宫颈"],["B","肾盂"],["C","口腔黏膜"],["D","支气管"]],"ABCD","鳞状细胞癌简称鳞癌，常发生鳞癌的部位是鳞状上皮被覆的部位和发生鳞状上皮化生的部位。皮肤、口腔（C对）、唇、食管、喉、子宫颈（A对）、阴道及阴茎等处正常即为鳞状上皮，而支气管（D对）、膀胱、肾盂（B对）等部位可发生鳞状上皮化生，以上组织均可发生鳞状细胞癌。","","N"],["2002-N150",3,"第2节 急性炎症","纤维蛋白性炎",2002,150,"X","","与纤维蛋白渗出过程相关的病变是",[["A","大叶性肺炎"],["B","绒毛心"],["C","细菌性痢疾"],["D","病毒性肝炎"]],"ABC","纤维蛋白渗出过程常见于纤维素性炎，大叶性肺炎（A对）、绒毛心（B对）和细菌性痢疾（C对）均为纤维素性炎。病毒性肝炎属于变质性炎（纤维素性炎属于渗出性炎），无纤维蛋白渗出（D错）。","","N"],["2003-N33",8,"第6节 慢性肺源性心脏病","肺血管疾病",2003,33,"A","","慢性肺源性心脏病发生的关键环节是",[["A","肺间质纤维化"],["B","肺气肿"],["C","肺动脉高压"],["D","肺动脉分支血栓栓塞"],["E","肺阻塞性通气障碍"]],"C","肺间质纤维化（A错）、肺气肿（B错）、肺动脉分支血栓栓塞（D错）和肺阻塞性通气障碍（E错）均为慢性肺源性心脏病的潜在病因，但非决定因素，只有通过各种机制引起肺动脉高压（C对）时才会导致慢性肺源性心脏病发生。","","N"],["2003-N34",0,"第4节 细胞不可逆性损伤（细胞死亡）","液化性坏死",2003,34,"A","","病毒性肝炎时，肝细胞的灶性坏死属于",[["A","凝固性坏死"],["B","液化性坏死"],["C","干酪样坏死"],["D","固缩性坏死"],["E","坏疽"]],"B","各型病毒性肝炎最常见的病变为细胞水肿，严重的细胞水肿可发展为溶解性坏死（液化性坏死），根据溶解性坏死的范围和分布不同，可分为点状坏死、碎片状坏死（灶性坏死）（B对）、桥接坏死和大片坏死等类型。","","N"],["2003-N35",1,"第1节 再生","软骨组织和骨组织的再生",2003,35,"A","","前臂断肢再植手术成功后，下列哪种愈合属于完全再生",[["A","动脉吻合口愈合"],["B","皮肤伤口愈合"],["C","骨折愈合"],["D","肌肉断端愈合"],["E","肌腱断端愈合"]],"C","组织的损伤修复的过程可以概括为两种不同的形式：①由损伤周围的同种细胞来修复，称为再生，如果完全恢复原组织的结构及功能，则称为完全再生；②由纤维结缔组织来修复，称为纤维性修复，以后形成瘢痕，故也称瘢痕修复。骨组织再生能力强，骨折经过良好复位后，几个月内便可完全愈合，恢复正常结构和功能，为完全再生（C对）。血管平滑肌细胞再生能力弱，动脉吻合口愈合时由结缔组织增生连接，形成瘢痕修复（A错）。皮肤伤口愈合时有肉芽组织形成，存在瘢痕修复（B错）。骨骼肌细胞无再生能力，肌肉断端愈合完全依靠瘢痕修复（D错）。十版病理学P37明确表明肌腱断端愈合时，经过功能锻炼而不断改建可达到完全再生，故E选项也应为正确答案。但本题给出的参考答案仅为C。","","N"],["2003-N36",2,"第3节 血栓形成","白色血栓",2003,36,"A","","下列各项中，属于白色血栓的是",[["A","延续性血栓的体部"],["B","阻塞冠状动脉左前降支的血栓"],["C","阻塞肺动脉主干的血栓栓子"],["D","疣状血栓性心内膜炎的疣状赘生物"],["E","基底动脉的血栓"]],"D","血栓类型可分为四种：白色血栓、混合血栓、红色血栓和透明血栓。疣状心内膜炎（风湿性心内膜炎）的瓣膜赘生物属于白色血栓（D对）。延续性血栓的体部为混合血栓（A错）。阻塞冠状动脉左前降支的血栓（B错）和基底动脉的血栓（E错）一般由动脉粥样硬化引起，为混合血栓。阻塞肺动脉主干的血栓栓子绝大多数来自下肢膝以上的深部静脉血栓的脱落，为红色血栓（红色血栓易脱落）（十版病理学P48）（C错）。","","N"],["2003-N37",3,"第2节 急性炎症","趋化作用",2003,37,"A","","具有趋化作用的炎症介质是",[["A","组胺"],["B","缓激肽"],["C","氧自由基"],["D","C3b"],["E","C5a"]],"E","具有趋化作用的炎症介质称趋化因子，趋化因子可以是外源性的，如细菌产物 ，也可以是内源性，如C5a（E对）、LTB₄、和IL-8等。C3b（D错）为调理素（十版病理学P67），可以通过包裹微生物而增强吞噬细胞的吞噬功能。组胺（A错）为血管活性胺（十版病理学P69），可使细动脉扩张和细静脉通透性增加。缓激肽（B错）为血管活性肽（十版病理学P69），可使细动脉扩张、血管通透性增加、支气管平滑肌收缩，并可引起疼痛。氧自由基（C错）为活性氧（十版病理学P71），可杀死和降解微生物及坏死细胞，亦可引起机体正常组织损伤。","","N"],["2003-N38",3,"第2节 急性炎症","血流动力学改变",2003,38,"A","","炎症时，经被动过程从血管内到血管外组织的细胞是",[["A","淋巴细胞"],["B","红细胞"],["C","单核细胞"],["D","嗜酸性粒细胞"],["E","嗜碱性粒细胞"]],"B","白细胞穿过血管壁进入周围组织的过程称为白细胞游出。白细胞游出主要是由于炎性灶产生的化学趋化因子介导的，这些趋化因子作用于粘附于血管内皮的白细胞，刺激白细胞以阿米巴运动的主动方式从内皮细胞连接处溢出，故白细胞的游出是主动过程，白细胞包括中性粒细胞、嗜酸性粒细胞（D错）、嗜碱性粒细胞（E错）、单核细胞（C错）和各种淋巴细胞（A错）。而红细胞从血管内到血管外组织的过程，为血管内皮细胞间隙增大或内皮细胞损伤后的被动漏出过程（B对）。","","N"],["2003-N39",5,"第7节 良性肿瘤与恶性肿瘤的区别","交界性肿瘤概念",2003,39,"A","","交界性肿瘤是",[["A","既有癌，又有肉瘤成分的肿瘤"],["B","侵犯表皮和真皮交界部位的肿瘤"],["C","介于良性和恶性肿瘤之间的肿瘤"],["D","侵犯黏膜和黏膜肌层交界部位的肿瘤"],["E","既有腺癌成分，又有鳞癌成分的肿瘤"]],"C","交界性肿瘤是指组织形态和生物学行为介于良恶性肿瘤之间的肿瘤（C对）。既有癌，又有肉瘤成分的肿瘤称为癌肉瘤（A错）。侵犯表皮和真皮交界部位的肿瘤为发生于皮肤的早期浸润癌（只侵犯表皮未侵犯真皮的肿瘤为原位癌）（B错）。既有腺癌成分，又有鳞癌成分的肿瘤是腺鳞癌（E错）。重点解释一下D选项，消化道管壁由内至外依次可分为黏膜层、黏膜下层、肌层和浆膜层共四层，黏膜层又可分为黏膜上皮层（含基底膜）、黏膜固有层和黏膜肌层三个部分，故“侵犯黏膜和黏膜肌层交界部位”这一说法是不准确的，出题者的原意在此无法揣测，现将各种情况总结如下：肿瘤局限在黏膜上皮层时（未突破基底膜），为原位癌（胃肠道的原位癌不易发现）；肿瘤突破黏膜上皮层基底膜，但未突破黏膜肌层时，为黏膜内癌（最早期的浸润癌）；肿瘤突破黏膜肌层到达黏膜下层，但未侵及肌层，为黏膜下癌。以上原位癌、黏膜内癌、黏膜下癌均属于早期癌。","","N"],["2003-N40",5,"第3节 肿瘤的命名与分类","肿瘤命名的特殊情况",2003,40,"A","","下列哪项属于真性肿瘤",[["A","畸胎瘤"],["B","动脉瘤"],["C","错构瘤"],["D","迷离瘤"],["E","结核瘤"]],"A","畸胎瘤是性腺或胚胎剩件中的全能细胞发生的肿瘤，属于真性肿瘤（A对）。动脉瘤、错构瘤、迷离瘤、结核瘤等病变虽带“瘤”字，但不属于肿瘤。动脉瘤（十版病理学P153）是为动脉壁上的脆弱部分向外膨出、扩张而形成的薄壁球状物（B错）。错构瘤（二版八年制病理学P128）是由与所在器官相同的组织构成，但结构紊乱比例失常而形成的包块（C错）。迷离瘤（二版八年制病理学P128）指正常组织易位到其它部位而形成的包块（D错）。结核瘤（十版病理学P347）又称结核球，是有纤维包裹的孤立的境界分明的干酪样坏死灶（E错）。","","N"],["2003-N41",4,"第2节 免疫缺陷病","恶性肿瘤",2003,41,"A","","艾滋病患者中，最常见的恶性肿瘤是",[["A","霍奇金病"],["B","非霍奇金淋巴瘤"],["C","Kaposi肉瘤"],["D","子宫颈癌"],["E","阴茎癌"]],"C","艾滋病（AIDS）患者因免疫功能低下，常伴发多种恶性肿瘤，以Kaposi肉瘤（C对）最为常见。","","N"],["2003-N42",4,"第3节 器官和骨髓移植排斥反应","慢性排斥反应",2003,42,"A","","慢性排斥反应中，移植物的血管病变特点是",[["A","血管内膜纤维化"],["B","血管肌层肥厚"],["C","血管外膜纤维组织增生"],["D","血管壁纤维素样坏死"],["E","血管壁玻璃样变性"]],"A","慢性排斥反应中，移植物的血管病变特点是血管内膜纤维化（A对）。血管肌层肥厚（B错）是高血压肌型小动脉的病变特点。血管外膜纤维组织增生（C错）是系统性红斑狼疮累及脾动脉时的病变特点（十版病理学P80）。血管壁纤维素样坏死（D错）是超急性排斥反应、风湿病、结节性多动脉炎、新月体性肾小球肾炎、急进型高血压等多种变态反应性疾病（十版病理学P20）的病变特点。血管玻璃样变性（E错）是良性高血压细小动脉硬化的病变特点（十版病理学P151）。","","N"],["2003-N43",7,"第8节 心肌炎","特发性巨细胞性心肌炎",2003,43,"A","","形成肉芽肿的心肌炎是",[["A","特发性巨细胞性心肌炎"],["B","柯萨奇B病毒性心肌炎"],["C","埃可病毒性心肌炎"],["D","白喉性心肌炎"],["E","葡萄球菌性心肌炎"]],"A","特发性巨细胞性心肌炎属于孤立性心肌炎，病灶的心肌内可见灶状坏死和肉芽肿形成（A对）。柯萨奇B病毒性心肌炎（B错）和埃可病毒性心肌炎（C错）属于病毒性心肌炎，主要表现为心肌细胞间质水肿，淋巴细胞和单核细胞浸润。白喉性心肌炎（D错）和葡萄球菌性心肌炎（E错）属于细菌性心肌炎，前者主要表现为心肌细胞嗜酸性变和脂肪变性和淋巴细胞、单核细胞及少数中性粒细胞浸润，后者主要表现为心肌及间质多发性小脓肿，心肌细胞不同程度变性坏死，大量中性粒细胞浸润。","","N"],["2003-N44",7,"第6节 心瓣膜病","主动脉瓣关闭不全",2003,44,"A","","引起水冲脉的疾病是",[["A","二尖瓣关闭不全"],["B","三尖瓣关闭不全"],["C","主动脉瓣关闭不全"],["D","二尖瓣狭窄"],["E","主动脉瓣狭窄"]],"C","水冲脉指脉搏骤起骤落，犹如潮水涨落，见于可导致脉压增大的疾病。多由周围血管扩张、血流量增大，或存在血液分流、反流所致。前者常见于甲状腺功能亢进、严重贫血、脚气病等，后者常见于主动脉瓣关闭不全（C对）、动脉导管未闭、动静脉瘘等疾病。主动脉关闭不全时，左心室前负荷增加，心肌收缩力增加，心排出量增大，收缩压增高；舒张期血液从主动脉向左心室反流，造成舒张期动脉压迅速下降，因而脉压明显增大，出现水冲脉。","","N"],["2003-N45",9,"第8节 肝硬化","镜下",2003,45,"A","","肝硬化的特征性病变是",[["A","肝细胞增生"],["B","小胆管增生"],["C","纤维组织增生"],["D","肝细胞坏死"],["E","假小叶形成"]],"E","肝硬化是一种或多种原因引起的、以肝组织弥漫性纤维化、假小叶形成和再生结节为组织学特征的进行性慢性肝病，假小叶是由广泛增生的纤维组织分割原来的肝小叶并包绕成大小不等的圆形或类圆形的肝细胞团，是肝硬化的特征性病变，对肝硬化的诊断有重要意义（E对）。肝细胞增生（A错）、小胆管增生（B错）、纤维组织增生（C错）、肝细胞坏死（D错）均可在肝硬化中见到，但非肝硬化的特征性病变。","","N"],["2003-N46",10,"第2节 淋巴组织肿瘤","蕈样肉芽肿病的病理改变",2003,46,"A","","以皮肤病变为特点的淋巴瘤是",[["A","蕈样霉菌病"],["B","Burkitt淋巴瘤"],["C","免疫母细胞性淋巴瘤"],["D","小淋巴细胞性淋巴瘤"],["E","滤泡性淋巴瘤"]],"A","蕈样霉菌病（A对）主要累及皮肤，以皮肤病变为特点。Burkitt淋巴瘤（十版病理学P233）（B错）主要累及颌骨和腹腔，以颌面部巨大包块及腹腔内巨大肿物为特点。免疫母细胞性淋巴瘤（十版病理学P237）（C错）、小淋巴细胞性淋巴瘤（十版病理学P231）（D错）和滤泡淋巴瘤（十版病理学P232）（E错）主要累及淋巴结。","","N"],["2003-N117",7,"第2节 高血压病","高血压病类型和病理变化",2003,117,"C","","高血压病可引起",[["A","血管壁纤维素样坏死"],["B","血管壁玻璃样变性"],["C","二者均有"],["D","二者均无"]],"C","原发性高血压可分为良性高血压和恶性高血压两类，两种类型的高血压病理变化不同。良性高血压可发生细小动脉硬化，表现为细小动脉玻璃样变（B对）。恶性高血压可发生坏死性细动脉炎，表现为细动脉内膜和中膜管壁发生纤维素样坏死（A对）。本题AB均对，正确答案为C。","","N"],["2003-N118",7,"第4节 风湿病","变质渗出期",2003,118,"C","","风湿病可引起",[["A","血管壁纤维素样坏死"],["B","血管壁玻璃样变性"],["C","二者均有"],["D","二者均无"]],"A","风湿性动脉炎时大小动脉均可受累，以小动脉受累较为常见，急性期，血管壁发生纤维素样坏死（A对），伴淋巴细胞浸润，并伴有Aschoff小体形成。病变后期，血管壁纤维化而增厚，管腔狭窄，并发血栓形成。","","N"],["2003-N137",9,"第12节 消化系统常见肿瘤","结直肠黏膜上皮癌变",2003,137,"X","","在大肠癌发生发展中，起重要作用的基因有",[["A","ret"],["B","ras"],["C","APC"],["D","p53"]],"BCD","在大肠癌发生发展中，起重要作用的基因有：ras（B对）、APC（C对）、p53（D对）等。ret基因主要在先天性巨结肠、多发性内分泌肿瘤及家族性甲状腺髓样癌的形成中发挥作用，与大肠癌的发生和发展无关（A错）。","","N"],["2003-N138",16,"第2节 结核病","继发性肺结核病概述",2003,138,"X","","继发性肺结核的病理特点有",[["A","多局限于肺内"],["B","多从右肺尖开始"],["C","病变新旧不一"],["D","病变上重下轻"]],"ABCD","继发性肺结核的病理特点有：①病变最先并最常见于肺尖部（右肺支气管粗、短、直，更易被累及）（B对），病变呈上旧下新、上重下轻（D对）的特点；②病程长，病变复杂，随着机体免疫反应和变态反应的消长，新旧病灶交错（C对），临床症状时好时坏；③以气道播散为主，多局限于肺内（A对）。","","N"],["2003-N139",13,"第2节 甲状腺疾病","未分化癌",2003,139,"X","","甲状腺未分化癌包括",[["A","髓样癌"],["B","巨细胞癌"],["C","梭形细胞癌"],["D","小细胞癌"]],"BCD","甲状腺癌可分为乳头状癌、滤泡癌、髓样癌和未分化癌四种类型，其中未分化癌又可分为小细胞型（D对）、梭型细胞型（C对）、巨细胞型（B对）和混合细胞型。","","N"],["2003-N140",16,"第10节 寄生虫病","急性虫卵结节",2003,140,"X","","急性血吸虫卵结节的病理变化有",[["A","上皮样细胞增生"],["B","异物巨细胞形成"],["C","嗜酸性粒细胞浸润"],["D","卵壳附有放射状棒状物"]],"CD","急性血吸虫卵结节是由成熟虫卵引起的一种急性坏死、渗出性病灶。镜下见结节中央常有1～2个成熟虫卵，虫卵表面（卵壳）有时可见附有放射状嗜酸性的棒状体（D对），虫卵周围可见无结构的颗粒状坏死物及大量嗜酸性粒细胞浸润（C对）。上皮样细胞增生（A错）和异物巨细胞增生（B错）是慢性虫卵结节的病理变化。","","N"],["2004-N33",0,"第3节 细胞可逆性损伤","转移性钙化",2004,33,"A","","转移性钙化可发生于",[["A","血栓"],["B","肾小管"],["C","干酪样坏死"],["D","粥瘤"],["E","死亡血吸虫卵"]],"B","病理性钙化有转移性钙化和营养不良性钙化两种形式。转移性钙化是由于全身钙磷代谢失调使钙盐沉积于正常组织所致，多见于血管、肾小管（B对）、肺泡和胃黏膜等处。营养不良性钙化为钙盐沉积于坏死或即将坏死的组织或异物所致，多见于血栓（A错）、干酪样坏死（C错）、动脉粥样硬化（粥瘤）（D错）、死亡血吸虫卵（E错）等处。","","N"],["2004-N34",0,"第1节 适应","鳞状上皮的化生",2004,34,"A","","与化生相关的癌是",[["A","食管鳞癌"],["B","皮肤鳞癌"],["C","子宫颈鳞癌"],["D","膀胱鳞癌"],["E","阴茎鳞癌"]],"D","化生是指一种分化成熟的细胞类型被另一种分化成熟的细胞类型所取代的过程，正常情况下，食管（A错）、皮肤（B错）、子宫颈（C错）和阴茎（E错）的被覆细胞均为鳞状上皮细胞，因此这些组织发生的鳞癌都与化生无关。而膀胱的被覆细胞为移形上皮细胞，膀胱鳞癌经历了由移形上皮细胞向鳞状上皮细胞化生的过程（D对）。此类题的关键是看发生肿瘤组织或器官原来是否存在该细胞类型，若原来存在，则不是化生，若不存在，则是化生。例如子宫颈存在鳞状细胞，发生鳞癌就不是化生；而膀胱不存在鳞状细胞，发生鳞癌则是化生。","","N"],["2004-N35",2,"第3节 血栓形成","透明血栓",2004,35,"A","","主要由纤维蛋白构成的血栓是",[["A","透明血栓"],["B","红色血栓"],["C","混合血栓"],["D","白色血栓"],["E","附壁血栓"]],"A","血栓类型可分为四种：白色血栓、混合血栓、红色血栓和透明血栓。各种类型血栓的主要成分①白色血栓：血小板+少量纤维蛋白（D错）；②混合血栓：血小板+纤维蛋白+红细胞（C错）；③红色血栓：纤维蛋白+红细胞+白细胞（B错）；④透明血栓：纤维蛋白（A对）。附壁血栓为混合性血栓，由血小板、纤维蛋白和红细胞组成（E错）。","","N"],["2004-N38",7,"第1节 动脉粥样硬化","动脉平滑肌细胞的作用",2004,38,"A","","造成动脉粥样硬化病灶中纤维增生的主要细胞是",[["A","内皮细胞"],["B","泡沫细胞"],["C","平滑肌细胞"],["D","纤维母细胞"],["E","淋巴细胞"]],"C","动脉粥样硬化的基本病理变化包括脂纹、纤维斑块、粥样斑块和继发性改变。其中纤维斑块即由纤维增生引起，纤维增生由平滑肌细胞介导（分泌大量的胶原纤维）（C对）。纤维母细胞即成纤维细胞，在大多数病灶中为介导纤维增生的主要细胞（也是分泌大量的胶原纤维），但在动脉粥样硬化病灶的纤维增生中几乎不发挥作用（但其表面含LDL受体，被激活后能增加脂质在病灶内积聚，加速动脉粥样硬化发展）（D错）。内皮细胞（A错）损伤是发生动脉粥样硬化的前提条件，泡沫细胞（B错）为动脉粥样硬化病灶早期脂纹病变的主要细胞，淋巴细胞（E错）为动脉粥样硬化病灶中的慢性炎症细胞，此三种细胞均与纤维增生无关。","","N"],["2004-N39",8,"第1节 呼吸道和肺炎症性疾病","严重急性呼吸综合征的病理变化",2004,39,"A","","非典型肺炎属于",[["A","肺化脓性炎"],["B","肺纤维素性炎"],["C","肺泡性炎"],["D","肺间质性炎"],["E","肺出血性炎"]],"D","非典型肺炎是一个泛称，泛指所有不具有典型肺炎症状的肺炎，一般由非细菌病原体引起。这些病原体有可能是病毒、也有可能是支原体、衣原体或立克次体。2003年在我国所爆发的严重急性呼吸道综合征（SARS）是由某种冠状病毒引起的，属于非典型性肺炎之一。非典型肺炎一般属于肺间质性炎（D对），无明显湿啰音、肺实变等肺炎体征。肺化脓性炎（A错）见于小叶性肺炎（十版病理学P174）。肺纤维素性炎（B错）见于大叶性肺炎（十版病理学P172）。肺泡性炎（C错）见于大叶性肺炎。肺出血性炎（E错）见于肺出血肾炎综合征（Goodpasture syndrome）（十版病理学P255）。","","N"],["2004-N40",9,"第12节 消化系统常见肿瘤","早期癌",2004,40,"A","","无淋巴结转移的癌是",[["A","早期食管癌"],["B","早期胃癌"],["C","早期大肠癌"],["D","肺鳞癌"],["E","胰腺癌"]],"A","早期食管癌、早期胃癌和早期大肠癌均可有（或无）淋巴结转移（ABC错）。肺鳞癌（D错）和胰腺癌（E错）包括早期、中期和晚期等阶段，因此都可有淋巴结转移。早期食管癌可有（或无）淋巴结转移为十版教材观点，按十版教材本题无答案，原参考答案为A。","","N"],["2004-N41",10,"第2节 淋巴组织肿瘤","结节性淋巴细胞为主型霍奇金淋巴瘤",2004,41,"A","","缺乏典型诊断性R-S细胞的霍奇金淋巴瘤亚型是",[["A","结节硬化型"],["B","混合细胞型"],["C","淋巴细胞减少型"],["D","弥漫性淋巴细胞为主型"],["E","结节性淋巴细胞为主型"]],"E","在WHO分类中，将霍奇金淋巴瘤（HL）分为结节性淋巴细胞为主型HL和经典型HL。结节性淋巴细胞为主型HL的病变淋巴结模糊不清，R-S细胞难觅（即缺乏典型诊断性R-S细胞）（E对），其典型肿瘤细胞为爆米花样细胞（LP细胞）。经典型HL包括4种亚型：结节硬化型（A错）、混合细胞型（B错）、富于淋巴细胞型（D错）和淋巴细胞减少型（C错），4种HL亚型内或多或少均可见到典型诊断性R-S细胞。","","N"],["2004-N42",11,"第1节 肾小球疾病","膜增生性肾小球肾炎病理变化",2004,42,"A","","致密沉积物病属于下列哪种肾小球肾炎",[["A","膜性肾小球肾炎"],["B","快速进行性肾小球肾炎"],["C","系膜增生性肾小球肾炎"],["D","膜性增生性肾小球肾炎"],["E","毛细血管内增生性肾小球肾炎"]],"D","膜性增生性肾小球肾炎（D对）根据超微结构和免疫荧光的特点分为两个主要类型：①Ⅰ型超微结构可见系膜区和内皮细胞下出现散在的电子致密物；②Ⅱ型超微结构可见基膜致密层内出现大量块状的电子致密物，呈带状沉积，又称为致密沉积物病。","","N"],["2004-N43",16,"第8节 性传播性疾病","树胶样肿",2004,43,"A","","下列关于梅毒树胶肿的叙述，正确的是",[["A","大片干酪样坏死"],["B","类上皮细胞丰富"],["C","大量郎罕巨细胞"],["D","淋巴细胞、浆细胞少见"],["E","可见原有血管壁轮廓"]],"E","梅毒树胶样肿又称梅毒瘤，是梅毒的基本病变之一，其镜下特点有：中央为形态类似干酪样坏死的凝固性坏死（A错），但坏死不如干酪样坏死彻底，弹力纤维尚保存，弹力纤维染色后组织内可见原有血管壁轮廓（E对）。坏死灶周围肉芽组织中富含淋巴细胞、浆细胞（D错），而上皮样细胞（类上皮细胞）（B错）和郎罕巨细胞（C错）较少。","","N"],["2004-N44",4,"第2节 免疫缺陷病","恶性肿瘤",2004,44,"A","","下列关于Kaposi肉瘤的叙述，正确的是",[["A","来源于纤维组织的恶性肿瘤"],["B","仅累及皮肤"],["C","肿瘤边界清楚"],["D","是由梭形细胞和血管构成的恶性肿瘤"],["E","80%以上艾滋病患者受累"]],"D","Kaposi肉瘤是艾滋病（AIDS）最常合并的恶性肿瘤，约30%（E错）的患者可患病。Kaposi肉瘤来源于血管或淋巴内皮细胞（A错），主要由梭形细胞和血管构成（D对），可局限于皮肤和黏膜，但也可累及重要脏器（B错）。与其他肉瘤（十版病理学P86）一样，Kaposi肉瘤的肉瘤细胞呈弥漫分布，实质与间质分界不清（C错）。","","N"],["2004-N45",12,"第7节 乳腺疾病","非特殊型浸润性癌",2004,45,"A","","下列属于非浸润性乳腺癌的是",[["A","粉刺癌"],["B","黏液癌"],["C","小管癌"],["D","髓样癌"],["E","硬癌"]],"A","乳腺癌有多种分型方法，八版病理学将乳腺癌分为非浸润性癌和浸润性癌两类：非浸润性癌包括导管内原位癌和小叶原位癌，导管内原位癌又可分为粉刺癌（A对）、非粉刺型导管内癌、乳头Paget病伴导管原位癌；浸润性癌包括浸润性导管癌、浸润性小叶癌和特殊类型癌，特殊类型癌又可分为乳头Paget病伴导管浸润癌、典型髓样癌（D错）、小管癌（C错）、黏液癌（B错）等。硬癌为九版外科学分型方法中的一种类型，属于浸润性乳腺癌（E错）。","","N"],["2004-N46",4,"","",2004,46,"A","","皮肤活检时，SLE最典型的发现是",[["A","真皮浅表部出血"],["B","真皮深部出血"],["C","真皮内色素沉积"],["D","真皮深部免疫复合物沉积"],["E","真皮浅表部免疫复合物沉积"]],"E","系统性红斑狼疮（SLE）可累及全身各器官，其中约80%的患者可表现出不同程度的皮肤损害，皮肤活检时，最典型的表现是真皮与表皮交界处（即真皮浅表部）有免疫复合物沉积（E对），形成颗粒或团块状的明亮荧光带（称狼疮带）。","","N"],["2004-N99",11,"第1节 肾小球疾病","系膜增生性肾小球肾炎病理变化",2004,99,"B","","系膜增生性肾小球肾炎电镜下可见",[["A","上皮细胞足突消失"],["B","上皮下驼峰样沉积物"],["C","系膜区沉积物"],["D","内皮下、致密层和上皮下沉积物"],["E","上皮下沉积物伴基膜增厚"]],"C","系膜增生性肾小球肾炎的主要病理变化，除光镜下可见弥漫性系膜细胞增生及系膜基质增多以外，部分病例可见系膜区沉积物（C对）。上皮细胞足突消失（A错）为微小病变性肾小球病（脂性肾病）（十版病理学P259）、膜性肾小球病（十版病理学P256）和局灶性节段性肾小球硬化（十版病理学P259）的病变特点。上皮下驼峰样沉积物（B错）为急性弥漫性增生性肾炎（急性肾炎）的病变特点（十版病理学P254）。内皮下、致密层和上皮下沉积物（D错）为膜增生性肾小球肾炎（十版病理学P258）的病变特点。上皮下沉积物伴基膜增厚（E错）为膜性肾小球病的病变特点（十版病理学P256）。","","N"],["2004-N100",11,"第1节 肾小球疾病","急性弥漫性增生性肾小球肾炎病理变化",2004,100,"B","","毛细血管内增生性肾小球肾炎电镜下可见",[["A","上皮细胞足突消失"],["B","上皮下驼峰样沉积物"],["C","系膜区沉积物"],["D","内皮下、致密层和上皮下沉积物"],["E","上皮下沉积物伴基膜增厚"]],"B","毛细血管内增生性肾小球肾炎（急性弥漫性增生性肾小球肾炎）电镜下可见上皮下驼峰样沉积物（B对）。上皮细胞足突消失（A错）为微小病变性肾小球病（脂性肾病）（十版病理学P259）、膜性肾小球病（十版病理学P256）和局灶性节段性肾小球硬化（十版病理学P259）的镜下特征。内皮下、致密层和上皮下沉积物（D错）为膜增生性肾炎（十版病理学P258）的镜下特征（值得注意的是九版病理学教材并未提及有上皮下沉积物，但查阅文献可知，膜增生性肾炎除教材所分类的Ⅰ型和Ⅱ型外，还存在第Ⅲ型，此型可见上皮下沉积物）。上皮下沉积物伴基膜增厚（E错）为膜性肾病（十版病理学P256）的镜下特征。","","N"],["2004-N117",5,"第8节 常见肿瘤举例","鳞状细胞癌",2004,117,"C","","腺鳞癌可见",[["A","角化珠形成"],["B","腺腔形成"],["C","二者均是"],["D","二者均非"]],"C","分化好的鳞癌，镜下癌巢中央可出现角化珠（A对）；腺癌可见腺样结构（含腺腔）（B对）。腺鳞癌同时具有腺癌和鳞状细胞癌的成分，因此，角化珠和腺腔均可见。本题AB均对，正确答案为C。","","N"],["2004-N118",13,"第2节 甲状腺疾病","髓样癌",2004,118,"C","","髓样癌可见",[["A","角化珠形成"],["B","腺腔形成"],["C","二者均是"],["D","二者均非"]],"D","髓样癌主要见于乳腺癌（十版病理学P285）和甲状腺癌（十版病理学P296），髓样癌的癌细胞呈实性片巢状或乳头状、滤泡状排列，既无腺腔形成（B错），也无角化珠形成（A错）。本题AB均错，正确答案为D。","","N"],["2004-N137",7,"第5节 感染性心内膜炎","亚急性感染性心内膜炎",2004,137,"X","","亚急性感染性心内膜炎可引起",[["A","心瓣膜变形"],["B","无菌性梗死"],["C","局灶性肾小球肾炎"],["D","Osler结节"]],"ABCD","亚急性感染性心内膜炎主要病理变化有：①心脏：此病最常侵犯二尖瓣和主动脉瓣，病变特点是常在有病变的瓣膜上形成赘生物，受累瓣膜易变形（A对），发生溃疡和穿孔；②血管：由于细菌毒素和赘生物破裂脱落形成的栓子，引起动脉性栓塞和血管炎。栓子不含菌或仅含极少的细菌，细菌毒力弱，常为无菌性梗死（B对）；③变态反应：因微栓塞的发生引起局灶性肾小球肾炎（C对）或弥漫性肾小球肾炎。皮肤出现红色、微隆起、有压痛的小结节，称Osler小结（D对）；④败血症：脱落的微生物内有细菌，侵入血流后在血流中繁殖，引起败血症。","","N"],["2004-N138",8,"第6节 慢性肺源性心脏病","肺血管疾病",2004,138,"X","","下列属于慢性肺源性心脏病肺内血管病变的有",[["A","毛细血管数量减少"],["B","中型动脉纤维素样坏死"],["C","无肌性细动脉肌化"],["D","肌型小动脉中膜增厚"]],"ACD","肺心病时肺内血管病变主要累及肺小动脉，表现为：①无肌型细动脉肌化（C对）及肌型小动脉中膜增生（D对）、肥厚，内膜下出现纵行平滑肌束等。②还可见肺小动脉炎、肺小动脉弹力纤维及胶原纤维增生、腔内血栓形成和机化。③肺泡间隔毛细血管数量减少（A对）。慢性肺心病一般不累及中型动脉。中型动脉纤维素样坏死（B错）是血管受到急性免疫损伤时的变化，见于风湿性动脉炎（十版病理学P157）、结节性多动脉炎（十版病理学P20）等变态反应性疾病。","","N"],["2004-N139",9,"第12节 消化系统常见肿瘤","肝细胞癌的病理变化概述",2004,139,"X","","原发性肝癌的组织学类型有",[["A","鳞癌"],["B","胆管细胞癌"],["C","混合性肝癌"],["D","肝细胞癌"]],"BCD","原发性肝癌的组织学类型有三种：胆管细胞癌（B对）、混合性肝癌（C对）和肝细胞癌（D对）。鳞癌（A错）主要见于食管癌（十版病理学P215），肝癌中尚无鳞癌存在的报告。","","N"],["2004-N140",3,"第3节 慢性炎症","一般慢性炎症的特点",2004,140,"X","","下列属于肺炎性假瘤病理变化的有",[["A","增生的肺泡上皮"],["B","增生的纤维、血管组织"],["C","浸润的炎症细胞"],["D","异型性明显的肿瘤细胞"]],"ABC","炎性假瘤本质上是炎症，由肉芽组织、炎细胞（C对）、增生的实质细胞（A对）和纤维结缔组织（B对）构成，为境界清楚的瘤样病变，常发生在肺。由于炎性假瘤并非肿瘤，故无异型性明显的肿瘤细胞（D错）。","","N"],["2005-N37",0,"第1节 适应","萎缩的病理变化",2005,37,"A","","脂褐素大量增加最常见于",[["A","细胞萎缩"],["B","细胞坏死"],["C","细胞凋亡"],["D","细胞水样变性"],["E","细胞玻璃样变性"]],"A","脂褐素是细胞自噬溶酶体内未被消化的细胞器碎片残体，其大量增加最常见于细胞萎缩（A对）。细胞凋亡可由细胞萎缩发展而来（十版病理学P6），故细胞凋亡时也可见脂褐素，但细胞凋亡与脂褐素并无直接和必然的联系（C错）。细胞坏死（B错）、细胞水样变性（细胞水肿）（D错）和细胞玻璃样变性（E错）均无脂褐素增加。","","N"],["2005-N38",3,"第2节 急性炎症","纤维蛋白性炎",2005,38,"A","","假膜性炎渗出物中的特征性成分是",[["A","黏液"],["B","浆液"],["C","纤维蛋白"],["D","坏死的炎症细胞膜"],["E","坏死的黏膜上皮细胞膜"]],"C","假膜性炎属于纤维素性炎，其渗出物中的特征性成分为纤维蛋白（纤维素）（C对）。其渗出物中也可见坏死的炎症细胞膜（D错）和坏死的黏膜上皮细胞膜（E错），但此二者非特征性成分。","","N"],["2005-N39",1,"第2节 纤维性修复","肉芽组织的成分及形态",2005,39,"A","","下列哪种新生的细胞是机化时出现的特征性细胞",[["A","平滑肌细胞"],["B","成纤维细胞"],["C","类上皮细胞"],["D","横纹肌细胞"],["E","上皮细胞"]],"B","机化指肉芽组织的形成过程，肉芽组织的特征性细胞是成纤维细胞（B对）。平滑肌细胞普遍存在于内脏器官中（A错）。类上皮细胞又称上皮样细胞，为肉芽肿的主要细胞成分之一（十版病理学P76）（C错）。横纹肌细胞（九版生理学P47）指骨骼肌细胞和心肌细胞（D错）。上皮细胞指位于皮肤或腔道表层的细胞（E错）。","","N"],["2005-N40",1,"第1节 再生","软骨组织和骨组织的再生",2005,40,"A","","组织修复过程中，再生能力弱的组织是",[["A","上皮组织"],["B","纤维组织"],["C","软骨细胞"],["D","骨组织"],["E","毛细血管"]],"C","上皮组织、纤维组织、骨组织、毛细血管均具有较强的再生修复能力。但软骨细胞的再生修复能力较弱（C对），软骨组织缺损较大时由纤维组织参与修补。","","N"],["2005-N41",2,"第3节 血栓形成","混合血栓",2005,41,"A","","混合血栓的形态学特征是",[["A","血小板和少量纤维蛋白"],["B","血小板小梁、纤维蛋白及红细胞"],["C","血液中细胞成分与血浆成分分层"],["D","同质的纤维蛋白"],["E","纤维蛋白网眼中充满红细胞"]],"B","血栓类型可分为四种：白色血栓、混合血栓、红色血栓和透明血栓。各种类型血栓的主要成分①白色血栓：血小板+少量纤维蛋白（A错）；②混合血栓：血小板+纤维蛋白+红细胞（B对）；③红色血栓：纤维蛋白+红细胞+白细胞；④透明血栓：纤维蛋白（D错）。","","N"],["2005-N42",2,"第4节 栓塞","栓子的概念",2005,42,"A","","栓子的最确切定义是",[["A","阻塞血管的异常物质"],["B","阻塞血管的液态物质"],["C","阻塞血管的固态物质"],["D","阻塞血管的气态物质"],["E","阻塞血管的脂肪"]],"A","在循环血液中出现的不溶于血液的异常物质，随血流运行阻塞血管腔的现象称为栓塞。这些阻塞血管的异常物质称为栓子（A对），最常见的栓子是脱落的血栓或其节段，罕见的为脂肪滴、空气、羊水和肿瘤细胞团。","","N"],["2005-N43",5,"第5节 肿瘤的分级和分期","肿瘤分期",2005,43,"A","","肿瘤分期是指",[["A","肿瘤细胞的分化程度"],["B","肿瘤的恶性程度"],["C","肿瘤细胞核分裂象的多少"],["D","肿瘤的生长范围和扩散程度"],["E","肿瘤细胞的浸润及转移能力"]],"D","肿瘤的“分期”是指恶性肿瘤的生长范围和播散程度（D对），肿瘤的分期与原发肿瘤的大小，浸润深度，浸润范围，邻近器官受累情况，局部和远处淋巴结转移情况，远处转移等有关。肿瘤细胞的分化程度（A错）、肿瘤的恶性程度（B错）、肿瘤细胞核分裂象的多少（C错）、肿瘤细胞的浸润及转移能力（E错）均与肿瘤分级（十版病理学P100）有关。","","N"],["2005-N44",7,"第1节 动脉粥样硬化","冠状动脉粥样硬化",2005,44,"A","","冠状动脉粥样硬化发生率的最高的部位是",[["A","左主干"],["B","左旋支"],["C","左前降支"],["D","右冠脉"],["E","后降支"]],"C","冠状动脉粥样硬化是冠状动脉最常见的疾病，根据病变检出率和统计结果，以左冠状动脉前降支发生率为最高（C对），其余依次为右主干、左主干或左旋支、后降支。","","N"],["2005-N45",13,"第6节 神经内分泌肿瘤","类癌",2005,45,"A","","肺癌中恶性程度最低的类型是",[["A","类癌"],["B","腺癌"],["C","鳞癌"],["D","大细胞癌"],["E","小细胞癌"]],"A","肺类癌由支气管黏膜上皮及黏膜下腺体中的神经内分泌细胞（Kulchitsky细胞）发生，分化好，恶性程度低（A对）。选项中提及的肺癌类型，恶性程度从大到小依次为：小细胞癌＞大细胞癌＞腺癌＞鳞癌＞类癌。","","N"],["2005-N46",9,"第6节 病毒性肝炎","点状坏死",2005,46,"A","","肝细胞点状坏死的特点是",[["A","肝细胞核碎裂为小点状的坏死"],["B","破坏界板的坏死"],["C","形成嗜酸性小体"],["D","坏死灶仅累及几个肝细胞"],["E","伴有严重脂肪变性的坏死"]],"D","肝细胞点状坏死，为单个或数个肝细胞（D对）的坏死，常见于急性普通型肝炎。肝细胞核碎裂为小点状，是肝细胞坏死时光镜下见到的细胞核的自溶性改变，可见于各种坏死类型，非点状坏死的特点（A错）。破坏界板的坏死为碎片状坏死的特点（B错）。形成嗜酸性小体为嗜酸性坏死（凋亡）的特点（C错）。伴有严重脂肪变性的坏死见于酒精性肝病（十版病理学P208）（E错）。","","N"],["2005-N47",10,"第2节 淋巴组织肿瘤","伯基特淋巴瘤病理改变",2005,47,"A","","镜下肿瘤细胞间有散在巨噬细胞存在，形成满天星图像的淋巴瘤是",[["A","Burkitt淋巴瘤"],["B","大B细胞淋巴瘤"],["C","霍奇金淋巴瘤"],["D","滤泡型淋巴瘤"],["E","周围T细胞淋巴瘤"]],"A","镜下肿瘤细胞之间有散在的反应性巨噬细胞存在，形成了“满天星”图像是Burkitt淋巴瘤（A对）的特征性病理表现。大B细胞淋巴瘤（十版病理学P232）（B错）的病理表现是形态相对单一、体积较大的异型淋巴细胞弥漫浸润。霍奇金淋巴瘤（C错）的特征性病理表现是出现R-S细胞（十版病理学P239）。滤泡型淋巴瘤（D错）的特征性病理表现是低倍镜下肿瘤细胞明显的滤泡样生长。周围T细胞淋巴瘤（十版病理学P236）（E错）的病理表现是淋巴结的结构有不同程度的破坏，肿瘤细胞在副皮质区浸润或呈弥漫浸润，有较多的高内皮血管及瘤细胞侵袭血管现象。","","N"],["2005-N48",13,"第2节 甲状腺疾病","乳头状癌",2005,48,"A","","诊断甲状腺乳头状癌最重要的依据是",[["A","癌细胞核明显异型"],["B","癌细胞有大量核分裂象"],["C","癌细胞核明显深染"],["D","癌细胞核有粗大核仁"],["E","癌细胞核呈毛玻璃状"]],"E","乳头状癌是甲状腺癌中最常见的类型，镜下特点为乳头分支多，乳头中心间质内常见砂粒体。癌细胞分化程度不一，核染色质少（C错），常呈透明或毛玻璃状，无核仁（D错），其中癌细胞核呈毛玻璃状（E对）是最重要的诊断依据。癌细胞核明显异型（A错）见于分化差的滤泡癌。癌细胞有大量核分裂象（B错）见于未分化癌。","","N"],["2005-N49",16,"第2节 结核病","干酪性肺炎",2005,49,"A","","结核瘤是指",[["A","结核引起的良性肿瘤"],["B","结核引起的恶性肿瘤"],["C","结核引起的肿瘤样浸润性病灶"],["D","结核引起的孤立性干酪样坏死灶"],["E","结核引起的冷脓肿"]],"D","结核瘤又称结核球，属于继发性肺结核病，是由结核杆菌引起的孤立性干酪样坏死灶（D对）。结核瘤虽被称为“瘤”，但并不是真正的肿瘤（AB错），只是肺结核的一种特殊类型。结核瘤有纤维包裹，境界分明，无浸润性（C错）。冷脓肿（十版病理学P349）（E错）是骨结核的特征性表现：骨结核病变可累及骨周围软组织，形成干酪样坏死和结核性肉芽组织，坏死物液化后在骨旁形成结核性“脓肿”，该脓肿局部无红、热、痛，称为冷脓肿。","","N"],["2005-N50",4,"第1节 自身免疫病","肾",2005,50,"A","","狼疮性肾炎的特征性病变是",[["A","内皮细胞增生"],["B","苏木素小体"],["C","上皮细胞增生"],["D","中性粒细胞浸润"],["E","巨噬细胞浸润"]],"B","狼疮性肾炎是指系统性红斑狼疮（SLE）累及肾脏时，产生的肾脏免疫性损害，苏木素小体（狼疮小体）（B对）是其特征性病变。内皮细胞增生（A错）是急性弥漫性增生性肾小球肾炎的病变特点（十版病理学P254）。上皮细胞（壁层上皮细胞）增生（C错）是新月体性肾小球肾炎的病变特点（十版病理学P255）。中性粒细胞浸润（D错）可见于急性肾盂肾炎（十版病理学P263）。巨噬细胞浸润（E错）可见于药物和中毒引起的肾炎（十版病理学P265）。","","N"],["2005-N115",8,"第1节 呼吸道和肺炎症性疾病","大叶性肺炎的病理变化及临床病理联系",2005,115,"B","","大叶性肺炎的主要病理学特征是",[["A","浆液性炎"],["B","纤维素性炎"],["C","化脓性炎"],["D","出血性炎"],["E","间质性炎"]],"B","浆液性炎（A错）可见于大叶性肺炎的充血水肿期，但是大叶性肺炎的主要病理学特征是红色肝样变期和灰色肝样变期出现的纤维素性炎（B对）。化脓性炎（C错）见于小叶性肺炎（十版病理学P174）。出血性炎（D错）见于肺出血肾炎综合征（Goodpasture syndrome）（十版病理学P255）。间质性炎（E错）见于病毒性肺炎（十版病理学P175）和支原体肺炎（十版病理学P176）。","","N"],["2005-N116",8,"第1节 呼吸道和肺炎症性疾病","病毒性肺炎的病理变化",2005,116,"B","","病毒性肺炎的主要病理学特征是",[["A","浆液性炎"],["B","纤维素性炎"],["C","化脓性炎"],["D","出血性炎"],["E","间质性炎"]],"E","病毒性肺炎的主要病理学特征是间质性炎（E对），镜下表现为间质水肿及淋巴细胞、单核细胞浸润。浆液性炎（A错）可见于大叶性肺炎的充血水肿期。纤维素性炎（B错）是大叶性肺炎（十版病理学P172）的主要特征，见于大叶性肺炎的红色肝样变期和灰色肝样变期。化脓性炎（C错）见于小叶性肺炎（十版病理学P174）。出血性炎（D错）见于肺出血肾炎综合征（Goodpasture syndrome）（十版病理学P255）。","","N"],["2005-N117",11,"第1节 肾小球疾病","急性弥漫性增生性肾小球肾炎病理变化",2005,117,"B","","急性弥漫增生性肾小球肾炎的主要病理变化是",[["A","内皮细胞增生"],["B","脏层上皮细胞增生"],["C","壁层上皮细胞增生"],["D","成纤维细胞增生"],["E","淋巴细胞增生"]],"A","急性弥漫增生性肾小球肾炎（急性肾炎）的主要病理变化是毛细血管内皮细胞（A对）和系膜细胞增生。脏层上皮细胞增生（B错）主要见于免疫复合物性肾炎（十版病理学P251），壁层上皮细胞增生（C 错）主要见于新月体性肾小球肾炎（急进性肾小球肾炎）。成纤维细胞增生（D错）和淋巴细胞增生（E错）主要见于慢性肾小球肾炎（十版病理学P260）。","","N"],["2005-N118",11,"第1节 肾小球疾病","急进性肾小球肾炎病理变化",2005,118,"B","","快速进行性肾小球肾炎的主要病理变化是",[["A","内皮细胞增生"],["B","脏层上皮细胞增生"],["C","壁层上皮细胞增生"],["D","成纤维细胞增生"],["E","淋巴细胞增生"]],"C","快速进行性肾小球肾炎又称新月体肾炎，其主要病理变化是壁层上皮细胞增生（C对），亦可见脏层上皮细胞增生（B错）。内皮细胞增生（A错）是急性弥漫性增生性肾小球肾炎（急性肾炎）的主要病理变化（十版病理学P254）。成纤维细胞增生（D错）和淋巴细胞增生（E错）主要见于慢性肾小球肾炎（十版病理学P260）。","","N"],["2005-N137",7,"第8节 心肌炎","病毒性心肌炎的病因和发病机制",2005,137,"X","","病毒性心肌炎的常见病原体有",[["A","柯萨奇病毒"],["B","埃可病毒"],["C","流行性感冒病毒"],["D","EB病毒"]],"ABC","病毒性心肌炎是指嗜心肌性病毒感染引起的心肌非特异性间质性炎症病变。几乎所有的人类病毒感染均可累及心脏，引起病毒性心肌炎。常见的病原体包括柯萨奇病毒（A对）、埃可病毒（B对）、腺病毒、流感病毒（C对）、风疹病毒、肝炎病毒等等。根据9版内科学P270，柯萨奇病毒、埃可病毒为常见病毒，而流感病毒、EB病毒并不常见，故正确答案应为AB，但原参考答案为ABC。","","N"],["2005-N138",0,"第3节 细胞可逆性损伤","细胞水肿的病理变化",2005,138,"X","","符合变性的改变有",[["A","细胞内出现异常物质"],["B","细胞内的正常物质异常增多"],["C","细胞核固缩"],["D","为可逆性损伤"]],"ABD","变性是指细胞或细胞间质受损伤后，由于代谢障碍，使细胞内或细胞间质内出现异常物质（A对）或正常物质异常蓄积（B对）的现象。常见的变性包括细胞水肿、脂肪变、玻璃样变、淀粉样变等，去除病因后，大多数变性可恢复正常，因为变性时细胞或细胞间质的损伤为可逆性损伤（D对）。核固缩、核碎裂、核溶解是细胞坏死时细胞核的表现，不属于变性的改变（C错）。","","N"],["2005-N139",9,"第12节 消化系统常见肿瘤","胃癌的概述",2005,139,"X","","与胃癌发生有关的疾病或病变有",[["A","萎缩性胃炎"],["B","胃溃疡"],["C","黏膜上皮非典型增生"],["D","黏膜肠上皮化生"]],"ABCD","慢性萎缩性胃炎（A对）、胃息肉、胃溃疡（B对）、胃黏膜上皮非典型增生（C对）、胃黏膜肠上皮化生（D对）等均与胃癌的发生有关。","","N"],["2005-N140",16,"第2节 结核病","局灶型肺结核",2005,140,"X","","局灶型肺结核的特点有",[["A","病灶位于肺下叶上部"],["B","境界清楚"],["C","以增生性病变为主"],["D","属活动性结核病"]],"BC","局灶型肺结核是继发性肺结核病的早期病变，X线可见位于肺尖部的结节状病灶（A错）。病灶境界清楚（B对），有纤维包裹。镜下病变以增生性病变为主（C对），中央为干酪样坏死。患者常无自觉症状，多在体检时发现，属于非活动性结核病（D错）。","","N"],["2006-N37",1,"第1节 再生","肌组织的再生",2006,37,"A","","下列细胞中，再生能力最弱的是",[["A","心肌细胞"],["B","骨细胞"],["C","纤维细胞"],["D","血管内皮细胞"],["E","平滑肌细胞"]],"A","按再生能力的强弱可将人体细胞分为不稳定细胞、稳定细胞、永久性细胞三类。不稳定细胞的再生能力最强，这类细胞总是都在进行新老更替，具有应对损伤的强大再生修复能力。稳定细胞的再生能力次之，这类细胞在生理情况下再生现象并不明显，但当受到损伤时，会表现出较强的再生能力，骨细胞（B错）、纤维细胞（C错）、血管内皮细胞（D错）和平滑肌细胞（E错）均属于稳定细胞。永久性细胞再生能力最弱，这类细胞无论在生理情况下还是在受到损伤刺激的情况下，均不具有再生能力，心肌细胞即属于永久性细胞（A对）。","","N"],["2006-N38",2,"第1节 充血和淤血","肺淤血",2006,38,"A","","急性肺淤血时，肺泡腔内的主要成分是",[["A","心力衰竭细胞"],["B","纤维蛋白"],["C","伊红色水肿液"],["D","嗜中性粒细胞"],["E","黏液"]],"C","急性肺淤血时，毛细血管扩张充血，肺泡间隔水肿，部分肺泡腔内充满伊红色水肿液（C对）。心力衰竭细胞（A错）见于慢性肺淤血。纤维蛋白（B错）主要见于大叶性肺炎的渗出，急性肺淤血肺泡腔内含有少量纤维蛋白，纤维蛋白不是其主要成分。中性粒细胞浸润为细菌性肺炎的特点（D错）。黏液由呼吸道腺体分泌，在呼吸道感染时增多（E错）。","","N"],["2006-N39",3,"第3节 慢性炎症","肉芽肿性炎的常见类型",2006,39,"A","","下列选项中，属于肉芽肿性炎的疾病是",[["A","梅毒"],["B","阿米巴病"],["C","痢疾"],["D","白喉"],["E","淋病"]],"A","梅毒（A对）是由梅毒螺旋体引起的慢性肉芽肿性炎。阿米巴病（B错）是以组织溶解液化性坏死为主的变质性炎（十版病理学P358）。急性细菌性痢疾（C错）早期是卡他性炎，后期为假膜性炎（十版病理学P351）。白喉（D错）是发生于黏膜的纤维素性炎，又称假膜性炎（十版病理学P72）。淋病（E错）是由淋病奈瑟菌（淋球菌）引起的急性化脓性炎（十版病理学P355）。","","N"],["2006-N40",5,"第12节 肿瘤与遗传","常染色体显性遗传的遗传性肿瘤综合征",2006,40,"A","","属于常染色体显性遗传的遗传性肿瘤综合征是",[["A","Bloom综合征"],["B","着色性干皮病"],["C","Fanconi贫血"],["D","神经纤维瘤病Ⅰ型"],["E","毛细血管扩张性共济失调症"]],"D","常染色体显性遗传的遗传性肿瘤综合征包括家族性视网膜母细胞瘤、家族性腺瘤性息肉病、神经纤维瘤病（D对）等。常染色体隐性遗传的遗传性肿瘤综合征包括着色性干皮病（B错）、毛细血管扩张性共济失调症（E错）、Bloom综合征（A错）、Li-Fraumeni综合征、Fanconi贫血（先天性再生障碍性贫血）（C错）等。","","N"],["2006-N41",5,"第3节 肿瘤的命名与分类","肿瘤的分类",2006,41,"A","","下列肿瘤中，属于良性肿瘤的是",[["A","视网膜母细胞瘤"],["B","神经母细胞瘤"],["C","骨母细胞瘤"],["D","肾母细胞瘤"],["E","肝母细胞瘤"]],"C","来源于幼稚组织的肿瘤称为母细胞瘤，其中大多数为恶性肿瘤，多见于儿童。常见的恶性肿瘤有：视网膜母细胞瘤（A错）、神经母细胞瘤（B错）、髓母细胞瘤、肾母细胞瘤（D错）、肝母细胞瘤（E错）等；良性肿瘤有：骨母细胞瘤（C对）、软骨母细胞瘤、脂肪母细胞瘤和肌母细胞瘤。由于母细胞瘤多数为恶性，牢记几种良性母细胞瘤即可。","","N"],["2006-N42",5,"第3节 肿瘤的命名与分类","肿瘤的分类",2006,42,"A","","下列肿瘤中，属于恶性肿瘤的是",[["A","血管瘤"],["B","软骨母细胞瘤"],["C","纤维腺瘤"],["D","多形性腺瘤"],["E","精原细胞瘤"]],"E","血管瘤（十版病理学P105）为发生于血管的间叶组织良性肿瘤（A错）。软骨母细胞瘤为来源于幼稚软骨细胞的良性肿瘤（B错）。纤维腺瘤为多发于乳腺（十版病理学P285）的由上皮和间叶组织构成的良性肿瘤（C错）。多形性腺瘤又称腮腺混合瘤，是一种含有腮腺组织、黏液和软骨样组织的良性肿瘤（D错）。精原细胞瘤（十版病理学P281）为发生于睾丸原始生殖细胞的恶性肿瘤（E对）。在历年西医综合真题中，良恶性肿瘤的鉴别反复出现，现将常考的良恶性肿瘤归纳如下——良性肿瘤：骨母细胞瘤、软骨母细胞瘤（B错）、脂肪母细胞瘤、肌母细胞瘤、葡萄胎、血管瘤（A错）、神经鞘瘤、纤维腺瘤（C错）、多形性腺瘤（D错）；恶性肿瘤：淋巴瘤、白血病、黑色素瘤、视网膜母细胞瘤、神经母细胞瘤、肾母细胞瘤、肝母细胞瘤、绒毛膜癌、无性细胞瘤、精原细胞瘤（E对）、骨髓瘤、尤文氏瘤。","","N"],["2006-N43",7,"第2节 高血压病","肾脏病变",2006,43,"A","","引起原发性颗粒性固缩肾的最主要病变是",[["A","部分肾小球纤维化"],["B","肾间质纤维组织增生"],["C","肾间质淋巴细胞浸润"],["D","入球小动脉玻璃样变性"],["E","部分肾小球代偿性肥大"]],"D","肾小球纤维化（A）、肾间质纤维组织增生（B）、肾间质淋巴细胞浸润（C）、部分肾小球代偿性肥大（E）均为原发性颗粒性固缩肾的病变特点。但引起这些病理变化的根本原因是肾入球动脉的玻璃样变性（D对）。","","N"],["2006-N44",8,"第1节 呼吸道和肺炎症性疾病","病毒性肺炎的病理变化",2006,44,"A","","病毒性肺炎的特征性病变是",[["A","纤维素性肺炎"],["B","化脓性肺炎"],["C","出血性肺炎"],["D","肺纤维化"],["E","间质性肺炎"]],"E","病毒性肺炎的主要病理学特征是间质性炎（E对），镜下表现为间质水肿及淋巴细胞、单核细胞浸润。纤维素性肺炎（A错）是大叶性肺炎（十版病理学P172）的主要特征，见于大叶性肺炎的红色肝样变期和灰色肝样变期。化脓性肺炎（B错）见于小叶性肺炎（十版病理学P174）。出血性肺炎（C错）见于肺出血肾炎综合征（Goodpasture syndrome）（十版病理学P255）。肺纤维化（D错）见于肺硅沉着病（矽肺）（十版病理学P182）。","","N"],["2006-N45",9,"第8节 肝硬化","镜下",2006,45,"A","","肝硬化的特征性病变是",[["A","肝细胞增生"],["B","小胆管增生"],["C","肝细胞坏死"],["D","慢性炎细胞浸润"],["E","假小叶形成"]],"E","肝硬化是一种或多种原因引起的、以肝组织弥漫性纤维化、假小叶形成和再生结节为组织学特征的进行性慢性肝病，假小叶是由广泛增生的纤维组织分割原来的肝小叶并包绕成大小不等的圆形或类圆形的肝细胞团，是肝硬化的特征性病变，对肝硬化的诊断有重要意义（E对）。肝细胞增生（A错）、小胆管增生（B错）、肝细胞坏死（C错）、慢性炎细胞浸润（D错）均可在肝硬化中见到，但并非肝硬化的特征性病变。","","N"],["2006-N46",10,"第2节 淋巴组织肿瘤","非霍奇金淋巴瘤的概述",2006,46,"A","","下列关于非霍奇金淋巴瘤的叙述，错误的是",[["A","多数为B细胞起源"],["B","正常淋巴结结构破坏"],["C","可伴有免疫功能缺陷"],["D","多克隆起源"],["E","确诊时，常已有播散"]],"D","大多数非霍奇金淋巴瘤（NHL）都是B细胞起源（A对）的。NHL正常淋巴结结构被破坏（B对），淋巴滤泡和淋巴窦消失。NHL的发生与淋巴细胞增殖分化产生的某种免疫细胞恶变有关，且免疫力低下患者的发病率较高，因此NHL可伴有免疫功能缺陷（C对）。与其他恶性肿瘤一样，非霍奇金淋巴瘤是由单个肿瘤细胞反复分裂增殖而来，为单克隆起源（D错，为本题正确答案）。NHL多为侵袭性，发展迅速，确诊时常已发生播散（E对）。","","N"],["2006-N47",11,"第1节 肾小球疾病","急进性肾小球肾炎发病机制",2006,47,"A","","引起新月体性肾小球肾炎发生的主要基础病变是",[["A","基底膜缺损、断裂"],["B","中性粒细胞渗出"],["C","单核细胞渗出"],["D","系膜细胞增生"],["E","内皮细胞增生"]],"A","新月体性肾小球肾炎又称急进性肾小球肾炎，其主要基础病变是基底膜缺损、断裂（A对），使纤维素从肾小球毛细血管渗出，进入肾小球囊，刺激肾小球囊的壁层细胞大量增生，形成新月体。中性粒细胞渗出和单核细胞渗出均可见于新月体性肾小球肾炎，但非主要基础病变（BC错）。系膜细胞增生（D错）和内皮细胞增生（E错）见于急性弥漫性增生性肾小球肾炎（急性肾炎）（十版病理学P254）。","","N"],["2006-N48",16,"第2节 结核病","原发性肺结核病",2006,48,"A","","下列选项中，由原发性肺结核引起的是",[["A","急性粟粒性肺结核"],["B","局灶型肺结核"],["C","浸润型肺结核"],["D","干酪性肺炎"],["E","空洞性肺结核"]],"A","原发性肺结核病的原发综合征形成后，由于细胞免疫的建立，大多数病例将不再发展，但少数可出现病灶扩大、干酪样坏死和空洞形成，有的甚至在肺内或全身播散形成急性粟粒性肺结核病（A对）。局灶型肺结核（B错）、浸润型肺结核（C错）、干酪性肺炎（D错）和（慢性纤维）空洞型肺结核（E错）均属于继发性肺结核。","","N"],["2006-N49",4,"第1节 自身免疫病","病因和发病机制",2006,49,"A","","类风湿关节炎较具特异性的自身抗体是",[["A","抗IgG Fc片段抗体"],["B","抗双股DNA和Sm抗原抗体"],["C","抗SS-A和SS-B抗体"],["D","抗DNA拓扑异构酶抗体"],["E","抗tRNA合成酶抗体"]],"A","类风湿关节炎（RA）患者中近80%存在抗IgG Fc片段抗体（A对），即类风湿因子（RF），RF的出现及滴度高低与疾病程度一致，可作为临床诊断及预后判断的重要指标，因此RF是RA较具特异性的自身抗体。抗双股DNA和Sm抗原抗体（B错）是系统性红斑狼疮（SLE）较具特异性的自身抗体（十版病理学P78）。抗SS-A和SS-B抗体（C错）是口眼干燥综合征（SS）较具特异性的自身抗体（十版病理学P81）。抗DNA拓扑异构酶抗体（D错）是硬皮病较具特异性的自身抗体（十版病理学P82）。抗tRNA合成酶抗体（E错）是多发性肌炎（PM）较具特异性的自身抗体（十版病理学P81）。","","N"],["2006-N50",11,"第3节 肾和膀胱常见肿瘤","肾细胞癌病理变化",2006,50,"A","","肾细胞癌最常见的病理组织学类型是",[["A","乳头状癌"],["B","透明细胞癌"],["C","嫌色细胞癌"],["D","集合管癌"],["E","未分化癌"]],"B","肾细胞癌具有多种不同的病理组织学类型，其中以肾透明细胞癌（B对）最为常见（约占70%～80%）。其它组织学类型有：乳头状肾细胞癌（约占10%～15%）（A错）、嫌色性肾细胞癌（约占5%）（C错）、集合管癌（<1%）（D错）和未分类性肾癌（3%～5%）。","","N"],["2006-N115",9,"第6节 病毒性肝炎","大块及亚大块坏死",2006,115,"B","","急性重型肝炎的特征性病变是",[["A","点状坏死"],["B","桥接坏死"],["C","碎片状坏死伴桥接坏死"],["D","亚大片坏死"],["E","大片坏死"]],"E","急性重型肝炎起病急骤，病变严重，镜下表现为肝细胞坏死广泛而严重，肝细胞索解离，肝细胞溶解，出现弥漫性大片坏死（E对）。点状坏死常见于急性普通型肝炎（A错）。桥接坏死（B错）及碎片状坏死伴桥接坏死（C错）均见于常见于中、重度慢性肝炎（十版病理学P204）。亚大片状坏死常见于亚急性重型肝炎（D错）。","","N"],["2006-N116",9,"第6节 病毒性肝炎","碎片状坏死",2006,116,"B","","中度慢性肝炎的特征性病变是",[["A","点状坏死"],["B","桥接坏死"],["C","碎片状坏死伴桥接坏死"],["D","亚大片坏死"],["E","大片坏死"]],"C","中度慢性肝炎肝细胞变性坏死较明显，中度碎片状坏死，并伴有桥接坏死（C对B错）。点状坏死见于急性普通型肝炎（A错）。亚大片状坏死常见于亚急性重型肝炎（D错）。大片坏死常见于急性重型肝炎和亚急性重型肝炎（E错）。本题答案略有争议，有人认为仅桥接坏死为特征性病变，答案应为B，官方参考答案为C。","","N"],["2006-N117",7,"第4节 风湿病","风湿性心内膜炎",2006,117,"B","","风湿性心内膜炎的发生",[["A","由致病力强的化脓菌引起"],["B","由致病力弱的草绿色链球菌引起"],["C","与A组溶血性链球菌感染有关"],["D","与系统性红斑狼疮有关"],["E","与慢性消耗性疾病有关"]],"C","风湿病是一种与A组β溶血链球菌感染有关的变态反应性疾病，病变累及心内膜时发生风湿性心内膜炎，故风湿性心内膜炎的发生与A组溶血性链球菌感染有关（C对）。由致病力强的化脓菌引起的是急性感染性心内膜炎（十版病理学P158）（A错）。由致病力弱的草绿色链球菌引起的是亚急性感染性心内膜炎（十版病理学P158）（B错）。与系统性红斑狼疮有关的是非细菌性疣赘性心内膜炎（Libman-Sacks心内膜炎）（十版病理学P80）（D错）。与慢性消耗性疾病有关的是非细菌性血栓性心内膜炎（消耗性心内膜炎）（E错）。","","N"],["2006-N118",7,"第5节 感染性心内膜炎","亚急性感染性心内膜炎",2006,118,"B","","亚急性细菌性心内膜炎的发生",[["A","由致病力强的化脓菌引起"],["B","由致病力弱的草绿色链球菌引起"],["C","与A组溶血性链球菌感染有关"],["D","与系统性红斑狼疮有关"],["E","与慢性消耗性疾病有关"]],"B","亚急性感染性心内膜炎主要由毒力相对较弱的草绿色链球菌所引起（约占75%）（B对），还有肠球菌、革兰氏阴性杆菌、立克次体、真菌等均可引起此病的发生。由致病力强的化脓菌引起的是急性感染性心内膜炎（十版病理学P158）（A错）。与A组溶血性链球菌感染有关的是风湿性心内膜炎（十版病理学P156）（C错）。与系统性红斑狼疮有关的是非细菌性疣赘性心内膜炎（Libman-Sacks心内膜炎）（十版病理学P80）（D错）。与慢性消耗性疾病有关的是非细菌性血栓性心内膜炎（消耗性心内膜炎）（E错）。","","N"],["2006-N137",0,"第1节 适应","代偿性肥大",2006,137,"X","","下列选项中，不伴有细胞增生的肥大有",[["A","高血压病性心肌病理性肥大"],["B","运动员骨骼肌生理性肥大"],["C","妊娠子宫生理性肥大"],["D","哺乳期乳腺生理性肥大"]],"AB","肥大指细胞、组织或器官的体积增大，增生指组织或器官内的细胞数量增多，组织和器官的肥大通常是由于实质细胞的体积增大所致，但也可伴实质细胞数量的增多。对于细胞增殖能力强的子宫（C错）、乳腺（D错）等，其组织器官的肥大可以是细胞体积增大（肥大）和细胞数量增多（增生）的共同结果，但对于细胞分裂增殖能力较低的心肌（A对）、骨骼肌（B对）等，其组织器官的肥大仅因细胞肥大所致。","","N"],["2006-N138",3,"第2节 急性炎症","血管通透性增加",2006,138,"X","","炎症时，引起渗出增加的原因有",[["A","新生毛细血管增加"],["B","血管内皮细胞损伤"],["C","血管内皮细胞收缩"],["D","血管内皮细胞穿胞作用增强"]],"ABCD","炎症局部组织血管内的液体和细胞成分，通过血管壁进入组织间质、体腔、黏膜表面和体表的过程叫做渗出。血管通透性增加是导致炎症局部液体和蛋白渗出血管的重要原因。在炎症过程中，引起血管通透性增加的机制有新生毛细血管高通透性（A对）、内皮细胞损伤（B对）、内皮细胞收缩（C对）、内皮细胞穿胞作用增强（D对）。","","N"],["2006-N139",16,"第2节 结核病","干酪性肺炎",2006,139,"X","","干酪样坏死的形态学特征有",[["A","镜下不见原有组织结构轮廓"],["B","肉眼观坏死灶微黄、细腻"],["C","周围有大量嗜中性粒细胞浸润"],["D","周围反应中常有异型性细胞存在"]],"AB","干酪样坏死是一种坏死更为彻底的凝固性坏死，其形态学特征有：肉眼观，坏死灶呈淡黄色（微黄），均匀细腻（B对）；镜下观，不见坏死部位原有组织结构轮廓（A对），仅剩无结构颗粒状红染物。干酪样坏死周围有上皮样细胞、Langhans巨细胞和大量淋巴细胞浸润（C错）。周围反应中有异型性细胞存在（D错）提示恶性肿瘤的发生。","","N"],["2006-N140",4,"第2节 免疫缺陷病","发病机制",2006,140,"X","","HIV可以感染的细胞有",[["A","CD4⁺T细胞"],["B","巨噬细胞"],["C","树突状细胞"],["D","B细胞"]],"ABC","艾滋病（AIDS）是由HIV（人类免疫缺陷病毒）感染所引起的：①HIV可以感染CD4⁺T细胞（A对），②HIV可以感染巨噬细胞（B对）。③HIV可以感染树突状细胞（C对），并使其成为HIV的“储备池，④HIV感染后，可通过多克隆抗体激活B淋巴细胞，使外周血液中B淋巴细胞数量增加”。","","N"],["2007-N37",0,"第1节 适应","萎缩的病理变化",2007,37,"A","","萎缩发生时，细胞内常出现",[["A","脂褐素"],["B","含铁血黄素"],["C","胆红素"],["D","黑色素"]],"A","萎缩是指已发育正常的细胞、组织或器官的体积缩小，是细胞适应的一种类型，萎缩细胞胞质中常可出现脂褐素颗粒（A对）。含铁血黄素是巨噬细胞吞噬、降解红细胞血红蛋白所产生的铁蛋白微粒聚集体，生理、病理情况下均可见（B错）。胆红素为血液中红细胞衰老破坏后的产物，常见于慢性出血性疾病（C错）。黑色素可见于黑色素细胞、皮肤基底部的角质细胞及真皮的巨噬细胞内，病理情况下还可见于色素痣、黑色素瘤、基底细胞癌等（D错）。","","N"],["2007-N38",0,"第4节 细胞不可逆性损伤（细胞死亡）","干酪样坏死",2007,38,"A","","光镜下，干酪样坏死的病理改变是",[["A","属于凝固性坏死，但保存原有的组织轮廓"],["B","属于凝固性坏死，原有的组织轮廓消失"],["C","属于液化性坏死，但仍保持细胞周围网架结构"],["D","属于液化性坏死，细胞周围网架结构被破坏"]],"B","干酪样坏死为坏死更彻底的特殊类型凝固性坏死，多位于结核病灶内，因病灶中含脂质较多，坏死区呈黄色，状似干酪而得名。干酪样坏死在光镜下为无结构颗粒状红染物，不见坏死部位原有组织轮廓（B对），甚至不见核碎屑。","","N"],["2007-N39",2,"第1节 充血和淤血","肺淤血",2007,39,"A","","肺褐色硬化是下列哪种疾病的形态改变",[["A","特发性肺纤维化"],["B","机化性肺炎"],["C","慢性肺淤血"],["D","大叶性肺炎"]],"C","慢性肺淤血（C对）时，由于长期缺氧造成肺间质纤维组织增生，肺质地变硬，加之大量含铁血黄素沉积，肺呈棕褐色，发生肺褐色硬化。特发性肺纤维化（A错）是一种原因不明，以弥漫性肺泡炎和肺泡结构紊乱为特征，最终导致肺间质纤维化为特征的疾病。大叶性肺炎（十版病理学P172）（D错）是主要由肺炎球菌引起的以肺泡内弥漫性纤维素渗出为主的炎症。机化性肺炎（十版病理学P173）（B错）又称肺肉质变，为大叶性肺炎的并发症，因肺内炎性病灶中中性粒细胞渗出过少，释放的蛋白酶量不足以溶解渗出物中的纤维素，大量未能被溶解吸收的纤维素被肉芽组织取代而机化所致。","","N"],["2007-N40",3,"第3节 慢性炎症","肉芽肿性炎的概念",2007,40,"A","","肉芽肿性炎症时，最主要的特征性炎症细胞来源于",[["A","中性粒细胞"],["B","巨噬细胞"],["C","淋巴细胞"],["D","嗜酸性粒细胞"]],"B","肉芽肿性炎以炎症局部巨噬细胞及其衍生细胞增生形成境界清楚的结节状病灶（即肉芽肿）为特征，是一种特殊类型的慢性炎症。肉芽肿最具特征性的炎症细胞是上皮样细胞和多核巨细胞，具有诊断意义，此两种细胞均来源于巨噬细胞（B对）。中性粒细胞多见于化脓性炎症（A错）。淋巴细胞多见于非特异性慢性炎症（C错）。嗜酸性粒细胞多见于过敏性炎症和寄生虫感染性炎症（D错）。","","N"],["2007-N41",5,"第7节 良性肿瘤与恶性肿瘤的区别","良性肿瘤与恶性肿瘤诊断方法",2007,41,"A","","目前鉴别肿瘤良、恶性最有效的方法是",[["A","HE染色后光镜检查"],["B","锇酸染色后电镜检查"],["C","免疫组织化学染色检查"],["D","分子生物学检查"]],"A","临床病理医生常通过观察肿瘤的结构异型性和细胞异型性来判断肿瘤的良恶性，最常用、最有效的方法即HE染色后光镜检查（如P92图6-2、P93图6-3）（A对）。锇酸染色后电镜检查可用于鉴别某些肿瘤的组织起源，并不用于鉴别肿瘤的良恶性（B错）。免疫组织化学染色也可用于鉴别肿瘤的组织起源（如鉴别分化差的癌和肉瘤，已取代锇酸染色后电镜检查），及对HE难以诊断的肿瘤进行诊断，也不用于鉴别肿瘤的良恶性（C错）。分子生物学检查是近几年兴起的肿瘤学检测方法，通过检测某些肿瘤基因的表达水平，用于肿瘤的早期诊断、个性化治疗、预后等工作，而不用于鉴别肿瘤的良恶性（D错）。","","N"],["2007-N42",12,"第1节 子宫颈疾病","子宫颈鳞状上皮内病变",2007,42,"A","","子宫颈癌最重要的病因是",[["A","HIV感染"],["B","HBV感染"],["C","HPV感染"],["D","HCV感染"]],"C","子宫颈癌最重要的病因是HPV（人乳头瘤病毒）感染（C对）。HIV（人类免疫缺陷病毒）（十版病理学P84）感染（A错）与艾滋病有关。HBV（乙型肝炎病毒）感染（B错）和HCV（丙型肝炎病毒）感染（D错）均与肝炎及肝硬化、肝癌有关。","","N"],["2007-N43",7,"第1节 动脉粥样硬化","损伤-应答反应学说",2007,43,"A","","在动脉粥样硬化的发病机制中，粥样斑块形成的首要条件是",[["A","慢性、反复的血管内皮细胞损伤"],["B","血脂的沉积及其氧化作用"],["C","炎症细胞的渗出"],["D","平滑肌细胞反应"]],"A","根据动脉粥样硬化的损伤-应答反应学说，慢性、反复的血管内皮细胞损伤是所有动脉粥样硬化病发生的首要条件（A对），血脂的沉积及其氧化作用（B错）、炎症细胞的渗出（C错）、平滑肌细胞反应（D错）均为继发于血管内皮细胞损伤的改变。","","N"],["2007-N44",8,"第8节 呼吸系统常见肿瘤","腺癌",2007,44,"A","","下列癌中，属于肺腺癌特殊类型的是",[["A","小细胞肺癌"],["B","大细胞肺癌"],["C","肺类癌"],["D","肺瘢痕癌"]],"D","肺癌按组织学可分为鳞状细胞癌、腺癌、腺鳞癌、小细胞癌、大细胞癌、肉瘤样癌、类癌和唾液腺癌8个基本类型，因此小细胞肺癌（A错）、大细胞肺癌（B错）和肺类癌（C错）为肺腺癌的平行概念，不属于肺腺癌的特殊类型。肺瘢痕癌（Ｄ对）为肺腺癌的特殊类型，因伴纤维化或瘢痕形成而得名。","","N"],["2007-N45",9,"第3节 消化性溃疡病","消化性溃疡病的病理变化",2007,45,"A","","下列关于消化性溃疡形态特征的叙述，错误的是",[["A","表层以伊红色坏死组织和炎性渗出为主"],["B","坏死组织下是大量新生毛细血管和成纤维细胞"],["C","底层瘢痕内可见闭塞性动脉内膜炎"],["D","溃疡周围见大量异型细胞增生"]],"D","消化性溃疡是以胃或十二指肠黏膜形成慢性溃疡的一种疾病，镜下，溃疡底部由内向外分四层：最表层为白细胞、纤维素等炎性渗出，其下为伊红色坏死组织（A对）；坏死组织下则见由大量新生毛细血管和成纤维细胞组成的肉芽组织层（十版病理学P33）（B对）；最下层由肉芽组织移行为陈旧瘢痕组织。瘢痕底部小动脉因炎症刺激常有增殖性动脉内膜炎，使小动脉管壁增厚，管腔狭窄或有血栓形成，可出现闭塞性动脉内膜炎（C对）。溃疡周围见大量异型细胞增生为恶性肿瘤溃疡的表现（D错，为本题正确答案）。","","N"],["2007-N46",11,"第1节 肾小球疾病","微小病变性肾小球病病理变化",2007,46,"A","","微小病变肾病的主要病理改变是",[["A","常规光镜检查肾小球无异常，免疫荧光显示其毛细血管基膜上有免疫复合物沉积"],["B","常规光镜检查肾小球无异常，电镜显示肾小球上皮细胞足突融合或消失"],["C","常规光镜检查显示肾小球内存在微小硬化灶"],["D","常规光镜检查显示肾小球内存在微小炎细胞浸润灶"]],"B","微小病变肾病又称脂性肾病，其病理检查可见：常规光镜下肾小球无异常，电镜下肾小球上皮细胞足突融合或消失（B对）。常规光镜检查肾小球无异常、免疫荧光显示毛细血管基膜上有免疫复合物沉积（十版病理学P256）见于膜性肾病（A错）。常规光镜检查显示肾小球内存在微小硬化灶（十版病理学P259）是局灶节段性肾小球肾炎的病理改变（C错）。常规光镜检查肾小球内存在微小炎细胞浸润灶（十版病理学P254）见于急性肾炎（D错）。","","N"],["2007-N47",4,"第2节 免疫缺陷病","HIV感染CD4⁺T细胞",2007,47,"A","","HIV感染细胞时，主要的入侵门户是",[["A","CD3"],["B","CD4"],["C","CD8"],["D","CD20"]],"B","CD4分子（B对）是HIV（人类免疫缺陷病毒）的主要受体，也是HIV感染细胞时入侵的主要门户：当HIV感染人体时，将与CD4受体和共受体（趋化因子受体CXCR4和CCR5）结合而进入CD4⁺T细胞内，造成CD4⁺T细胞大量破坏、功能受损，导致细胞免疫缺陷。","","N"],["2007-N48",10,"第2节 淋巴组织肿瘤","滤泡性淋巴瘤细胞遗传学",2007,48,"A","","滤泡型淋巴瘤发生的主要分子机制是",[["A","BCL-2基因转位"],["B","BCL-2基因点突变"],["C","BCL-2基因扩增"],["D","BCL-2基因缺失"]],"A","BCL-2基因是一种原癌基因，它具有抑制凋亡的作用。滤泡型淋巴瘤（FL）发生的主要分子机制为：18号染色体上的BCL-2基因转位（A对），使BCL-2基因活化，引起BCL-2蛋白的高表达。基因点突变（B错）和基因扩增（C错）也是原癌基因活化的常见方式（十版病理学P111），但与FL的发生无关。基因缺失是抑癌基因的致癌机制（十版病理学P113）（D错）。","","N"],["2007-N49",12,"第5节 前列腺疾病","前列腺癌病理变化",2007,49,"A","","增生腺体周围的一种细胞缺失是病理确认前列腺癌的重要依据，这种细胞是",[["A","基底细胞"],["B","肌上皮细胞"],["C","腺上皮细胞"],["D","成纤维细胞"]],"A","前列腺腺体基底细胞（A对）缺失是病理确认前列腺癌的重要依据。机制未明，有文献指出，基底细胞缺失与肿瘤浸润可能相互促进，肿瘤浸润促进基底细胞缺失，而基底细胞缺失又可使肿瘤细胞微环境发生变化而促进肿瘤浸润。","","N"],["2007-N50",14,"第3节 中枢神经系统感染性疾病","脑膜炎概述",2007,50,"A","","流行性脑膜炎时，病变主要累及",[["A","胶质细胞"],["B","神经元"],["C","硬脑膜"],["D","软脑膜"]],"D","流行性脑膜炎是由脑膜炎双球菌感染引起的急性化脓性炎症，包括硬脑膜炎和软脑膜炎，由于各种抗生素的问世和临床应用，继发于颅骨感染的硬脑膜炎（C错）发病率大为降低，现在脑膜炎一般是指软脑膜炎（D对）。累及脑实质（包括胶质细胞、神经元等）（AB错）的为流行性乙型脑炎的主要病变（十版病理学P312）。","","N"],["2007-N115",5,"第11节 环境致瘤因素","人乳头状瘤病毒",2007,115,"B","","HPV的E6蛋白能灭活",[["A","ras基因产物"],["B","p53基因产物"],["C","Rb基因产物"],["D","myc基因产物"]],"B","HPV（人乳头瘤病毒）与宫颈癌的发病密切相关，HPV可分泌E6和E7两种病毒蛋白，前者可抑制p53基因产物（B对），后者可抑制Rb基因产物（P122页E6、E7与RB、p53的对应关系有误）。p53基因和Rb基因为人体内最重要的两种抑癌基因，即HPV通过灭活抑癌基因产物发挥致癌作用。","","N"],["2007-N116",5,"第11节 环境致瘤因素","人乳头状瘤病毒",2007,116,"B","","HPV的E7蛋白能灭活",[["A","ras基因产物"],["B","p53基因产物"],["C","Rb基因产物"],["D","myc基因产物"]],"C","HPV（人乳头瘤病毒）与宫颈癌的发病密切相关，HPV可分泌E6和E7两种病毒蛋白，前者可抑制p53基因产物，后者可抑制Rb基因产物（P122页E6、E7与RB、p53的对应关系有误）（C对）。p53基因和Rb基因为人体内最重要的两种抑癌基因，即HPV通过灭活抑癌基因产物发挥致癌作用。","","N"],["2007-N117",16,"第3节 伤寒","溃疡期",2007,117,"B","","肠伤寒可见",[["A","三角烧瓶样溃疡"],["B","与肠长轴平行的溃疡"],["C","与肠长轴垂直的溃疡"],["D","火山口状溃疡"]],"B","肠伤寒溃疡期时，坏死肠黏膜脱落后可形成圆形或椭圆形的溃疡，其长轴与肠的长轴平行（B对）。三角烧瓶样溃疡（A错）见于肠阿米巴病（十版病理学P358）。与肠长轴垂直的溃疡（C错）见于肠结核（十版病理学P348）。火山口状溃疡（D错）是恶性溃疡，见于胃癌（十版病理学P216）。","","N"],["2007-N118",16,"第10节 寄生虫病","肠阿米巴病病理变化概述",2007,118,"B","","阿米巴肠病可见",[["A","三角烧瓶样溃疡"],["B","与肠长轴平行的溃疡"],["C","与肠长轴垂直的溃疡"],["D","火山口状溃疡"]],"A","阿米巴肠病可见口小底大的三角烧瓶样溃疡（A对）。与肠长轴平行的溃疡（B错）见于肠伤寒（十版病理学P350）。与肠长轴垂直的溃疡（C错）见于肠结核（十版病理学P348）。火山口状溃疡（D错）常见于胃癌（十版病理学P216）。","","N"],["2007-N137",5,"第3节 肿瘤的命名与分类","肿瘤的分类",2007,137,"X","","下列肿瘤中，属于良性肿瘤的有",[["A","肾母细胞瘤"],["B","肌母细胞瘤"],["C","神经母细胞瘤"],["D","软骨母细胞瘤"]],"BD","肾母细胞瘤（十版病理学P266）为起源于后肾胚基组织的恶性肿瘤（A错）。肌母细胞瘤又称炎性肌纤维母细胞瘤，主要由增生的纤维母细胞及肌纤维母细胞组成，瘤组织中可见大量的炎症细胞散在分布。肌母细胞瘤的良恶性存在争议，西医综合真题的标准答案将归类为良性肿瘤（B对）。神经母细胞瘤（十版病理学P324）为发生于交感神经节和肾上腺髓质的恶性肿瘤（C错）。软骨母细胞瘤为来源于幼稚软骨细胞的良性肿瘤（D对）。在历年西医综合真题中，良恶性肿瘤的鉴别反复出现，现将常考的良恶性肿瘤归纳如下——良性肿瘤：骨母细胞瘤、软骨母细胞瘤（D对）、脂肪母细胞瘤、肌母细胞瘤（B对）、葡萄胎、血管瘤、神经鞘瘤、纤维腺瘤、多形性腺瘤；恶性肿瘤：淋巴瘤、白血病、黑色素瘤、视网膜母细胞瘤、神经母细胞瘤（C错）、肾母细胞瘤（A错）、肝母细胞瘤、绒毛膜癌、无性细胞瘤、精原细胞瘤、骨髓瘤、尤文氏瘤。","","N"],["2007-N138",8,"第2节 慢性阻塞性肺疾病","慢性支气管炎的病理变化",2007,138,"X","","慢性支气管炎的病理变化可有",[["A","柱状上皮的纤毛倒伏，甚至完全脱失"],["B","支气管腺体增生和黏液腺化生"],["C","支气管管壁中出现大量淋巴细胞"],["D","支气管管壁中软骨细胞出现不典型增生"]],"ABC","慢性支气管炎早期病变常限于较大的支气管，随病情的进展逐渐累积较小的支气管和细支气管。主要病变为：①呼吸道黏液-纤毛排送系统受损，纤毛柱状上皮变性、坏死脱落（A对），再生的上皮杯状细胞增多，并发生鳞状上皮化生；②黏膜下腺体增生肥大和浆液性上皮发生黏液腺化生（B对），导致分泌黏液增多；③管壁充血水肿，淋巴细胞、浆细胞浸润（C对）；④管壁平滑肌断裂、萎缩，软骨可变性、萎缩或骨化，但不会出现不典型增生（D错），不典型增生（异型增生）见于肿瘤性病变（十版病理学P108）。","","N"],["2007-N139",7,"第1节 动脉粥样硬化","动脉粥样硬化的危险因素",2007,139,"X","","下列选项中，动脉粥样硬化的主要危险因素有",[["A","高脂血症"],["B","高血压"],["C","吸烟"],["D","糖尿病"]],"ABCD","低密度脂蛋白（LDL）是引起动脉粥样硬化（AS）的主要因素，与极低密度脂蛋白（VLDL）共同称为致AS性的脂蛋白，而高密度脂蛋白（HDL）对AS则有预防作用。高脂血症（A对）时血浆总胆固醇含量增高，导致LDL水平升高（LDL是血液中胆固醇的主要载体），促进AS的发生。高血压（B对）时血流对血管壁的机械性压力和冲击引起血管内皮损伤，使内膜对脂质的通透性增加，脂质因渗入内膜，可促进AS发生。吸烟（C对）可使LDL易于氧化，ox-LDL可促进血液单核细胞迁入内膜并转化为泡沫细胞，促使AS发生。糖尿病（D对）患者血中甘油三酯（TG）及极低密度脂蛋白（VLDL）水平明显升高，高密度脂蛋白（HDL）水平降低，而且高血糖可使LDL氧化，促进血液单核细胞迁入内膜及转化为泡沫细胞，促进AS的发生。","","N"],["2007-N140",3,"第3节 慢性炎症","主要的慢性炎症细胞",2007,140,"X","","巨噬细胞的主要功能有",[["A","吞噬、杀灭病原菌和异物等"],["B","分泌参与炎症反应的生物活性介质"],["C","摄取并处理抗原，并把抗原信息递呈给淋巴细胞"],["D","分泌抗体，中和炎症中产生的有害物质"]],"ABC","单核-巨噬细胞是机体重要的免疫细胞（包括骨髓中的前单核细胞、外周血中的单核细胞、及组织内的巨噬细胞），在宿主防御和炎症反应中发挥关键作用。巨噬细胞能够吞噬、杀灭病原菌和异物（A对），能分泌参与炎症反应的生物活性介质（TNF、IL-1、化学趋化因子等）（B对），也能作为抗原呈递细胞摄取并处理抗原，并把抗原信息递呈给淋巴细胞（C对）。巨噬细胞不能分泌抗体，分泌抗体的是浆细胞（由B淋巴细胞分化而来）（D错）。","","N"],["2007-N172-J",0,"第3节 细胞可逆性损伤","细胞内玻璃样变",2007,172,"A","B","下列病变中，属于变性的是肝细胞浆内出现",[["A","Mallory小体"],["B","HBsAg"],["C","HBcAg"],["D","巨大病毒包涵体"]],"A","变性是指细胞或细胞间质受损伤后，由于代谢障碍，使细胞内或细胞间质内出现异常物质或正常物质异常蓄积的现象，常见的变性包括水变性、脂肪变性、玻璃样变性等。Mallory小体由肝细胞胞质中细胞中间丝前角蛋白变性聚集而成，属于玻璃样变性（A对）。乙肝表面抗原（HBsAg）（B 错）和乙肝核心抗原（HBcAg）（C 错）为乙肝病毒（HBV）的蛋白成分，与肝细胞变性无关。巨大病毒包涵体是巨细胞病毒感染的标志，与肝细胞变性无关（D 错）。","","N"],["2007-N173-J",2,"第4节 栓塞","体循环动脉栓塞",2007,173,"A","B","下肢动脉血栓栓塞最常来源于",[["A","右心"],["B","左心"],["C","主动脉"],["D","髂动脉"]],"B","在循环血液中出现的不溶于血液的异常物质，随血流运行阻塞血管腔的现象称为栓塞（十版病理学P50），阻塞血管的异常物质称为栓子，栓子的运行方向一般与血流方向一致，最终停留在口径与其相当的血管并阻断血流。来自左心的栓子（B对），随动脉血流运行，依次经左心房、左心室、升主动脉、主动脉弓、胸主动脉、腹主动脉、髂外动脉，进入下肢动脉，造成下肢动脉血栓栓塞。","","N"],["2007-N174-J",3,"第2节 急性炎症","血管通透性增加",2007,174,"A","B","炎症病灶内血管发生速发持续反应时，血管内皮的主要变化是",[["A","细胞穿胞作用增强"],["B","细胞变性，坏死"],["C","细胞迅速收缩"],["D","细胞凋亡"]],"B","在炎症过程中引起血管通透性增加的原因有内皮细胞收缩、内皮细胞损伤、内皮细胞穿胞作用增强等。其中，由炎症介质引起的内皮细胞收缩发生迅速（C错），持续时间短，被称为速发短暂反应；由内皮细胞损伤引起的细胞变性、坏死（B对）、细胞膜通透性增加等反应持续时间较长被称为速发持续反应。速发短暂反应的主要病变是细胞迅速收缩（C错）。而细胞穿胞作用增强是血管通透性增加的另一机制（A错）。炎症主要引起局部组织细胞的变性和坏死，而不是凋亡（D错）。","","N"],["2007-N175-J",5,"第3节 肿瘤的命名与分类","肿瘤的分类",2007,175,"A","B","下列肿瘤中，属于恶性肿瘤的是",[["A","无性细胞瘤"],["B","骨母细胞瘤"],["C","多形性腺瘤"],["D","畸胎瘤"]],"A","无性细胞瘤（十版病理学P281）为发生于卵巢原始生殖细胞的恶性肿瘤（A对）。骨母细胞瘤是一种特殊类型的肿瘤，过去这种肿瘤被冠以良性二字（良性骨母细胞瘤），该肿瘤在组织学上虽无恶性表现，但常有侵袭性甚至会出现肺转移或恶变，现在逐渐将良性二字弃用，但仍将其视为良性肿瘤（B错）。多形性腺瘤又称腮腺混合瘤，是一种含有腮腺组织、黏液和软骨样组织的良性肿瘤（C错）。畸胎瘤有良性畸胎瘤和恶性畸胎瘤之分，因此，畸胎瘤本身不代表良性或恶性（D错）。在历年西医综合真题中，良恶性肿瘤的鉴别反复出现，现将常考的良恶性肿瘤归纳如下——良性肿瘤：骨母细胞瘤（B错）、软骨母细胞瘤、脂肪母细胞瘤、肌母细胞瘤、葡萄胎、血管瘤、神经鞘瘤、纤维腺瘤、多形性腺瘤（C错）；恶性肿瘤：淋巴瘤、白血病、黑色素瘤、视网膜母细胞瘤、神经母细胞瘤、肾母细胞瘤、肝母细胞瘤、绒毛膜癌、无性细胞瘤（A对）、精原细胞瘤、骨髓瘤、尤文氏瘤。","","N"],["2007-N176-J",12,"第1节 子宫颈疾病","子宫颈浸润癌的临床病理联系",2007,176,"A","B","子宫颈CINⅢ是指异型增生细胞占据上皮的",[["A","下1/3"],["B","下1/3～2/3"],["C","下2/3以上但未累及全层"],["D","下2/3以上及原位癌"]],"D","CIN为宫颈上皮內瘤变的英文简称，可分为三级：CIN Ⅰ，是指异型增生细胞占据上皮的下1/3（相当于Ⅰ级异型增生）（A错）；CIN Ⅱ，是指异型增生细胞占据上皮的下1/3～2/3（相当于Ⅱ级异型增生）（B错）；CIN Ⅲ，是指异型增生细胞占据上皮的下2/3以上（相当于Ⅲ级异型增生）及原位癌（D对C错）。","","N"],["2007-N177-J",7,"第7节 心肌病","扩张型心肌病",2007,177,"A","B","特发性心肌病中，最常见的类型是",[["A","克山病"],["B","限制性心肌病"],["C","扩张性心肌病"],["D","肥厚性心肌病"]],"C","特发性心肌病亦称原发性心肌病，或简称为心肌病（七版病理学P132），主要包括三种类型：扩张性心肌病、肥厚性心肌病和限制性心肌病。克山病至今病因未明，也属于心肌病范畴。根据15版实用内科学，扩张性心肌病是最常见的类型，故正确答案为C。但是，扩张型心肌病（16版实用内科学P953）在我国的患病率约为19/10万。肥厚型心肌病（16版实用内科学P956）是导致年轻人猝死和继发性心衰的常见病因。北美、日本和中国的患病率相似，约为0.2%”（相当于200/10万）。故根据最新版本教材，本题正确答案应为D，但当年官方给出的参考答案为C。","","N"],["2007-N178-J",9,"第2节 胃炎","慢性萎缩性胃炎",2007,178,"A","B","伴有恶性贫血的慢性胃炎是",[["A","巨大肥厚性胃炎"],["B","慢性浅表性胃炎"],["C","疣状胃炎"],["D","A型慢性萎缩性胃炎"]],"D","根据发病是否与自身免疫有关以及是否伴有恶性贫血，将慢性萎缩性胃炎分为A、B两型。A型属于自身免疫病，患者血中抗壁细胞抗体和内因子抗体检查阳性，抗壁细胞抗体和内因子抗体均可使内因子减少（抗壁细胞抗体通过损害壁细胞，使壁细胞分泌内因子减少），内因子减少进而影响维生素B₁₂的吸收（九版生理学P206），导致恶性贫血（D对），即巨幼红细胞性贫血（九版生理学P206）。","","N"],["2007-N179-J",10,"第2节 淋巴组织肿瘤","结节硬化型",2007,179,"A","B","有多量陷窝细胞出现的霍奇金淋巴瘤的亚型是",[["A","结节硬化型"],["B","淋巴细胞消减型"],["C","混合细胞型"],["D","淋巴细胞为主型"]],"A","霍奇金淋巴瘤（HL）分为结节性淋巴细胞为主型霍奇金淋巴瘤（NLPHL）和经典型霍奇金淋巴瘤（CHL），CHL又分为结节硬化型、混合细胞型、富于淋巴细胞型和淋巴细胞减少型。其中，结节硬化型（A对）的特点为含有大量陷窝细胞。淋巴细胞减少型（淋巴细胞消减型）（B错）的特点为淋巴细胞大量减少，出现大量典型R-S细胞或多形性瘤细胞。混合细胞型（C错）的特点为典型R-S细胞（双核型R-S细胞）及单核型R-S细胞与各种炎细胞混合存在。淋巴细胞为主型（D错）的特点为典型R-S细胞难觅，出现大量爆米花细胞（LP细胞）。","","N"],["2007-N180-J",16,"第8节 性传播性疾病","一期梅毒",2007,180,"A","B","一期梅毒的特征性病变是",[["A","树胶样肿"],["B","硬下疳"],["C","梅毒疹"],["D","闭塞性动脉内膜炎"]],"B","后天性梅毒可分为一、二、三期，其中一期梅毒的特征性病变是硬下疳（B对）。树胶样肿（A错）是三期梅毒的特征性病变。梅毒疹（C错）是二期梅毒的特征性病变。闭塞性动脉内膜炎（D错）可见于各期梅毒。","","N"],["2008-N41",9,"第6节 病毒性肝炎","凋亡",2008,41,"A","","下列肝细胞的病理改变中，属于凋亡的是",[["A","脂肪空泡形成"],["B","嗜酸性小体形成"],["C","Mallory小体形成"],["D","病毒包涵体形成"]],"B","嗜酸性小体见于病毒性肝炎中，表现为单个细胞内深红色、细胞核消失的圆形小体，属于细胞凋亡（B对）。脂肪空泡形成多见于肝脂肪变性（A错）。酒精性肝病时，肝细胞胞质中细胞中间丝前角蛋白变性，形成Mallory小体，为玻璃样变性（十版病理学P16）（C错）。病毒包涵体是病毒感染的标志，为病毒在增殖的过程中，使寄主细胞内形成的一种蛋白质性质的病变结构，与凋亡无关（D错）。","","N"],["2008-N42",0,"第1节 适应","鳞状上皮的化生",2008,42,"A","","下列子宫内膜癌的病理类型中，与化生密切相关的是",[["A","子宫内膜样腺癌"],["B","浆液性腺癌"],["C","透明细胞癌"],["D","鳞状细胞癌"]],"D","化生是指一种分化成熟的细胞或组织被另一种分化成熟的细胞或组织所取代。判断肿瘤是否与化生有关，只需看发生肿瘤组织的细胞类型是否在原正常组织存在，若原来存在，则不是化生，若不存在，则是化生。正常情况下，子宫内膜是由腺上皮组成的，当其发生鳞状细胞癌时必然是腺上皮化生为鳞状上皮所致，与化生有关（D对）。子宫内膜样腺癌（A错）、浆液性腺癌（B错）均为腺癌，组织类型为腺上皮，故不存在化生。透明细胞癌只是一种形态学名称，因肿瘤细胞在显微镜下看起来透亮而得名。许多器官或组织均可发生透明细胞癌，如肾透明细胞癌、卵巢透明细胞、子宫内膜透明细胞癌等，因此不能从透明细胞癌推测其组织来源，也就不能推测其与化生是否有关（C错）。","","N"],["2008-N43",2,"第3节 血栓形成","透明血栓",2008,43,"A","","透明血栓的主要成分是",[["A","纤维蛋白"],["B","血小板"],["C","红细胞"],["D","中性粒细胞"]],"A","各种类型血栓的主要成分①白色血栓：血小板+少量纤维蛋白；②混合血栓：血小板+纤维蛋白+红细胞；③红色血栓：纤维蛋白+红细胞+白细胞；④透明血栓：纤维蛋白（A对）。","","N"],["2008-N44",3,"第3节 慢性炎症","肉芽肿性炎的常见类型",2008,44,"A","","下列病变中，属于非感染性肉芽肿的是",[["A","树胶样肿"],["B","伤寒小结"],["C","风湿小结"],["D","结核结节"]],"C","树胶样肿（梅毒螺旋体感染）（A错）、伤寒小结（伤寒杆菌感染）（B错）、结核结节（结核杆菌感染）（D错）均属于感染性肉芽肿。风湿小结与A组溶血性链球菌感染有关，但风湿小结并非由链球菌直接刺激产生（风湿小结内无链球菌存在），风湿小结本质上为变态反应性炎症，故风湿小结属于非感染性肉芽肿（C对）。值得注意的是十版病理学 P75-P76将肉芽肿性炎分为感染性肉芽肿、异物性肉芽肿和原因不明的肉芽肿三种类型，风湿小结似乎不能归属于以上任何一种类型。","","N"],["2008-N45",5,"第9节 癌前病变和原位癌","异型增生和原位癌",2008,45,"A","","下列病变中，属于真性肿瘤的是",[["A","动脉瘤"],["B","Bowen病"],["C","迷离瘤"],["D","错构瘤"]],"B","动脉瘤、错构瘤、迷离瘤等病变虽带“瘤”字，但不属于肿瘤。动脉瘤（十版病理学P153）是为动脉壁上的脆弱部分向外膨出、扩张而形成的薄壁球状物（A错）。迷离瘤（二版八年制病理学P128）指正常组织易位到其它部位而形成的包块（C错）。错构瘤（二版八年制病理学P128）是由与所在器官相同的组织构成，但结构紊乱比例失常而形成的包块（D错）。Bowen病又称原位鳞状细胞癌，为发生于皮肤或黏膜的表皮内鳞状细胞癌，属于真性肿瘤（B对）。","","N"],["2008-N46",4,"第3节 器官和骨髓移植排斥反应","病理变化",2008,46,"A","","超急性排斥反应时，血管病变的特点是",[["A","血管壁纤维素样坏死"],["B","血管周围纤维组织增生"],["C","血管壁玻璃样变性"],["D","血管内膜纤维化"]],"A","超急性排斥反应本质上属于由抗原抗体复合物引起的Ⅲ型变态反应，抗原抗体复合物可引发移植物血管胶原纤维肿胀崩解（十版病理学P20），使血管壁发生纤维素样坏死（A对）。血管周围纤维组织增生（B错）是系统性红斑狼疮（SLE）累及脾动脉时的病理改变（十版病理学P80）。血管壁玻璃样变性（C错）为良性高血压的基本病变（十版病理学P151）。血管内膜纤维化（D错）是慢性排斥反应的突出病变（十版病理学P89）。","","N"],["2008-N47",4,"第1节 自身免疫病","心脏",2008,47,"A","","Libman-Sacks血栓性心内膜炎常发生于",[["A","休克"],["B","败血症"],["C","癌症晚期"],["D","系统性红斑狼疮"]],"D","Libman-Sacks血栓性心内膜炎是由系统性红斑狼疮（D对）引起的非细菌性疣赘性心内膜炎，常累及二尖瓣和三尖瓣。","","N"],["2008-N48",8,"第8节 呼吸系统常见肿瘤","腺癌",2008,48,"A","","肉眼类型多为弥漫型的肺癌是",[["A","鳞状细胞癌"],["B","小细胞癌"],["C","中分化腺癌"],["D","细支气管-肺泡细胞癌"]],"D","肺癌按组织学（十版病理学P190）可分为鳞状细胞癌、腺癌、腺鳞癌、小细胞癌、大细胞癌、肉瘤样癌、类癌和唾液腺癌8个基本类型，按肿瘤在肺内分布部位（十版病理学P190）可分为中央型、周围型和弥漫型三个主要类型。细支气管-肺泡细胞癌属于高分化腺癌，多为弥漫型肺癌（D对）。鳞状细胞癌和小细胞癌多为中央型肺癌（AB错）。腺癌多为周围型肺癌（C错）。","","N"],["2008-N49",9,"第12节 消化系统常见肿瘤","伴有肠黏膜增生的慢性肠疾病",2008,49,"A","","下列病变中，与大肠癌的发生关系不密切的是",[["A","增生性息肉"],["B","腺瘤性息肉"],["C","家族性腺瘤性息肉病"],["D","溃疡性结肠炎"]],"A","腺瘤性息肉（息肉状腺瘤）（B对）、家族性腺瘤性息肉病（C对）和溃疡性结肠炎（D对）均为伴有肠黏膜增生的慢性肠疾病，与大肠癌的发生关系密切，其中家族性腺瘤性息肉病与遗传因素有关，如不予治疗，将不可避免地出现癌变。增生性息肉（A错，为本题正确答案）发生癌变的可能性小，与大肠癌无关。注：注意区分息肉与息肉病，前者只有少量息肉增生，癌变可能性很小，后者有大量息肉增生，癌变可能性大，为癌前病变。","","N"],["2008-N50",11,"第1节 肾小球疾病","膜性肾小球病病理变化",2008,50,"A","","膜性肾小球肾炎电镜下的特征性病变是",[["A","系膜区低密度电子致密物沉积"],["B","基底膜外侧驼峰样电子致密物沉积"],["C","上皮下电子致密物与基膜样物质形成钉突结构"],["D","基膜内皮侧、致密层和系膜区电子致密物沉积"]],"C","膜性肾小球肾炎在电镜下观察可见：基膜与上皮之间（上皮下）有电子致密物沉积，且沉积物之间的基膜样物质增多形成钉状突起（C对）。系膜区低密度电子致密物沉积（A错）为系膜增生性肾炎的特征性病变（十版病理学P258）。基底膜外侧驼峰样电子致密物沉积（B错）为急性弥漫性增生性肾小球肾炎（急性肾炎）的特征性病变（十版病理学P254）。基膜内皮侧、致密层和系膜区电子致密物沉积（D错）为膜增生性肾小球肾炎的特征性病变（十版病理学P258）。","","N"],["2008-N51",12,"第3节 滋养层细胞疾病","绒毛膜癌病理变化",2008,51,"A","","下列关于绒毛膜癌病理变化的叙述，错误的是",[["A","大片出血"],["B","滋养层细胞增生"],["C","可见胎盘绒毛"],["D","组织坏死"]],"C","绒毛膜癌是滋养层细胞异常增生（B对）引起的高度侵袭性恶性肿瘤。绒毛膜癌癌组织自身无间质血管，依靠侵袭宿主血管获取营养，故癌组织和周围正常组织可见大片出血（A对）及组织坏死（D对）。绒毛膜癌细胞不形成绒毛结构（C错，为本题正确答案）。","","N"],["2008-N52",10,"第2节 淋巴组织肿瘤","蕈样肉芽肿病的概述",2008,52,"A","","起源于T细胞的淋巴瘤是",[["A","套细胞淋巴瘤"],["B","Burkitt淋巴瘤"],["C","蕈样霉菌病"],["D","滤泡性淋巴瘤"]],"C","蕈样霉菌病（C对）是一种起源于T细胞的淋巴瘤。套细胞淋巴瘤（九版病理学P243）（A错）、Burkitt淋巴瘤（十版病理学P233）（B错）、滤泡性淋巴瘤（十版病理学P232）（D错）都是起源于B细胞的淋巴瘤。","","N"],["2008-N53",16,"第2节 结核病","慢性纤维空洞型肺结核",2008,53,"A","","下列选项中，属于开放性肺结核病的是",[["A","局灶型肺结核"],["B","慢性纤维空洞性肺结核病"],["C","浸润型肺结核病"],["D","结核球"]],"B","开放性肺结核病是指痰中有结核菌排出，具有较强传染性的肺结核病。慢性纤维空洞性肺结核病（B对）的病变空洞与支气管相通，痰中有大量结核菌排出，具有很强的传染性，属于开放型肺结核病。局灶型肺结核（A错）和结核球（D错）均有纤维包裹，痰中无结核菌排出，无传染性，不属于开放型肺结核。浸润性肺结核病（C错）一般不形成空洞，若形成空洞也为易愈合的急性空洞，传染性有限，不属于开放性肺结核。","","N"],["2008-N54",7,"第8节 心肌炎","特发性巨细胞性心肌炎",2008,54,"A","","以肉芽肿病变为特点的心肌炎是",[["A","特发性巨细胞性心肌炎"],["B","细菌性心肌炎"],["C","病毒性心肌炎"],["D","弓形虫性心肌炎"]],"A","特发性巨细胞性心肌炎属于孤立性心肌炎，病灶的心肌内可见灶状坏死和肉芽肿形成（A对）。细菌性心肌炎（B错）主要表现为心肌及间质多发性小脓肿（白喉性心肌炎除外），大量中性粒细胞浸润。病毒性心肌炎（C错）主要表现为心肌细胞间质水肿，淋巴细胞和单核细胞浸润。弓形虫性心肌炎（D错）表现为心肌细胞周围淋巴细胞、单核细胞浸润，愈合后瘢痕形成。","","N"],["2008-N55",12,"第7节 乳腺疾病","特殊类型浸润性癌",2008,55,"A","","乳腺髓样癌的病理组织学特点是",[["A","癌组织中大量腺体形成"],["B","癌巢小而少，大量纤维组织增生"],["C","大片癌细胞巢伴淋巴细胞浸润"],["D","大量黏液形成，其中漂浮癌细胞团"]],"C","乳腺髓样癌的镜下特点为癌细胞体积大，融合成片，癌细胞巢内间质较少，伴大量淋巴细胞浸润（C对）。癌组织中大量腺体形成（A错）为小管癌（二版八年制病理学P376）的特点。癌巢小而少，大量纤维组织增生（B错）为硬癌的特点。大量黏液形成，其中漂浮癌细胞团（D错）是黏液癌（八版病理学P97）的特点。","","N"],["2008-N56",13,"第2节 甲状腺疾病","未分化癌",2008,56,"A","","恶性程度最高的甲状腺肿瘤是",[["A","滤泡癌"],["B","乳头状癌"],["C","未分化癌"],["D","髓样癌"]],"C","甲状腺癌可分为乳头状癌（B错）、滤泡癌（A错）、髓样癌（D错）和未分化癌（C对）四种类型，其中乳头状癌（B错）分化最好，恶性程度最低；滤泡癌（A错）和髓样癌（D错）分化较好，恶性程度较低；未分化癌分化最差，恶性程度最高（C对）。","","N"],["2008-N133",3,"第3节 慢性炎症","肉芽肿性炎的常见类型",2008,133,"B","","肺结节病属于",[["A","纤维素性炎"],["B","化脓性炎"],["C","肉芽肿性炎"],["D","出血性炎"]],"C","肺结节病为原因不明的变态反应疾病，其特征性病理改变是非干酪样上皮样细胞肉芽肿（C对），主要由高分化的单核吞噬细胞（上皮样细胞和巨噬细胞）和淋巴细胞组成。","","N"],["2008-N134",8,"第1节 呼吸道和肺炎症性疾病","小叶性肺炎的病理变化",2008,134,"B","","小叶性肺炎属于",[["A","纤维素性炎"],["B","化脓性炎"],["C","肉芽肿性炎"],["D","出血性炎"]],"B","小叶性肺炎为主要由化脓性细菌感染引起的急性化脓性炎症（B对）。纤维素性炎（A错）是大叶性肺炎（十版病理学P172）的主要特征，见于大叶性肺炎的红色肝样变期和灰色肝样变期。肉芽肿性炎（C错）可见于肺结节病（九版内科学P93）。出血性炎（D错）见于肺出血肾炎综合征（Goodpasture syndrome）（十版病理学P255）。","","N"],["2008-N135",9,"第2节 胃炎","慢性萎缩性胃炎",2008,135,"B","","慢性萎缩性胃炎的病变特点是",[["A","胃黏膜内多量中性粒细胞浸润"],["B","胃黏膜内多量淋巴细胞浸润"],["C","胃黏膜腺体减少伴肠上皮化生"],["D","被覆上皮增生导致胃黏膜增厚"]],"C","慢性萎缩性胃炎以胃黏膜萎缩变薄，黏膜腺体减少或消失并伴有肠上皮化生（C对），胃黏膜固有层内多量淋巴细胞（B对）、浆细胞浸润为特点，且因其是一种慢性炎症病变，胃黏膜内不会出现急性炎症细胞（中性粒细胞）浸润（A错） 。黏膜腺体肥大增生是慢性肥厚性胃炎的病理特点（D错）。故本题BC均对，但给出的参考答案仅为C，可能与B选项并不特异有关。","","N"],["2008-N136",9,"第2节 胃炎","非萎缩性胃炎",2008,136,"B","","慢性浅表性胃炎的病变特点是",[["A","胃黏膜内多量中性粒细胞浸润"],["B","胃黏膜内多量淋巴细胞浸润"],["C","胃黏膜腺体减少伴肠上皮化生"],["D","被覆上皮增生导致胃黏膜增厚"]],"B","镜下，慢性浅表性胃炎的病变部位主要位于黏膜浅层即黏膜层上三分之一，呈灶状或弥漫分布，胃黏膜充血、水肿、表浅上皮坏死脱落，固有层有淋巴细胞（B对）、浆细胞等慢性炎症细胞浸润。慢性浅表性胃炎为慢性炎症病变，胃黏膜内不会出现急性炎症细胞（中性粒细胞）浸润（A错）。胃黏膜腺体减少伴肠上皮化生是慢性萎缩性胃炎（十版病理学P196）的病理特点（C错）。黏膜腺体肥大增生是慢性肥厚性胃炎（十版病理学P197）的病理特点（D错）。","","N"],["2008-N137",11,"第1节 肾小球疾病","急进性肾小球肾炎病理变化",2008,137,"B","","新月体性肾小球肾炎的病变特点是",[["A","系膜细胞及系膜基质增生"],["B","系膜细胞及内皮细胞增生"],["C","壁层上皮细胞及巨噬细胞增生"],["D","脏层上皮细胞及巨噬细胞增生"]],"C","新月体性肾小球肾炎（急进性肾炎）的病理特点是壁层上皮细胞及单核巨噬细胞增生（C对），形成新月体。脏层上皮细胞增生只能见于部分新月体性肾小球肾炎（由免疫复合物介导的II型）（D错）。系膜细胞和系膜基质增生（A错）是系膜增生性肾小球肾炎的病变特点（十版病理学P258）。系膜细胞及内皮细胞增生（B错）是急性弥漫性增生性肾小球肾炎（急性肾炎）的病变特点。","","N"],["2008-N138",11,"第1节 肾小球疾病","急性弥漫性增生性肾小球肾炎病理变化",2008,138,"B","","毛细血管内增生性肾小球肾炎的病变特点是",[["A","系膜细胞及系膜基质增生"],["B","系膜细胞及内皮细胞增生"],["C","壁层上皮细胞及巨噬细胞增生"],["D","脏层上皮细胞及巨噬细胞增生"]],"B","毛细血管内增生性肾小球肾炎（急性肾炎）的病变特点是系膜细胞及毛细血管内皮细胞增生（B对）。系膜细胞和系膜基质增生（A错）是系膜增生性肾小球肾炎的病变特点（十版病理学P258）。壁层上皮细胞及巨噬细胞（单核细胞）增生（C错）见于新月体性肾小球肾炎（急进性肾小球肾炎）。脏层上皮细胞及巨噬细胞（单核细胞）增生（D错）见于免疫复合物性肾炎（十版病理学P251）。","","N"],["2008-N163",1,"第1节 再生","永久性细胞",2008,163,"X","","人体内属于恒定细胞的有",[["A","神经细胞"],["B","表皮细胞"],["C","心肌细胞"],["D","肠上皮细胞"]],"AC","按再生能力的强弱可将人体细胞分为不稳定细胞、稳定细胞、永久性细胞（恒定细胞）三类。不稳定细胞，又称持续分裂细胞，这类细胞总是都在进行新老更替，具有应对损伤的强大再生修复能力再生能力，表皮细胞（B错）和肠上皮细胞（D错）均属于此类型。稳定细胞又称静止细胞，这类细胞在生理情况下增殖现象并不明显，但当受到损伤时，会表现出较强的再生能力。永久性细胞（恒定细胞）又称非分裂细胞，这类细胞无论在生理情况下还是在受到损伤刺激的情况下，均不具有再生能力，神经细胞（A对）和心肌细胞（C对）均属于此类。","","N"],["2008-N164",2,"第1节 充血和淤血","肺淤血",2008,164,"X","","慢性肺淤血可以引起",[["A","肺漏出性出血"],["B","肺褐色硬化"],["C","肺癌"],["D","肺结节病"]],"AB","慢性肺淤血常由左心衰引起，左心腔内压力升高，阻碍肺静脉回流，导致肺泡壁毛细血管扩张，通透性增高，血液漏出血管外（漏出性出血）（A对）。慢性肺淤血时，由于长期缺氧造成肺间质纤维组织增生，肺质地变硬，加之大量含铁血黄素沉积，肺呈棕褐色，称肺褐色硬化（B对）。肺癌（十版病理学P189）与吸烟、空气污染等因素有关，与慢性肺淤血无关（C错）。肺结节病是一种病因未明的多系统多器官的肉芽肿性疾病，与肺淤血无关（D错）。","","N"],["2008-N165",10,"第2节 淋巴组织肿瘤","伯基特淋巴瘤临床表现",2008,165,"X","","Burkitt淋巴瘤的临床病理特点有",[["A","T细胞来源"],["B","与EB病毒感染有关"],["C","镜下可见星天现象"],["D","属高度侵袭性肿瘤"]],"BCD","Burkitt淋巴瘤（BL）是B细胞起源（A错）的高度侵袭性肿瘤（D对），其发生（尤其是非洲地方性BL的发生）多与EB病毒（B对）感染有关，所有患者的绝大多数肿瘤细胞内含有EB病毒基因。BL的瘤细胞之间散在分布着胞质丰富而透亮的反应性巨噬细胞，镜下可见“满天星（星天）”现象（C对）。","","N"],["2008-N166",12,"第4节 卵巢肿瘤","浆液性肿瘤",2008,166,"X","","卵巢浆液性囊腺癌的病理特点有",[["A","肉眼可见囊内实性结节"],["B","乳头被覆异型性明显的细胞"],["C","无间质浸润"],["D","砂粒体形成"]],"ABD","卵巢浆液性囊性癌肉眼可见单个或多个纤维分隔的囊腔，囊内可见实性结节（A对）。镜下，细胞层次超过3层，伴有明显的癌细胞破坏性间质浸润（C错），乳头分支多而复杂，被覆异型性明显的细胞（B对），常可见砂粒体（D对）。","","N"],["2008-N167",4,"第2节 免疫缺陷病","病理变化",2008,167,"X","","完全型艾滋病的诊断标准有",[["A","抗HIV抗体阳性"],["B","CD8⁺细胞显著减少"],["C","肺孢子虫性肺炎"],["D","Kaposi肉瘤"]],"ACD","完全型艾滋病的定义为：血清抗HIV抗体阳性（A对）、CD4⁺（而不是CD8⁺）T淋巴细胞显著减少（B错），伴有条件性感染和恶性肿瘤的艾滋病。其中条件性感染最常见的是肺孢子虫性肺炎（C对），发生率约为70%～80%，恶性肿瘤最常见的是Kaposi肉瘤（D对），发生率约为30%。","","N"],["2008-N168",16,"第10节 寄生虫病","肠阿米巴病病理变化概述",2008,168,"X","","阿米巴病的肠道病变特点有",[["A","主要累及回肠末端"],["B","形成烧瓶状溃疡"],["C","大量纤维素渗出"],["D","溃疡周围可见滋养体"]],"BD","阿米巴病的肠道病变主要累及盲肠和升结肠（A错），其次为乙状结肠和直肠，严重者整个结肠和小肠下段均受累。其基本病变为组织溶解液化为主的变质性炎，而不是纤维素性炎，因此不会有大量纤维素渗出（C错）。阿米巴肠病的主要病变特点是形成烧瓶状溃疡（B对），且在溃疡周围及肠壁的小静脉腔内可见滋养体（D对）。","","N"],["2009-N41",0,"第1节 适应","萎缩的病理变化",2009,41,"A","","下列选项中，不符合萎缩特点的是",[["A","自噬小体增多"],["B","器官均匀性缩小"],["C","器官功能低下"],["D","细胞核固缩"]],"D","萎缩是指已发育正常的细胞、组织或器官的体积均匀性缩小（B对），伴有功能下降（C对），是细胞适应的一种类型。萎缩细胞电镜下见细胞器减少、退化，可伴有实质细胞数量的减少，自噬小体增多（A对），心肌细胞和肝细胞等萎缩细胞胞质中可出现脂褐素（自噬溶酶体内未被消化的细胞器碎片残体）。而核固缩是细胞坏死（十版病理学P19）和细胞凋亡的细胞核表现（D错，为本题正确答案）。","","N"],["2009-N42",1,"第1节 再生","稳定细胞",2009,42,"A","","下列选项中属于稳定细胞的是",[["A","表皮细胞"],["B","消化道黏膜被覆上皮细胞"],["C","肾小管上皮细胞"],["D","神经细胞"]],"C","按再生能力的强弱可将人体细胞分为不稳定细胞、稳定细胞、永久性细胞三类。不稳定细胞又称持续分裂细胞，这类细胞总是都在进行新老更替，具有应对损伤的强大再生修复能力，如表皮细胞（A错）、呼吸道和消化道黏膜被覆细胞（B错）、男性及女性生殖器官管腔的被覆细胞、淋巴及造血细胞、间皮细胞等。稳定细胞又称静止细胞，这类细胞在生理情况下增殖现象并不明显，但当受到损伤时，会表现出较强的再生能力，如肝、胰、涎腺、内分泌腺、汗腺、皮脂腺和肾小管的上皮细胞（C对）等。永久性细胞又称非分裂细胞，这类细胞再生能力极弱，无论在生理情况下还是在受到损伤刺激的情况下，均不具有再生能力，如神经细胞（D错）、骨骼肌细胞及心肌细胞等。","","N"],["2009-N43",1,"第3节 伤口愈合","营养",2009,43,"A","","维生素C缺乏常导致创伤愈合不良的主要原因是",[["A","表皮再生困难"],["B","难以形成前胶原分子"],["C","炎症难以控制"],["D","局部神经营养不良"]],"B","前胶原分子形成过程需要经历脯氨酸及赖氨酸的羟基化，而维生素C是羟基化酶的辅助因子，维生素C缺乏时前胶原分子难以形成（B对），进而影响胶原纤维的形成，最终导致创伤愈合不良。","","N"],["2009-N44",2,"第1节 充血和淤血","肺淤血",2009,44,"A","","肺内出现弥散分布的，胞浆内有大量含铁血黄素颗粒的巨噬细胞，最常见于",[["A","大叶性肺炎"],["B","小叶性肺炎"],["C","间质性肺炎"],["D","左心衰竭"]],"D","左心衰竭（D对）常引起慢性肺淤血，肺泡壁毛细血管扩张充血，红细胞漏出，漏出的红细胞被巨噬细胞吞噬，血红蛋白被溶酶体酶分解，析出含铁血黄素并堆积在巨噬细胞内，这种细胞称含铁血黄素细胞或心衰细胞。大叶性肺炎红色肝样变期（十版病理学P172）肺内也可见含铁血黄素颗粒的巨噬细胞，但数量较少（A错）。小叶性肺炎（十版病理学P174）为化脓性炎，可见大量中性粒细胞浸润（B错）。病毒性肺炎（十版病理学P175）和支原体肺炎（十版病理学P176）均为间质性肺炎，主要可见淋巴细胞、单核细胞浸润（C错）。","","N"],["2009-N45",2,"第3节 血栓形成","心血管内皮细胞损伤",2009,45,"A","","动脉内血栓形成最重要的因素是",[["A","血管内血流缓慢"],["B","血流轴流消失"],["C","内皮细胞损伤"],["D","血小板增加"]],"C","血栓形成的条件包括心血管内皮细胞损伤、血流状态改变（如血管内血流缓慢和血流轴流消失）（AB错）和血液凝固性增加（如血小板增加）（D错），其中心血管内皮细胞损伤（C对）是血栓形成的最重要和最常见的原因。","","N"],["2009-N46",3,"第2节 急性炎症","纤维蛋白性炎",2009,46,"A","","假膜性炎是发生于",[["A","黏膜的化脓性炎"],["B","黏膜的纤维素性炎"],["C","黏膜的出血性炎"],["D","黏膜的浆液性炎"]],"B","纤维素性炎易发生于黏膜、浆膜和肺组织，黏膜发生的纤维素性炎（B对），渗出的纤维素、中性粒细胞和坏死黏膜组织以及病原菌等可在黏膜表面形成一层灰白色膜状物，称为“假膜”，故又称为假膜性炎。","","N"],["2009-N47",5,"第5节 肿瘤的分级和分期","肿瘤分级",2009,47,"A","","肿瘤的分级是指",[["A","肿瘤的大小"],["B","肿瘤的浸润范围"],["C","肿瘤是否累及淋巴结"],["D","肿瘤的分化程度"]],"D","恶性肿瘤的分级是描述其恶性程度的指标，病理学上，根据恶性肿瘤的分化程度（D对）、异型性、核分裂象的数目等对恶性肿瘤进行分级。目前多使用三级分级法，Ⅰ级为高分化，分化良好，恶性程度低；Ⅱ级为中分化，中度恶性；Ⅲ级为低分化，恶性程度高。肿瘤的大小（A错）、肿瘤的浸润范围（B错）、肿瘤是否累及淋巴结（C错）项均为肿瘤分期（十版病理学P100）的指标。","","N"],["2009-N48",8,"第1节 呼吸道和肺炎症性疾病","肺肉质变",2009,48,"A","","中性粒细胞渗出过少的大叶性肺炎易引发的并发症是",[["A","肺肉质变"],["B","肺脓肿"],["C","脓胸"],["D","败血症"]],"A","大叶性肺炎的并发症主要有①肺肉质变：由于肺内炎性病灶中中性粒细胞渗出过少，释放的蛋白酶量不足以溶解渗出物中的纤维素，大量未能被溶解吸收的纤维素即被肉芽组织取代而机化（A对）；②胸膜肥厚和粘连：大叶性肺炎病变时常累及局部胸膜伴发纤维素性胸膜炎若胸膜及胸膜腔内的纤维素不能被完全吸收而发生机化，则致胸膜增厚粘连；③肺脓肿及脓胸（BC错）：当病原菌毒力强大或机体抵抗力低下时，由金黄色葡萄球菌和肺炎链球菌混合感染者易并发肺脓肿，并伴有脓胸；④败血症或脓毒败血症（D错）：严重感染时，细菌侵入血液大量繁殖并产生毒素所致；⑤感染性休克：见于重症患者，主要表现为严重的全身中毒症状和微循环衰竭，又称为中毒性休克或休克性肺炎。","","N"],["2009-N49",8,"第8节 呼吸系统常见肿瘤","神经内分泌癌",2009,49,"A","","肺癌中恶性程度最高的是",[["A","鳞癌"],["B","腺癌"],["C","细支气管肺泡细胞癌"],["D","小细胞癌"]],"D","小细胞癌又称小细胞神经内分泌癌，占全部肺癌的10%～20%，是肺癌中恶性程度最高的一型（D对），生长迅速，转移早，存活期大多不超过一年，手术切除效果差，对放化疗效果好，但复发转移率高。","","N"],["2009-N50",9,"第6节 病毒性肝炎","点状坏死",2009,50,"A","","急性普通型肝炎的典型病变是",[["A","肝细胞广泛水样变性伴点状坏死"],["B","肝细胞广泛脂肪变性伴点状坏死"],["C","肝细胞广泛水样变性伴桥接坏死"],["D","肝细胞广泛脂肪变性伴碎片坏死"]],"A","急性普通型肝炎肝细胞坏死轻微但广泛，以细胞水肿（水样变性）为主，肝小叶内可见点状坏死和嗜酸性小体（A对）。肝细胞广泛脂肪变性伴点状坏死见于酒精性肝病（B错）。桥接坏死（C错）和碎片状坏死（D错）为慢性肝炎的特征。","","N"],["2009-N51",11,"第1节 肾小球疾病","急进性肾小球肾炎病理变化",2009,51,"A","","快速进行性肾小球肾炎主要增生的细胞是",[["A","内皮细胞"],["B","系膜细胞"],["C","脏层上皮细胞"],["D","壁层上皮细胞"]],"D","快速进行性肾小球肾炎又称新月体肾炎，其增生的细胞包括壁层上皮细胞（D）、脏层上皮细胞（C）和巨噬细胞等，以壁层上皮细胞为主（D对）。内皮细胞（A错）和系膜细胞（B错）是弥漫性增生性肾小球肾炎（急性肾炎）（十版病理学P254）主要增生的细胞。","","N"],["2009-N52",12,"第7节 乳腺疾病","浸润性小叶癌",2009,52,"A","","乳腺浸润性小叶癌的主要病理学特征是",[["A","癌细胞呈巢状分布"],["B","间质中有大量淋巴细胞浸润"],["C","癌细胞呈单排分布"],["D","间质中有特征性淀粉样物质沉积"]],"C","乳腺浸润性小叶癌是由小叶原位癌穿透基膜向间质浸润所致，其主要病理学特征是癌细胞呈单排分布（串珠状或细条索状）（C对）于纤维间质之间，或环形排列在正常导管周围。癌细胞呈巢状分布（A错）为乳腺浸润性导管癌的主要病理学特征（十版病理学P286）。间质中有大量淋巴细胞浸润（B错）是髓样癌的主要病理学特征（二版八年制病理学P376）。间质中有特征性淀粉样物质沉积（D错）是甲状腺髓样癌的特征（十版病理学P297）。","","N"],["2009-N53",14,"第3节 中枢神经系统感染性疾病","软化灶形成",2009,53,"A","","乙型脑炎的特征性病变是",[["A","血管淋巴套形成"],["B","镂空筛状软化灶"],["C","胶质细胞增生"],["D","卫星现象"]],"B","血管淋巴套形成（A错）、镂空筛状软化灶（B对）、胶质细胞增生（C错）和卫星现象（D错）均为乙型脑炎的基本病变，其中镂空筛状软化灶（B对）对乙型脑炎的诊断有一定的特征性意义。","","N"],["2009-N54",2,"第5节 梗死","贫血性梗死",2009,54,"A","","易发生贫血性梗死的脏器是",[["A","脾、心、肾"],["B","脾、心、肺"],["C","肾、心、肺"],["D","心、脑、肠"]],"A","根据梗死灶内含血量的多少，可将梗死分为两种类型：贫血性梗死和出血性梗死。贫血性梗死发生于组织结构较致密、侧支循环不充分的实质器官，如脾、肾、心和脑组织（A对）。而出血性梗死发生于组织结构疏松、严重淤血的器官，如肺和肠（BCD错）。","","N"],["2009-N55",2,"第3节 血栓形成","白色血栓",2009,55,"A","","风湿病时，心内膜疣状赘生物属于",[["A","白色血栓"],["B","红色血栓"],["C","混合血栓"],["D","透明血栓"]],"A","血栓类型可分为四种：白色血栓、混合血栓、红色血栓和透明血栓。急性风湿性心内膜炎时在二尖瓣闭锁缘上形成的赘生物由血小板和纤维蛋白构成，为白色血栓（A对）。","","N"],["2009-N56",9,"第8节 肝硬化","镜下",2009,56,"A","","下列肝硬化的病变中符合假小叶的是",[["A","肉眼下见肝内大小不等的结节"],["B","再生的肝细胞所形成的结节"],["C","广泛增生的纤维组织包绕的肝细胞结节"],["D","异型增生肝细胞所形成的结节"]],"C","假小叶为广泛增生的纤维组织分割原来的肝小叶并包绕成大小不等的圆形或类圆形的肝细胞结节（C对），此为假小叶的镜下表现，而非肉眼表现（A错）。异型增生肝细胞所形成的结节为肝癌结节的特点（十版病理学P221）（D错）。再生的肝细胞所形成的结节可见于亚急性重型肝炎（十版病理学P207）（B错）。","","N"],["2009-N133",1,"第1节 再生","不稳定细胞",2009,133,"B","","属于不稳定细胞的是",[["A","小肠黏膜被覆上皮细胞"],["B","肝细胞"],["C","神经细胞"],["D","心肌细胞"]],"A","按再生能力的强弱可将人体细胞分为不稳定细胞、稳定细胞、永久性细胞三类。小肠黏膜被覆上皮细胞属于不稳定细胞（A对），这类细胞总是都在进行新老更替，具有应对损伤的强大再生修复能力。肝细胞属于稳定细胞（B错），这类细胞在生理情况下增殖现象并不明显，但当受到损伤时，会表现出较强的再生能力。神经细胞和心肌细胞属于永久性细胞（CD错），这类细胞无论在生理情况下还是在受到损伤刺激的情况下，均不具有再生能力。","","N"],["2009-N134",1,"第1节 再生","稳定细胞",2009,134,"B","","属于稳定细胞的是",[["A","小肠黏膜被覆上皮细胞"],["B","肝细胞"],["C","神经细胞"],["D","心肌细胞"]],"B","按再生能力的强弱可将人体细胞分为不稳定细胞、稳定细胞、永久性细胞三类。小肠黏膜被覆上皮细胞属于不稳定细胞（A错），这类细胞总是都在进行新老更替，具有应对损伤的强大再生修复能力。肝细胞属于稳定细胞（B对），这类细胞在生理情况下增殖现象并不明显，但当受到损伤时，会表现出较强的再生能力。神经细胞（C错）和心肌细胞（D错）属于永久性细胞，这类细胞无论在生理情况下还是在受到损伤刺激的情况下，均不具有再生能力。","","N"],["2009-N135",7,"第2节 高血压病","细动脉硬化",2009,135,"B","","良性高血压的基本病变是",[["A","细动脉玻璃样变性"],["B","细动脉纤维化"],["C","细动脉淀粉样变性"],["D","细动脉纤维素样坏死"]],"A","良性高血压的基本病变是细动脉硬化，表现为细动脉玻璃样变（A对），最易累及肾入球小动脉、视网膜动脉和脾中心动脉。细动脉纤维化见于器官移植的慢性排斥反应（十版病理学P89）（B错）。细动脉淀粉样变性见于全身性淀粉样变（十版病理学P17）（C错）。细动脉纤维素样坏死见于恶性高血压（十版病理学P153）（D错）。","","N"],["2009-N136",7,"第2节 高血压病","恶性高血压",2009,136,"B","","恶性高血压的基本病变是",[["A","细动脉玻璃样变性"],["B","细动脉纤维化"],["C","细动脉淀粉样变性"],["D","细动脉纤维素样坏死"]],"D","恶性高血压又称急进型高血压，特征性病理变化是增生性小动脉硬化和坏死性细动脉炎，主要累及肾。前者主要表现为动脉内膜明显增厚，伴有SMC增生，胶原纤维增生致血管壁呈层状洋葱皮样增厚，管腔狭窄。后者病变累及内膜和中膜，管壁发生纤维素样坏死（D对）。细动脉玻璃样变性是良性高血压的主要病变特征（十版病理学P151）（A错）。细动脉纤维化见于器官移植的慢性排斥反应（十版病理学P89）（B错）。细动脉淀粉样变性见于全身性淀粉样变（十版病理学P17）（C错）。","","N"],["2009-N137",16,"第2节 结核病","急性全身粟粒性结核病",2009,137,"B","","属于血源播散性肺结核的是",[["A","急性粟粒性肺结核"],["B","急性空洞型肺结核"],["C","局限型肺结核"],["D","干酪性肺炎"]],"A","属于血源播散性肺结核的是急性粟粒性肺结核（A对）：肺门、纵隔、支气管旁含有结核杆菌的淋巴结干酪样坏死破入邻近大静脉播散于两肺，或含有结核杆菌的淋巴液由胸导管回流入血而播散于两肺，均可引起急性粟粒性肺结核。急性空洞型肺结核（B错）、局限型肺结核（C错）和干酪性肺炎（D错）均属于继发性肺结核病，主要经支气管播散，且局限性肺结核是非活动性结核，播散几率很小。","","N"],["2009-N138",16,"第2节 结核病","局灶型肺结核",2009,138,"B","","属于非活动性肺结核的是",[["A","急性粟粒性肺结核"],["B","急性空洞型肺结核"],["C","局限型肺结核"],["D","干酪性肺炎"]],"C","局灶型肺结核（C对）是继发性肺结核的早期病变，患者常无自觉症状，仅在体检时发现，属于非活动性结核病。急性粟粒性肺结核（A错）、急性空洞型肺结核（B错）、干酪性肺炎（D错）均属于活动性肺结核。","","N"],["2009-N163",0,"第1节 适应","化生的类型",2009,163,"X","","下列选项中，属于化生的有",[["A","纤维结缔组织中出现软骨细胞"],["B","支气管上皮中出现鳞状上皮细胞"],["C","肌肉组织中出现类上皮细胞"],["D","血栓中出现毛细血管及成纤维细胞"]],"AB","化生常发生于同源性细胞之间，即上皮细胞之间或间叶细胞之间。纤维结缔组织中出现软骨细胞属于间叶组织的化生（A对），支气管上皮中出现鳞状上皮细胞属于上皮组织的化生（B对）。类上皮细胞是慢性肉芽肿的细胞成分，肌肉组织中出现类上皮细胞，是慢性炎症的表现，而不是化生（C错）。血栓中出现毛细血管及成纤维细胞是血栓机化的表现（D错）。","","N"],["2009-N164",1,"第2节 纤维性修复","肉芽组织的成分及形态",2009,164,"X","","肉芽组织中常见的细胞有",[["A","郎罕氏巨细胞"],["B","成纤维细胞"],["C","新生内皮细胞"],["D","浆细胞"]],"BCD","肉芽组织由新生薄壁的毛细血管（C对）以及增生的成纤维细胞（B对）构成，并伴有巨噬细胞、中性粒细胞、浆细胞（D对）等炎症细胞浸润。郎罕氏巨细胞（Langhans巨细胞）由上皮样细胞融合而来，是肉芽肿的主要细胞成分之一，不出现在肉芽组织中（A错）。","","N"],["2009-N165",9,"第12节 消化系统常见肿瘤","早期胃癌的概述",2009,165,"X","","下列选项中，符合早期胃癌诊断的有",[["A","肿瘤直径小于2cm"],["B","肿瘤局限于黏膜层"],["C","肿瘤累及肌层"],["D","肿瘤累及黏膜下层"]],"BD","胃壁由内至外依次可分为黏膜层、黏膜下层、肌层和浆膜层共四层，早期胃癌的癌组织浸润仅限于黏膜层（B对）或黏膜下层（D对），当癌组织浸润累及肌层（超过黏膜下层）时为中晚期胃癌（C错）。肿瘤直径不是早期胃癌的诊断标准（A错）。","","N"],["2009-N166",11,"第1节 肾小球疾病","IgA肾病病理变化",2009,166,"X","","IgA肾病组织学改变可为",[["A","内皮细胞增生"],["B","局灶性节段性增生"],["C","弥漫性系膜增生"],["D","可有新月体形成"]],"BCD","IgA肾病的组织学改变各异，最常见的是弥漫性系膜增生（C对），也可表现为局灶性节段性增生（B对），少数病例可有新月体形成（D对）。IgA肾病可涉及肾小球肾炎几乎所有的病理类型（九版内科学P469），其中就包括有内皮细胞增生的急性弥漫性增生性肾小球肾炎，因此按照内科学观点，A选项也正确，但本题给出的参考答案仅为BCD。","","N"],["2009-N167",9,"第7节 酒精性肝病和非酒精性脂肪性肝病","酒精性肝炎",2009,167,"X","","酒精性肝炎常见的肝细胞病变有",[["A","肝细胞气球样变"],["B","肝细胞浆内出现透明小体"],["C","肝细胞内出现大脂肪滴"],["D","肝细胞嗜酸性小体形成"]],"BC","酒精性肝炎常见的肝细胞病变有三种：肝细胞脂肪变性（C对）、酒精透明小体（Mallory小体）形成（B对）和灶状肝细胞坏死伴中性粒细胞浸润。肝细胞气球样变为病毒性肝炎时肝细胞水肿状态（A错）。肝细胞嗜酸性小体又称凋亡小体，见于病毒性肝炎发生嗜酸性坏死（凋亡）时（D错）。","","N"],["2009-N168",5,"第12节 肿瘤与遗传","遗传性肿瘤综合征举例",2009,168,"X","","下列选项中，属于遗传性疾病的有",[["A","神经纤维瘤病"],["B","纤维瘤病"],["C","白血病"],["D","毛细血管扩张共济失调症"]],"AD","神经纤维瘤病（A对）均为常染色体显性遗传的遗传性肿瘤综合征。毛细血管扩张共济失调症（D对）为常染色体隐性遗传的遗传性肿瘤综合征。纤维瘤病（B错）和白血病（C错）的病因中均有遗传性因素，但不属于遗传性疾病。","","N"],["2010-N41",0,"第3节 细胞可逆性损伤","转移性钙化",2010,41,"A","","下列钙化中，属于转移性钙化的是",[["A","肝内血吸虫卵钙化"],["B","肾小管钙化"],["C","淋巴结干酪样坏死钙化"],["D","主动脉粥瘤钙化"]],"B","病理性钙化有转移性钙化和营养不良性钙化两种形式。转移性钙化是由于全身钙磷代谢失调使钙盐沉积于正常组织所致，多见于血管、肾小管（B对）、肺泡和胃黏膜等处。营养不良性钙化为钙盐沉积于坏死或即将坏死的组织或异物所致，多见于血栓、血吸虫虫卵（A错）、结核病（干酪样坏死）（C错）、动脉粥样硬化（粥瘤）（D错）等处。","","N"],["2010-N42",0,"第3节 细胞可逆性损伤","细胞内玻璃样变",2010,42,"A","","下列小体中，与中间丝蛋白聚集有关的是",[["A","石棉（Ferruginous）小体"],["B","马洛里（Mallory）小体"],["C","嗜酸性（Councilman）小体"],["D","拉塞尔（Russell）小体"]],"B","Mallory小体为酒精性肝病时肝细胞胞质中细胞中间丝前角蛋白变性形成的玻璃样变（B对）。石棉（Ferruginous）小体（十版病理学P184）是由铁蛋白包裹的石棉纤维，石棉肺时在增生的纤维组织内可见（A错）。嗜酸性（Councilman）小体又称康氏小体（十版病理学P204），为细胞凋亡过程中的玻璃样变性（C错），常见于黄热病毒引起的病毒性肝炎。拉塞尔（Russell）小体是浆细胞胞质粗面内质网中免疫球蛋白蓄积形成的玻璃样变（D错）。","","N"],["2010-N43",2,"第5节 梗死","血栓形成",2010,43,"A","","脑贫血性梗死最常见的原因是",[["A","脑动脉栓塞"],["B","脑动脉炎症性病变"],["C","脑动脉血栓形成"],["D","脑动脉发育异常"]],"C","脑梗死一般为贫血性梗死（十版病理学P54）。脑动脉栓塞（A）、脑动脉炎症性病变（B）、脑动脉血栓形成（C）、脑动脉发育异常（D）四项均可导致组织缺血缺氧而致脑组织发生贫血性梗死，但脑动脉血栓形成是最常见的原因（C对）。","","N"],["2010-N44",3,"第3节 慢性炎症","肉芽肿性炎的概念",2010,44,"A","","异物肉芽肿中，最主要的炎症细胞是",[["A","嗜酸性粒细胞"],["B","中性粒细胞"],["C","淋巴细胞"],["D","巨噬细胞"]],"D","异物性肉芽肿是由于异物刺激长期存在而形成的慢性炎症。其主要细胞成分包括巨噬细胞（D对）及其衍生而来的上皮样细胞和多核巨细胞（异物巨细胞），此外还可以见少量的淋巴细胞（C错）、浆细胞、成纤维细胞等。嗜酸性粒细胞多见于过敏性炎症和寄生虫感染（A错）。中性粒细胞多见于化脓性炎症（B错）。","","N"],["2010-N45",5,"第4节 肿瘤的生长和扩散","侵袭性生长",2010,45,"A","","呈浸润性生长，但不发生转移的肿瘤是",[["A","骨髓瘤"],["B","淋巴瘤"],["C","血管瘤"],["D","精原细胞瘤"]],"C","转移是恶性肿瘤最具特征性的变化，骨髓瘤（A错）、淋巴瘤（B错）、精原细胞瘤（D错）均为恶性肿瘤，可发生转移。血管瘤为良性肿瘤，所以不会发生转移（C对），但与一般的良性肿瘤不同，血管瘤无被膜，界限不清，呈浸润性生长。","","N"],["2010-N46",4,"第1节 自身免疫病","病理变化",2010,46,"A","","类风湿关节炎的滑膜病变特点是",[["A","浆液性炎"],["B","肉芽肿性炎"],["C","化脓性炎"],["D","慢性增生性炎"]],"D","类风湿关节炎（RA）是一种以慢性增生性滑膜炎（D对）为病变特点的自身免疫病，其组织学表现为：关节囊内层的滑膜细胞肥大增生和慢性炎症细胞浸润。浆液性炎（十版病理学P72）（A错）是以浆液渗出为主要特征的急性渗出性炎症，亦可发生于滑膜，常见于风湿性关节炎（十版病理学P156）。肉芽肿性炎（十版病理学P75）（B错）是一种以肉芽肿形成为主要特征的特殊慢性增生性炎症，常见于结核病、麻风病等。化脓性炎（十版病理学P72）（C错）是以中性粒浸润为主要特征的急性渗出性炎症。","","N"],["2010-N47",7,"第4节 风湿病","风湿性心内膜炎",2010,47,"A","","风湿性心内膜炎时，心瓣膜疣状赘生物的主要成分是",[["A","细菌菌落与炎症细胞"],["B","血小板与纤维素"],["C","肉芽组织与瘢痕"],["D","小血管与风湿肉芽肿"]],"B","风湿性心内膜炎病变初期可在瓣膜上形成由血小板和纤维蛋白（纤维素）（B对）构成的疣状赘生物，附着牢固，为白色血栓。","","N"],["2010-N48",8,"第1节 呼吸道和肺炎症性疾病","小叶性肺炎的病因和发病机制",2010,48,"A","","吸入性肺炎的病理学类型是",[["A","支气管肺炎"],["B","大叶性肺炎"],["C","间质性肺炎"],["D","弥漫性肺泡损伤"]],"A","人在神志不清时（如全身麻醉、脑血管意外、酒精中毒等情况下），防御功能减弱或消失，异物（胃内容物居多）吸入气管，引起化学性损伤，常继发细菌感染，造成吸入性肺炎。吸入性肺炎属于小叶性肺炎，而小叶性肺炎常以细支气管为中心，又称为支气管肺炎，故吸入性肺炎的病理学类型为支气管肺炎（A对）。","","N"],["2010-N49",9,"第8节 肝硬化","胆色素代谢障碍",2010,49,"A","","下列色素中，引起肝细胞羽毛状坏死的是",[["A","胆色素"],["B","含铁血黄素"],["C","脂褐素"],["D","黑色素"]],"A","胆汁性肝硬化分为原发性和继发性两种。继发性胆汁性肝硬化时，镜下见肝细胞明显淤胆（胆色素）（A对）而变性坏死，坏死肝细胞肿大，胞质疏松呈网状，核消失，称网状或羽毛状坏死。","","N"],["2010-N50",9,"第12节 消化系统常见肿瘤","伴有肠黏膜增生的慢性肠疾病",2010,50,"A","","与大肠癌发生密切相关的息肉是",[["A","炎性息肉"],["B","增生性息肉"],["C","幼年性息肉"],["D","腺瘤性息肉"]],"D","腺瘤性息肉（D对）又称息肉状腺瘤（二版八年制病理学P132），是伴有肠黏膜增生的慢性肠疾病，与大肠癌的发生关系密切。而炎性息肉（A错）、增生性息肉（B错）和幼年性息肉（C错）均为非肿瘤性息肉，发生癌变的可能性很小，与大肠癌的发生无关。记忆技巧：带有“腺瘤”和“病”的息肉通常为癌前病变，不带则一般为非癌前病变。","","N"],["2010-N51",10,"第2节 淋巴组织肿瘤","蕈样肉芽肿病的概述",2010,51,"A","","下列非霍奇金淋巴瘤中，属于T细胞淋巴瘤的是",[["A","蕈样霉菌病"],["B","Burkitt淋巴瘤"],["C","滤泡性淋巴瘤"],["D","套细胞淋巴瘤"]],"A","蕈样霉菌病起源于T细胞，属于T细胞淋巴瘤（A对）。Burkitt淋巴瘤（十版病理学P233）（B错）、滤泡性淋巴瘤（十版病理学P232）（C错）、套细胞淋巴瘤（D错）都属于B细胞淋巴瘤。","","N"],["2010-N52",11,"第1节 肾小球疾病","微小病变性肾小球病病理变化",2010,52,"A","","轻微病变性肾小球肾炎的特征性病变是",[["A","系膜细胞增生"],["B","系膜细胞及内皮细胞增生"],["C","脏层上皮细胞足突融合消失"],["D","壁层上皮细胞及巨噬细胞增生"]],"C","轻微病变性肾小球肾炎的特征性病变是脏层上皮细胞足突融合消失（C对）。系膜细胞增生（A错）可见于急性弥漫性增生性肾小球肾炎（急性肾炎）（十版病理学P254）和系膜增生性肾炎（十版病理学P258）。系膜细胞及内皮细胞增生（B错）是急性弥漫性增生性肾小球肾炎（急性肾炎）的特征性病变。壁层上皮细胞及巨噬细胞增生（D错）为急进性（新月体性）肾小球肾炎的特征性病变（十版病理学P255）。","","N"],["2010-N53",11,"第3节 肾和膀胱常见肿瘤","尿路上皮肿瘤概述",2010,53,"A","","膀胱最常见的恶性肿瘤是",[["A","鳞状细胞癌"],["B","腺癌"],["C","移行细胞癌"],["D","腺鳞癌"]],"C","绝大多数膀胱恶性肿瘤起源于尿路移行上皮，为移行细胞癌（C对）。也可为鳞状细胞癌、腺癌、腺鳞癌和肉瘤，但均较少见（ABD错）。","","N"],["2010-N54",12,"第2节 子宫体疾病","子宫内膜腺癌病理变化",2010,54,"A","","最容易发展为子宫内膜腺癌的子宫内膜病变是",[["A","不规则增生"],["B","单纯增生"],["C","复杂性增生"],["D","非典型增生"]],"D","子宫内膜增生症根据腺体结构和分化程度，可分为单纯性增生、复杂性增生和非典型增生（异型增生）三种类型，其中非典型增生（D对）有1/3的患者在5年内可发展为腺癌，是最容易发展为子宫内膜腺癌的子宫内膜病变。","","N"],["2010-N55",16,"第2节 结核病","溃疡型",2010,55,"A","","肠结核的溃疡特点是",[["A","裂隙状"],["B","环形腰带状"],["C","火山口状"],["D","烧瓶状"]],"B","肠结核病变沿肠壁淋巴管扩散，而肠壁淋巴管环肠管行走，因此溃疡呈环形腰带状（B对），其长轴与肠腔长轴垂直。裂隙状溃疡（A错）为克罗恩病溃疡的特点（九版内科学P377）。火山口状溃疡（C错）为胃癌溃疡的特点（十版病理学P216）。烧瓶状溃疡（D错）为肠阿米巴病溃疡的特点（十版病理学P358）。","","N"],["2010-N56",13,"第2节 甲状腺疾病","乳头状癌",2010,56,"A","","下列甲状腺癌中，出现砂粒体结构的是",[["A","乳头状癌"],["B","髓样癌"],["C","滤泡癌"],["D","梭形细胞癌"]],"A","甲状腺癌的主要组织类型有乳头状癌、滤泡癌、髓样癌和未分化癌。其中乳头状癌（A对）最常见，镜下可见乳头中心间质内有同心圆状的钙化小体，即砂粒体。髓样癌（B错）的特点为镜下可见间质内常有淀粉样物质沉着。滤泡癌（C错）的特点为镜下可见大量分化程度不同的滤泡。梭型细胞癌（D错）的特点为镜下可见大量分化程度较低的梭型细胞，属于未分化癌。","","N"],["2010-N133",5,"第4节 肿瘤的生长和扩散","种植性转移",2010,133,"B","","黏液潴留在癌细胞内的肿瘤是",[["A","高分化腺癌"],["B","中分化腺癌"],["C","黏液腺癌"],["D","印戒细胞癌"]],"D","分泌大量黏液的腺癌称为黏液腺癌（黏液癌），黏液腺癌的黏液一般分泌至癌细胞外，但有时黏液会滞留在癌细胞内，将核挤向一侧，形成的癌细胞呈印戒状，称为印戒细胞癌（D对）。","","N"],["2010-N134",5,"第8节 常见肿瘤举例","腺癌",2010,134,"B","","由分化良好腺体构成的恶性肿瘤是",[["A","高分化腺癌"],["B","中分化腺癌"],["C","黏液腺癌"],["D","印戒细胞癌"]],"A","病理学中根据恶性肿瘤的分化程度、异型性、核分裂象数目等对恶性肿瘤进行分级，其中三级分类法使用较多。腺癌是腺上皮的恶性肿瘤，因此也可用三级分类法进行分类（如P272子宫内膜腺癌的分类）：Ⅰ级为高分化腺癌（A对），由分化良好的腺体构成，恶性程度低；Ⅱ级为中分化腺癌（B错），由中等分化的腺体构成，中度恶性；Ⅲ级为低分化腺癌，腺体分化程度低，恶性程度高。黏液癌（十版病理学P104）是指分泌大量黏液的腺癌，一种为黏液堆积在腺腔内，并可由于腺体的崩解而成为黏液湖，当癌组织中黏液成分超过50%时，称为黏液腺癌（C错）（北京大学医学出版社病理学P100）；另一种黏液聚积在癌细胞内，将核挤向一侧，使该细胞成印戒状，称为印戒细胞癌（D错），均与腺体的分化程度无关。","","N"],["2010-N135",12,"第3节 滋养层细胞疾病","葡萄胎病理变化",2010,135,"B","","葡萄胎的主要病理变化是",[["A","绒毛水肿，滋养层细胞增生"],["B","异型增生滋养层细胞浸润深肌层，但可见绒毛结构"],["C","异型增生滋养层细胞浸润深肌层，无绒毛结构，出血、坏死明显"],["D","在胎盘种植部位滋养层细胞浸润肌层，无出血、坏死"]],"A","葡萄胎的主要病理变化是滋养层细胞增生、绒毛水肿（A对）及绒毛间质内血管消失，其中滋养层细胞增生是最重要的特征。异型增生滋养层细胞浸润深肌层，可见绒毛结构（B错）是侵蚀性葡萄胎的主要病理变化（十版病理学P275）。异型增生滋养层细胞浸润深肌层、无绒毛结构，出血、坏死明显（C错）是绒毛膜癌的主要病理变化（十版病理学P276）。在胎盘种植部位滋养层细胞浸润肌层，无出血、坏死（D错）是胎盘部位滋养细胞肿瘤的主要病理变化（十版病理学P277）。","","N"],["2010-N136",12,"第3节 滋养层细胞疾病","绒毛膜癌病理变化",2010,136,"B","","绒毛膜癌的主要病理变化是",[["A","绒毛水肿，滋养层细胞增生"],["B","异型增生滋养层细胞浸润深肌层．但可见绒毛结构"],["C","异型增生滋养层细胞浸润深肌层，无绒毛结构，出血、坏死明显"],["D","在胎盘种植部位滋养层细胞浸润肌层，无出血、坏死"]],"C","绒毛膜癌是起源于妊娠绒毛滋养层上皮的高度侵袭性恶性肿瘤，其主要病理变化是异型增生滋养层细胞浸润深肌层，无绒毛结构，且出血、坏死明显（C对）。绒毛水肿，滋养层细胞增生（A错）是葡萄胎的主要病理变化（十版病理学P275）。异型增生滋养层细胞浸润深肌层．但可见绒毛结构（B错）是侵蚀性葡萄胎的主要病理变化（十版病理学P275）。在胎盘种植部位滋养层细胞浸润肌层，无出血、坏死（D错）是胎盘部位滋养细胞肿瘤的主要病理变化（十版病理学P277）。","","N"],["2010-N137",7,"第2节 高血压病","细动脉硬化",2010,137,"B","","良性高血压的基本病变是",[["A","细动脉壁玻璃样变性"],["B","细动脉壁纤维素样坏死"],["C","小动脉内膜纤维化"],["D","小血管内纤维素样血栓形成"]],"A","良性高血压的基本病变是细动脉硬化，表现为细动脉玻璃样变（A对），最易累及肾入球小动脉、视网膜动脉和脾中心动脉。细动脉壁纤维素样坏死见于恶性高血压（十版病理学P153）（B错）。小动脉内膜纤维化见于器官移植的慢性排斥反应（十版病理学P89）（C错）。小血管内纤维素性血栓（即透明血栓）形成见于弥散性血管内凝血（DIC）（十版病理学P49）（D错）。","","N"],["2010-N138",4,"第3节 器官和骨髓移植排斥反应","慢性排斥反应",2010,138,"B","","慢性排斥反应的基本病变是",[["A","细动脉壁玻璃样变性"],["B","细动脉壁纤维素样坏死"],["C","小动脉内膜纤维化"],["D","小血管内纤维素样血栓形成"]],"C","慢性排斥反应多发生在术后几个月至1年以后，其基本病变是小动脉内膜纤维化（C对）。细动脉壁玻璃样变性（A错）是良性高血压细小动脉硬化的基本病变（十版病理学P151）。细动脉壁纤维素样坏死（B错）是超急性排斥反应、风湿病、结节性多动脉炎、新月体性肾小球肾炎、急进型高血压等多种变态反应性疾病（十版病理学P20）的病变特点。小血管内纤维素样血栓形成（D错）为透明血栓的特点，最常见于DIC（十版病理学P49）。","","N"],["2010-N163",2,"第1节 充血和淤血","肺淤血",2010,163,"X","","慢性肺淤血的病理变化有",[["A","肺泡壁毛细血管扩张，充盈"],["B","肺泡腔内心衰细胞聚集"],["C","肺泡腔内蛋白性水肿液聚集"],["D","肺间质纤维增生"]],"ABCD","慢性肺淤血时肺泡壁毛细血管扩张、充盈（A对），通透性增高，血液漏出血管外，表现为肺泡腔内蛋白性水肿液聚集（C对）及出血，巨噬细胞吞噬漏出的红细胞，形成大量心衰细胞（B对），而长期淤血导致肺缺氧，使肺间质纤维增生（D对），肺质地变硬，最终发展为肺褐色硬化。","","N"],["2010-N164",16,"第2节 结核病","结核病基本病理变化",2010,164,"X","","下列选项中，属于结核结节成分的有",[["A","成纤维细胞"],["B","类上皮细胞"],["C","异物巨细胞"],["D","淋巴细胞"]],"ABD","以增生为主的结核病变中，可形成具有诊断价值的结核结节，其主要成分为上皮样细胞（类上皮细胞）（B对）、朗汉斯巨细胞、淋巴细胞（D对）和成纤维细胞（A对）。异物巨细胞（C错）与朗汉斯巨细胞同属于多核巨细胞，多见于异物肉芽肿（十版病理学P75）。","","N"],["2010-N165",10,"第2节 淋巴组织肿瘤","结节硬化型",2010,165,"X","","结节硬化型霍奇金淋巴瘤的病理特点有",[["A","可见多量陷窝细胞"],["B","可见典型R-S细胞"],["C","可见混合性炎症细胞反应"],["D","纤维组织系带状增生"]],"ABCD","结节硬化型霍奇金淋巴瘤的组织学特点是纤维组织系带状增生（“硬化”的原因）（D对），分隔病变淋巴结为大小不等的结节。其肿瘤细胞多为陷窝细胞（A对），亦可见少量典型的R-S细胞（B对），可见嗜酸性粒细胞和中性粒细胞为主的混合性炎症细胞反应（C对）。","","N"],["2010-N166",12,"第7节 乳腺疾病","非特殊型浸润性癌",2010,166,"X","","下列乳腺癌中，属于非浸润性癌的有",[["A","髓样癌"],["B","小管癌"],["C","粉刺癌"],["D","小叶原位癌"]],"CD","乳腺癌按照组织形态可分为非浸润性癌和浸润性癌两类：非浸润性癌包括导管内原位癌和小叶原位癌（D对），导管内原位癌又可分为粉刺癌（C对）、非粉刺型导管内癌、乳头Paget病伴导管原位癌；浸润性癌包括浸润性导管癌、浸润性小叶癌和特殊类型癌，特殊类型癌又可分为乳头Paget病伴导管浸润癌、典型髓样癌（A错）、小管癌（B错）、黏液癌等。以上分类方式可参见八版病理学P303树状图。","","N"],["2010-N167",4,"第2节 免疫缺陷病","淋巴组织的变化",2010,167,"X","","晚期艾滋病的淋巴结特征病变有",[["A","副皮质区仍存在"],["B","淋巴细胞大量减少"],["C","血管及纤维组织增生"],["D","淋巴滤泡消失"]],"BCD","晚期艾滋病的淋巴结特征病变有：淋巴结呈现一片荒芜，副皮质区及淋巴滤泡消失（D对A错），淋巴细胞大量减少（B对），几乎消失殆尽，仅残留少许巨噬细胞和浆细胞，血管及纤维组织增生（C对）。","","N"],["2010-N168",16,"第3节 伤寒","伤寒其他病变",2010,168,"X","","伤寒病时，可出现伤寒肉芽肿的部位有",[["A","肝"],["B","胆囊"],["C","脾"],["D","骨髓"]],"ACD","伤寒肉芽肿是指增生活跃时，巨噬细胞吞噬伤寒杆菌、红细胞和细胞碎片成为伤寒细胞，伤寒细胞聚集成团所形成的结节。因此，伤寒肉芽肿主要出现在巨噬细胞增生活跃的组织器官，如肝（A对）、脾（C对）、骨髓（D对）等。虽然伤寒杆菌可在胆汁中大量繁殖，但大多数患者的胆囊（B错）中无伤寒肉芽肿形成。","","N"],["2011-N41",1,"第1节 再生","软骨组织和骨组织的再生",2011,41,"A","","患者，20岁，骨折愈合良好，5年后骨折处骨组织病理变化表现为",[["A","大量成纤维细胞"],["B","大量新生毛细血管"],["C","正常骨组织"],["D","大量多核巨细胞"]],"C","患者为20岁的青少年，骨组织再生能力强，且题中已提示骨折愈合良好，正常情况下，几个月内便可完全愈合，表现为正常骨组织（C对）。成纤维细胞（A错）和新生毛细血管（B错）是肉芽组织的主要成分，可在骨折愈合过程（纤维性骨痂形成期）中出现。多核巨细胞是肉芽肿的细胞成分（D错）。","","N"],["2011-N42",0,"第3节 细胞可逆性损伤","转移性钙化",2011,42,"A","","下列选项中，属于转移性钙化的是",[["A","结核病灶钙化"],["B","肺间质钙化"],["C","粥瘤钙化"],["D","血栓钙化"]],"B","病理性钙化有转移性钙化和营养不良性钙化两种形式。转移性钙化是由于全身钙磷代谢失调使钙盐沉积于正常组织所致，常发生在血管及肾、肺（B对）和胃的间质组织。营养不良性钙化为钙盐沉积于坏死或即将坏死的组织或异物所致，多见于血栓（D错）、血吸虫虫卵、结核病灶（A错）、动脉粥样硬化（粥瘤）（C错）等处。","","N"],["2011-N43",3,"第2节 急性炎症","趋化作用",2011,43,"A","","下列炎症介质中，具有趋化作用的是",[["A","缓激肽"],["B","前列腺素"],["C","NO"],["D","IL-8"]],"D","趋化作用是指白细胞被趋化因子吸引，朝趋化因子所在处游走的现象。趋化因子可以是外源性的，如细菌产物，也可以是内源性，如C5a、LTB₄、和IL-8（D对）等。缓激肽（A错）为血管活性肽（P76），可使细动脉扩张、血管通透性增加、支气管平滑肌收缩，并可引起疼痛。前列腺素（B错）为花生四烯酸代谢产物（十版病理学P69），可使血管扩张，引起发热和疼痛等。NO（C错）为活性氮（十版病理学P71），可杀伤病原微生物，是宿主抗感染的炎症介质。","","N"],["2011-N44",0,"第4节 细胞不可逆性损伤（细胞死亡）","凋亡的形态学和生物化学特征",2011,44,"A","","下列选项中，属于凋亡特征的是",[["A","死亡细胞质膜破裂"],["B","活体内单个细胞死亡"],["C","死亡细胞自溶"],["D","伴有急性炎症反应"]],"B","凋亡是活体内局部组织中单个细胞程序性细胞死亡的表现形式（B对）。凋亡的形态学特征表现为细胞皱缩、核染色质凝集、细胞膜（又称细胞质膜）及细胞器膜完整（A错），膜可发泡成芽，形成凋亡小体。凋亡小体因其质膜完整，阻止了与其他细胞分子间的识别，故不引起周围组织炎症反应（D错），但可被周围实质细胞和巨噬细胞吞噬降解（而非通过细胞自溶降解，细胞自溶为坏死的降解方式）（C错）。","","N"],["2011-N45",2,"第4节 栓塞","羊水栓塞",2011,45,"A","","女,23岁，足月初产，无妊娠并发症。在阴道分娩过程中，突然呼吸困难，紫绀，血压下降，全身抽搐，昏迷，抢救无效死亡，尸体解剖，肺小动脉和毛细血管内最有可能发现的是",[["A","角化上皮"],["B","脂滴"],["C","气泡"],["D","血栓"]],"A","患者在分娩的过程中突发呼吸困难，紫绀，血压下降，全身抽搐，昏迷，抢救无效死亡，据此可诊断为羊水栓塞。羊水栓塞时，肺小动脉和毛细血管内可观察到羊水的成分，包括角化鳞状上皮（A对）、胎毛、胎脂、胎粪和黏液等。脂滴见于脂肪栓塞（B错）。气泡见于气体栓塞（C错）。血栓见于血栓栓塞（D错）。","","N"],["2011-N46",5,"第3节 肿瘤的命名与分类","肿瘤的分类",2011,46,"A","","下列选项中属于良性肿瘤的是",[["A","视网膜母细胞瘤"],["B","软骨母细胞瘤"],["C","肾母细胞瘤"],["D","神经母细胞瘤"]],"B","视网膜母细胞瘤（十版病理学P108）为产生于视网膜胚基的恶性肿瘤（A错）。软骨母细胞瘤为来源于幼稚软骨细胞的良性肿瘤（B对）。肾母细胞瘤（十版病理学P266）为起源于后肾胚基组织的恶性肿瘤（C错）。神经母细胞瘤（十版病理学P324）为发生于交感神经节和肾上腺髓质的恶性肿瘤（D错）。在历年西医综合真题中，良恶性肿瘤的鉴别反复出现，现将常考的良恶性肿瘤归纳如下——良性肿瘤：骨母细胞瘤、软骨母细胞瘤（B对）、脂肪母细胞瘤、肌母细胞瘤、葡萄胎、血管瘤、神经鞘瘤、纤维腺瘤、多形性腺瘤；恶性肿瘤：淋巴瘤、白血病、黑色素瘤、视网膜母细胞瘤（A错）、神经母细胞瘤（D错）、肾母细胞瘤（C错）、肝母细胞瘤、绒毛膜癌、无性细胞瘤、精原细胞瘤、骨髓瘤、尤文氏瘤。","","N"],["2011-N47",5,"第10节 肿瘤的分子基础","获得侵袭和转移能力",2011,47,"A","","患者，女，58岁。因左乳腺外上象限肿物伴腋窝淋巴结肿大住院。手术标本病理诊断为左乳浸润性导管癌伴淋巴结转移（2/10）。下列病理变化中，与患者肿瘤转移关系最密切的是",[["A","角蛋白的表达增高"],["B","凋亡增多"],["C","层粘连蛋白受体增多"],["D","出现坏死灶"]],"C","肿瘤的转移大致可分为四个步骤：1.癌细胞表面黏附分子减少；2.癌细胞与基底膜的黏着增加；3.细胞外基质降解；4.癌细胞迁移。层粘连蛋白受体（LN）增多（C对）能使癌细胞与基底膜的黏着增加，促进肿瘤的转移过程。角蛋白的表达增高与肿瘤的分期和预后有一定关系，与肿瘤转移无关（A错）。凋亡增多（B错）和出现坏死灶（D错）与肿瘤转移无关。","","N"],["2011-N48",7,"第4节 风湿病","变质渗出期",2011,48,"A","","风湿病变质渗出期的主要病变是",[["A","纤维素样坏死形成"],["B","阿绍夫小体形成"],["C","梭形瘢痕形成"],["D","小化脓灶形成"]],"A","风湿病变质渗出期的主要病变是黏液样变性和纤维素样坏死（A对）。阿绍夫小体（Aschoff小体）为风湿病增生期的主要病变（B错）。梭形瘢痕为风湿病纤维化期的主要病变（C错）。小化脓灶为细菌性心肌炎（十版病理学P164）的主要病变（D错）。","","N"],["2011-N49",4,"第1节 自身免疫病","皮肤",2011,49,"A","","系统性红斑狼疮的狼疮带是指带状免疫荧光出现于",[["A","关节滑膜内"],["B","血管壁"],["C","肾小球基膜"],["D","真皮与表皮交界处"]],"D","系统性红斑狼疮（SLE）可累及全身各器官，其中约80%的患者可表现出不同程度的皮肤损害，其典型表现为真皮与表皮交界处（D对）出现狼疮带，即免疫复合物沉积所形成的带状免疫荧光。","","N"],["2011-N50",7,"第1节 动脉粥样硬化","动脉粥样硬化的发病机制",2011,50,"A","","与动脉粥样硬化斑块形成无关的细胞是",[["A","内皮细胞"],["B","平滑肌细胞"],["C","单核细胞"],["D","成纤维细胞"]],"D","根据损伤-应答反应学说，内皮细胞损伤是动脉粥样硬化斑块形成的前提条件。损伤的内皮细胞分泌生长因子，激活单核细胞及平滑肌细胞摄取脂质，形成动脉粥样硬化斑块的重要组成部分：单核细胞源性泡沫细胞及平滑肌细胞源性泡沫细胞。因此，内皮细胞、平滑肌细胞和单核细胞均与动脉粥样硬化斑块形成有关（ABC错）。本题给出参考答案D，即认为成纤维细胞与动脉粥样硬化斑块形成无关，但根据八版病理学P131动脉SMC增殖或突变学说，成纤维细胞也有参与动脉粥样硬化斑块的形成过程。","","N"],["2011-N51",8,"第5节 肺尘埃沉着病","硅结节的形成",2011,51,"A","","形成早期细胞性硅结节的细胞主要是",[["A","巨噬细胞"],["B","淋巴细胞"],["C","成纤维细胞"],["D","嗜中性粒细胞"]],"A","硅肺的基本病变是硅结节的形成和肺组织的弥漫性纤维化，硅结节形成的早期阶段是由吞噬硅尘的巨细胞聚集形成的细胞性结节（A对），随病程进展，结节内成纤维细胞增生，结节发生纤维化遂形成纤维性结节。","","N"],["2011-N52",8,"第2节 慢性阻塞性肺疾病","腺泡中央型肺气肿",2011,52,"A","","中央型肺气肿是指",[["A","三、四级支气管和周围肺泡囊扩张"],["B","呼吸性细支气管扩张，周围肺泡囊扩张不明显"],["C","肺门周围的肺组织扩张，近胸膜处肺组织扩张不明显"],["D","呼吸性细支气管扩张不明显，周围肺泡管和肺泡囊扩张"]],"B","肺泡性肺气肿病变发生在肺腺泡内，根据发生的部位和范围可分为：腺泡中央型肺气肿、腺泡周围型肺气肿和全腺泡型肺气肿。腺泡中央型肺气肿是指位于肺腺泡中央的呼吸性细支气管呈囊状扩张，而肺泡管和肺泡囊和肺泡扩张不明显（B对）。呼吸性细支气管扩张不明显，周围肺泡管和肺泡囊扩张（D错）见于腺泡周围型肺气肿。不存在AC选项描述的情况（AC错）。注：根据支气管树的分级标准，A选项提及的3、4级支气管为段支气管，而非17、18、19级的呼吸性细支气管，故A选项非全腺泡型肺气肿（呼吸性细支气管、肺泡管、肺泡囊和肺泡均扩张）。","","N"],["2011-N53",10,"第2节 淋巴组织肿瘤","前体B细胞的免疫表型",2011,53,"A","","下列选项中，符合前体B细胞淋巴母细胞白血病/淋巴瘤的叙述是",[["A","老年患者多见"],["B","95%TdT阳性"],["C","白细胞计数超过100×10⁹／L"],["D","Bcl-2蛋白过度表达"]],"B","前体 B 细胞淋巴母细胞白血病/淋巴瘤（B-ALL）的患者多是儿童（A错），常表现为白血病， 一般有广泛的骨髓累及和外周血白细胞数量增加，可高达100×10⁹ /L（C对）。约95%的病例可见TdT阳性（B对）。Bcl2蛋白过度表达（D错）是滤泡性淋巴瘤的表现（十版病理学P232）。本题的答案存在争议。","","N"],["2011-N54",4,"第3节 器官和骨髓移植排斥反应","超急性排斥反应",2011,54,"A","","超急性排异反应的主要病因是",[["A","受者存在抗移植物循环抗体"],["B","受者与供者HLA配型不理想"],["C","受者存在严重的免疫缺陷"],["D","受者存在抗移植物T淋巴细胞"]],"A","同种异体移植中，排斥反应有宿主抗移植物反应和移植物抗宿主反应两种基本类型，其中宿主抗移植物反应根据形态变化和发病机制不同又可分为超急性排斥反应、急性排斥反应和慢性排斥反应。超急性排斥（异）反应一般于移植后数分钟至数小时出现，其主要病因为受者存在抗移植物循环抗体（移植前循环中已有HLA抗体存在）（A对），或受者与供者ABO血型不符，本质上属于Ⅲ型变态反应。受者与供者HLA配型不理想（B错）为急性排斥反应或慢性排斥反应的主要病因。若受者存在抗移植物T淋巴细胞（D错），器官移植后常发生急性排斥反应。受者存在严重的免疫缺陷（C错），器官移植后常发生移植物抗宿主反应。","","N"],["2011-N55",9,"第6节 病毒性肝炎","溶解性坏死的概述",2011,55,"A","","下列肝细胞坏死的病变中，可以经过完全再生修复的是",[["A","大块坏死"],["B","桥接坏死"],["C","灶状坏死"],["D","碎片坏死"]],"C","大块坏死、桥接坏死、碎片坏死三种类型的坏死，由于坏死范围较大，修复时不能完全再生。灶状坏死由于范围较小（病理学未提及灶状坏死概念，可参见八版传染病学P26，灶状坏死比点状坏死略大，有时二者并不作区分而合称点灶状坏死），坏死后可由邻近肝细胞完全再生修复（C对）。","","N"],["2011-N56",12,"第7节 乳腺疾病","导管原位癌",2011,56,"A","","下列乳腺癌的病理学类型中，属于原位癌的是",[["A","导管内癌"],["B","黏液癌"],["C","髓样癌"],["D","小管癌"]],"A","乳腺癌按照组织形态可分为非浸润性癌和浸润性癌两类，非浸润性癌即原位癌，又可分为导管内原位癌（导管内癌）（A对）和小叶原位癌两种，其中导管内原位癌包括粉刺癌、非粉刺型导管内癌和乳头Paget病伴导管原位癌。黏液癌（B错）、髓样癌（C错）、小管癌（D错）均属于浸润性癌。","","N"],["2011-N133",16,"第2节 结核病","溃疡型",2011,133,"B","","肠结核的病变特征是",[["A","溃疡长轴与肠道长轴平行"],["B","溃疡长轴与肠道长轴垂直"],["C","弥漫性小溃疡上有假膜形成"],["D","溃疡呈三角烧瓶状"]],"B","肠结核病变沿肠壁淋巴管扩散，而肠壁淋巴管环肠管行走，因此溃疡呈环形，其长轴与肠道长轴垂直（B对）。溃疡长轴与肠道长轴平行（A错）是肠伤寒溃疡的病变特征（十版病理学P350）。弥漫性小溃疡上有假膜形成（C错）是细菌性痢疾的病变特征（十版病理学P351）。溃疡呈三角烧瓶状（D错）是肠阿米巴病的病变特征（十版病理学P358）。","","N"],["2011-N134",16,"第10节 寄生虫病","肠阿米巴病病理变化概述",2011,134,"B","","肠阿米巴病的病变特点是",[["A","溃疡长轴与肠道长轴平行"],["B","溃疡长轴与肠道长轴垂直"],["C","弥漫性小溃疡上有假膜形成"],["D","溃疡呈三角烧瓶状"]],"D","肠阿米巴病的病变特点是形成口小底大的三角烧瓶状溃疡（D对）。溃疡长轴与肠道长轴平行（A错）是肠伤寒的病变特点（十版病理学P350）。溃疡长轴与肠道长轴垂直（B错）是肠结核的病变特点（十版病理学P348）。弥漫性小溃疡上有假膜形成（C错）是细菌性痢疾的病变特征（十版病理学P351）。","","N"],["2011-N135",3,"第2节 急性炎症","化脓性炎",2011,135,"B","","属于化脓性炎的是",[["A","急性细菌性痢疾"],["B","肠伤寒"],["C","急性蜂窝织炎"],["D","急性重症肝炎"]],"C","根据炎症的基本病变性质进行分类，可分为变质性炎、渗出性炎和增生性炎。任何炎症都在一定程度上包含变质、渗出、增生这三种基本病变，但往往以一种病变为主，以变质为主时称为变质性炎；以渗出为主时称为渗出性炎；以增生为主时称为增生性炎。渗出性炎还可以根据渗出物的主要成分和病变特点，进一步分为浆液性炎、纤维素性炎、化脓性炎、出血性炎等。其中化脓性炎多由化脓菌（如葡萄球菌、链球菌、脑膜炎双球菌或大肠杆菌等）感染所致，也可由组织坏死继发感染产生。急性蜂窝织炎为疏松结缔组织的化脓性炎（C对），常发生于皮肤、肌肉和阑尾。急性细菌性痢疾（十版病理学P351）属于纤维素性炎（假膜性炎）（A错）。肠伤寒（十版病理学P350）属于增生性炎症（肉芽肿性炎）（B错）。急性重症肝炎属于变质性炎症（D错）。","","N"],["2011-N136",3,"第3节 慢性炎症","肉芽肿性炎的常见类型",2011,136,"B","","属于肉芽肿性炎的是",[["A","急性细菌性痢疾"],["B","肠伤寒"],["C","急性蜂窝织炎"],["D","急性重症肝炎"]],"B","肉芽肿性炎以炎症局部巨噬细胞及其衍生细胞增生形成境界清楚的结节状病灶（即肉芽肿）为特征，是一种特殊类型的慢性炎症。常见的肉芽肿性炎有：结核病（结核结节）、伤寒（伤寒小结）（B对）、梅毒（树胶样肿）、血吸虫病（虫卵结节）等。","","N"],["2011-N137",3,"第2节 急性炎症","出血性炎",2011,137,"B","","属于出血性炎的是",[["A","空洞性肺结核"],["B","细菌性痢疾"],["C","小叶性肺炎"],["D","钩端螺旋体病"]],"D","根据炎症的基本病变性质进行分类，可分为变质性炎、渗出性炎和增生性炎。任何炎症都在一定程度上包含变质、渗出、增生这三种基本病变，但往往以一种病变为主，以变质为主时称为变质性炎；以渗出为主时称为渗出性炎；以增生为主时称为增生性炎。渗出性炎还可以根据渗出物的主要成分和病变特点，进一步分为浆液性炎、纤维素性炎、化脓性炎、出血性炎等。出血性炎是指炎症病灶的血管损伤严重，渗出物中含有大量红细胞，常见于流行性出血热、钩端螺旋体病（D对）和鼠疫等。空洞性肺结核为增生性炎（A错）。细菌性痢疾为纤维素性炎（B错）。小叶性肺炎为化脓性炎（C错）。","","N"],["2011-N138",3,"第2节 急性炎症","纤维蛋白性炎",2011,138,"B","","属于纤维素性炎的是",[["A","空洞性肺结核"],["B","细菌性痢疾"],["C","小叶性肺炎"],["D","钩端螺旋体病"]],"B","根据炎症的基本病变性质进行分类，可分为变质性炎、渗出性炎和增生性炎。任何炎症都在一定程度上包含变质、渗出、增生这三种基本病变，但往往以一种病变为主，以变质为主时称为变质性炎；以渗出为主时称为渗出性炎；以增生为主时称为增生性炎。渗出性炎还可以根据渗出物的主要成分和病变特点，进一步分为浆液性炎、纤维素性炎、化脓性炎、出血性炎等。纤维素性炎是以渗出物中含有大量纤维蛋白（纤维素）为特征的炎症，易发生于黏膜、浆膜和肺组织，常见的纤维素性炎有大叶性肺炎、细菌性痢疾（B对）、白喉、风湿性心包炎等。空洞性肺结核为增生性炎（A错）。小叶性肺炎为化脓性炎（C错）。钩端螺旋体病为出血性炎（D错）。","","N"],["2011-N163",7,"第2节 高血压病","脑病变",2011,163,"X","","高血压病可引起的脑内病变有",[["A","脑水肿"],["B","脑梗死"],["C","脑出血"],["D","脑内微小动脉瘤"]],"ABCD","高血压时，由于脑小动脉硬化和痉挛，局部组织缺血，毛细血管通透性增加，发生脑水肿（A对），严重时，可发生缺血坏死，形成梗死灶（B对）。高血压时，脑血管的细小动脉硬化使血管壁变脆，当血压突然升高时引起破裂性出血（C对）。高血压时，血管壁弹性下降，血管壁可局部膨出形成小动脉瘤和微小动脉瘤，恶性高血压时细小动脉壁发生纤维素样坏死，也可促进形成动脉瘤（D对）。","","N"],["2011-N164",11,"第1节 肾小球疾病","急性弥漫性增生性肾小球肾炎病理变化",2011,164,"X","","急性弥漫性增生性肾小球肾炎的病理特点有",[["A","肾小球内皮细胞增生"],["B","肾小球系膜细胞增生"],["C","病变严重者有肾小球毛细血管纤维素样坏死"],["D","电镜下脏层上皮细胞足突消失"]],"ABC","急性弥漫性增生性肾小球肾炎的病理特点是肾小球内皮细胞增生（A对）和肾小球系膜细胞增生（B对），病变严重者可有肾小球毛细血管纤维素样坏死（C对）。电镜下脏层上皮细胞足突消失（D错）为微小病变性肾小球病（脂性肾病）（十版病理学P259）、膜性肾小球病（十版病理学P256）和局灶性节段性肾小球硬化（十版病理学P259）的病理特点。","","N"],["2011-N165",9,"第12节 消化系统常见肿瘤","结直肠癌病理变化概述",2011,165,"X","","大肠癌的肉眼类型有",[["A","隆起型"],["B","溃疡型"],["C","浸润型"],["D","胶样型"]],"ABC","大肠癌的肉眼类型大体可分为三型，分别为隆起型（A对）、溃疡型（B对）、浸润型（C对）。10版教材已删除胶样型（D错）。","","N"],["2011-N166",16,"第2节 结核病","原发性肺结核病",2011,166,"X","","原发性肺结核病理特点有",[["A","病灶多位于肺尖部"],["B","常循血道播散"],["C","常循淋巴道播散"],["D","常为浸润型肺结核"]],"BC","原发性肺结核的病理特点有：病灶多位于肺上叶下部或下叶上部（A错），病变常循血道（B对）或淋巴道（C对）播散到全身。浸润型肺结核（D错）属于继发性肺结核。","","N"],["2011-N167",9,"第12节 消化系统常见肿瘤","伴有肠黏膜增生的慢性肠疾病",2011,167,"X","","下列大肠息肉病变中，属于癌前病变的有",[["A","幼年性息肉"],["B","家族性腺瘤性息肉病"],["C","炎症性息肉"],["D","腺瘤性息肉"]],"BD","家族性腺瘤性息肉病（B对）和腺瘤性息肉（息肉状腺瘤）（D对）均为伴有肠黏膜增生的慢性肠疾病，与大肠癌的发生关系密切，属于癌前病变。其中家族性腺瘤性息肉病与遗传因素有关，如不予治疗，将不可避免地出现癌变。幼年性息肉（A错）和炎症性息肉（C错）均为非肿瘤性息肉，发生癌变的可能性小。记忆技巧：带有“腺瘤”和“病”的息肉通常为癌前病变，不带则一般为非癌前病变。","","N"],["2011-N168",11,"第1节 肾小球疾病","肾病综合征",2011,168,"X","","引起肾病综合征的肾炎类型有",[["A","膜性肾小球肾炎"],["B","弥漫性毛细血管内增生性肾小球肾炎"],["C","新月体性肾小球肾炎"],["D","轻微病变型肾小球肾炎"]],"AD","可引起肾病综合征的肾炎类型有：膜性肾小球肾炎（A对）、轻微（微小）病变型肾小球肾炎（D对）、局灶性节段性肾小球硬化、膜增生性肾小球肾炎和系膜增生性肾小球肾炎。弥漫性毛细血管内增生性肾小球肾炎（B错）也称急性肾炎，引起急性肾炎综合征。新月体性肾小球肾炎（C错）也称急进性肾炎，引起急进性肾炎综合征。","","N"],["2012-N41",0,"第1节 适应","萎缩的病理变化",2012,41,"A","","在下列病变中，脂褐素主要出现在",[["A","萎缩"],["B","脂肪变性"],["C","坏死"],["D","凋亡"]],"A","脂褐素是细胞自噬溶酶体内未被消化的细胞器碎片残体，其大量增加最常见于细胞萎缩（A对）。细胞凋亡可由细胞萎缩发展而来（十版病理学P6），故细胞凋亡时也可见脂褐素，但细胞凋亡与脂褐素并无直接和必然的联系（D错）。脂肪变性（B错）和坏死（C错）均无脂褐素增加。","","N"],["2012-N42",0,"第3节 细胞可逆性损伤","脂肪变的病理变化",2012,42,"A","","虎斑心的组织学改变是",[["A","心肌纤维间大量淋巴细胞浸润"],["B","心肌纤维间出现脂肪沉积"],["C","心肌细胞中出现脂肪沉积"],["D","心肌细胞中出现透明蛋白小体"]],"C","虎斑心因心肌的脂肪变性（心肌细胞中出现脂肪沉积）引起（C对）。心肌纤维间大量淋巴细胞浸润是病毒性心肌炎的表现（十版病理学P164）（A错）。心肌纤维间出现脂肪沉积为心肌脂肪浸润，并非心肌细胞脂肪变性（B错）。透明蛋白小体多见于酒精性肝炎，为肝细胞胞质中细胞中间丝前角蛋白的玻璃样变性（D错）。","","N"],["2012-N43",0,"第4节 细胞不可逆性损伤（细胞死亡）","脂肪坏死",2012,43,"A","","在下列坏死中有特征性钙皂形成的是",[["A","凝固性坏死"],["B","液化性坏死"],["C","干酪性坏死"],["D","脂肪坏死"]],"D","脂肪坏死后，释出的脂肪酸和组织中的钙离子结合，形成钙皂（D对）。脂肪坏死属于液化性坏死，但并不是所有的液化性坏死均有钙皂的形成，如肝细胞的液化性坏死（B错）。凝固性坏死与健康组织间界限多较明显，镜下特点为细胞微细结构消失，而组织结构轮廓仍可保存，无钙皂形成（A错）。干酪样坏死是坏死更为彻底的特殊类型凝固性坏死，也无钙皂形成（C错）。","","N"],["2012-N44",1,"第3节 伤口愈合","骨性骨痂形成",2012,44,"A","","下列骨折愈合描述中，骨折处表现为肉芽组织和排列紊乱的骨小梁的是",[["A","纤维性骨痂形成"],["B","骨性骨痂形成"],["C","骨不愈合"],["D","骨痂重塑完成"]],"B","骨折愈合可分为血肿形成、纤维性骨痂形成、骨性骨痂形成、骨痂改建或重塑共四个阶段。纤维性骨痂含肉芽组织，但无骨小梁形成（A错）。骨性骨痂含肉芽组织和排列紊乱的骨小梁（编织骨）（B对）。骨痂重塑完成后，肉芽组织消失，骨小梁排列正常（D错）。骨折不愈合时，骨折处无骨痂形成，肉芽组织和骨小梁均不可见（C错）。","","N"],["2012-N45",2,"第3节 血栓形成","混合血栓",2012,45,"A","","肉眼所见的混合血栓中灰白色条纹在镜下所见的是",[["A","血小板小梁"],["B","纤维蛋白网络"],["C","淋巴细胞浸润"],["D","血栓机化时的肉芽组织"]],"A","静脉血栓在形成血栓头部后，其下游的血流变慢和出现旋涡，导致另一个血小板小梁状的凝集堆形成。在血小板小梁之间的血液发生凝固，纤维蛋白形成网状结构，网内充满红细胞。由于这一过程反复交替进行，导致形成的血栓肉眼观时呈灰白色和红褐色层状交替结构，灰白色即为血小板小梁（A对），红色为红细胞。","","N"],["2012-N46",2,"第3节 血栓形成","透明血栓",2012,46,"A","","透明血栓主要发生的组织部位是",[["A","毛细血管"],["B","静脉瓣膜"],["C","动脉管壁"],["D","心房内膜"]],"A","血栓类型可分为四种：白色血栓、混合血栓、红色血栓和透明血栓。透明血栓主要发生的组织部位是毛细血管（A对）。静脉瓣膜处由于血流缓慢，常发生混合血栓（B错）。动脉和心房内血流较快，常发生白色血栓（CD错）。","","N"],["2012-N47",3,"第2节 急性炎症","纤维蛋白性炎",2012,47,"A","","在假膜性炎症中，最具有特征性的渗出物是",[["A","白蛋白"],["B","纤维蛋白"],["C","淋巴细胞"],["D","中性粒细胞"]],"B","假膜性炎属于纤维素性炎，其最具有特征性的渗出物是纤维蛋白（纤维素）（B对）。白蛋白主要见于浆液性炎（十版病理学P72）（A错）。淋巴细胞（C错）和中性粒细胞（D错）可见于假膜性炎，但此二者非假膜性炎的特征性成分。","","N"],["2012-N48",5,"第4节 肿瘤的生长和扩散","肿瘤的演进和异质性",2012,48,"A","","肿瘤的异质性是指",[["A","肿瘤细胞的大小"],["B","肿瘤起源于不同的细胞亚群"],["C","肿瘤细胞形成具有不同的生长侵袭特性的亚群"],["D","肿瘤细胞核染色体深浅不一"]],"C","恶性肿瘤虽然是从一个发生恶性转化的细胞单克隆性增殖而来（即起源于同一个细胞亚群）（B错），但在生长过程中，经过许多代分裂增殖产生的子代细胞，可出现不同的基因改变或其它大分子的改变，其生长速度、侵袭能力、对生长信号的反应、对抗癌药物细胞的敏感性等方面都可以有差异。这时，这一肿瘤细胞群体不再是由完全一样的肿瘤细胞组成，而是具有异质性的肿瘤细胞群体，是具有各自特性的亚克隆。简而言之，异质性是指一个克隆来源的肿瘤细胞群在生长过程中形成的侵袭性能力、生长速度、对激素的反应、对抗癌药的敏感性等方面有所不同的亚克隆过程（C对）。肿瘤细胞的大小不一（A错）、肿瘤细胞核染色体深浅不一（D错）属于肿瘤的细胞异型性（十版病理学P92）。","","N"],["2012-N49",12,"第7节 乳腺疾病","乳腺癌分子分型",2012,49,"A","","下列原癌基因中，其表达产物与乳腺癌预后明确相关的是",[["A","ras"],["B","jun"],["C","myc"],["D","her2/neu"]],"D","her2/neu（D对）基因为乳腺癌的原癌基因。取名her2，是由于其表达产物的结构与人表皮因子受体（human epidermal growth factor receptor，即EGFR，或称her1）相似；又名neu，是由于其最初是在大鼠神经母细胞瘤（neuroblastoma）的细胞株内被发现的。her2/neu基因的表达与乳腺癌的预后密切相关，her2过度表达（可激活EGFR的信号通路，促进肿瘤增殖）者，乳腺癌增殖活性高，预后差。ras（A错）、jun（B错）、myc（C错）均为常见的原癌基因，但表达产物均与乳腺癌预后无关。备注：her2/neu基因还有一个名字为erb-B2，是由于其结构与禽类原始红细胞白血病原癌基因B（erythroblastosis oncogene B，后证明即为EGFR）相似而得名。","","N"],["2012-N50",5,"第10节 肿瘤的分子基础","肿瘤抗原",2012,50,"A","","在下列肿瘤标志物中，属于胚胎抗原的是",[["A","角蛋白"],["B","甲胎蛋白"],["C","波形蛋白"],["D","前列腺特异性蛋白"]],"B","题干中的“癌胚抗原”应为“胚胎抗原”或“肿瘤胎儿抗原”。有些抗原在胎儿组织中表达量大，在分化成熟组织中不表达或表达量很小，但在癌变组织中表达增加，这种抗原称为胚胎抗原或肿瘤胎儿抗原。例如，甲胎蛋白（B对）可见于胎肝细胞和肝细胞癌中，癌胚抗原可见于大肠癌和胰腺癌中。角蛋白、波形蛋白和前列腺特异性蛋白除见于癌变组织外，还可见于分化成熟的正常组织（细胞）：角蛋白为存在于正常上皮组织（细胞）的中间丝蛋白；波形蛋白为存在于正常间叶组织的中间丝蛋白；前列腺特异性蛋白（前列腺特异性抗原）为存在于正常前列腺上皮细胞的丝氨酸蛋白酶。因此均不属于胚胎抗原（ACD错）。","","N"],["2012-N51",4,"第3节 器官和骨髓移植排斥反应","血管型排斥反应",2012,51,"A","","在肾移植排异反应中，最典型的Ⅱ型超敏反应是",[["A","超急性排异反应"],["B","急性细胞型排异反应"],["C","急性血管型排异反应"],["D","慢性排异反应"]],"C","Ⅱ型超敏反应是抗体依赖的细胞溶解型或细胞毒型变态反应，在肾移植排异反应中，急性血管型排异反应（C对）是由抗体介导的排斥反应，抗体及补体的沉积可引起血管损伤，属于典型的Ⅱ型超敏反应。超急性排斥反应（A错）属于Ⅲ型超敏反应（十版病理学P88）。急性细胞型排斥反应（B错）属于Ⅳ型超敏反应。慢性排斥反应（D错）可能与Ⅳ型超敏反应有关。","","N"],["2012-N52",5,"第4节 肿瘤的生长和扩散","种植性转移",2012,52,"A","","双侧卵巢发生肿瘤转移形成克氏瘤（Krukenbergtumor）时，其原发肿瘤主要为",[["A","胃印戒细胞癌"],["B","肠型胃腺癌"],["C","肠腺癌"],["D","肠印戒细胞癌"]],"A","胃癌特别是胃黏液癌（胃印戒细胞癌）（A对）癌细胞浸润至胃浆膜表面时可脱落至腹腔，种植于腹腔及盆腔器官的浆膜上，当种植于卵巢上时，导致双侧卵巢发生肿瘤转移，称克氏瘤（Krukenberg tumor）。","","N"],["2012-N53",9,"第12节 消化系统常见肿瘤","肝细胞癌的扩散",2012,53,"A","","肝细胞性肝癌最常见的转移部位为",[["A","肝"],["B","肺"],["C","骨"],["D","肝门区淋巴结"]],"A","肝细胞性肝癌最常见的转移方式为肝内的直接蔓延，因此肝（A对）为其最常见的转移部位。肺（B错）是肝细胞性肝癌最常见的肝外转移部位。骨（C错）转移可发生于晚期肝癌，但较少见。肝门区淋巴结（D错）是肝外淋巴转移的常见部位。","","N"],["2012-N54",12,"第2节 子宫体疾病","子宫平滑肌肿瘤病理变化",2012,54,"A","","子宫平滑肌瘤与子宫平滑肌肉瘤镜下的主要鉴别点是",[["A","细胞核异型程度"],["B","肿瘤大小"],["C","细胞核分裂象数量"],["D","边界是否清晰"]],"C","平滑肌瘤核分裂象罕见（十版病理学P106），而平滑肌肉瘤分裂象多见，且分裂象的多少对平滑肌肉瘤的诊断及其恶性程度的判断很重要（十版病理学P107）。因此，子宫平滑肌瘤与子宫平滑肌肉瘤镜下的主要鉴别点是核分裂象数量（C对）。细胞核异型程度指肿瘤细胞与正常细胞之间细胞核的差异程度，严格来说细胞核分裂象数量增多亦属于细胞核“异型”，但本题的细胞核异型程度似乎更倾向于指细胞核的大小、形状和染色差异程度（十版病理学P91）等，故不选择A选项。肿瘤大小（B错）、边界是否清晰（D错）均有辅助鉴别价值，并非主要的鉴别点。","","N"],["2012-N55",16,"第3节 伤寒","伤寒肠道病变概述",2012,55,"A","","伤寒溃疡的形态取决于",[["A","肠黏膜皱襞形态"],["B","肠黏膜淋巴小结的形态"],["C","肠黏膜淋巴管的走向"],["D","肠黏膜血管的走向"]],"B","伤寒溃疡的形态取决于肠黏膜淋巴小结的形态（B对）：发生于集合淋巴小结的溃疡，呈椭圆形，长轴与肠的长轴平行，发生于孤立淋巴小结的溃疡呈小圆形。肠黏膜的淋巴管走向（C错）决定肠结核溃疡的形态（十版病理学P348）。","","N"],["2012-N56",13,"第2节 甲状腺疾病","滤泡癌",2012,56,"A","","甲状腺癌中，一般只从血行转移的是",[["A","滤泡状癌"],["B","乳头状癌"],["C","髓样癌"],["D","未分化癌"]],"A","甲状腺癌可分为乳头状癌、滤泡状癌、髓样癌和未分化癌四种组织学类型，四种类型均可见血行转移和淋巴结转移，只是滤泡状癌（A）以血行转移为主而已，因此本题并不严谨。","","N"],["2012-N133",8,"第2节 慢性阻塞性肺疾病","全腺泡型肺气肿",2012,133,"B","","全腺泡型肺气肿见于",[["A","吸烟"],["B","慢性支气管炎"],["C","α₁-抗胰蛋白酶缺乏"],["D","瘢痕附近区"]],"C","α₁抗胰蛋白酶缺乏（C对）是全腺泡型肺气肿的发病机制之一：α₁-抗胰蛋白酶广泛存在于组织和体液中，对包括弹性蛋白酶在内的多种蛋白水解酶有抑制作用。α₁抗胰蛋白酶缺乏时，中性粒细胞和巨噬细胞分泌的弹性蛋白酶数量增多、活性增强，破坏了肺组织的结构，使呼吸性细支气管、肺泡管、肺泡囊和肺泡的回缩力均减弱，促进全腺泡型肺气肿的发生。吸烟（A错）和慢性支气管炎（B错）常引起腺泡中央型肺气肿。瘢痕附近区（D错）可见瘢痕旁肺气肿。","","N"],["2012-N134",8,"第2节 慢性阻塞性肺疾病","腺泡周围型肺气肿",2012,134,"B","","腺泡远端肺气肿见于",[["A","吸烟"],["B","慢性支气管炎"],["C","α₁-抗胰蛋白酶缺乏"],["D","瘢痕附近区"]],"D","腺泡远端肺气肿是指病变主要累及肺腺泡远端部位如肺泡管、肺泡囊和肺泡等部位的肺气肿类型。腺泡周围型肺气肿病变部位为肺泡管、肺泡囊和肺泡，是最典型的腺泡远端肺气肿。瘢痕附近区（D对）可见瘢痕旁肺气肿（十版病理学P179），瘢痕旁肺气肿由肺泡破裂融合形成，病变部位仅为肺泡，也属于腺泡远端肺气肿。吸烟（A错）和慢性支气管炎（B错）常引起腺泡中央型肺气肿。α₁抗胰蛋白酶缺乏（C错）常引起全腺泡型肺气肿。","","N"],["2012-N135",3,"第3节 慢性炎症","主要的慢性炎症细胞",2012,135,"B","","急性炎症晚期开始出现的细胞是",[["A","淋巴细胞"],["B","中性粒细胞"],["C","浆细胞"],["D","巨噬细胞"]],"D","炎症的不同阶段游出的白细胞种类有所不同，在急性炎症的早期（24小时以内）中性粒细胞（B错）首先游出，中期（24～48小时）以单核细胞浸润为主，晚期（24～48小时之后）单核细胞转变为巨噬细胞，以巨噬细胞浸润为主（D对）。淋巴细胞（A错）和浆细胞（C错）主要见于慢性炎症。","","N"],["2012-N136",3,"第3节 慢性炎症","肉芽肿性炎的概念",2012,136,"B","","出现在肉芽肿性炎症的主要细胞是",[["A","淋巴细胞"],["B","中性粒细胞"],["C","浆细胞"],["D","巨噬细胞"]],"D","肉芽肿性炎是一种特殊类型的慢性炎症，其主要细胞成分包括巨噬细胞（D对）及其衍生而来的上皮样细胞和多核巨细胞，此外还可见少量的淋巴细胞（A错）和浆细胞（C错）。中性粒细胞多见于化脓性炎症（B错）。","","N"],["2012-N137",11,"第1节 肾小球疾病","急性弥漫性增生性肾小球肾炎病理变化",2012,137,"B","","属于循环免疫复合物型肾炎的是",[["A","急性弥漫增生性肾炎"],["B","肺出血肾炎综合征"],["C","微小病变肾病"],["D","Heymann 肾炎"]],"A","循环免疫复合物型肾炎（十版病理学P251）是肾小球肾炎的一种病因学分类，是由Ⅲ型超敏反应引起的免疫性病变，抗体与非肾小球性可溶性抗原结合，形成免疫复合物，随血液循环流经肾脏，沉积于肾小球内，并常与补体结合，引起肾小球病变。最典型的循环免疫复合物型肾炎是急性弥漫增生性肾炎（A对），急性弥漫增生性肾炎因链球菌感染刺激机体产生抗体，并形成循环免疫复合物沉积于肾小球而致病。肺出血肾炎综合征（Goodpasture综合征）（十版病理学P255）（B错）是指一些Ⅰ型急进型肾小球肾炎（抗GBM抗体性肾炎）患者的抗GBM（抗基底膜）抗体与肺泡基底膜发生交叉免疫反应，引起肺出血，属于原位免疫复合物型肾炎（十版病理学P252）。微小病变肾病（十版病理学P259）（C错）的肾小球内无免疫复合物沉积，病因不清。Heymann肾炎（D错）是一种与原发性膜性肾小球病相似的自身免疫病（十版病理学P252），属于原位免疫复合物型肾炎。","","N"],["2012-N138",11,"第1节 肾小球疾病","急进性肾小球肾炎病因",2012,138,"B","","属于抗肾小球基膜型肾炎的是",[["A","急性弥漫增生性肾炎"],["B","肺出血肾炎综合征"],["C","微小病变肾病"],["D","Heymann 肾炎"]],"B","肺出血肾炎综合征（B对）因患者的抗肾小球基膜（GBM）抗体与肺泡基膜发生交叉反应而致病，见于Ⅰ型急进性肾炎患者，后者属于抗肾小球基膜型肾炎（十版病理学P251）。急性弥漫增生性肾炎（十版病理学P254）（A错）患者肾小球内有免疫复合物沉积，损伤由免疫复合物介导，属于循环免疫复合物型肾炎（十版病理学P251）。微小病变肾病（十版病理学P259）（C错）病因不清。Heymann肾炎（D错）是一种与原发性膜性肾小球病相似的自身免疫病（十版病理学P252），属于原位免疫复合物型肾炎。","","N"],["2012-N163",11,"第1节 肾小球疾病","微小病变性肾小球病病理变化",2012,163,"X","","在微小病变型肾小球肾炎中，肾小管容易形成的变性有",[["A","水样变性"],["B","脂肪变性"],["C","玻璃样变性"],["D","纤维素样变性"]],"BC","微小病变型肾小球肾炎又称脂性肾病，光镜下可见有脂质沉积于肾小管上皮细胞内，因此，肾小管容易形成脂肪变性（B对）。此外，当微小病变型肾炎出现蛋白尿时，血浆蛋白经肾小球滤出，可被肾小管上皮细胞吞饮并在胞浆内融合成玻璃样小滴，因此，肾小管也容易形成玻璃样变性（C对）。水样变性（A错）又称细胞水肿（十版病理学P15），是由于细胞内含水量过多引起的，主要见于病毒性肝炎（十版病理学P203）。纤维素样坏死（十版病理学P20），旧称纤维素样变性（D错），是指病变部位形成与纤维素染色性质相似的无结构物质，常出现于急进性肾炎、恶性高血压、风湿病等变态反应性疾病的血管病变中。","","N"],["2012-N164",1,"第2节 纤维性修复","肉芽组织的成分及形态",2012,164,"X","","下列选项中符合肉芽组织特征的有",[["A","较多的多核巨细胞"],["B","较多的成纤维细胞"],["C","较多的内皮细胞"],["D","较多的类上皮细胞"]],"BC","肉芽组织由新生薄壁的毛细血管（由内皮细胞组成）（C对）以及增生的成纤维细胞（B对）构成。类上皮细胞（D错）和多核巨细胞（A错）为肉芽肿的主要细胞成分，肉芽肿为肉芽肿性炎的特征性病变，区别于肉芽组织。","","N"],["2012-N165",2,"第5节 梗死","出血性梗死",2012,165,"X","","除了贫血性梗死形成所需的条件外，出血性梗死的形成还需要的条件有",[["A","组织蛋白质含量高"],["B","组织有严重的淤血"],["C","组织有双重血供"],["D","组织疏松"]],"BD","出血性梗死发生的条件：①严重淤血（B对）：当器官原有严重淤血时，血管阻塞引起的梗死为出血性梗死，如肺淤血。严重淤血是肺梗死形成的先决条件，因为在左心功能下降时，肺脏出现淤血，肺静脉和毛细血管内压增高，一旦肺动脉发生阻塞，原有的肺淤血影响支气管支气管动脉的有效供血，致使肺脏出现梗死。由于梗死灶组织疏松，血液进入肺泡，因此肺梗死是出血性梗死。②组织疏松（D对）：肠和肺的组织较疏松，梗死初期疏松的组织间隙可容纳大量漏出的血液，当组织坏死吸收水分而膨胀时，也不能把漏出的血液挤出梗死灶外，因而梗死灶为出血性。③动脉阻塞同时伴有静脉阻塞：如卵巢扭转、肠扭转。在动脉供血停止的同时，静脉回流也受阻，血液从淤血的毛细血管内漏出，形成出血性梗死。④双重血供（C对）：并行的未阻塞血管的血流可进入坏死区，但这种灌流又不足以弥补局部的缺血时发生出血性梗死。九版病理学认为出血性梗死的发生条件为严重淤血和组织疏松，按照九版观点此题答案选BD，但按照三版八年制教材和官方答案BCD为正确答案。","","N"],["2012-N166",7,"第1节 动脉粥样硬化","动脉平滑肌细胞的作用",2012,166,"X","","在动脉粥样硬化的早期病变中，有大量的泡沫细胞存在，这些细胞的来源有",[["A","血管内皮细胞"],["B","血管平滑肌细胞"],["C","巨噬细胞"],["D","成纤维细胞"]],"BC","单核细胞（巨噬细胞）通过表面的清道夫受体、CD36受体和Fc受体的介导，摄取脂质，形成单核细胞（巨噬细胞）源性泡沫细胞（十版病理学P142）（C对）。血管平滑肌细胞（SMC）通过表面的LPL受体介导摄取脂质，形成血管平滑肌细胞（SMC）源性泡沫细胞（十版病理学P142）（B对）。","","N"],["2012-N167",9,"第12节 消化系统常见肿瘤","结直肠黏膜上皮癌变",2012,167,"X","","在大肠癌发生中，常见的失活抑癌基因有",[["A","p53"],["B","APC"],["C","DCC"],["D","PDGF"]],"ABC","APC（B对）、p53（A对）和DCC（C对）均为与大肠癌发生相关的抑癌基因，这些抑制基因的失活将导致大肠癌的发生。PDGF（血小板源性生长因子）（D错）为原癌基因（九版生物化学P408），其活化与大肠癌的发生有关。","","N"],["2012-N168",10,"第2节 淋巴组织肿瘤","结节性淋巴细胞为主型霍奇金淋巴瘤",2012,168,"X","","结节性淋巴细胞为主型霍奇金淋巴瘤的肿瘤细胞特点有",[["A","爆米花样细胞"],["B","双核R-S细胞"],["C","CD20阳性"],["D","CD30阳性"]],"AC","结节性淋巴细胞为主型霍奇金淋巴瘤的肿瘤细胞多为多分叶核的爆米花样细胞（A对），典型的双核R-S细胞（B错）罕见。肿瘤细胞的免疫表型多为CD20（C对）、CD79a阳性，CD30阳性（D错）少见。","","N"],["2013-N41",2,"第1节 充血和淤血","肺淤血",2013,41,"A","","在下列病变中，含铁血黄素主要出现在",[["A","肺褐色硬化"],["B","小叶性肺炎"],["C","ARDS"],["D","间质性肺炎"]],"A","慢性肺淤血时，由于巨噬细胞吞噬漏出的红细胞，导致该种巨噬细胞中含有大量含铁血黄素颗粒，使肺外观呈现棕褐色，长期肺淤血又导致肺缺氧，造成肺间质纤维组织增生，肺质地变硬，最终发展为肺褐色硬化（A对）。小叶性肺炎（十版病理学P174）（B错）、ARDS（成人呼吸窘迫综合征）（C错）（十版病理学P185）、间质性肺炎[包括病毒性肺炎（十版病理学P175）和支原体肺炎（十版病理学P175）]（D错）均无含铁血黄素出现。","","N"],["2013-N42",0,"第4节 细胞不可逆性损伤（细胞死亡）","干酪样坏死",2013,42,"A","","镜下坏死组织结构的轮廓消失，呈现一片嗜酸性颗粒状物，其坏死类型是",[["A","凝固性坏死"],["B","液化性坏死"],["C","干酪样坏死"],["D","脂肪坏死"]],"C","干酪样坏死为坏死更彻底的特殊类型凝固性坏死，多位于结核病灶内，因病灶中含脂质较多，坏死区呈黄色，状似干酪而得名。干酪样坏死在镜下为无结构颗粒状红染物（嗜酸性），不见坏死部位原有组织轮廓（C对），甚至不见核碎屑。","","N"],["2013-N43",0,"第3节 细胞可逆性损伤","细胞内玻璃样变",2013,43,"A","","酒精中毒时，肝细胞内出现马洛里小体（Mallorybody），其病变性质是",[["A","水样变性"],["B","脂肪变性"],["C","玻璃样变性"],["D","纤维素样变性"]],"C","玻璃样变性是细胞内或间质中出现半透明状蛋白质蓄积，Mallory小体由肝细胞胞质中细胞中间丝前角蛋白变性聚集而成，属于玻璃样变（C对）。","","N"],["2013-N44",0,"第1节 适应","化生的类型",2013,44,"A","","在下列叙述中，不会发生的化生是",[["A","胃腺上皮化生为肠腺上皮"],["B","柱状上皮化生为鳞状上皮"],["C","纤维组织化生为软骨组织"],["D","鳞状上皮化生为纤维组织"]],"D","一种分化成熟的细胞类型被另一种分化成熟的细胞类型所取代的过程，称为化生，化生通常发生于同源性细胞之间，即上皮细胞之间或间叶细胞之间，鳞状上皮属于上皮组织，纤维组织属于间叶组织，故鳞状上皮不能化生为纤维组织（D对）。","","N"],["2013-N45",1,"第2节 纤维性修复","纤维化",2013,45,"A","","在伤口愈合时，对增加伤口愈合强度起主要作用的是",[["A","成纤维细胞"],["B","毛细血管"],["C","细胞外基质"],["D","良好的血供"]],"C","在伤口愈合的过程中，成纤维细胞的数量是逐渐减少的（A错）。但是成纤维细胞合成了大量细胞外基质（胶原蛋白、弹力蛋白等），能够显著增加伤口愈合的强度（C对）。伤口愈合时，毛细血管（B错）的主要作用是提供营养，良好的血供（D错）供有利于伤口的愈合，但与伤口愈合强度关系不大。","","N"],["2013-N46",3,"第2节 急性炎症","纤维蛋白性炎",2013,46,"A","","发生在下列不同部位的纤维蛋白性炎症中，属于假膜性炎症的是",[["A","心包膜"],["B","胸膜"],["C","关节滑膜"],["D","肠黏膜"]],"D","纤维蛋白性炎症（纤维素性炎）易发生于黏膜、浆膜和肺组织。黏膜（D对）发生的纤维素性炎称为假膜性炎，常见的假膜性炎有白喉、细菌性痢疾等。心包膜（A错）、胸膜（B错）可发生纤维素性炎，为浆膜性纤维素性炎，而不发生假膜性炎。关节滑膜可以发生浆液性炎和纤维素性炎，也不会发生假膜性炎（C错）。","","N"],["2013-N47",5,"第2节 肿瘤的形态和结构","肿瘤的异型性",2013,47,"A","","下列选项中，符合肿瘤间变概念的是",[["A","良恶性肿瘤之间的形态改变"],["B","肿瘤细胞的去分化"],["C","肿瘤发生过程中的一种癌前病变"],["D","肿瘤亲子代之间的遗传特性继承"]],"B","肿瘤的分化是指肿瘤组织（细胞）在形态和功能上与某种正常组织（细胞）的相似之处，相似的程度称为肿瘤的分化程度。异型性是肿瘤组织（细胞）出现成熟障碍和分化障碍的表现。肿瘤组织（细胞）的异型性越大，分化程度越低，与相应正常组织（细胞）的差异越大，异型性特别明显时，分化程度极低（去分化）（B对），称肿瘤间变。","","N"],["2013-N48",5,"第10节 肿瘤的分子基础","点突变",2013,48,"A","","下列原癌基因中，以点突变为主要激活方式成为癌基因的是",[["A","ras"],["B","PDGF"],["C","cyclin D1"],["D","myc"]],"A","ras基因（A对）的激活方式为点突变。PDGF（血小板源性生长因子）的原癌基因sis的激活方式为过度表达（十版病理学P112）（B错）。cyclin D1基因的激活方式为染色体相互易位（十版病理学P112）（与染色体转位同属于染色体易位）（C错）。myc基因的激活方式为染色体转位（十版病理学P111）（与染色体相互易位同属于染色体易位）和基因扩增（十版病理学P111）（D错）。","","N"],["2013-N49",5,"第3节 肿瘤的命名与分类","肿瘤的分类",2013,49,"A","","在恶性肿瘤的鉴别诊断中，免疫组织化学染色角蛋白阳性，波形蛋白阴性，该肿瘤为",[["A","癌"],["B","肉瘤"],["C","黑色素瘤"],["D","神经内分泌肿瘤"]],"A","免疫组织化学（十版病理学P366）是利用抗原-抗体的特异性结合反应来检测和定位组织或细胞中某种化学物质（抗原）的技术。免疫组织化学具有较高的敏感性和特异性，被广泛应用于恶性肿瘤的诊断与鉴别诊断中。角蛋白（Keratin）和波形蛋白均为肿瘤免疫组织化学标记物，常用于上皮组织肿瘤（癌）和间叶组织肿瘤（肉瘤等）的鉴别诊断工作。角蛋白阳性表达主要见于上皮组织及上皮组织肿瘤（癌）（A对）。波形蛋白阳性主要见于间叶组织和间叶组织肿瘤，肉瘤（十版病理学P106）（B错）、神经内分泌肿瘤（十版病理学P303）（D 错）均属于间叶组织肿瘤。恶性黑色素瘤（C错）属于神经外胚叶肿瘤。","","N"],["2013-N50",5,"第9节 癌前病变和原位癌","大肠腺瘤",2013,50,"A","","在下列癌前病变中，癌变几率最高的是",[["A","结节性肝硬化"],["B","黏膜白斑"],["C","结肠腺瘤性息肉病"],["D","未降睾丸"]],"C","癌前病变是指某些具有潜在癌变可能性的病变或疾病。结肠腺瘤性息肉病（属于家族性腺瘤性息肉病）几乎均会发生癌变（C对），而结节性肝硬化（A错）、黏膜白斑（B错）和未降睾丸（D错）的癌变几率相对较小。","","N"],["2013-N51",4,"第1节 自身免疫病","组织损伤机制",2013,51,"A","","引起系统性红斑狼疮的超敏反应类型是",[["A","Ⅰ型"],["B","Ⅱ型"],["C","Ⅲ型"],["D","Ⅳ型"]],"C","Ⅲ型超敏反应又称免疫复合物型变态反应，是由中等大小可溶性的抗原抗体复合物沉积到毛细血管壁或组织中，激活补体或进一步招引白细胞而造成的，属于Ⅲ型超敏反应的疾病有系统性红斑狼疮（SLE）（C对）、外源性哮喘、链球菌感染后的部分肾小球肾炎等。Ⅰ型超敏反应（A错）又称过敏性或速发型变态反应，反应迅速、消退也快为此型的特征，属于Ⅰ型超敏反应的疾病有青霉素过敏反应、药物引起的药疹、花粉或尘埃引起的过敏性鼻炎等。Ⅱ型超敏反应（B错）又称细胞溶解型或细胞毒型变态反应，由IgG或者IgM介导，细胞溶解破坏为此型的特征（SLE中的特异性抗红细胞、粒细胞、血小板自身抗体，可经Ⅱ型超敏反应导致相应血细胞的损伤和溶解，引起全血细胞减少，因此SLE中也存在Ⅱ型超敏反应，但不是主要的反应类型）（十版病理学P79），属于Ⅱ型超敏反应的疾病有血型不符的输血反应、新生儿溶血反应等。Ⅳ型超敏反应（D错）又称迟发性变态反应，由免疫细胞介导，属于Ⅳ型超敏反应的疾病有结核病、梅毒及器官移植后排斥反应等。","","N"],["2013-N52",10,"第2节 淋巴组织肿瘤","弥漫性大B细胞淋巴瘤细胞遗传学",2013,52,"A","","在临床上，约有40%的滤泡型淋巴瘤会转化为弥漫大B细胞型淋巴瘤，其最常见的分子机制是",[["A","p53基因突变"],["B","ras基因突变"],["C","bcr-abl融合基因形成"],["D","myc基因扩增"]],"A","滤泡型淋巴瘤转化为弥漫大B细胞型淋巴瘤的过程中，常伴有p53基因突变（A对）（六版病理学P233）。ras基因突变（B错）与肺癌、结肠癌、胰腺癌等发生有关（P112-113表6-7 癌基因举例）。bcr-abl融合基因形成（C错）与慢性粒细胞性白血病有关（十版病理学P245）。myc基因扩增（D错）与神经母细胞瘤、小细胞肺癌等发病有关（P112-113表6-7 癌基因举例）。","","N"],["2013-N53",11,"第1节 肾小球疾病","IgA肾病病理变化",2013,53,"A","","在下列选项中，符合IgA肾病镜下特征的病变是",[["A","肾小球内皮细胞增生"],["B","肾小球系膜区细胞增生"],["C","肾小球毛细血管袢纤维素样坏死"],["D","肾小球内中性粒细胞浸润"]],"B","IgA肾病的组织学改变各异，其中以肾小球系膜区细胞增生（B对）最为常见（并非特征性病变，题干表述不严谨）。由于IgA肾病可涉及肾小球肾炎几乎所有的病理类型（九版内科学P469），因此肾小球内皮细胞增生（A错）、肾小球毛细血管袢纤维素样坏死（C错）、肾小球内中性粒细胞浸润（D错）均可见于IgA肾病，但均相对少见。","","N"],["2013-N54",16,"第2节 结核病","溃疡型",2013,54,"A","","肠结核溃疡的形态特征取决于",[["A","肠黏膜的皱襞形态"],["B","肠黏膜淋巴小结的形态"],["C","肠黏膜淋巴管的走向"],["D","肠黏膜血管的走向"]],"C","肠结核溃疡呈环形，此形态特征与肠黏膜淋巴管的环肠管走向有关（C对）。肠黏膜淋巴小结形态（B错）决定肠伤寒溃疡的形态特征（十版病理学P350）。","","N"],["2013-N55",16,"第10节 寄生虫病","虫卵引起的损害概述",2013,55,"A","","在血吸虫病中，给病人造成最大危害的因素是",[["A","虫卵"],["B","童虫"],["C","成虫"],["D","尾蚴"]],"A","血吸虫病时，引起机体严重损害的是虫卵（A对），虫卵沉着于乙状结肠、直肠和肝等处，形成虫卵结节，造成损害。童虫（B错）可引起肺组织充血、水肿、点状出血及白细胞浸润，但病变一般轻微而短暂。成虫（C错）对机体的损害作用较轻。尾蚴（D错）主要引起尾蚴性皮炎，表现为入侵局部瘙痒的小丘疹，数日后自然消退。","","N"],["2013-N56",13,"第2节 甲状腺疾病","乳头状癌",2013,56,"A","","一例甲状腺肿瘤，呈浸润性生长。镜下见癌细胞呈滤泡状排列，细胞核呈毛玻璃状，核重叠，核沟明显。应诊断为",[["A","乳头状癌"],["B","滤泡状癌"],["C","髓样癌"],["D","未分化癌"]],"A","根据细胞核呈毛玻璃状的镜下特点，可将此病例诊断为乳头状癌（A对）。滤泡状癌和髓样癌镜下均可见癌细胞呈滤泡状排列，但癌细胞核不会呈毛玻璃状（BC错）。未分化癌（D错）镜下可见癌细胞大小、形态、染色深浅不一，核分裂象多。","","N"],["2013-N133",7,"第4节 风湿病","风湿性心肌炎",2013,133,"B","","对风湿病最有诊断意义的病变是",[["A","关节病变"],["B","心包内纤维蛋白性炎症"],["C","心肌内Aschoff小体"],["D","心内膜炎"]],"C","风湿病的增生期在变质渗出的基础上，在心肌间质、心内膜下和皮下结缔组织中形成特征性的肉芽肿病变，称为Aschoff小体或风湿小体（C对），为对风湿病最有诊断意义的病变。关节病变（A错）、心包内纤维蛋白性炎症（B错）和心内膜炎（D错）均可在风湿病时出现，但不具有特异性，不能作为风湿病的病理诊断依据。","","N"],["2013-N134",7,"第4节 风湿病","风湿性心内膜炎",2013,134,"B","","对风湿病人造成最严重危害的病变是",[["A","关节病变"],["B","心包内纤维蛋白性炎症"],["C","心肌内Aschoff小体"],["D","心内膜炎"]],"D","风湿病最常累及心脏、关节（A）和血管等处，以心脏病变最为严重，表现为风湿性心内膜炎（D）、风湿性心肌炎（C）和风湿性心外膜炎（B）。其中风湿性心内膜炎为风湿病最重要的病变（二版八年制病理学P201）（D对），主要累及心瓣膜，引起瓣膜炎，也可累及瓣膜邻近的心内膜和腱索，引起瓣膜变形和功能障碍。","","N"],["2013-N135",8,"第1节 呼吸道和肺炎症性疾病","支原体肺炎",2013,135,"B","","肺炎支原体肺炎的病理类型通常是",[["A","大叶性肺炎"],["B","小叶性肺炎"],["C","间质性肺炎"],["D","有肉芽肿形成的肺炎"]],"C","肺炎支原体肺炎是由肺炎支原体引起的一种间质性肺炎（C对），镜下表现为肺泡间隔明显增宽，其内血管扩张、充血，间质水肿及淋巴细胞、单核细胞浸润。大叶性肺炎（A错）是由肺炎球菌引起的肺泡内纤维素性炎（十版病理学P172）。小叶性肺炎（B错）是由葡萄球菌、肺炎球菌、流感嗜血杆菌等化脓菌引起的以细支气管为中心的化脓性炎症（十版病理学P174）。有肉芽肿形成的肺炎（D错）见于肺结节病（九版内科学P93）。","","N"],["2013-N136",8,"第1节 呼吸道和肺炎症性疾病","病毒性肺炎的病理变化",2013,136,"B","","病毒性肺炎的病理类型通常是",[["A","大叶性肺炎"],["B","小叶性肺炎"],["C","间质性肺炎"],["D","有肉芽肿形成的肺炎"]],"C","病毒性肺炎的主要病理类型是间质性肺炎（C对），镜下表现为间质水肿及淋巴细胞、单核细胞浸润。大叶性肺炎（A错）是由肺炎球菌引起的肺泡内纤维素性炎（十版病理学P172）。小叶性肺炎（B错）是由葡萄球菌、肺炎球菌、流感嗜血杆菌等化脓菌引起的以细支气管为中心的化脓性炎症（十版病理学P174）。有肉芽肿形成的肺炎（D错）见于肺结节病（九版内科学P93）。","","N"],["2013-N137",2,"第4节 栓塞","肺动脉栓塞",2013,137,"B","","下肢骨折7天，起床时突然死亡，尸体解剖时最可能的发现是",[["A","肺动脉血栓栓塞"],["B","肺动脉脂肪栓塞"],["C","肺动脉血栓形成"],["D","肺毛细血管血栓形成"]],"A","下肢骨折后长期卧床，血流变慢甚至停滞，易形成下肢深静脉血栓，患者起床时肌肉挤压可致血栓脱落，血栓依次经下肢深静脉、下腔静脉、右心房、右心室，最终进入肺动脉，引起肺动脉血栓栓塞（A对），造成患者突然死亡。下肢骨折可导致骨髓内脂肪细胞破裂并释出脂滴，脂滴循血栓相同路径进入肺动脉，引起肺动脉脂肪栓塞。但脂肪栓塞一般在损伤后1～3天内出现（十版病理学P51），且不受卧床或起床状态影响（B错）。肺动脉血流较快，不易形成肺动脉血栓，且肺动脉血栓（C错）或肺毛细血管血栓形成（D错）与骨折本身并无直接关联。","","N"],["2013-N138",2,"第3节 血栓形成","透明血栓",2013,138,"B","","中毒性休克病人死亡，尸体解剖时最可能的发现是",[["A","肺动脉血栓栓塞"],["B","肺动脉脂肪栓塞"],["C","肺动脉血栓形成"],["D","肺毛细血管血栓形成"]],"D","中毒性休克晚期常发生弥散性血管内凝血（DIC），引起毛细血管内广泛纤维素性血栓（透明血栓）形成。故中毒性休克病人死亡，尸体解剖时最可能的发现是肺毛细血管血栓形成（D对）。","","N"],["2013-N163",3,"第2节 急性炎症","急性炎症过程中的血管反应",2013,163,"X","","下列形态改变中，属于炎症的主要病理变化有",[["A","血管反应"],["B","肉芽组织形成"],["C","炎细胞浸润"],["D","上皮细胞增生"]],"AC","血管反应（A对）和炎细胞浸润（C对）是急性炎症的主要病理变化。肉芽组织（十版病理学P33）为组织损伤的修复方式，与炎症反应无关（与炎症反应相关的是肉芽肿）（B错）。上皮细胞增生（注意与损伤修复过程中上皮细胞再生区别）可见于炎症的增生期，如鼻黏膜慢性炎症时被覆上皮增生，故D选项也属于炎症的病理变化，但原参考答案为AC，可能与上皮细胞增多只见于部分炎症类型有关（不能算作炎症的主要病理变化）。","","N"],["2013-N164",13,"第6节 神经内分泌肿瘤","类癌",2013,164,"X","","下列符合类癌特点的有",[["A","起源于上皮细胞"],["B","小于2厘米者很少转移"],["C","细胞形态较一致"],["D","可发生淋巴转移"]],"BCD","类癌是一组起源于APUD细胞（神经内分泌细胞）（A错）的恶性肿瘤。类癌具有恶变倾向，可发生淋巴转移（D对），但直径小于2cm的类癌生长缓慢，转移率极低（B对）。类癌细胞在显微镜下呈圆形或多角形，细胞形态较一致（C对）。需要注意的是，在新版WHO分类中，关于肠道“DNES”肿瘤（APUD瘤）的分类建议不再使用“类癌”。","","N"],["2013-N165",4,"第2节 免疫缺陷病","恶性肿瘤",2013,165,"X","","下列关于艾滋病的描述，正确的有",[["A","艾滋病病毒是RNA病毒"],["B","艾滋病病毒的入侵门户是CD8分子"],["C","早期病变时淋巴滤泡发生萎缩"],["D","继发性恶性肿瘤中最常见的为卡波西肉瘤"]],"AD","艾滋病病毒（人类免疫缺陷病毒，HIV）是单链RNA病毒（A对）。艾滋病病毒的入侵门户是CD4分子（B错）：HIV感染人体时，将与CD4受体和共受体结合而进入CD4⁺T细胞内，造成CD4⁺T细胞大量破坏、功能受损，导致细胞免疫缺陷。HIV感染人体后，早期淋巴结肿大，淋巴滤泡明显增生（C错），晚期淋巴细胞几乎消失殆尽，淋巴结呈现一片荒芜。艾滋病患者因免疫功能低下，极易患继发性恶性肿瘤，其中最常见的为卡波西（Kaposi）肉瘤（D对）。","","N"],["2013-N166",9,"第3节 消化性溃疡病","消化性溃疡病的病理变化",2013,166,"X","","胃溃疡的镜下病理特征有",[["A","纤维蛋白和中性粒细胞渗出"],["B","肉芽肿形成"],["C","纤维瘢痕形成"],["D","闭塞性动脉内膜炎"]],"ACD","消化性溃疡是以胃或十二指肠黏膜形成慢性溃疡的一种疾病，镜下，溃疡底部由内向外分四层：最内层为纤维蛋白（纤维素）和中性粒细胞等炎性渗出（A对），其下为坏死组织，坏死组织下为肉芽组织（而非肉芽肿）（B错），最下层由肉芽组织移行为陈旧瘢痕组织（C对）。瘢痕底部小动脉因炎症刺激常有增殖性动脉内膜炎，使小动脉管壁增厚，管腔狭窄或有血栓形成，可出现闭塞性动脉内膜炎（D对）。","","N"],["2013-N167",9,"第6节 病毒性肝炎","丙型肝炎病毒（HCV）",2013,167,"X","","丙型肝炎除了一般病毒性肝炎的病理特点外，其相对特异的镜下特点还有",[["A","碎屑样坏死"],["B","凋亡小体"],["C","汇管区淋巴滤泡形成"],["D","肝细胞脂肪变性明显"]],"CD","镜下，丙型肝炎除了有肝炎的典型变化外，还有一些独特的变化，包括肝细胞脂肪变性（D对）、汇管区淋巴滤泡形成（C对）、胆管损伤等。碎屑样坏死（A错）、凋亡小体（B错）为一般病毒性肝炎的病理特点。","","N"],["2013-N168",12,"第7节 乳腺疾病","特殊类型浸润性癌",2013,168,"X","","下列属于乳腺髓样癌形态特点的有",[["A","边界清楚"],["B","癌细胞体积大"],["C","有较多的淋巴细胞浸润"],["D","HER2/neu过表达"]],"ABC","乳腺髓样癌的肉眼观为肿瘤灰白质软，边界清楚（A对）；镜下特点为癌细胞体积大（B对），间质较少，有较多的淋巴细胞浸润（C对）等。HER2/neu过表达提示预后不佳，可见于各种类型的乳腺癌，不具有特异性（D错）。","","N"],["2014-N42",0,"第1节 适应","化生的类型",2014,42,"A","","下列选项中，不属于化生的是",[["A","舌根部出现甲状腺组织"],["B","气管内出现鳞状上皮"],["C","胃黏膜中出现肠上皮"],["D","子宫内膜出现鳞状上皮"]],"A","化生是一种分化成熟的细胞类型被另一种分化成熟的细胞类型所取代。气管的假复层纤毛柱状上皮被鳞状上皮所取代（B错）、胃黏膜单层柱状上皮被肠上皮所取代（C错）、及子宫内膜腺上皮被鳞状上皮所取代（D错），均为化生。而舌根部出现甲状腺组织属于组织异位（迷离瘤），是胚胎发育过程中甲状腺组织异位于舌根部所致，不属于化生（A对）。","","N"],["2014-N43",3,"第2节 急性炎症","花生四烯酸代谢产物",2014,43,"A","","下列炎性介质中，引起发热的是",[["A","前列腺素"],["B","缓激肽"],["C","IL-8"],["D","NO"]],"A","根据十版病理学P71表4-3，可知引起发热的炎性介质包括IL-1、TNF和前列腺素（PG）（A对）。缓激肽（B错）为血管活性肽（十版病理学P71），可使细动脉扩张、血管通透性增加、支气管平滑肌收缩，并可引起疼痛。IL-8（C错）为趋化因子（十版病理学P66），可吸引白细胞进行定向移动。NO（D错）为活性氮（十版病理学P76），可杀伤病原微生物，是宿主抗感染的炎症介质。","","N"],["2014-N44",9,"第6节 病毒性肝炎","嗜酸性变",2014,44,"A","","下列肝细胞坏死中，属于凋亡的是",[["A","碎片状坏死"],["B","点状坏死"],["C","桥接坏死"],["D","嗜酸性坏死"]],"D","嗜酸性坏死名为坏死，实为凋亡（D对），由嗜酸性样变发展而来，胞质进一步浓缩，核也浓缩消失，最终形成深红色浓染的圆形小体，称为嗜酸性小体（凋亡小体）。碎片状坏死（A错）、点状坏死（B错）、桥接坏死（C错）都为病毒性肝炎时的坏死类型。","","N"],["2014-N45",2,"第4节 栓塞","脂肪栓塞",2014,45,"A","","女性，73岁。下楼梯时，不慎摔倒，股骨骨折，行手术内固定术时，突然呼吸困难，发绀，血压下降，全身抽搐，昏迷，抢救无效死亡，尸体解剖，肺血管内最可能的发现是",[["A","脂滴"],["B","空气"],["C","角化上皮"],["D","血栓"]],"A","患者因股骨骨折导致突发呼吸困难、血压下降和昏迷，符合脂肪栓塞的特点，故尸体解剖，肺血管内最可能的发现是脂滴（A对）。空气见于空气栓塞（B错）。角化上皮见于羊水栓塞（C错）。血栓见于血栓栓塞（D错）。","","N"],["2014-N46",5,"第12节 肿瘤与遗传","遗传性肿瘤综合征举例",2014,46,"A","","下列选项中，不属于遗传性肿瘤的是",[["A","纤维瘤病"],["B","神经纤维瘤病"],["C","结肠腺瘤性息肉病"],["D","Li-Fraumeni综合征"]],"A","神经纤维瘤病（B错）和结肠腺瘤性息肉病（C错）均属于常染色体显性遗传的遗传性肿瘤。Li-Fraumeni综合征（D错）为常染色体隐性遗传的遗传性肿瘤。纤维瘤病的病因不明，可能与遗传性因素有关，但不属于遗传性疾病（A对）。","","N"],["2014-N47",12,"第7节 乳腺疾病","浸润性小叶癌",2014,47,"A","","女性，58岁。左乳腺外上象限肿物，直径约2cm，组织学检查，肿瘤细胞小，在纤维组织中排列成单排细胞，浸润周围脂肪组织，应诊断为",[["A","浸润性小叶癌"],["B","浸润性导管癌"],["C","导管内癌"],["D","小叶原位癌"]],"A","乳腺肿瘤细胞在纤维组织中排列成单排细胞，浸润周围脂肪组织，是浸润性小叶癌（A对）的组织学特点。浸润性导管癌（B错）的组织学特点是癌细胞排列成巢状、团索状，或伴有少量腺样结构。导管内癌（导管内原位癌）（C错）和小叶原位癌（D错）均属于非浸润性癌，癌细胞局限于基底膜内，不会浸润周围的脂肪组织。","","N"],["2014-N48",7,"第7节 心肌病","扩张型心肌病的病理变化",2014,48,"A","","扩张性心肌病肉眼检查不包括的主要病理变化是",[["A","心脏重量增加达500～800g"],["B","两侧心腔扩张"],["C","二尖瓣、三尖瓣关闭不全"],["D","心内膜增厚"]],"D","扩张型心肌病主要表现为心脏扩大，并伴有一定程度的心肌肥厚。肉眼观，心脏重量增加，可达500～800g（A对）或更重，两侧心腔明显扩张（B对），心室壁略厚或正常（离心性肥大，此为病理学观点，内科学认为扩张性心肌病室壁变薄），心尖部室壁常呈钝圆形。二尖瓣和三尖瓣可因心室扩张所致关闭不全（C对）。心内膜增厚（D对），常见附壁血栓。本题给出的参考答案为D，但按照七、八、九、十版病理学的说法，本题无正确答案。","","N"],["2014-N49",4,"第1节 自身免疫病","肾",2014,49,"A","","对红斑狼疮性肾炎最具有诊断意义的病变是",[["A","免疫复合物沉积"],["B","苏木素小体"],["C","基底膜增厚"],["D","系膜增生"]],"B","红斑狼疮性肾炎是指系统性红斑狼疮（SLE）累及肾脏时，产生的肾脏免疫性损害，苏木素小体（狼疮小体）（B对）的出现对其最具有诊断意义。原发性肾小球肾炎的各种组织学类型在狼疮性肾炎时均可出现，故免疫复合物沉积（A 错）、基底膜增厚（C 错）和系膜增生（D错）均可见于红斑狼疮性肾炎，但缺乏特异性，不具有诊断意义。","","N"],["2014-N50",7,"第1节 动脉粥样硬化","动脉平滑肌细胞的作用",2014,50,"A","","与动脉粥样斑块表面的纤维帽形成关系密切的细胞是",[["A","平滑肌细胞"],["B","内皮细胞"],["C","成纤维细胞"],["D","单核细胞"]],"A","动脉粥样硬化的基本病理变化包括脂纹、纤维斑块、粥样斑块和继发性改变。纤维帽位于纤维斑块之上，由大量的平滑肌细胞（SMC）（A对）及其分泌的细胞外基质（胶原纤维和蛋白聚糖）组成。","","N"],["2014-N51",8,"第7节 呼吸窘迫综合征","成人呼吸窘迫综合征的病理变化",2014,51,"A","","弥漫性肺泡损伤的早期病理改变是",[["A","脱屑性肺泡炎"],["B","肺纤维化"],["C","肺充血和透明膜形成"],["D","肺大片出血"]],"C","弥漫性肺泡损伤见于成人呼吸窘迫综合征（ARDS），主要表现为肺毛细血管和肺泡上皮细胞损伤，使管壁通透性增高，导致肺泡内和肺间质水肿、纤维素大量渗出，镜下可见肺间质毛细血管扩张、充血。肺泡上皮（特别是Ⅱ型上皮）损伤后，肺泡表面活性物质减少，导致肺透明膜的形成和肺萎陷（C对）。脱屑性肺泡炎（A错）为受损的肺泡上皮细胞脱落到肺泡腔内引起的肺炎，可见于严重急性呼吸综合征（SARS）（十版病理学P176）和肺石棉沉着病（十版病理学P183）。肺纤维化（B错）是多种肺疾病的最后的结局，而不是早期病理改变。肺大片出血（D错）因肺动脉破裂引起，常见于肺挫伤，而ARDS多为散在出血点。","","N"],["2014-N52",8,"第6节 慢性肺源性心脏病","心脏病变",2014,52,"A","","慢性肺源性心脏病心脏变化的主要指标是",[["A","肺动脉瓣下2cm处右心室壁厚超过0.5cm"],["B","左心室肥厚"],["C","心脏重量增加可达850g"],["D","三尖瓣关闭不全"]],"A","慢性肺源性心脏病，简称肺心病，是因慢性肺疾病、肺血管及胸廓的病变引起肺循环阻力增加，肺动脉压升高而导致以右心室壁肥厚（B错）、心腔扩大甚或发生右心衰竭的心脏病。通常以肺动脉瓣下2cm处右心室前壁肌层厚度超过5mm（正常位3～4mm）作为诊断肺心病的病理形态学标准（A对）。心脏重量增加（C错）可见于各种原因所致的心室肥厚，并无特异性。三尖瓣关闭不全（D错）可见于风湿性二尖瓣病、先天性心脏病等，亦无特异性。","","N"],["2014-N53",10,"第2节 淋巴组织肿瘤","伯基特淋巴瘤概述",2014,53,"A","","下列选项中，符合Burkitt淋巴瘤的叙述是",[["A","老年患者多见"],["B","国内多见"],["C","与EB病毒感染有关"],["D","T细胞淋巴瘤"]],"C","Burkitt淋巴瘤为B细胞起源（D错）的非霍奇金淋巴瘤（NHL），常见于非洲赤道附近地区的儿童和青少年（A错），国内少见（B错）。Burkitt淋巴瘤（尤其是非洲地方性Burkitt淋巴瘤）与EB病毒感染（C对）密切相关，所有患者的绝大多数肿瘤细胞内含有EB病毒基因。","","N"],["2014-N54",4,"第3节 器官和骨髓移植排斥反应","病理变化",2014,54,"A","","符合超急性排斥反应的病理变化是",[["A","血管内膜增厚"],["B","大量淋巴细胞浸润"],["C","血管周围洋葱皮样改变"],["D","急性小动脉炎"]],"D","超急性排斥反应一般于移植后数分钟至数小时出现，其病理变化有广泛分布的急性小动脉炎（D对）、血栓形成和组织缺血性坏死。急性排斥反应分为细胞型排斥反应和血管型排斥反应，血管内膜增厚（A错）是血管型排斥反应的表现。大量淋巴细胞浸润（B错）为急性细胞型排斥反应的病理变化（十版病理学P89）。血管周围洋葱皮样改变（C错）为系统性红斑狼疮（SLE）累及脾动脉时的病理特点（十版病理学P80）。","","N"],["2014-N55",9,"第6节 病毒性肝炎","桥接坏死",2014,55,"A","","下列肝细胞病变中，与肝硬化形成最相关的是",[["A","大块坏死"],["B","桥接坏死"],["C","灶状坏死"],["D","碎片样坏死"]],"B","肝硬化主要包括门脉性肝硬化（十版病理学P209）、坏死后性肝硬化（十版病理学P209）和胆汁性肝硬化（十版病理学P209）三种类型，其中以门脉性肝硬化最为多见。门脉性肝硬化多由慢性普通型肝炎晚期转变而来，慢性普通型肝炎根据病变的严重程度不同可见灶状坏死（轻度）、碎片样坏死（中、重度）和桥接坏死（中、重度），其中桥接坏死（B对）可导致肝小叶重建，为肝硬化形成的主要机制。大块坏死（A错）为急性重型肝炎所致坏死后性肝硬化的主要机制，但坏死后性肝硬化相对少见。","","N"],["2014-N56",12,"第7节 乳腺疾病","导管原位癌",2014,56,"A","","下列乳腺癌的病理学类型中，属于原位癌的是",[["A","髓样癌"],["B","黏液癌"],["C","小管癌"],["D","粉刺癌"]],"D","乳腺癌按照组织形态可分为非浸润性癌和浸润性癌两类，非浸润性癌即原位癌，又可分为导管内原位癌和小叶原位癌两种，其中导管内原位癌包括粉刺癌（D对）、非粉刺型导管内癌和乳头Paget病伴导管原位癌。髓样癌（A错）、黏液癌（B错）和小管癌（C错）均属于浸润性癌。","","N"],["2014-N133",9,"第2节 胃炎","慢性萎缩性胃炎",2014,133,"B","","慢性萎缩性胃炎的主要病变",[["A","胃小凹上皮增生"],["B","胃黏膜内出现胰腺组织"],["C","胃黏膜浅层糜烂出血"],["D","胃黏膜腺体变小、减少"]],"D","慢性胃炎分慢性浅表性胃炎、慢性萎缩性胃炎、慢性肥厚性胃炎和疣状胃炎四类。慢性萎缩性胃炎以胃黏膜萎缩变薄，黏膜腺体减少或消失（D对）并伴有肠上皮化生，固有层内多量淋巴细胞、浆细胞浸润为特点。胃小凹上皮增生（A错）和胃黏膜浅层糜烂出血（C错）均见于慢性浅表性胃炎。胃黏膜内出现胰腺组织可能是迷离瘤，与慢性萎缩性胃炎无关（B错）。","","N"],["2014-N134",5,"","",2014,134,"B","","迷离瘤的病变是",[["A","胃小凹上皮增生"],["B","胃黏膜内出现胰腺组织"],["C","胃黏膜浅层糜烂出血"],["D","胃黏膜腺体变小、减少"]],"B","迷离瘤又称迷芽瘤，是指分化正常的组织误位于异常部位而形成的包块，胃黏膜出现胰腺组织即为迷离瘤（B对）。","","N"],["2014-N135",3,"第1节 炎症概述","变质",2014,135,"B","","属于变质性炎的是",[["A","白喉"],["B","淋巴结结核"],["C","急性蜂窝织性阑尾炎"],["D","乙型肝炎"]],"D","根据炎症的基本病变性质进行分类，可分为变质性炎、渗出性炎和增生性炎。任何炎症都在一定程度上包含变质、渗出、增生这三种基本病变，但往往以一种病变为主，以变质为主时称为变质性炎；以渗出为主时称为渗出性炎；以增生为主时称为增生性炎。渗出性炎还可以根据渗出物的主要成分和病变特点，进一步分为浆液性炎、纤维素性炎、化脓性炎、出血性炎等。白喉属于纤维蛋白性炎（十版病理学P72）（A错）。淋巴结结核属于增生性炎（B错）。急性蜂窝织性阑尾炎属于化脓性炎（C错）。乙型肝炎属于变质性炎（D对）。","","N"],["2014-N136",3,"第2节 急性炎症","纤维蛋白性炎",2014,136,"B","","属于假膜性炎的是",[["A","白喉"],["B","淋巴结结核"],["C","急性蜂窝织性阑尾炎"],["D","乙型肝炎"]],"A","根据炎症的基本病变性质进行分类，可分为变质性炎、渗出性炎和增生性炎。任何炎症都在一定程度上包含变质、渗出、增生这三种基本病变，但往往以一种病变为主，以变质为主时称为变质性炎；以渗出为主时称为渗出性炎；以增生为主时称为增生性炎。渗出性炎还可以根据渗出物的主要成分和病变特点，进一步分为浆液性炎、纤维素性炎、化脓性炎、出血性炎等。白喉为发生于黏膜的纤维素性炎，可在黏膜表面形成一层灰白色膜状物，称为“假膜”，故称为假膜性炎（A对）。淋巴结结核属于增生性炎（B错）。急性蜂窝织性阑尾炎属于化脓性炎（C错）。乙型肝炎属于变质性炎（D错）。","","N"],["2014-N137",16,"第8节 性传播性疾病","一期梅毒",2014,137,"B","","属于Ⅰ期梅毒的病变是",[["A","硬性下疳"],["B","树胶样肿"],["C","梅毒疹"],["D","脊髓痨"]],"A","后天性梅毒可分为Ⅰ、Ⅱ、Ⅲ期，其中Ⅰ期梅毒可见硬性下疳（A对）。树胶样肿（B错）和脊髓痨（D错）均属于Ⅲ期梅毒的病变。梅毒疹（C错）属于Ⅱ期梅毒的病变。","","N"],["2014-N138",16,"第8节 性传播性疾病","二期梅毒",2014,138,"B","","属于Ⅱ期梅毒的病变是",[["A","硬性下疳"],["B","树胶样肿"],["C","梅毒疹"],["D","脊髓痨"]],"C","后天性梅毒可分为Ⅰ、Ⅱ、Ⅲ期，其中Ⅱ期梅毒可见梅毒疹（C对）。硬性下疳（A错）属于Ⅰ期梅毒的病变。树胶样肿（B错）和脊髓痨（D错）属于Ⅲ期梅毒的病变。","","N"],["2014-N163",3,"第2节 急性炎症","炎症介质在炎症过程中的作用",2014,163,"X","","炎性介质的作用包括",[["A","发热"],["B","趋化作用"],["C","血管通透性降低"],["D","疼痛"]],"ABD","参与和介导炎症反应的化学因子称为炎性介质。炎性介质的功能包括：血管扩张、血管通透性升高（C错）、趋化作用（B对）、白细胞渗出和激活、发热（A对）、疼痛（D对）、组织损伤等。","","N"],["2014-N164",12,"第4节 卵巢肿瘤","畸胎瘤",2014,164,"X","","良性畸胎瘤内可以出现的组织有",[["A","脑组织"],["B","皮肤及其附属器"],["C","甲状腺组织"],["D","软骨组织"]],"ABCD","畸胎瘤是来源于生殖细胞的肿瘤，具有向人体各成熟组织细胞分化的潜能和表现。良性畸胎瘤（成熟畸胎瘤）镜下可见各种成熟组织，如脑组织（A对）、皮肤及其附属器（B对）、甲状腺组织（C对）和软骨组织（D对）等。","","N"],["2014-N165",9,"第12节 消化系统常见肿瘤","中晚期癌",2014,165,"X","","中晚期食管癌的肉眼类型有",[["A","胶样型"],["B","髓质型"],["C","溃疡型"],["D","隆起型"]],"BCD","中晚期食管癌根据肉眼形态可分为四型：髓质型（B对）、蕈伞型（隆起型、息肉型）（D对）、溃疡型（C对）和缩窄型。胶样型（九版病理学P233）（A错）为大肠癌的肉眼类型。","","N"],["2014-N166",16,"第2节 结核病","继发性肺结核病概述",2014,166,"X","","继发性肺结核的病理特点",[["A","常循血道播散"],["B","常循淋巴道播散"],["C","常循气道播散"],["D","病灶多从肺尖开始"]],"CD","继发性肺结核常循气道播散（C对），最先发病于肺尖部（D对）。常循血道（A错）和淋巴道（B错）播散是原发性肺结核的病理特点。","","N"],["2014-N167",5,"第9节 癌前病变和原位癌","癌前病变",2014,167,"X","","胃黏膜病变中，属于癌前病变的有",[["A","非典型增生"],["B","炎症性息肉"],["C","腺瘤性息肉"],["D","幼年性息肉"]],"AC","癌前病变（十版病理学P108）是指本身不是恶性肿瘤，但具有发展为恶性肿瘤潜能的疾病或病变。非典型增生（A对）即异型增生，为上皮性癌前病变的形态学改变。腺瘤性息肉（C对）又称息肉状腺瘤，发生于黏膜，呈息肉状，可发生癌变。炎症性息肉（十版病理学P74）（B错）由慢性炎症引起，恶变率极低，不属于癌前病变。幼年性息肉（D错）为多发于幼儿、病因未明的良性息肉，恶变率极低，不属于癌前病变（但幼年性息肉病为癌前病变）。","","N"],["2014-N168",11,"第1节 肾小球疾病","急进性肾小球肾炎病理变化",2014,168,"X","","新月体性肾小球肾炎类型有",[["A","免疫复合物型"],["B","免疫反应缺乏型"],["C","致密沉积物型"],["D","抗肾小球基膜抗体型"]],"ABD","新月体性肾小球肾炎（急进性肾小球肾炎）可分为三个类型：抗肾小球基底膜抗体型（Ⅰ型）（D对）、免疫复合物型（Ⅱ型）（A对）、免疫反应缺乏型（Ⅲ型）（B对）。致密沉积物型（十版病理学P258）（C错）是膜增生性肾小球肾炎的类型（Ⅱ型）。","","N"],["2015-N41",1,"第1节 再生","不稳定细胞",2015,41,"A","","男性，25岁。患急性糜烂性胃炎，经治疗痊愈后，原胃体黏膜糜烂处表现为",[["A","正常胃黏膜"],["B","幽门腺化生"],["C","肠上皮化生"],["D","表面腺体增厚"]],"A","胃黏膜上皮细胞为不稳定细胞，再生能力极强。急性糜烂性胃炎时，胃黏膜上皮细胞可通过不断分裂增殖替代损伤性细胞，经治疗痊愈后，黏膜糜烂处可恢复正常胃黏膜结构（A对）。幽门腺化生（B错）和肠上皮化生（C错）见于慢性萎缩性胃炎（十版病理学P196），表面腺体增厚（D错）见于慢性肥厚性胃炎（十版病理学P197）。","","N"],["2015-N42",9,"第6节 病毒性肝炎","病毒性肝炎的发病机制",2015,42,"A","","不会引起慢性肝炎的肝炎病毒是",[["A","HAV"],["B","HBV"],["C","HCV"],["D","HDV"]],"A","甲型肝炎病毒引起的甲肝均表现为急性肝炎，不会引起慢性肝炎（A对）。HBV引起的乙型肝炎约5%～10%转变为慢性肝炎（B错）。HCV引起的丙型肝炎约3/4可演变成慢性肝炎（C错）。HDV为复制缺陷型RNA病毒，它必须依赖同HBV复合感染才能复制，若在HBV携带者中再感染HDV，约80%可转变成慢性HBV/HDV复合性慢性肝炎（D错）。","","N"],["2015-N43",3,"第2节 急性炎症","内皮细胞损伤",2015,43,"A","","严重烧伤时，导致血管通透性增加的主要机制是",[["A","内皮细胞穿胞作用增加"],["B","内皮细胞直接损伤"],["C","白细胞介导的内皮细胞损伤"],["D","新生毛细血管的高通透性"]],"B","血管通透性增加的机制有内皮细胞收缩、内皮细胞损伤、内皮细胞穿胞作用增强和新生毛细血管高通透性等。烧伤作为一种严重的损伤性刺激，可以通过内皮细胞收缩、直接损伤内皮细胞和白细胞介导的内皮细胞损伤等机制，引起血管通透性增加，体液外渗，但最主要的作用机制为直接引起内皮细胞的损伤（B对）。内皮细胞穿胞作用增强（A错）和新生毛细血管的高通透性（D错）均为血管通透性增高的机制，但不是烧伤时血管通透性增加的主要机制。烧伤时可以通过白细胞介导的内皮细胞损伤导致血管通透性增强，但并不是其主要机制（C错）。","","N"],["2015-N44",0,"第4节 细胞不可逆性损伤（细胞死亡）","坏疽",2015,44,"A","","下列可以发生坏疽的病变是",[["A","肝大片状坏死"],["B","脾梗死"],["C","脑梗死"],["D","肠套叠"]],"D","湿性坏疽多发生于与外界相通的内脏，如肺、肠、子宫、阑尾及胆囊等，因此，肠套叠可发生湿性坏疽（D对）。肝大片状坏死为液化性坏死（溶解性坏死）（十版病理学P204）（A错）。脑梗死也为液化性坏死（C错）。脾梗死为凝固性坏死（B错）。","","N"],["2015-N45",2,"第4节 栓塞","空气栓塞",2015,45,"A","","使用正压静脉输液时，可能发生的栓塞是",[["A","脂肪栓塞"],["B","空气栓塞"],["C","肿瘤栓塞"],["D","血栓栓塞"]],"B","栓塞为循环血液中出现的不溶于血液的异常物质，随血流运行阻塞血管腔的现象。阻塞血管的异常物质称为栓子。根据栓子的不同，栓塞分为血栓栓塞、脂肪栓塞、气体栓塞、羊水栓塞和其他栓塞。使用正压静脉输液时，空气可因吸气时静脉腔内负压而被吸引入血循环，形成气泡阻塞血管，造成空气栓塞（B对）。脂肪栓塞的栓子为脂肪滴，常来源于长骨骨折、脂肪组织严重挫伤和烧伤等（A错）。肿瘤栓塞常见于晚期肿瘤，肿瘤细胞脱落阻塞血管所致（C错）。血栓栓塞为血栓栓子脱落所致（D错）。","","N"],["2015-N46",12,"第7节 乳腺疾病","导管原位癌",2015,46,"A","","下列属于原位癌的病变是",[["A","胃黏膜内癌"],["B","食管黏膜下癌"],["C","乳腺导管内癌"],["D","大肠黏膜下癌"]],"C","原位癌（十版病理学P109）是指累及上皮全层但未突破基底膜向下浸润的癌。乳腺导管内癌（C对）癌细胞局限于扩张的导管内，未突破基底膜，属于原位癌，因此又称乳腺导管内原位癌。胃黏膜内癌（A错）、大肠黏膜下癌（D错）、食管黏膜下癌（B错）均属于消化道早期癌。注：早期癌是指癌症的早期阶段，对于消化道肿瘤而言，早期癌包括原位癌、黏膜内癌和黏膜下癌。","","N"],["2015-N47",9,"第12节 消化系统常见肿瘤","胃癌的种植性转移",2015,47,"A","","双侧卵巢肿大，活检发现癌细胞，首先考虑癌细胞来源于",[["A","子宫"],["B","肠"],["C","胃"],["D","卵巢"]],"C","双侧卵巢肿大，活检发现癌细胞，首先应考虑卵巢的转移性肿瘤，而卵巢转移性肿瘤中最常见的转移来源是胃（C对），由胃部种植转移至卵巢而形成的转移性黏液癌，称为克鲁根勃（Krukenberg）瘤。原发于卵巢本身的肿瘤多为单侧（D错）。","","N"],["2015-N48",7,"第4节 风湿病","增生期或肉芽肿期",2015,48,"A","","风湿小结内的阿绍夫细胞来源于",[["A","T淋巴细胞"],["B","B淋巴细胞"],["C","巨噬细胞"],["D","成纤维细胞"]],"C","风湿小结内的阿少夫细胞（阿绍夫细胞）由增生的巨噬细胞（C对）吞噬纤维素样坏死物质转变而来。T淋巴细胞（A错）和B淋巴细胞（少见，大多数成熟为浆细胞）（B错）均为风湿小结内的慢性炎症细胞。成纤维细胞来源于阿绍夫细胞（而不是阿绍夫细胞来源于成纤维细胞）（D错）：在风湿病纤维化期，阿绍夫细胞转变为成纤维细胞，使风湿小体逐渐纤维化，最后形成梭形小瘢痕。","","N"],["2015-N49",4,"第1节 自身免疫病","病理变化",2015,49,"A","","类风湿关节炎滑膜内浸润的特征性细胞是",[["A","嗜酸性粒细胞"],["B","巨噬细胞"],["C","浆细胞和淋巴细胞"],["D","中性粒细胞"]],"C","类风湿关节炎是以慢性增生性滑膜炎为表现的自身免疫病，其滑膜内浸润的主要是淋巴细胞（大部分为活化的CD4⁺TH细胞），其次为浆细胞（九版内科学 P807）（C对）。CD4⁺TH细胞可分泌多种细胞因子和生长因子，激活其他免疫细胞和巨噬细胞（B）分泌炎症介质、组织降解因子，综上可见，CD4⁺TH细胞在类风湿关节炎的滑膜病变中起主要作用，因此本题的最佳答案是C，而不是B。嗜酸性粒细胞（A错）常见于寄生虫病、某些过敏性疾病等。中性粒细胞（D错）常见于急性炎症（十版病理学P63）。","","N"],["2015-N50",7,"第1节 动脉粥样硬化","脂纹",2015,50,"A","","早期动脉粥样硬化病变的主要细胞是",[["A","平滑肌细胞"],["B","泡沫细胞"],["C","成纤维细胞"],["D","内皮细胞"]],"B","动脉粥样硬化的基本病理变化包括脂纹、纤维斑块、粥样斑块和继发性改变。脂纹是AS肉眼可见的最早病变，光镜下，病灶处的内膜下有大量泡沫细胞（B对）聚集，为脂纹的主要组成细胞。内皮细胞（D错）损伤是发生动脉粥样硬化的前提条件，平滑肌细胞（A错）是泡沫细胞的来源之一，成纤维细胞（C错）能促进动脉粥样硬化的发生，三者均与病变有关，但均不是病变的主要细胞。","","N"],["2015-N51",8,"第8节 呼吸系统常见肿瘤","腺癌",2015,51,"A","","在下列肿瘤类型中，细支气管肺泡癌属于",[["A","小细胞癌"],["B","鳞状细胞癌"],["C","腺癌"],["D","大细胞癌"]],"C","肺癌的组织学表现复杂多样，将其分为鳞状细胞癌、腺癌、腺鳞癌、小细胞癌、大细胞癌、肉瘤样癌、类癌和唾液腺癌8个基本类型。细支气管肺泡癌为发生于细支气管、肺泡的高分化腺癌（C对），为腺癌的一种特殊类型。小细胞癌（十版病理学P191）是肺癌中恶性程度最高的一型，多为中央型，常发生于大支气管（A错）。鳞状细胞癌是肺癌中最常见的类型，80%～85%为中央型肺癌，多发生于段以上大支气管（B错）。大细胞癌（九版病理学P204）半数发生于大支气管（D错）。","","N"],["2015-N52",8,"第2节 慢性阻塞性肺疾病","腺泡周围型肺气肿",2015,52,"A","","腺泡周围型肺气肿的病理表现是",[["A","呼吸性细支气管不扩张，其周围的肺泡扩张"],["B","呼吸性细支气管扩张，周围肺泡扩张不明显"],["C","肺泡间隔内出现成串小气泡"],["D","呼吸性细支气管、肺泡管和肺泡囊均扩张"]],"A","肺泡性肺气肿病变发生在肺腺泡内，根据发生的部位和范围可分为：腺泡中央型肺气肿、腺泡周围型肺气肿和全肺泡型肺气肿。腺泡周围型肺气肿的病理表现是呼吸性细支气管不扩张，其周围的肺泡管、肺泡囊和肺泡扩张（A对）。呼吸性细支气管扩张，周围肺泡扩张不明显（B错）见于腺泡中央型肺气肿。呼吸性细支气管、肺泡管和肺泡囊均扩张（D错）见于全肺泡型肺气肿。肺泡间隔内出现成串小气泡（C错）见于间质性肺气肿（与肺泡性肺气肿并列的另一种肺气肿类型）（十版病理学P179）。","","N"],["2015-N53",10,"第2节 淋巴组织肿瘤","淋巴细胞的分化与淋巴瘤",2015,53,"A","","下列选项中，符合NK/T细胞淋巴瘤免疫表型的是",[["A","CD20"],["B","CD65"],["C","CD79"],["D","CD56"]],"D","免疫表型为白细胞分化抗原，不同的白细胞表达不同的免疫表型。NK/T细胞淋巴瘤的免疫表型既有NK细胞相关抗原CD56（D对），也有T细胞分化抗原如CD2、CD3（CD3ε）。CD20（A错）和CD79（C错）为B细胞的免疫表型（十版病理学P228）。CD65（B错）为粒细胞的免疫表型。现将常考的细胞免疫表型总结如下（十版病理学P228）：①T细胞：CD2、CD3、CD4、CD7、CD8（均为个位数）；②B细胞：CD10、CD19、CD20、CD79a；③NK细胞：CD16、CD56；④髓样细胞：CD13、CD33、CD117。","","N"],["2015-N54",12,"第2节 子宫体疾病","子宫内膜腺癌病理变化",2015,54,"A","","与子宫内膜癌关系不密切的子宫内膜变化是",[["A","复杂性增生"],["B","非典型增生"],["C","增殖期子宫内膜"],["D","单纯性增生"]],"C","子宫内膜增生症根据腺体结构和分化程度，可分为单纯性增生（D对）、复杂性增生（A对）和非典型增生（异型增生）（B对）三种类型，三种类型均可发展为子宫内膜癌。增殖期（增生期）是月经周期的一个阶段（八版生理学P427），增殖期子宫内膜（C错，为本题正确答案）在雌激素作用下增厚，子宫腺增多，属正常生理改变，与子宫内膜癌无关。","","N"],["2015-N55",16,"第2节 结核病","原发性肺结核病",2015,55,"A","","原发性肺结核的好发部位是",[["A","肺上叶下部、下叶上部"],["B","肺锁骨下区"],["C","肺下叶"],["D","肺尖部"]],"A","原发性肺结核的病灶好发于肺上叶下部或下叶上部（A对）。肺尖部（D错）和肺锁骨下区（B错）均为继发性肺结核的好发部位。（左）肺下叶（C错）是支气管扩张症的好发部位（十版病理学P181）。","","N"],["2015-N56",12,"第7节 乳腺疾病","非特殊型浸润性癌",2015,56,"A","","下列乳腺癌的病理学类型中，恶性度较低的是",[["A","浸润性小叶癌"],["B","髓样癌"],["C","小管癌"],["D","浸润型导管癌"]],"C","乳腺癌各种病理分型的恶性程度按从低到高排列依次为：非浸润性癌、浸润性特殊癌、浸润性非特殊癌。浸润性小叶癌（A错）和浸润型导管癌（D错）均属于浸润性非特殊癌，恶性程度高。小管癌（C对）又称高分化腺癌，属于浸润性特殊癌，恶性程度较低。髓样癌（B错）有伴大量淋巴细胞浸润和不伴大量淋巴细胞浸润两种类型，前者恶性程度较低，属于浸润性特殊癌，后者恶性程度较高，属于浸润性非特殊癌。","","N"],["2015-N133",9,"第12节 消化系统常见肿瘤","结直肠癌病理变化概述",2015,133,"B","","组织学上表现为黏液癌的大肠癌类型是",[["A","溃疡型"],["B","胶样型"],["C","浸润型"],["D","隆起型"]],"B","大肠癌的肉眼类型分为隆起型、溃疡型、浸润型和胶样型，其中胶样型癌的癌细胞可分泌大量黏液，肿瘤表面及切面均呈半透明、胶冻状，因此其组织学上可表现为黏液癌（B对）。","","N"],["2015-N134",9,"第12节 消化系统常见肿瘤","结直肠癌的浸润型",2015,134,"B","","较易引起肠梗阻的大肠癌类型是",[["A","溃疡型"],["B","胶样型"],["C","浸润型"],["D","隆起型"]],"C","大肠癌的肉眼类型分为隆起型、溃疡型、浸润型和胶样型，其中浸润型的病变特征为癌组织沿肠壁浸润，容易引起肠腔狭窄和肠梗阻（C对），多发生于左侧结肠。隆起型（D错）多发生于右侧结肠（八版外科学 P403），由于右侧肠腔较左侧肠腔大2～3倍，因此不易发生肠梗阻。","","N"],["2015-N135",16,"第2节 结核病","局灶型肺结核",2015,135,"B","","非活动性肺结核是",[["A","局灶性肺结核"],["B","浸润型肺结核"],["C","慢性纤维空洞性肺结核"],["D","干酪性肺炎"]],"A","局灶型肺结核（A对）是继发性肺结核的早期病变，患者常无自觉症状，仅在体检时发现，属于非活动性结核病。浸润型肺结核（B错）、慢性纤维空洞性肺结核（C错）、干酪性肺炎（D错）均属于活动性肺结核。","","N"],["2015-N136",16,"第2节 结核病","干酪性肺炎",2015,136,"B","","病情危重的肺结核是",[["A","局灶型肺结核"],["B","浸润型肺结核"],["C","慢性纤维空洞性肺结核"],["D","干酪性肺炎"]],"D","局灶型肺结核（A错）属于非活动性结核，患者常无自觉症状，病情较轻。浸润型肺结核（B错）多由局灶型肺结核发展而来，病变以渗出为主，中央有干酪样坏死，患者常有低热、疲乏、盗汗、咳嗽等症状，如病变继续发展，干酪样坏死扩大，坏死物液化后经支气管排出，局部形成急性空洞，洞壁坏死层内含大量结核杆菌，经支气管播散，可引起干酪性肺炎，干酪性肺炎病情危重（D对），出现高热、盗汗、虚脱等严重的结核中毒症状。慢性纤维空洞性肺结核（C错）系由浸润型肺结核急性空洞经久不愈发展而来，该病病程迁延，病情起伏，痰菌阳性，是结核病主要传播来源。","","N"],["2015-N137",3,"第3节 慢性炎症","肉芽肿性炎的常见类型",2015,137,"B","","属于肉芽肿性炎的是",[["A","鼠疫"],["B","梅毒"],["C","白喉"],["D","艾滋病"]],"B","肉芽肿性炎以炎症局部巨噬细胞及其衍生细胞形成境界清楚的结节状病灶（即肉芽肿）为特征，是一种特殊类型的慢性增生性炎症。常见的肉芽肿性炎包括结核病、麻风、梅毒（B对）等。鼠疫为出血性炎（A错），白喉为纤维素性炎（C错），二者均为急性渗出性炎症。艾滋病由于免疫系统严重破坏，炎症反应不明显（D错）。","","N"],["2015-N138",3,"第2节 急性炎症","出血性炎",2015,138,"B","","属于出血性炎症的是",[["A","鼠疫"],["B","梅毒"],["C","白喉"],["D","艾滋病"]],"A","根据炎症的基本病变性质进行分类，可分为变质性炎、渗出性炎和增生性炎。任何炎症都在一定程度上包含变质、渗出、增生这三种基本病变，但往往以一种病变为主，以变质为主时称为变质性炎；以渗出为主时称为渗出性炎；以增生为主时称为增生性炎。渗出性炎还可以根据渗出物的主要成分和病变特点，进一步分为浆液性炎、纤维素性炎、化脓性炎、出血性炎等。出血性炎是指炎症病灶的血管损伤严重，渗出物中含有大量红细胞，常见于流行性出血热、钩端螺旋体病和鼠疫（A对）等。梅毒（十版病理学P355）属于增生性炎（B错）。白喉属于纤维素性炎（C错）。艾滋病由于免疫系统严重破坏，炎症反应不明显（D错）。","","N"],["2015-N163",7,"第7节 心肌病","肥厚型心肌病的病理变化",2015,163,"X","","肥厚型心肌病的肉眼病理变化有",[["A","左心室壁肥厚"],["B","室间隔不均肥厚"],["C","二尖瓣肥厚"],["D","左心房壁肥厚"]],"AB","肥厚型心肌病（HCM）病变以心肌肥厚为主，心脏重量增加，肥厚为心室壁各处肥厚程度不等，无心房肌肥厚（D错），特征性病理变化为室间隔不均肥厚（非对称性室间隔肥厚）（B对），占90%，此外还可见室间隔对称性肥厚（均匀型肥厚）、心尖部肥厚和左心室前壁肥厚（A对）等。收缩期二尖瓣向前移动与左心室左侧心内膜接触，可引起二尖瓣增厚（选项中肥厚与增厚存在不一样的地方，故C选项不严谨）和主动脉瓣下的心内膜局限性增厚。本题正确答案应为ABC，原参考答案为AB。","","N"],["2015-N164",11,"第1节 肾小球疾病","急进性肾小球肾炎病理变化",2015,164,"X","","急进性肾小球肾炎电镜检查的病变特点有",[["A","Ⅱ型可见电子致密物沉积"],["B","肾小球系膜细胞增生"],["C","可见基底膜的缺损和断裂"],["D","脏层上皮细胞足突消失"]],"AC","急进性肾小球肾炎（新月体肾炎）分为三个类型：Ⅰ型（抗肾小球基膜抗体性）、Ⅱ型（免疫复合物性）、Ⅲ型（免疫反应缺乏性）。其中，Ⅱ型电镜检查可见电子致密物沉积（A对），所有类型均可见基底膜的缺损和断裂（C对）。急进性肾小球肾炎的特征性病变是肾小球壁层上皮细胞增生，而不是系膜细胞增生（B错），且系膜细胞增生多为光镜下检查所见，而非电镜检查。脏层上皮细胞足突消失（D错）为微小病变性肾小球病（脂性肾病）（十版病理学P259）、膜性肾小球病（十版病理学P256）和局灶性节段性肾小球硬化（十版病理学P259）的病变特点。","","N"],["2015-N165",9,"第12节 消化系统常见肿瘤","中晚期胃癌（进展期胃癌）",2015,165,"X","","胃癌的肉眼类型有",[["A","蕈伞型"],["B","溃疡型"],["C","浸润型"],["D","胶样型"]],"ABCD","胃癌分早期胃癌与中晚期胃癌。早期胃癌的肉眼形态大体分为三种类型：隆起型、表浅型和凹陷型。中晚期胃癌也可分为三型：蕈伞型（息肉型）（A对）、溃疡型（B对）和浸润型（C对）。胶样型为一种特殊类型，其癌细胞分泌大量黏液，癌组织肉眼呈半透明的胶冻状，其肉眼形态可表现为中晚期胃癌三型中的任何一种（D ）。本题给出的参考答案为ABCD，但D选项略有争议，八版教材P210与九版教材P231均提及胶样癌呈肉眼可见的半透明胶冻状，但又均未将其作为基本的肉眼类型单列出来，而是指其可表现为上述三种基本肉眼类型的一种。","","N"],["2015-N166",16,"第8节 性传播性疾病","梅毒基本病理变化",2015,166,"X","","属于梅毒的病变有",[["A","硬性下疳"],["B","梅毒疹"],["C","脊髓痨"],["D","黏液性水肿"]],"ABC","后天性梅毒可分为一、二、三期。硬性下疳（A对）属于一期梅毒的病变。梅毒疹（B对）属于二期梅毒的病变。脊髓痨（C对）属于三期梅毒的病变。黏液性水肿（十版病理学P17）（D错）属于甲状腺功能低下的特征性病变，指含有透明质酸的黏液样物质及水分在皮肤及皮下蓄积。","","N"],["2015-N167",9,"第2节 胃炎","慢性萎缩性胃炎",2015,167,"X","","慢性萎缩性胃炎的病变包括",[["A","胃黏膜慢性炎细胞浸润"],["B","肠上皮化生"],["C","鳞状上皮化生"],["D","幽门螺杆菌阳性"]],"ABD","慢性萎缩性胃炎以胃黏膜萎缩变薄，黏膜腺体减少或消失并伴有肠上皮化生（B对），固有层内多量淋巴细胞、浆细胞等慢性炎症细胞（A对）浸润为特点。鳞状上皮化生见于胃鳞癌（胃癌多为腺上皮细胞来源的腺癌，胃鳞癌较为少见）（C错）。慢性萎缩性胃炎分为A型和B型，A型因自身免疫引起，B型60%～70%为幽门螺杆菌感染（D对）引起。","","N"],["2015-N168",8,"第8节 呼吸系统常见肿瘤","神经内分泌癌",2015,168,"X","","呼吸系统肿瘤中，由神经内分泌细胞发生的包括",[["A","支气管类癌"],["B","腺癌"],["C","鳞癌"],["D","小细胞癌"]],"AD","支气管类癌（A对）和小细胞癌（D对）均属于起源于Kulchitsky细胞的神经内分泌性肿瘤。","","N"],["2016-N41",0,"第1节 适应","营养不良性萎缩",2016,41,"A","","营养不良性萎缩，最早发生的组织器官是",[["A","脂肪组织"],["B","脑组织"],["C","骨骼肌"],["D","心肌"]],"A","当机体能量供能不足时，机体优先动员脂肪供能，保证重要器官能量供应。因此，营养不良时最早萎缩的是脂肪组织（A对）。","","N"],["2016-N42",0,"第4节 细胞不可逆性损伤（细胞死亡）","分离排出",2016,42,"A","","阑尾切除术后切口处有肠内容物流出，该病变称为",[["A","瘘管"],["B","窦道"],["C","脓肿"],["D","溃疡"]],"A","阑尾切除术切口造成的通道，为内脏器官通向体表的通道样缺损，属于瘘管（A对）。窦道（B错）为组织坏死后形成的只开口于皮肤黏膜表面的深在盲管。溃疡（D错）为皮肤、黏膜上较深的组织缺损。脓肿（十版病理学P73）（C错）是指器官或组织内的局限性化脓性炎症，其主要特征是组织发生溶解坏死，形成充满脓液的脓腔。","","N"],["2016-N43",0,"第4节 细胞不可逆性损伤（细胞死亡）","凝固性坏死",2016,43,"A","","凝固性坏死的形态学特点",[["A","形成筛状软化灶"],["B","病灶中出现炎症细胞"],["C","细胞膜和细胞器膜完整"],["D","保持原有轮廓"]],"D","凝固性坏死的蛋白质变性凝固且溶酶体酶水解作用较弱，坏死区与健康组织间界限多较明显，镜下原有组织轮廓可保存数天（D对）。形成筛状软化灶（A错）为乙型脑炎液化性坏死的形态学特点（十版病理学P313）。病灶中出现炎症细胞可见于各种坏死类型，不属于凝固性坏死的特点（B错）。细胞膜和细胞器膜完整（C错）为细胞凋亡的形态学特点（十版病理学P22）。","","N"],["2016-N44",1,"第3节 伤口愈合","骨折愈合",2016,44,"A","","下列创伤中，能完全修复的是",[["A","闭合性骨折"],["B","一期愈合的手术切口"],["C","二期愈合的手术切口"],["D","三度烧伤的创面"]],"A","组织的损伤修复的过程可以概括为两种不同的形式：①由损伤周围的同种细胞来修复，称为再生，如果完全恢复原组织的结构及功能，则称为完全再生（完全修复）；②由纤维结缔组织来修复，称为纤维性修复，以后形成瘢痕，故也称瘢痕修复。骨组织再生能力强，闭合性骨折经过良好复位后，几个月内便可完全愈合，恢复正常结构和功能，属于完全修复（A对）。一期愈合的手术伤口（B错）、二期愈合的手术伤口（C错）、三度烧伤的创面（D错）恢复后均形成瘢痕，属于瘢痕修复。","","N"],["2016-N45",3,"第2节 急性炎症","纤维蛋白性炎",2016,45,"A","","引起绒毛心的原发疾病是",[["A","浆液性心包炎"],["B","纤维蛋白性心包炎"],["C","化脓性心包炎"],["D","结核性心包炎"]],"B","纤维蛋白性心包炎（纤维素性心包炎）（B对）时，心包脏层和壁层之间出现大量纤维素渗出，由于心脏的不断搏动，心包脏壁两层不断发生摩擦，使渗出的纤维素呈绒毛状，称绒毛心。浆液性心包炎（A错）有大量浆液渗出时可引起心包积液。化脓性心包炎（C错）和结核性心包炎（D错）均可引起缩窄性心包炎（十版病理学P165）。","","N"],["2016-N46",5,"第3节 肿瘤的命名与分类","肿瘤的分类",2016,46,"A","","下列肿瘤中属于良性肿瘤的是",[["A","肝母细胞瘤"],["B","神经母细胞瘤"],["C","髓母细胞瘤"],["D","软骨母细胞瘤"]],"D","来源于幼稚组织的肿瘤称为母细胞瘤，其中大多数为恶性肿瘤，多见于儿童。常见的恶性肿瘤有：视网膜母细胞瘤、神经母细胞瘤（B错）、髓母细胞瘤（C错）、肾母细胞瘤、肝母细胞瘤（A错）等；良性肿瘤有：骨母细胞瘤、软骨母细胞瘤（D对）、脂肪母细胞瘤和肌母细胞瘤。由于母细胞瘤多数为恶性，牢记几种良性母细胞瘤即可。","","N"],["2016-N47",4,"","",2016,47,"A","","属于系统性红斑狼疮的特征性病变是",[["A","血管周围大量浆细胞浸润"],["B","细动脉管壁玻璃样变性"],["C","血管纤维素样坏死"],["D","小动脉广泛血栓形成"]],"C","系统性红斑狼疮（SLE）发病时，肾脏、皮肤、血管及结缔组织中免疫复合物沉积，可导致全身急性坏死性小动脉、细动脉炎和血管纤维素样坏死（C对）。SLE时血管周围仅有少量浆细胞浸润（A错），血管周围大量浆细胞浸润可见于梅毒（十版病理学P355）。细动脉管壁玻璃样变性（B错）是良性高血压的特征性病变（十版病理学P151）。小动脉广泛血栓形成（D错）是肾移植后超急性排斥反应的特征性病变（十版病理学P88）。注：血管纤维素样坏死（十版病理学P20）还可见于风湿病（十版病理学P154）、新月体性肾小球肾炎（十版病理学P255）及急进型高血压（十版病理学P153）等多种变态反应性疾病，并不属于系统性红斑狼疮的特征性病变，因此本题的问法并不严谨。","","N"],["2016-N48",9,"第6节 病毒性肝炎","点状坏死",2016,48,"A","","下列病理改变属于急性普通型病毒性肝炎的是",[["A","汇管区炎症并突破界板"],["B","桥接坏死伴小叶结构破坏"],["C","肝细胞广泛脂肪病变伴嗜酸性粒细胞浸润"],["D","肝细胞广泛水肿伴点状坏死"]],"D","急性普通型肝炎的病变较轻，镜下以细胞水肿为主，肝细胞坏死轻微，以点状坏死为主（D对）。汇管区炎症并突破界板（A错）及桥接坏死（B错）均见于中、重度慢性肝炎。肝细胞广泛脂肪病变伴嗜酸性粒细胞浸润（C错）见于药物性肝炎。","","N"],["2016-N49",7,"第1节 动脉粥样硬化","主动脉粥样硬化",2016,49,"A","","动脉粥样硬化对人体危害最大的动脉类型是",[["A","大动脉"],["B","中动脉"],["C","小动脉"],["D","细动脉"]],"B","动脉粥样硬化（AS）的基本病变是动脉内膜的脂质沉积，内膜灶状纤维化和粥样斑块形成，致管壁变硬、管腔狭窄，引起相应器官缺血性改变。其中以发生在冠状动脉（属中动脉）（B对）时后果最为严重，冠状动脉粥样硬化可引起冠状动脉血管腔狭窄或阻塞，造成心肌缺血、缺氧或坏死而危及生命。","","N"],["2016-N50",8,"第7节 呼吸窘迫综合征","成人呼吸窘迫综合征的病理变化",2016,50,"A","","ARDS最典型的病变是",[["A","肺泡壁增厚，水肿"],["B","肺肉质变"],["C","肺透明膜形成"],["D","肺纤维化"]],"C","ARDS（成人呼吸窘迫综合征）时，在肺呼吸性细支气管、肺泡管及肺泡的内表面，可形成由血浆蛋白和坏死的肺泡上皮碎屑构成的薄层红染膜状物，即透明膜（C对），是ARDS最典型的病变。肺泡壁增厚，水肿（A错）和肺纤维化（D错）均可见于ARDS，但缺乏特异性（还可见于各种间质性肺炎）。肺肉质变（B错）亦称机化性肺炎，为大叶性肺炎的并发症（十版病理学P172）。","","N"],["2016-N51",17,"第12节 基因测序技术","基因测序技术概述",2016,51,"A","","检查大肠癌原癌基因RAS是否被异常激活成癌基因，有效的检测技术是",[["A","测序"],["B","免疫组织化学"],["C","Western blot"],["D","FISH"]],"A","大肠癌原癌基因RAS可发生点突变（十版病理学P111）而异常激活成癌基因，检测点突变最有效的方法是测序（A对）。FISH即荧光原位杂交技术，是指利用荧光素标记的特异DNA探针与组织切片上的肿瘤组织杂交，在荧光显微镜下显示相应染色体的某个区段或整条染色体的技术。FISH适用于检测染色体易位、缺失和扩增等，不能用于检测点突变（D错）。免疫组织化学（十版病理学P366）（B错）是一种利用抗原-抗体的特异性结合反应来检测和定位组织或细胞中的某种化学物质的技术，可用于检测蛋白及多肽类肿瘤标志物。Western blot（九版生物化学P441）又称蛋白质印迹，是一种利用抗原-抗体的特异性结合反应定性及半定量检测样品中某种特异性蛋白质的技术，常用于分子生物学实验中，不用于肿瘤的临床病理学诊断。","","N"],["2016-N52",10,"第2节 淋巴组织肿瘤","霍奇金淋巴瘤的预后",2016,52,"A","","预后最好的淋巴瘤是",[["A","滤泡型淋巴瘤"],["B","霍奇金结节硬化型"],["C","伯基特型淋巴瘤"],["D","弥漫大B型淋巴瘤"]],"B","霍奇金结节硬化型（十版病理学P241）（B对）淋巴瘤预后较好，化疗或放疗可治愈大多数病人。伯基特型淋巴瘤（十版病理学P233）（C错）和弥漫大B型淋巴瘤（十版病理学P232）（D错）属于侵袭性非霍奇金淋巴瘤，恶性度高，预后差。滤泡型淋巴瘤（A错）属于惰性非霍奇金淋巴瘤（二版八年制病理学P307），预后较好，10年生存率超50%，但有30%的可能性会进化为弥漫性大B细胞淋巴瘤，预后不良。","","N"],["2016-N53",11,"第2节 肾小管间质性肾炎","慢性肾盂肾炎病理变化",2016,53,"A","","属于慢性肾盂肾炎的病理变化是",[["A","肾小球内中性粒细胞浸润"],["B","肾小球囊壁层上皮细胞增生"],["C","肾小球囊壁纤维化"],["D","肾小球内系膜细胞增生"]],"C","慢性肾盂肾炎的肾小球囊壁可发生纤维化（C对）。慢性肾盂肾炎为肾小管和间质的慢性炎症，一般不累及肾小球，且浸润的细胞多为淋巴细胞和浆细胞浸润（A错）。肾小球囊壁层上皮细胞增生（B错）为急进性（新月体性）肾炎的病理变化（十版病理学P255）。肾小球内系膜细胞增生（D错）属于急性弥漫性增生性肾小球肾炎（十版病理学P254）、膜增生性肾小球肾炎（十版病理学P256）和系膜增生性肾小球肾炎（十版病理学P258）的病理变化。","","N"],["2016-N54",12,"第3节 滋养层细胞疾病","上皮样滋养细胞肿瘤概述",2016,54,"A","","不属于绒毛膜上皮癌的病理特征是",[["A","肿瘤细胞高度异型"],["B","出血坏死明显"],["C","没有肿瘤间质成分"],["D","高度水肿的绒毛"]],"D","绒毛膜上皮癌是源自妊娠绒毛滋养层上皮的高度侵袭性恶性肿瘤，肿瘤细胞异型性明显（A对）。该肿瘤没有肿瘤间质成分（血管）（C对），只能依靠侵袭宿主血管获取营养，因此癌组织和周围正常组织出血坏死明显（B对）。高度水肿的绒毛可见于葡萄胎和侵蚀性葡萄胎，而不见于绒毛膜上皮癌（D错，为本题正确答案）。","","N"],["2016-N55",16,"第8节 性传播性疾病","闭塞性动脉内膜炎",2016,55,"A","","梅毒性增生性动脉内膜炎时，血管周围浸润的特征性炎细胞是",[["A","T淋巴细胞"],["B","中性粒细胞"],["C","巨噬细胞"],["D","浆细胞"]],"D","梅毒累及小动脉时，小动脉周围出现大量单核细胞、淋巴细胞和浆细胞浸润，称为小动脉周围炎；小动脉内皮细胞及纤维细胞增生，使管壁增厚、血管腔狭窄闭塞，称为增生性动脉内膜炎（闭塞性动脉内膜炎），两者均为梅毒的基本病理变化。浆细胞（D对）恒定出现在血管周围是小动脉周围炎和增生性动脉内膜炎的病变特点。","","N"],["2016-N56",13,"第2节 甲状腺疾病","滤泡癌",2016,56,"A","","对诊断甲状腺滤泡状癌价值最大的病理变化是",[["A","肿瘤呈浸润性生长"],["B","肿瘤分化差，形态类似胚胎期甲状腺组织"],["C","肿瘤细胞高度异形"],["D","肿瘤细胞核为毛玻璃样"]],"A","肿瘤分化差，形态类似胚胎期甲状腺组织（B错）和肿瘤细胞高度异形（小细胞、梭形细胞、巨细胞等）（C错）均对诊断甲状腺未分化癌具有重要价值。肿瘤细胞核为毛玻璃样（D错）对诊断甲状腺乳头状癌具有重要价值。甲状腺癌的各类型（乳头状癌、滤泡状癌、髓样癌、未分化癌）均可呈浸润性生长，因此“肿瘤呈浸润性生长”对诊断甲状腺滤泡状癌缺乏特异性，价值“有限”。本题的参考答案为A，可能是因为A选项相对其他选项来说对诊断甲状腺滤泡状癌价值“最大”。","","N"],["2016-N133",3,"第2节 急性炎症","纤维蛋白性炎",2016,133,"B","","纤维蛋白渗出后可形成的病变是",[["A","小动脉纤维化"],["B","假膜性炎"],["C","纤维蛋白样变性"],["D","细动脉玻璃样变"]],"B","纤维蛋白渗出后可形成纤维素性炎，纤维素性炎易发生于黏膜、浆膜和肺组织。黏膜发生的纤维素性炎，渗出的纤维素、中性粒细胞和坏死黏膜组织以及病原菌等可在黏膜表面形成一层灰白色膜状物，称为“假膜”，故又称假膜性炎（B对），常见于白喉、细菌性痢疾等疾病。","","N"],["2016-N134",0,"第4节 细胞不可逆性损伤（细胞死亡）","纤维素样坏死",2016,134,"B","","血管壁受到体液免疫攻击的急性期病变为",[["A","小动脉纤维化"],["B","假膜性炎"],["C","纤维蛋白样变性"],["D","细动脉玻璃样变"]],"C","机体在病理状态下，体液免疫的抗原-抗体复合物可通过激活补体损伤血管壁，使血管壁发生纤维蛋白样变性（即纤维素样坏死）（C对），属于Ⅲ型变态反应。常见于风湿病、新月体性肾小球肾炎、急进型高血压、系统性红斑狼疮等变态反应性疾病。","","N"],["2016-N135",2,"第3节 血栓形成","白色血栓",2016,135,"B","","急性风湿性心内膜炎二尖瓣上的血栓主要成分",[["A","血小板凝块"],["B","红细胞凝块"],["C","纤维蛋白凝块"],["D","血小板和纤维蛋白相间凝块"]],"A","急性风湿性心内膜炎时在二尖瓣闭锁缘上形成的血栓为白色血栓，白色血栓的主要成分为血小板凝块（A对）。纤维蛋白凝块为透明血栓的主要成分（C错）。红细胞凝块为红色血栓的主要成分（B错）。本题的参考答案为A，但答案存在争议，2010N47A也考查急性风湿性心内膜炎心脏瓣膜白色血栓的主要成分，给出的参考答案为血小板和纤维蛋白（且题中无单独的血小板选项）（D对）。","","N"],["2016-N136",2,"第3节 血栓形成","透明血栓",2016,136,"B","","弥漫性毛细血管内凝血时血栓的主要成分是",[["A","血小板凝块"],["B","红细胞凝块"],["C","纤维蛋白凝块"],["D","血小板和纤维蛋白相间凝块"]],"C","弥漫性毛细血管内凝血（DIC）的血栓为透明血栓，其主要成分是纤维蛋白凝块（C对）。血小板凝块为白色血栓的主要成分（A错）。红细胞凝块为红色血栓的主要成分（B错）。","","N"],["2016-N137",3,"第2节 急性炎症","纤维蛋白性炎",2016,137,"B","","肺炎链球菌感染常引起",[["A","纤维性炎症"],["B","化脓性炎症"],["C","增生性炎症"],["D","浆液性炎症"]],"A","肺炎链球菌感染常引起大叶性肺炎，后者为纤维性炎症（A对）。化脓性炎症（B错）常由葡萄球菌、溶血性链球菌、脑膜炎双球菌等化脓菌感染引起（十版病理学P73）。增生性炎症（C错）常由结核杆菌、麻风杆菌、伤寒杆菌等感染引起。浆液性炎症（D错）主要由病毒感染引起。","","N"],["2016-N138",3,"第2节 急性炎症","纤维蛋白性炎",2016,138,"B","","痢疾杆菌感染常引起",[["A","纤维性炎症"],["B","化脓性炎症"],["C","增生性炎症"],["D","浆液性炎症"]],"A","痢疾杆菌是细菌性痢疾的主要致病菌，其病变以纤维性炎症（A对）为主，可形成假膜。化脓性炎症（B错）常由葡萄球菌、溶血性链球菌、脑膜炎双球菌等化脓菌感染引起（十版病理学P73）。增生性炎症（C错）常由结核杆菌、麻风杆菌、伤寒杆菌等感染引起。浆液性炎症（D错）主要由病毒感染引起。","","N"],["2016-N163",1,"第2节 纤维性修复","肉芽组织的成分及形态",2016,163,"X","","发生机化时，组织中出现的特征性细胞有",[["A","类上皮细胞"],["B","内皮细胞"],["C","成纤维细胞"],["D","多核巨细胞"]],"BC","机化是指新生肉芽组织长入并取代坏死组织、血栓、脓液、异物等的过程（十版病理学P21），肉芽组织由毛细血管（由内皮细胞增生形成）（B对）、成纤维细胞（C对）及炎症细胞构成。类上皮细胞（A错）和多核巨细胞（D错）为肉芽肿的特征性细胞（十版病理学P75），肉芽肿见于肉芽肿性炎，区别于机化的肉芽组织。","","N"],["2016-N164",2,"第5节 梗死","出血性梗死",2016,164,"X","","肺出血性梗死时，切片中可以看到与出血梗死相关病变的有",[["A","含铁血黄素"],["B","肉芽肿形成"],["C","肺组织坏死"],["D","肺泡内大量红细胞"]],"ACD","器官或局部组织由于血管阻塞导致缺氧而发生的坏死，称为梗死。当器官原有严重淤血或组织疏松时，易发生出血性梗死，常见于肺。肺出血性梗死时，镜下梗死灶呈凝固性坏死（C对），可见肺泡轮廓，肺泡腔（D对）、小支气管腔及肺间质充满红细胞，巨噬细胞吞噬、降解红细胞血红蛋白的铁蛋白微粒聚集体，形成含铁血黄素（A对）。肺出血性梗死时可见肉芽组织形成（十版病理学P55），而肉芽肿形成见于慢性炎症（十版病理学P74）（B错）。","","N"],["2016-N165",5,"第2节 肿瘤的形态和结构","肿瘤的异型性",2016,165,"X","","下列癌组织细胞中，不决定肿瘤特征的有",[["A","增生的成纤维细胞"],["B","增生的内皮细胞"],["C","上皮来源的异型细胞"],["D","浸润的淋巴细胞"]],"ABD","肿瘤的组织结构分为实质和间质两个组成部分：实质即肿瘤细胞，是肿瘤的主要成分，也是肿瘤分类和命名的根据；间质由纤维结缔组织及血管组成。肿瘤细胞的特征是具有异型性，上皮来源的异型细胞可为癌组织的特征（C对）。增生的成纤维细胞、增生的内皮细胞、浸润的淋巴细胞可见于肉芽组织等非癌组织（ABD错，为本题正确答案）。","","N"],["2016-N167",4,"第2节 免疫缺陷病","发病机制",2016,167,"X","","HIV病毒可以感染的人体细胞有",[["A","T淋巴细胞"],["B","B淋巴细胞"],["C","巨噬细胞"],["D","树突状细胞"]],"ACD","艾滋病（AIDS）是由HIV（人类免疫缺陷病毒）感染所引起的：①HIV可以感染CD4⁺T淋巴细胞（A对），而不是B淋巴细胞（B错）。②HIV可以感染巨噬细胞（C对）。③HIV可以感染树突状细胞（D对），并使其成为HIV的“储备池”。","","N"],["2016-N168",7,"第4节 风湿病","风湿病的各器官病变",2016,168,"X","","在风湿热病变中，可以出现Aschoff小体的有",[["A","风湿性心肌炎"],["B","环状红斑"],["C","皮下结节"],["D","风湿性动脉炎"]],"ACD","Aschoff小体为风湿病增生期出现的特征性肉芽肿性病变，可见于风湿性心肌炎（A对）、风湿性心内膜炎、风湿性关节炎、风湿性动脉炎（D对）和皮下结节（C对）。环形红斑（B错）为渗出性病变，不会出现Aschoff小体。","","N"],["2017-N29",0,"第4节 细胞不可逆性损伤（细胞死亡）","凋亡的形态学和生物化学特征",2017,29,"A","","下列形态学改变中属于凋亡特征的是",[["A","多为片状细胞死亡"],["B","细胞核固缩、碎裂"],["C","常为炎症反应和修复再生"],["D","细胞膜完整，发泡成芽"]],"D","凋亡的形态学特征主要表现为细胞固缩，核染色质边集，细胞膜及细胞器膜完整，膜可发泡成芽（D对），形成凋亡小体。片状细胞死亡（A错）见于细胞坏死，凋亡以单个细胞死亡多见。细胞核固缩、碎裂（B错）可见于细胞凋亡（十版病理学P22），但也亦可见于细胞坏死（十版病理学P19），非凋亡“特征”。炎症反应和修复再生（C错）见于细胞的损伤和修复。","","N"],["2017-N30",2,"第1节 充血和淤血","肺淤血",2017,30,"A","","急性左心功能衰竭导致肺出血的原因是",[["A","肺静脉小分支破裂"],["B","肺动脉小分支破裂"],["C","肺静脉端毛细血管漏出增加"],["D","肺动脉端毛细血管漏出增加"]],"C","急性左心衰时，心肌收缩力明显降低、心脏负荷加重，造成急性心排血量骤降、肺循环压力突然升高、周围循环阻力增加，出现急性肺淤血。急性肺淤血时，肺静脉压升高，肺静脉端毛细血管扩张充血，血浆和血细胞漏出（C对），导致肺出血。","","N"],["2017-N31",3,"第3节 慢性炎症","肉芽肿的组成成分和形态特点",2017,31,"A","","下列肉芽肿中常有langhans巨细胞的是",[["A","风湿小结"],["B","黏液潴留结节"],["C","结核结节"],["D","术后缝线反应"]],"C","巨细胞又称多核巨细胞，是肉芽肿的特征性细胞成分，由几十个，甚至几百个上皮样细胞融合而来。巨细胞有不同种类，在结核结节（C对）内，巨细胞内细胞核排列于细胞的周边呈马蹄铁形或环形，称为Langhans巨细胞（以发现此巨细胞的德国病理学家Langhans的名字命名）。术后缝线反应（D错）可导致异物性肉芽肿，亦可见巨细胞，异物性肉芽肿内巨细胞的细胞核杂乱无章地分布于细胞中，称为异物多核巨细胞（十版病理学P76）。风湿小结（十版病理学P155）（A错）由大量的Aschoff细胞和少量的淋巴细胞、浆细胞构成，其中Aschoff细胞也可见双核或多核者，又称Aschoff巨细胞。黏液性潴留结节（B错）为黏液潴留，不含巨细胞。","","N"],["2017-N32",16,"第2节 结核病","肺结核病血源播散所致病变概述",2017,32,"A","","尸检病理见脏层胸膜多发、粟粒大小、一致性硬结节，首先考虑",[["A","小叶性肺炎"],["B","肝癌肺转移"],["C","血源性播散性结核"],["D","栓塞性肺脓肿"]],"C","脏层胸膜多发、粟粒大小、一致性硬结节为粟粒性结核病的病理特征，粟粒性结核病属于血源性播散性结核（C对），多由肺内原发病灶或肺门干酪样坏死灶，以及肺外结核病灶内的结核杆菌侵入血流或经淋巴管由胸导管入血引起。小叶性肺炎（十版病理学P174）（A错）为以细支气管为中心的肺组织化脓性炎症，一般不累及胸膜。肝癌肺转移（B错）累及胸膜时的癌性结节大小不一，形状不规则。肺脓肿（D错）一般为单发性，累及胸膜时可使邻近胸膜增厚。","","N"],["2017-N33",0,"第4节 细胞不可逆性损伤（细胞死亡）","纤维素样坏死",2017,33,"A","","小血管壁纤维素样坏死，常见的疾病是",[["A","心肌病"],["B","良性高血压"],["C","急进性高血压"],["D","肺动脉高压"]],"C","小血管壁纤维素样坏死常见于急进性高血压（十版病理学P153）（C对）、风湿性动脉炎（十版病理学P157）、结节性多动脉炎、新月体性肾小球肾炎（十版病理学P255）等变态反应性疾病。心肌病（十版病理学P160）（A错）是一种原因不明的心肌疾病，病变一般不累及血管。良性高血压（十版病理学P151）（B错）主要表现为细小动脉玻璃样变。肺动脉高压（D错）可使肺血管构型改建，表现为无肌细动脉肌化、肺小动脉中膜增生肥厚等。","","N"],["2017-N34",8,"第1节 呼吸道和肺炎症性疾病","病毒性肺炎的病理变化",2017,34,"A","","下列病理改变符合病毒性肺炎的是",[["A","常有肺泡结构破坏"],["B","肺泡间隔水肿，炎细胞浸润"],["C","肺泡内壁常有大量纤维素渗出"],["D","局部区域中性粒细胞浸润"]],"B","病毒性肺炎肉眼病变不明显，镜下表现为肺泡间隔明显增宽，间质水肿及淋巴细胞、单核细胞等炎细胞浸润（B对），一般无渗出物，病变较严重时，出现由浆液、少量纤维素（C错）、红细胞及巨噬细胞混合成的渗出物。肺泡内壁大量纤维素渗出（C错）见于大叶性肺炎（十版病理学P172）。肺泡结构破坏（A错）和局部区域中性粒细胞浸润（D错）均见于小叶性肺炎（十版病理学P174）。","","N"],["2017-N35",9,"第6节 病毒性肝炎","乙型肝炎病毒（HBV）",2017,35,"A","","引起肝细胞毛玻璃样变性的病原体是",[["A","HAV"],["B","HBV"],["C","HCV"],["D","HEV"]],"B","肝细胞毛玻璃样变性是HBV（B对）引起的乙型肝炎的病理改变，该变性因光镜下肝细胞浆内充满嗜酸性细颗粒状物质，不透明似毛玻璃样而得名。HAV（A错）引起甲型肝炎，其常见病理改变为气球样变（水变性）。HCV（C错）引起丙型肝炎，其常见病理改变为脂肪变性。HEV（D错）引起戊型肝炎，病理改变似甲型肝炎，可见气球样变。","","N"],["2017-N36",16,"第2节 结核病","肠结核病概述",2017,36,"A","","下列疾病中，容易导致肠腔狭窄的疾病是",[["A","伤寒"],["B","阿米巴肠病"],["C","痢疾"],["D","肠结核"]],"D","肠结核（D对）根据病变特点可分为溃疡型和增生型，两种类型均可导致肠腔狭窄：溃疡型通过瘢痕形成和纤维收缩导致肠腔狭窄，增生型通过大量结核性肉芽组织形成和纤维组织增生导致肠腔狭窄。伤寒（十版病理学P350）（A错）可并发肠出血、肠穿孔，但不易导致肠腔狭窄。阿米巴肠病（十版病理学P358）（B错）可导致肠腔狭窄，但只在慢性期症状严重时出现。痢疾（十版病理学P351）（C错）亦可导致肠腔狭窄，但只在慢性细菌性痢疾的严重病例中可见到。","","N"],["2017-N37",11,"第2节 肾小管间质性肾炎","慢性肾盂肾炎发病机制",2017,37,"A","","慢性肾盂肾炎的炎症性质是",[["A","变质性炎症"],["B","增生性炎症"],["C","化脓性炎症"],["D","肉芽肿性炎症"]],"C","慢性肾盂肾炎为肾小管和肾间质的慢性化脓性炎症（C对），常有纤维化和瘢痕形成，伴肾盂和肾盏的纤维化和变形。","","N"],["2017-N38",10,"第2节 淋巴组织肿瘤","镜下改变",2017,38,"A","","在淋巴结活检切片中见到单核、双核的大细胞，核仁明显且呈红色，首先考虑的疾病是",[["A","T细胞淋巴瘤"],["B","霍奇金淋巴瘤"],["C","Burkitt淋巴瘤"],["D","弥漫性大B细胞淋巴瘤"]],"B","淋巴结活检切片中见到单核核仁明显且呈红色的大细胞考虑为霍奇金细胞，双核的核仁明显且呈红色的大细胞考虑为镜影细胞，二者均为R-S细胞，为霍奇金淋巴瘤的诊断性细胞（B对）。Burkitt淋巴瘤（十版病理学P233）（C错）瘤细胞中等大小，核内有2～4个小核仁。弥漫性大B细胞淋巴瘤（十版病理学P232）（D错）瘤细胞体积较大，但一般为单核，有单个或多个核仁。T细胞淋巴瘤（A错）不见核仁或核仁不清楚。","","N"],["2017-N39",12,"第3节 滋养层细胞疾病","葡萄胎病理变化",2017,39,"A","","在子宫肌层内发现水肿的绒毛，其诊断是",[["A","葡萄胎"],["B","绒毛状腺瘤"],["C","绒毛膜上皮癌"],["D","侵袭性葡萄胎"]],"D","侵蚀性葡萄胎为介于葡萄胎（即良性葡萄胎）和绒毛膜上皮癌之间的交界性肿瘤。侵蚀性葡萄胎（D对）和葡萄胎（A错）的主要区别是前者的子宫肌层内可见水肿的绒毛侵入，子宫肌层易发生出血坏死。绒毛膜上皮癌（绒癌）（C错）为发生于子宫的高度侵袭性恶性肿瘤，其病理结构无绒毛和水泡状结构（十版病理学P275）。绒毛状腺瘤（十版病理学P104）（B错）多见于结肠、直肠黏膜。","","N"],["2017-N40",4,"第1节 自身免疫病","心脏",2017,40,"A","","系统性红斑狼疮所致的疣状心内膜炎，其赘生物的主要成分是",[["A","纤维素"],["B","血小板凝块"],["C","血小板凝块和低毒化脓菌"],["D","纤维素网络和血小板小梁"]],"B","系统性红斑狼疮所致的疣状心内膜炎又称Libman-Sacks心内膜炎，其心瓣膜表面沉积的体积较小的非细菌性疣状赘生物为白色血栓，主要成分为血小板凝块（B对）。本考点存在争议，2010N47A考查急性风湿性心内膜炎心脏瓣膜白色血栓的主要成分，给出的参考答案为血小板与纤维素（D对）。","","N"],["2017-N124",7,"第2节 高血压病","细动脉硬化",2017,124,"B","","高血压病常见的血管病变是",[["A","动脉玻璃样变性"],["B","动脉纤维素样变性"],["C","动脉粥样硬化"],["D","动脉中层钙化"]],"A","高血压病又称为原发性或特发性高血压（十版病理学P148），可分为良性高血压和恶性高血压两类，以良性高血压最为常见（95%），良性高血压的血管病变主要表现为细小动脉玻璃样变性（A对）。恶性高血压不常见，其特征性病变为增生性小动脉硬化和坏死性细动脉炎，前者主要表现为动脉内膜的显著增厚，后者表现为动脉纤维素样变性（B错）。动脉粥样硬化（C错）（十版病理学P141）是一种常见的、与高血压病平行分类的心血管系统疾病，高血压病是动脉粥样硬化的危险因素。动脉硬化（十版病理学P141）包括动脉粥样硬化、动脉中层钙化（D错）、细动脉硬化三种类型。","","N"],["2017-N125",7,"第1节 动脉粥样硬化","心肌梗死",2017,125,"B","","心肌梗死常见的冠状动脉病变是",[["A","动脉玻璃样变性"],["B","动脉纤维素样变性"],["C","动脉粥样硬化"],["D","动脉中层钙化"]],"C","冠状动脉粥样硬化（C对）时，冠状动脉狭窄，冠状动脉供血中断，致供血区持续缺血而导致心肌梗死。","","N"],["2017-N126",3,"第2节 急性炎症","蜂窝织炎",2017,126,"B","","急性蜂窝状炎性阑尾炎的病理特点是",[["A","化脓性炎"],["B","纤维素性炎"],["C","浆液性炎"],["D","变质性炎"]],"A","急性蜂窝状炎性阑尾炎属于化脓性炎（A对）。化脓性炎以中性粒细胞渗出，并伴有不同程度的组织坏死和脓液形成为主要特点，包括表面化脓和积脓、蜂窝织炎和脓肿等类型。","","N"],["2017-N127",3,"第2节 急性炎症","浆液性炎",2017,127,"B","","风湿性关节炎的病理特点",[["A","化脓性炎"],["B","纤维素性炎"],["C","浆液性炎"],["D","变质性炎"]],"C","风湿性关节炎是一种发生于关节滑膜的浆液性炎（C对）。浆液性炎以浆液性渗出为特征，渗出的液体主要来自血浆，也可由浆膜的间皮细胞分泌，含有3%～5%的蛋白质（主要为白蛋白），同时混有少量中性粒细胞和纤维素。常发生于黏膜、浆膜、滑膜、皮肤和疏松结缔组织等处。","","N"],["2017-N148",8,"第8节 呼吸系统常见肿瘤","EB病毒",2017,148,"X","","下列肿瘤与EB病毒发生有关的是",[["A","肝癌"],["B","肺癌"],["C","鼻咽癌"],["D","淋巴瘤"]],"CD","EB病毒与鼻咽癌（C对）关系密切，90%以上患者血清中有EB病毒核抗原、膜抗原和壳抗原等多种成分的相应抗体。EB病毒亦与常发生于非洲儿童的地方性Burkitt淋巴瘤（D对）关系密切，所有患者中的绝大多数肿瘤细胞内含有EB病毒基因。肝癌（十版病理学P221）（A错）的发病多与肝炎病毒、肝硬化、酒精及真菌（如黄曲霉菌、青霉菌）有关。肺癌（十版病理学P189）（B错）的发病与吸烟、空气污染及职业因素有关。","","N"],["2017-N149",9,"第6节 病毒性肝炎","病毒性肝炎的基本病理变化",2017,149,"X","","毛玻璃样肝细胞的特点是",[["A","胞浆内含淀粉样物质"],["B","胞浆内含HBsAg阳性"],["C","胞浆不透明似毛玻璃状"],["D","胞浆内充满嗜酸性细颗粒物质"]],"BCD","HE染色光镜下，在乙型肝炎表面抗原（HBsAg）携带者和慢性肝炎患者的肝组织常可见部分肝细胞胞浆内充满嗜酸性细颗粒物质（D对），胞浆不透明似毛玻璃样（C对），故称此种细胞为毛玻璃样肝细胞。胞浆内免疫组织化学和免疫荧光检查HBsAg反应阳性（B对）。淀粉样变（A错）（十版病理学P16）是细胞间质内或小血管基膜下等部位淀粉样蛋白质和黏多糖复合物蓄积，因具有淀粉染色特征而得名。","","N"],["2017-N150",3,"第3节 慢性炎症","肉芽肿性炎的常见类型",2017,150,"X","","下列病变属于肉芽肿性炎的是",[["A","伤寒小结"],["B","子宫内膜结核"],["C","硅肺结节"],["D","新月体性肾小球肾炎"]],"ABC","肉芽肿性炎（十版病理学P75）以炎症局部巨噬细胞及其衍生细胞（上皮样细胞、多核巨细胞）增生形成境界清楚的结节状病灶（即肉芽肿）为特征，是一种特殊类型的慢性炎症。根据病因不同，肉芽肿性炎可以分为感染性肉芽肿、异物性肉芽肿和原因不明性肉芽肿等三种基本类型，伤寒小结（A对）和子宫内膜结核（B对）均属于感染性肉芽肿。新月体性肾小球肾炎（十版病理学P255）（D错）的主要病理改变为肾小球壁层上皮细胞增生，而非巨噬细胞及其衍生细胞增生，不属于肉芽肿性炎。硅肺结节（C）是极富争议的一个选项，硅肺结节的形成和发展大致经历以下三个阶段（三版八年制病理学P236）：①细胞性结节：为早期硅结节，由吞噬硅尘的巨噬细胞聚集在局部形成；②纤维性结节：由纤维母细胞、纤维细胞和胶原纤维组成；③玻璃样结节：纤维性结节从中心开始发生玻璃样变，最终形成典型的硅结节。纤维性结节和玻璃样结节不属于肉芽肿性炎，而细胞性结节是否属于肉芽肿性炎存在争议，细胞性结节由吞噬硅尘的巨噬细胞聚集在局部形成，具有肉芽肿性炎（异物性肉芽肿）的基本特征，但是缺乏具有诊断意义的上皮样细胞和多核巨细胞（十版病理学P76）。简而言之，硅肺结节在早期具有肉芽肿性炎的部分特征，在中晚期与肉芽肿性炎完全无关，而晚期的玻璃样结节又被认为是典型的硅结节。总体来看，硅肺结节不应算作肉芽肿性炎，教材似乎也暗示了这一点，在十版病理学P76介绍异物性肉芽肿时，提及了可造成尘肺的石棉，而没有提及更为常见的二氧化硅。然而，本题给出的参考答案（以高教社考试大纲为参考答案）为ABC。","","N"],["2017-N151",12,"第1节 子宫颈疾病","子宫颈浸润癌的临床病理联系",2017,151,"X","","下列病变属于子宫颈CINⅢ的是",[["A","轻度异型增生"],["B","中度异型增生"],["C","重度异型增生"],["D","原位癌"]],"CD","子宫颈上皮内瘤变（CIN）可分为CINⅠ级、CINⅡ级和CINⅢ级：轻度异型增生（A错）称为CINⅠ级，中度异型增生（B错）称为CINⅡ级，重度异型增生（C对）和原位癌（D对）称为CINⅢ级。","","N"],["2017-N152",4,"第1节 自身免疫病","病理变化",2017,152,"X","","类风湿关节炎的滑膜改变有",[["A","大量中性粒细胞浸润"],["B","多量淋巴细胞浸润"],["C","滑膜细胞增生"],["D","血管增生明显"]],"BCD","类风湿关节炎是一种以多发性和对称性慢性滑膜炎（慢性期）为主要表现的全身性自身免疫疾病。除慢性期外，类风湿关节炎还有急性期、亚急性期和稳定期等其他病变活动分期。大量淋巴细胞浸润（B对）、滑膜细胞增生（C对）和血管增生明显（D对）均为类风湿关节炎慢性期的滑膜改变（慢性滑膜炎）。大量中性粒细胞浸润（A）为类风湿关节炎急性期的滑膜改变。A选项也正确，原参考答案为BCD。","","N"],["2017-N153",10,"第2节 淋巴组织肿瘤","滤泡性淋巴瘤免疫表型",2017,153,"X","","滤泡细胞性淋巴瘤的免疫组化中，阳性的有",[["A","BCL-2"],["B","CD3"],["C","CD20"],["D","CD79a"]],"ACD","滤泡细胞性淋巴瘤（FL）是滤泡中心B细胞发生的淋巴瘤，具有正常B细胞的免疫表型，如CD19、CD20（C对）、CD79a（D对）、PAX5和表面Ig。此外，滤泡细胞性淋巴瘤由于t（14；18）染色体易位的原因，还表达特殊的免疫表型Bcl-2（A对）。CD3（B错）为T细胞的免疫表型。","","N"],["2018-N29",0,"第1节 适应","化生的类型",2018,29,"A","","下列组织中，不会发生化生的是",[["A","肾盂黏膜上皮"],["B","宫颈柱状上皮"],["C","结缔组织"],["D","神经纤维"]],"D","化生是一种分化成熟的细胞类型被另一种分化成熟的细胞类型所取代的过程，通常只出现在分裂增殖能力较活跃的细胞类型中，且通常发生于同源性细胞之间——上皮组织细胞之间或间叶组织细胞之间。肾盂黏膜上皮（A错）、宫颈柱状上皮（B错）属于上皮组织细胞，结缔组织（C错）属于间叶组织，均具有较强的分裂增殖能力，均可发生分化。神经纤维（D对）属于神经组织（人体的四大组织：上皮组织、结缔组织、肌肉组织、神经组织），附属于不具有分裂增殖能力的神经细胞，不能够发生分化。","","N"],["2018-N30",0,"第4节 细胞不可逆性损伤（细胞死亡）","纤维素样坏死",2018,30,"A","","下列组织中，不发生纤维素样坏死的是",[["A","骨骼肌肌纤维"],["B","心肌间质"],["C","肾小球"],["D","小动脉"]],"A","纤维素样坏死因坏死物质与纤维素染色性质相似而得名，是结缔组织及小血管壁常见的坏死形式，常见于某些变态反应性疾病。风湿性心肌炎（十版病理学P156）时，心肌间质（B错）结缔组织可发生纤维素样坏死。新月体性肾小球肾炎（十版病理学P255）时，肾小球（C错）可发生纤维素样坏死。恶性高血压（急进型高血压）（十版病理学P153）时，小动脉（D错）可发生纤维素样坏死。骨骼肌肌纤维（A对）可发生凝固性坏死，而不发生纤维素样坏死。","","N"],["2018-N31",3,"第2节 急性炎症","趋化作用",2018,31,"A","","炎症细胞自血管内游出后，在组织内作定向运动的现象是",[["A","炎性渗出"],["B","炎性浸润"],["C","趋化作用"],["D","阿米巴样运动"]],"C","炎症细胞自血管游出后，在组织内作定向运动的现象称为趋化作用（C对）。炎性渗出（白细胞渗出）为白细胞通过血管壁游出到血管外的过程（十版病理学P65），炎性浸润为炎细胞在炎症病灶周围聚集的现象，阿米巴样运动为白细胞从内皮细胞处溢出的方式（十版病理学P66）。炎性渗出（A错）、炎性浸润（B错）和阿米巴样运动（D错）均为炎症细胞的非定向运动现象。","","N"],["2018-N32",3,"第3节 慢性炎症","肉芽肿性炎的概念",2018,32,"A","","单核巨噬细胞在局部增生形成的结节状病灶是",[["A","炎性假瘤"],["B","肉芽肿"],["C","炎性息肉"],["D","肉芽组织"]],"B","单核巨噬细胞在局部增生、聚集而形成的结节状病灶称为肉芽肿（B对）。炎性假瘤（十版病理学P75）（A错）是由肉芽组织、炎细胞、增生的实质细胞和纤维结缔组织构成的境界清楚的瘤样病变。炎性息肉（十版病理学P75）（C错）是指黏膜组织的慢性炎症，为黏膜组织过度增生向黏膜表面突出形成的带蒂的肿物。肉芽组织（十版病理学P33）（D错）由新生薄壁的毛细血管以及增生的成纤维细胞构成，并伴有炎细胞浸润。","","N"],["2018-N33",5,"第8节 常见肿瘤举例","间叶组织良性肿瘤",2018,33,"A","","下列组织中，不发生癌的组织是",[["A","皮肤附件"],["B","肾上腺"],["C","淋巴造血组织"],["D","甲状旁腺"]],"C","癌是指发生在上皮组织的恶性肿瘤，上皮组织包括被覆上皮和腺上皮。皮肤附件（汗腺、皮脂腺）（A对）、肾上腺（B对）、甲状旁腺（D对）均含腺上皮细胞成分，均可发生癌变（汗腺癌、皮脂腺癌、肾上腺癌、甲状旁腺癌）。淋巴造血组织（C错，为本题正确答案）肿瘤包括淋巴瘤和白血病，属于恶性肿瘤，但不属于癌。","","N"],["2018-N34",7,"第4节 风湿病","风湿病的病因和发病机制",2018,34,"A","","下列对风湿热的描述中，错误的是",[["A","属于变态反应性疾病"],["B","发病与溶血性链球菌感染有关"],["C","常可导致关节畸形"],["D","心脏病变的后果对人体危害最严重"]],"C","风湿热是一种与A组β溶血性链球菌感染有关（B对）的变态反应性疾病（A对），病变常累及心脏、关节和血管，以心脏病变的后果最为严重（D对）。风湿热导致的关节病变关节腔内有浆液和纤维蛋白渗出，急性期后，渗出物易被完全吸收，一般不会留下关节畸形等后遗症（C错，为本题正确答案）。","","N"],["2018-N35",8,"第5节 肺尘埃沉着病","Ⅰ期硅肺",2018,35,"A","","硅沉着病（矽肺）最早期病变出现的部位是",[["A","两肺上叶"],["B","两肺下叶"],["C","上、下肺叶交界的胸膜处"],["D","肺门淋巴结"]],"D","肺硅沉着病，简称硅肺（曾称矽肺），是游离的二氧化硅微粒在肺内蓄积而引起的一种慢性职业病，以肺和肺门淋巴结等形成硅结节及肺组织弥漫性纤维化为其基本病变。肺硅沉着病可分为三期：①Ⅰ期硅肺硅结节形成主要局限于淋巴系统，病变主要位于双肺中、下叶近肺门处（D对）；②Ⅱ期硅肺硅结节明显扩展到淋巴系统以外的肺组织，硅结节数量增多并互相融合，肺间质纤维化，但病变范围不超过全肺的1/3；③Ⅲ期硅肺硅结节呈瘤样团块，直径超过2cm；或肺间质纤维化严重，病变范围超过全肺的1/3。","","N"],["2018-N36",9,"第6节 病毒性肝炎","碎片状坏死",2018,36,"A","","肝细胞碎片样坏死的形态学改变是",[["A","坏死肝细胞核碎裂"],["B","肝小叶内肝细胞广泛的点状坏死"],["C","坏死突破界板向肝小叶内扩散"],["D","肝细胞坏死超过1/3造成小叶结构不完整"]],"C","肝细胞的坏死根据坏死的范围和分布不同，可分为：①点状坏死，肝小叶内单个或数个肝细胞的坏死（B错），常见于急性普通型肝炎；②碎片状坏死，肝小叶周边部界板肝细胞的灶状坏死和崩解（C对），常见于慢性肝炎；③桥接坏死指中央静脉与汇管区之间，两个汇管区之间，或两个中央静脉之间出现的互相连接的坏死带，常见于中度和重度慢性肝炎；④大片坏死，指几乎累及整个肝小叶，造成小叶结构不完整的肝细胞坏死（D错），常见于重型肝炎。","","N"],["2018-N37",11,"第1节 肾小球疾病","急进性肾小球肾炎病理变化",2018,37,"A","","下列肾小球肾炎中，以肾小球内线状免疫荧光为特征的是",[["A","膜性肾病"],["B","新月体性肾炎"],["C","急性弥漫增生性肾炎"],["D","IgA肾病"]],"B","新月体性肾炎（急进性肾炎）分为三型：Ⅰ型为抗肾小球基膜抗体引起的肾炎，免疫荧光检查显示线性荧光（B对）；Ⅱ型为免疫复合物性肾炎，免疫荧光检查显示颗粒状荧光；Ⅲ型为免疫反应缺乏型，免疫荧光检查显示无荧光。膜性肾病（A错）、急性弥漫性肾炎（C错）和IgA肾病（D错）均因免疫球蛋白及补体沉积而表现为颗粒状免疫荧光。","","N"],["2018-N38",4,"第1节 自身免疫病","组织损伤机制",2018,38,"A","","引起系统性红斑狼疮组织损害的物质是",[["A","自身抗体"],["B","CD8⁺淋巴细胞"],["C","苏木素小体"],["D","狼疮细胞"]],"A","系统性红斑狼疮是一种全身性的自身免疫病，其免疫耐受的终止和破坏，导致大量的自身抗体（A对）产生是本病的主要原因。CD4⁺T淋巴细胞（B错）可能在自身抗体的产生过程中发挥重要作用。抗核抗体攻击变性或胞膜受损的细胞，与之接触的细胞核肿胀，被挤出胞体，形成狼疮小体（苏木素小体），是诊断SLE的特征性依据，吞噬了苏木素小体的细胞称为狼疮细胞。苏木素小体（C错）和狼疮细胞（D错）均为系统性红斑狼疮组织损伤的病理表现，而非病因。","","N"],["2018-N39",12,"第7节 乳腺疾病","浸润性癌",2018,39,"A","","乳腺浸润癌与乳腺硬化性腺病形态相似，鉴别两者最主要的依据是",[["A","浸润癌核分裂象多见"],["B","浸润癌腺体异形明显"],["C","浸润癌增生活跃"],["D","浸润癌腺腔周围无肌上皮细胞"]],"D","乳腺硬化性腺病是一种伴有显著间质硬化的以小叶为中心的良性病变。其临床检查、大体检查、甚至光镜表现均可类似乳腺浸润癌。乳腺硬化性腺病主要有以下特点：（1）大体表现有时非常类似于癌，如质硬、切面可见黄色斑点和条纹（弹力组织变性）；（2）低倍镜下观察，小叶及器官样生长方式（结节或漩涡状结构）具有提示意义；（3）高倍镜下硬化性腺病小管具有上皮和肌上皮，而癌性导管无肌上皮（D对）；（4）硬化性腺病小管有连续的基底膜，而浸润癌腺体没有；（5）发生于妊娠女性的硬化性腺病可呈旺炽性增生，此时腺上皮细胞可表现为高染色质或泡状核，核/浆比升高，核仁明显，非常容易与癌混淆，特别是在术中冰冻时。","","N"],["2018-N40",3,"第2节 急性炎症","化脓性炎",2018,40,"A","","下列疾病中，属于化脓性炎的是",[["A","大叶性肺炎"],["B","肠伤寒"],["C","淋病性尿道炎"],["D","阿米巴肝脓肿"]],"C","根据炎症的基本病变性质进行分类，可分为变质性炎、渗出性炎和增生性炎。任何炎症都在一定程度上包含变质、渗出、增生这三种基本病变，但往往以一种病变为主，以变质为主时称为变质性炎；以渗出为主时称为渗出性炎；以增生为主时称为增生性炎。渗出性炎还可以根据渗出物的主要成分和病变特点，进一步分为浆液性炎、纤维素性炎、化脓性炎、出血性炎等。其中化脓性炎（十版病理学P73）多由化脓菌（如葡萄球菌、链球菌、淋球菌、脑膜炎双球菌或大肠杆菌等）感染所致，也可由组织坏死继发感染产生。大叶性肺炎（十版病理学P172）（A错）是由肺炎球菌引起的以肺泡内弥漫性纤维素渗出为主的炎症，为纤维素性炎。肠伤寒（十版病理学P350）（B错）是以单核巨噬细胞系统细胞的增生为病变特征的增生性炎。淋病性尿道炎（C对）属于淋球菌引起的急性化脓性炎。阿米巴肝脓肿（十版病理学P358）（D错）属于以组织溶解液化为主的变质性炎。","","N"],["2018-N124",13,"第2节 甲状腺疾病","乳头状癌",2018,124,"B","","主要根据细胞核形态诊断的甲状腺癌是",[["A","乳头状癌"],["B","滤泡状癌"],["C","髓样癌"],["D","肉瘤样癌"]],"A","主要根据细胞核形态确诊的甲状腺癌是乳头状癌（A对），其癌细胞细胞核常呈透明或毛玻璃状。滤泡状癌（B错）主要根据细胞生物学行为确诊（癌细胞排列成滤泡状或腺管状，早期易血道转移等）。髓样癌（C错）和肉瘤样癌（D错）主要通过免疫组织化学检查确诊。","","N"],["2018-N125",13,"第2节 甲状腺疾病","滤泡癌",2018,125,"B","","主要根据细胞生物学行为诊断的甲状腺癌是",[["A","乳头状癌"],["B","滤泡状癌"],["C","髓样癌"],["D","肉瘤样癌"]],"B","滤泡状癌（B对）主要根据细胞生物学行为确诊（癌细胞排列成滤泡状或腺管状，早期易血道转移等）。乳头状癌（A错）主要通过细胞核形态确诊（细胞核常呈透明或毛玻璃状）。","","N"],["2018-N126",16,"第3节 伤寒","伤寒病理变化概述",2018,126,"B","","构成伤寒肉芽肿的主要细胞是",[["A","巨噬细胞"],["B","淋巴细胞"],["C","多核巨细胞"],["D","浆细胞"]],"A","构成伤寒肉芽肿的主要细胞是巨噬细胞（A对），这种巨噬细胞吞噬有伤寒杆菌、红细胞和细胞碎片，被称为伤寒细胞。多核巨细胞（C错）是结核肉芽肿的主要细胞成分之一（十版病理学P344）。浆细胞（D错）和淋巴细胞（B错）是梅毒肉芽肿的细胞成分（十版病理学P356），其中以浆细胞为主。","","N"],["2018-N127",16,"第8节 性传播性疾病","梅毒基本病理变化",2018,127,"B","","构成梅毒肉芽肿的主要细胞是",[["A","巨噬细胞"],["B","淋巴细胞"],["C","多核巨细胞"],["D","浆细胞"]],"D","浆细胞（D对）和淋巴细胞（B）是梅毒肉芽肿的细胞成分（十版病理学P356），其中以浆细胞（D对）为主（值得注意的是，教材只有提及浆细胞在梅毒闭塞性动脉内膜炎及小血管周围炎中恒定出现，并未说明其为梅毒肉芽肿的主要细胞）。巨噬细胞（A错）是构成伤寒肉芽肿的主要细胞（十版病理学P350）。多核巨细胞（C错）是结核肉芽肿的主要细胞成分之一（十版病理学P344）。","","N"],["2018-N148",9,"第8节 肝硬化","腹腔积液",2018,148,"X","","下列选项中，与肝硬化腹水生成机制相关的有",[["A","门静脉高压"],["B","肝脏处理胆红素功能下降"],["C","肝内纤维组织增生压迫肝静脉主干"],["D","淋巴液从肝包膜中外渗"]],"AD","肝硬化腹水是肝功能减退和门静脉高压的共同结果，是肝硬化失代偿期最突出的临床表现。腹水形成的机制涉及：①门静脉高压（A对），腹腔内脏血管床静水压增高，组织液回吸收减少而漏入腹腔，是腹水形成的决定性因素。②有效循环血容量不足，肾血流减少，肾素-血管紧张素系统激活，肾小球滤过率降低，排钠和排 尿量减少。③低白蛋白血症，白蛋白低于30g/L时，血浆胶体渗透压降低，毛细血管内液体漏入腹腔或组织间隙。④肝脏对醛固酮和抗利尿激素灭能作用减弱，导致继发性醛固酮增多和抗利尿激素增多。前者作用于远端肾小管，使钠重吸收增加；后者作用于集合管，使水的吸收增加。水、钠潴留，尿量减少。⑤肝淋巴量超过了淋巴循环引流的能力，肝窦内压升高，肝淋巴液生成增多，自肝包膜表面外渗漏入腹腔（D对），参与腹水形成。肝内纤维组织增生时，可使肝小叶内肝窦内压增高或闭塞，而非直接压迫肝静脉主干（C错），以致门静脉血不易流入肝小叶的中央静脉或小叶下静脉，血流淤滞，门静脉压增高。肝脏处理胆红素功能下降（九版生物化学P377）（B错）可引起黄疸，与肝硬化腹水生成无关。","","N"],["2018-N149",0,"第1节 适应","萎缩的病理变化",2018,149,"X","","在下列病变中，属于心肌褐色萎缩病变的有",[["A","心脏体积缩小"],["B","心底部大血管管腔缩小"],["C","冠状动脉呈扭曲状"],["D","心室内膜呈虎斑状"]],"AC","萎缩是指已发育正常的细胞、组织或器官的体积缩小（十版病理学P5），为细胞和组织的适应类型之一（萎缩、肥大、增生、化生）。心肌褐色萎缩时，心肌细胞、组织及心脏体积减小（A对），伴冠状动脉呈蛇行状扭曲（C对）。根据心脏解剖结构，心底部大血管位于心脏之外，故心脏发生褐色萎缩时，不涉及心底部大血管管腔缩小（B错）。心室内膜呈虎斑心（D错）为慢性酒精中毒或缺氧引起的心肌脂肪变（十版病理学P16），为心肌细胞的可逆性损伤表现，不属于适应的范畴。","","N"],["2018-N150",0,"第4节 细胞不可逆性损伤（细胞死亡）","纤维素样坏死",2018,150,"X","","在下列疾病中，会发生纤维素样坏死的有",[["A","膜性肾病"],["B","系统性红斑狼疮"],["C","风湿性心肌炎"],["D","良性高血压"]],"BC","纤维素样坏死是结缔组织和小血管壁常见的坏死形式。病变部位形成细丝状、颗粒状或小条状无结构物质，由于其与纤维素染色性质相似，故名纤维素样坏死。多见于一些变态反应性疾病，如风湿性心脏病（风湿性心内膜炎、风湿性心肌炎、风湿性心外膜炎）（C对）、系统性红斑狼疮（B对）、结节性动脉周围炎和新月体性肾小球肾炎等，也见于一些非变态反应性疾病，如恶性高血压（急进型高血压）的小动脉和胃溃疡底部的动脉壁。膜性肾病（A错）属于肾病综合征，以基底膜增生性病变为主，变质、渗出少见，不存在典型的炎症表现，因此不会发生纤维素样坏死。良性高血压（D错）的病变特点是细小动脉硬化，可发生玻璃样变性（十版病理学P151）。","","N"],["2018-N151",3,"第2节 急性炎症","纤维蛋白性炎",2018,151,"X","","在下列疾病中，属于假膜性炎的有",[["A","大叶性肺炎"],["B","白喉"],["C","细菌性痢疾"],["D","风湿性心包炎"]],"BC","假膜性炎是发生在黏膜的纤维素性炎，因渗出的纤维素、中性粒细胞和坏死黏膜组织以及病原菌等在黏膜表面形成一层灰白色“假膜”而得名。白喉（B对）为发生在咽喉部黏膜的假膜性炎。细菌性痢疾（C对）为发生在肠黏膜的假膜性炎。大叶性肺炎（十版病理学P172）（A错）为发生在肺组织的纤维素性炎，风湿性心包炎（十版病理学P156）（D错）为发生在浆膜（心外膜）的纤维素性炎（或浆液性炎），均不属于假膜性炎。","","N"],["2018-N152",5,"第5节 肿瘤的分级和分期","肿瘤分期",2018,152,"X","","在下列选项中，与肿瘤分期相关的有",[["A","肿瘤的大小"],["B","淋巴结有无转移"],["C","肿瘤的浸润深度"],["D","肿瘤的分化程度"]],"ABC","肿瘤的分期是指恶性肿瘤的生长范围和播散程度。临床医师多根据原发肿瘤的大小（A对）、浸润深度（C对），邻近器官受累情况以及淋巴结转移（B对）情况等，对肿瘤进行TNM分期。肿瘤的分化程度（D错）属于肿瘤分级的指标。","","N"],["2018-N153",9,"第12节 消化系统常见肿瘤","早期胃癌的概述",2018,153,"X","","下列选项中，符合早期胃癌描述的有",[["A","肿瘤最大径小于2cm"],["B","肿瘤尚未侵及肌层"],["C","可有局部淋巴结转移"],["D","可有单个的肝转移灶"]],"BC","胃壁由内至外依次可分为黏膜层、黏膜下层、肌层和浆膜层共四层，早期胃癌指癌症组织浸润仅限于黏膜层或黏膜下层（B对），而无论有无淋巴结转移（C对）。肿瘤直径与早期胃癌的诊断无关（A错）。可有单个的肝转移灶（D错）说明已经发生血道转移，见于晚期胃癌。","","N"],["2019-N29",0,"第4节 细胞不可逆性损伤（细胞死亡）","核固缩",2019,29,"A","","下列属于不可逆性病变的是",[["A","核固缩"],["B","线粒体肿胀"],["C","细胞质脂滴增加"],["D","内质网扩张"]],"A","细胞的损伤可分为可逆性损伤和不可逆性损伤两种，其中可逆性损伤包括细胞水肿、脂肪变、玻璃样变、淀粉样变、黏液样变、病理性色素沉着和病理性钙化等。不可逆性损伤（即细胞死亡）则包括凋亡和坏死两种类型。核固缩（A对）为细胞坏死的主要形态学标志之一，为不可逆损伤。细胞质脂滴增加（C错）见于脂肪变性（十版病理学P15），为可逆性损伤。线粒体肿胀（B错）和内质网扩张（D错）见于细胞水肿（十版病理学P15），亦为可逆性损伤。","","N"],["2019-N30",0,"第1节 适应","萎缩的病理变化",2019,30,"A","","肉眼观察判断心脏萎缩的最主要依据是",[["A","心脏变形，表面血管绷直"],["B","心肌质地硬韧"],["C","心脏外形不变，表面血管弯曲"],["D","心脏体积小"]],"C","萎缩是指已发育正常的细胞、组织或器官的体积缩小。心脏萎缩时，心脏外形不变，仅表现为心脏体积缩小，由于冠状动脉长度不变，所以在心脏表面形成蛇形弯曲（C对A错）。心肌质地硬韧（B错）和心脏体积小（D错）均可见于心脏萎缩，但表现缺少特征性，不能作为判断心脏萎缩的最主要依据。","","N"],["2019-N31",2,"第3节 血栓形成","透明血栓",2019,31,"A","","休克死亡者，组织切片中最常见的血栓类型是",[["A","混合血栓"],["B","透明血栓"],["C","白色血栓"],["D","红色血栓"]],"B","休克是机体有效循环血容量减少、组织灌注不足，细胞代谢紊乱和功能受损的病理生理过程，在休克发生发展过程中，机体微循环经历收缩期→扩张期→衰竭期，即病情持续发展，进入不可逆的休克，发生广泛循环衰竭，引起弥散性血管内凝血（DIC），故休克死亡的患者，组织切片中最常见的血栓类型是透明血栓（纤维素性血栓）（B对）。白色血栓（C错）常位于血流较快的心瓣膜、心腔内和动脉内，如急性风湿性心内膜炎二尖瓣闭锁缘上形成的血栓；在静脉性血栓中，白色血栓位于延续性血栓的起始部（血栓的头部）。混合血栓（A错）多见于静脉内延续性血栓的体部，亦见于心腔内、动脉粥样硬化溃疡部位或动脉瘤内（由于血栓底部与心壁或血管壁相连，称为附壁血栓）。红色血栓（D错）主要见于静脉内，当混合血栓逐渐增大并阻塞血管腔时，血栓下游局部血流停止，血液发生凝固，成为静脉内延续性血栓的尾部。","","N"],["2019-N32",5,"第3节 肿瘤的命名与分类","肿瘤的分类",2019,32,"A","","下列属于良性肿瘤的是",[["A","白血病"],["B","黑色素瘤"],["C","肾母细胞瘤"],["D","软骨母细胞瘤"]],"D","肿瘤的命名一般根据其组织或细胞类型以及生物学行为来命名，良性肿瘤命名的一般原则是在组织或细胞类型的名称后面加一个“瘤”字，恶性肿瘤根据其组织来源，上皮组织的恶性肿瘤统称为癌，间叶组织的恶性肿瘤统称为肉瘤。除一般命名规则外，有些肿瘤的命名已经约定俗成，如白血病（A错）、黑色素瘤（恶性黑色素瘤）（B错）为恶性肿瘤，有些肿瘤被称为“母细胞瘤”，良性者如骨母细胞瘤等，恶性者如肾母细胞瘤（C错）、神经母细胞瘤等。软骨母细胞瘤（D对）属于良性肿瘤，为来源于幼稚软骨细胞（软骨母细胞），多位于长骨末端的骨骺，通常于儿童晚期或青少年期发病。","","N"],["2019-N33",9,"第12节 消化系统常见肿瘤","早期胃癌的概述",2019,33,"A","","关于早期胃癌的描述，不正确的是",[["A","癌细胞不能侵犯黏膜下层"],["B","可有胃周淋巴结转移"],["C","无远处转移"],["D","大多数属于腺癌"]],"A","根据胃癌的病理变化，可将胃癌分为早期胃癌和中晚期胃癌。早期胃癌是指指癌组织浸润仅限于黏膜层或黏膜下层（A错，为本题正确答案），不论肿瘤面积大小及是否有胃周围淋巴结转移（B对）。镜下早期胃癌大多数为腺癌（D对）。早期胃癌多无远处转移（C对）。","","N"],["2019-N34",11,"第1节 肾小球疾病","急进性肾小球肾炎病理变化",2019,34,"A","","新月体性肾小球肾炎中，细胞性新月体病变中最主要的细胞是",[["A","肾小球囊壁层上皮细胞"],["B","肾小球囊脏层上皮细胞"],["C","成纤维细胞"],["D","中性粒细胞"]],"A","新月体性肾小球肾炎又称急进性肾小球肾炎，本组肾炎的组织学特征是肾小球壁层上皮细胞增生，形成新月体。新月体主要由增生的壁层上皮细胞（A对B错）和渗出的单核细胞构成，可有中性粒细胞（D错）和淋巴细胞浸润。成纤维细胞（C错）主要见于慢性肾小球肾炎。","","N"],["2019-N35",16,"第2节 结核病","原发性肺结核病",2019,35,"A","","下列病变中，属于原发性肺结核病的是",[["A","干酪性肺炎"],["B","浸润型肺结核"],["C","肺门淋巴结结核"],["D","结核球"]],"C","原发性肺结核是指机体第一次感染结核杆菌所引起的肺结核病，结核杆菌被吸入肺泡后，最先引起的病变叫做原发灶，原发灶的病变侵入淋巴管，循淋巴液引流到局部肺门淋巴结，引起相应的结核性淋巴管炎和淋巴结炎，肺的原发病灶、淋巴管炎和肺门淋巴结结核（C对）称为原发综合征，属于原发性肺结核的典型表现。结核球（D错）、干酪性肺炎（A错）及浸润性肺结核（B错）均属于继发性肺结核的临床分型。","","N"],["2019-N36",10,"第2节 淋巴组织肿瘤","结节性淋巴细胞为主型霍奇金淋巴瘤",2019,36,"A","","结节性淋巴细胞为主型霍奇金淋巴瘤肿瘤细胞的免疫组化表型是",[["A","CD3⁺"],["B","CD15⁺"],["C","CD20⁺"],["D","CD30⁺"]],"C","WHO分类中，将霍奇金淋巴瘤（HL）分为两大类：经典型霍奇金淋巴瘤（CHL）和结节性淋巴细胞为主型霍奇金淋巴瘤（NLPHL）。经典型霍奇金淋巴瘤肿瘤细胞的免疫组化表型是CD30和大部分CD15阳性，CD20阴性。结节性淋巴细胞为主型霍奇金淋巴瘤肿瘤细胞的免疫组化表型是CD20（C对）和CD79a阳性，CD15阴性（B错），偶有CD30（D错）弱阳性。CD3（A错）是T细胞及其肿瘤的标志（十版病理学P228）。","","N"],["2019-N37",7,"第1节 动脉粥样硬化","颈动脉及脑动脉粥样硬化",2019,37,"A","","脑动脉粥样硬化病变最常累及的部位是",[["A","小脑"],["B","大脑基底核"],["C","脑桥"],["D","丘脑"]],"B","脑动脉粥样硬化病变好发于大脑中动脉分支处，而大脑中动脉的分支豆纹动脉是大脑基底核（基底神经节）的主要供血动脉，故脑动脉粥样硬化病变最常累及的部位是大脑基底核（B对）。","","N"],["2019-N38",13,"第2节 甲状腺疾病","乳头状癌",2019,38,"A","","甲状腺最常见的恶性肿瘤是",[["A","未分化癌"],["B","滤泡癌"],["C","乳头状癌"],["D","髓样癌"]],"C","甲状腺最常见的恶性肿瘤是乳头状癌（C对），约占60%，青少年女性较多见，肿瘤生长缓慢，恶性程度较低，预后较好。滤泡癌（B错）约占20%～25%，常比乳头状癌恶性程度高、预后差。髓样癌（D错）是由滤泡旁细胞发生的恶性肿瘤，占甲状腺癌的5%～10%，40～60岁高发。未分化癌（A错）占甲状腺癌的5%～10%，多见于50岁以上的女性，恶性程度高，预后差。","","N"],["2019-N39",12,"第1节 子宫颈疾病","子宫颈浸润癌的临床病理联系",2019,39,"A","","在下列描述中，子宫颈癌Ⅰ期是",[["A","癌细胞尚未突破基底膜"],["B","癌细胞浸润并局限于子宫颈内"],["C","癌细胞分化较成熟"],["D","癌细胞浸润范围超过子宫颈"]],"B","临床上，子宫颈癌根据其累及范围分期如下：①0期：原位癌（CINⅢ）：异型增生的细胞累及子宫颈黏膜上皮全层，但病变局限于上皮层内，未突破基膜（A错）；②Ⅰ期：癌局限于子宫颈以内（B对）；③Ⅱ期：肿瘤超出子宫颈（D错）进入盆腔，但未累及盆腔壁，癌肿侵及阴道，但未累及阴道的下1/3；④Ⅲ期：癌扩展至盆腔壁及阴道的下1/3；⑤Ⅳ期：癌组织已超越骨盆，或累及膀胱黏膜或直肠，包括癌的散播性转移。","","N"],["2019-N40",11,"第3节 肾和膀胱常见肿瘤","肾细胞癌病理变化",2019,40,"A","","肾细胞癌最常见的组织学类型是",[["A","透明细胞性肾细胞癌"],["B","嫌色性肾细胞癌"],["C","乳头状肾细胞癌"],["D","未分化性肾细胞癌"]],"A","WHO在2004年对肾细胞癌的分类重新进行了修订（第3版，新分型），主要类型包括：①透明细胞性肾细胞癌（A对），是肾细胞癌最常见的组织学类型（70%～80%）；②乳头状肾细胞癌（C错），约占肾细胞癌的10%～15%；③嫌色性肾细胞癌（B错），约占肾细胞癌的5%。肾癌的其他类型还包括集合管癌和未分类性肾细胞癌。未分化性肾细胞癌（D错）为曾经被广泛采用的1981年WHO肾癌分类标准（第1版，传统分型）中的一种病理分型，该分型在九版五年制病理学及三版八年制病理学中已经不再提及。","","N"],["2019-N124",0,"第4节 细胞不可逆性损伤（细胞死亡）","凝固性坏死",2019,124,"B","","心肌梗死的病理变化是",[["A","坏疽"],["B","液化性坏死"],["C","凝固性坏死"],["D","脂肪坏死"]],"C","心肌梗死的形态变化是一个动态演变过程，其病理变化为凝固性坏死（3版八年制病理学P190）（C对）。凝固性坏死还常见于脾、肾的梗死。液化性坏死（十版病理学P20）（B错）见于细菌或某些真菌感染引起的脓肿、缺血缺氧引起的脑软化，以及由细胞水肿发展而来的溶解性坏死等。脂肪坏死（十版病理学P20）（D错）也属液化性坏死范畴，可见于急性胰腺炎。坏疽（十版病理学P20）（A错）分为干性、湿性和气性坏疽等类型，干性坏疽常见于动脉阻塞但静脉回流尚通畅的四肢末端，湿性坏疽多发生于与外界相通的内脏或动脉阻塞及静脉回流受阻的肢体，气性坏疽是湿性坏疽的一种，系深达肌肉的开放性创伤，合并产气荚膜杆菌等厌氧菌感染。","","N"],["2019-N125",0,"第4节 细胞不可逆性损伤（细胞死亡）","液化性坏死",2019,125,"B","","阿米巴肝脓肿的病理变化是",[["A","坏疽"],["B","液化性坏死"],["C","凝固性坏死"],["D","脂肪坏死"]],"B","阿米巴肝脓肿是肠外阿米巴中最常见的类型，脓肿一般单个，大小不一，脓肿内容物为阿米巴溶解组织所致的液体性坏死物质（B对）和陈旧性血液混合而成的果酱样物质。凝固型坏死（十版病理学P20）（C错）多见于心、肝、肾和脾等实质器官，常因缺血缺氧、细菌毒素、化学腐蚀剂作用引起。脂肪坏死（十版病理学P20）（D错）常见于急性胰腺炎。坏疽（十版病理学P20）（A错）分为干性、湿性和气性坏疽等类型，干性坏疽常见于动脉阻塞但静脉回流尚通畅的四肢末端，湿性坏疽多发生于与外界相通的内脏或动脉阻塞及静脉回流受阻的肢体，气性坏疽是湿性坏疽的一种，系深达肌肉的开放性创伤，合并产气荚膜杆菌等厌氧菌感染。","","N"],["2019-N126",2,"第4节 栓塞","减压病",2019,126,"B","","深度潜水快速上浮时可能产生的栓塞是",[["A","脂肪栓塞"],["B","氮气栓塞"],["C","空气栓塞"],["D","血栓栓塞"]],"B","深度潜水快速上浮时可能产生的栓塞是氮气栓塞（B对），因为深度潜水时，人处于高气压环境下，吸入的气体（特别是氮气）可大量溶解在血液和组织中，当人体从高气压环境迅速进入常压或低气压环境时，原来溶于血液、组织液和脂肪组织的气体（包括氧气、二氧化碳和氮气）迅速游离形成气泡，氧和二氧化碳可再溶于体液内被吸收，但氮气在体液内溶解迟缓，故在血液和组织内形成很多微气泡或融合成大气泡，引起气体栓塞，故又称为氮气栓塞。","","N"],["2019-N127",2,"第4节 栓塞","血栓栓塞",2019,127,"B","","长骨骨折患者出院后卧床休息3周，起立后突然死亡的原因可能是",[["A","脂肪栓塞"],["B","氮气栓塞"],["C","空气栓塞"],["D","血栓栓塞"]],"D","长骨骨折后长期卧床，血流变慢甚至停滞，易形成下肢深静脉血栓，患者起床时肌肉挤压可致血栓脱落，引起致命的肺动脉栓塞，造成患者突然死亡（D对）。下肢骨折可导致骨髓内脂肪细胞破裂并释出脂滴，由破裂的骨髓血管窦状隙或静脉进入血液循环引起脂肪栓塞，脂肪栓塞典型症状约在损伤1～3天内出现，临床表现为突然发作性的呼吸急促、呼吸困难、心动过速和特征性的瘀斑性皮疹（A错）。","","N"],["2019-N148",0,"第3节 细胞可逆性损伤","玻璃样变的病理变化",2019,148,"X","","属于细胞内玻璃样变性的有",[["A","肺上皮细胞内病毒包涵体"],["B","肝细胞内的Mallory小体"],["C","肾小管上皮细胞内吸收蛋白"],["D","浆细胞中的Rusell小体"]],"BCD","细胞内或间质中出现半透明状蛋白质蓄积，称为玻璃样变，玻璃样变是一组形态学上物理性状相同，但其化学成分、发生机制各异的病变。根据病变部位，玻璃样变可分为细胞内玻璃样变、纤维结缔组织玻璃样变和细小动脉壁玻璃样变，肝细胞内的Mallory小体（B对）、肾小管上皮细胞内吸收蛋白（C对）和浆细胞中的Rusell小体（D对）均属于细胞内玻璃样变。病毒包涵体是病毒在增殖过程中，在寄主细胞内形成的一种蛋白质性质的病变结构，在光学显微镜下可见，多为圆形、卵圆形或不定形，一般是由完整的病毒颗粒或尚未装配的病毒亚基聚集而成。病毒包涵体是否为玻璃样变性存在争议：本题官方给出的参考答案为BCD，认为肺上皮细胞内病毒包涵体不属于玻璃样变性，然而2002N45A的参考答案却将狂犬病时神经细胞胞质内的病毒包涵体Negri小体归入了玻璃样变性。","","N"],["2019-N149",12,"第3节 滋养层细胞疾病","绒毛膜癌病理变化",2019,149,"X","","绒毛膜癌区别于恶性葡萄胎的病理特点有",[["A","呈浸润性生长"],["B","出血、坏死更明显"],["C","滋养细胞增生"],["D","无绒毛和水泡形成"]],"BD","绒毛膜癌是一种源自妊娠绒毛滋养层上皮的高度侵袭性恶性肿瘤，由于其肿瘤自身无间质血管，主要依靠侵袭宿主血管获取营养，故癌组织和周围正常组织有相比恶性葡萄胎更加明显出血坏死（B对）。绒毛膜癌的癌细胞不形成绒毛和水泡状结构，这一点和恶性葡萄胎（侵蚀性葡萄胎）明显不同（D对）。绒毛膜癌和恶性葡萄胎均呈浸润性生长（A错），均有滋养细胞增生（C错）。","","N"],["2019-N150",3,"第3节 慢性炎症","主要的慢性炎症细胞",2019,150,"X","","来源于单核巨噬细胞系统的细胞有",[["A","小胶质细胞"],["B","伤寒细胞"],["C","心衰细胞"],["D","Langhans巨细胞"]],"ABCD","小胶质细胞（A对）属单核巨噬细胞系统，各种损伤均可导致其快速活化，对损伤的常见反应有噬神经细胞现象等。伤寒细胞（B对）是伤寒杆菌引起机体炎症时，吞噬伤寒杆菌、红细胞和细胞碎片的巨噬细胞。心衰细胞（C对）是慢性肺淤血时候吞噬含铁血黄素的巨噬细胞。Langhans巨细胞（朗汉斯巨细胞）（D对）是结核结节中的多核巨细胞，多核巨细胞由巨噬细胞转变而来。故以上各细胞均来源于单核巨噬细胞系统。","","N"],["2019-N151",9,"第3节 消化性溃疡病","消化性溃疡病的病理变化",2019,151,"X","","消化性溃疡好发部位是",[["A","十二指肠球部"],["B","十二指肠升部"],["C","胃窦部小弯侧"],["D","胃窦部大弯侧"]],"AC","消化性溃疡以胃或十二指肠黏膜形成慢性溃疡为主要表现，本病多反复发作呈慢性病程，十二指肠溃疡较胃溃疡多见，前者多发生在十二指肠球部（A对B错），后者多发生于胃窦部小弯侧（C对），胃底和胃大弯侧少见（D错）。","","N"],["2019-N152",9,"第6节 病毒性肝炎","病毒性肝炎的发病机制",2019,152,"X","","能引起慢性肝炎的肝炎病毒有",[["A","甲型肝炎病毒"],["B","乙型肝炎病毒"],["C","丙型肝炎病毒"],["D","戊型肝炎病毒"]],"BC","目前已证实能引起病毒性肝炎的肝炎病毒有甲型（HAV）、乙型（HBV）、丙型（HCV）、丁型（HDV）、戊型（HEV）和庚型（HGV）共六型，除甲型和戊型和庚型外（BC对AD错），均可引起慢性肝炎。","","N"],["2019-N153",1,"第2节 纤维性修复","肉芽组织的作用及结局",2019,153,"X","","关于肉芽组织正确的描述有",[["A","是不完全修复的必经之路"],["B","老化时血管和胶原纤维明显增加"],["C","有数量不等的炎症细胞"],["D","含有毛细血管和成纤维细胞"]],"ACD","修复过程可概括为两种不同的形式：①由损伤周围的同种细胞来修复，称为再生。如果完全恢复了原组织的结构及功能，则称为完全再生。②由纤维结缔组织来修复，称为纤维性修复，以后形成瘢痕，故也称瘢痕修复或不完全修复，这种修复通过肉芽组织增生（A对），溶解、吸收损伤局部的坏死组织及其他异物，并填补组织缺损，以后肉芽组织转化成以胶原纤维为主的瘢痕组织，修复才告完成。肉芽组织（十版病理学P33）由新生薄壁的毛细血管以及增生的成纤维细胞构成（D对），并伴有炎细胞浸润（C对）。老化的肉芽组织部分毛细血管管腔闭塞，数目减少（B错），改建为小动脉和小静脉，成纤维细胞产生胶原纤维数目增多，而成纤维细胞本身数目减少。","","N"],["2020-N29",0,"第1节 适应","失用性萎缩",2020,29,"A","","左下肢股骨干骨折固定6周后，左下肢明显比右下肢细。这种病变属于",[["A","压迫性萎缩"],["B","失用性萎缩"],["C","去神经性萎缩"],["D","损伤性萎缩"]],"B","左下肢股骨干骨折固定后，可因左下肢制动，活动量及负荷减小，代谢低下，而出现失用性萎缩（B对），导致左下肢比右下肢细。压迫性萎缩（十版病理学P6）（A错）因组织与器官长期受压迫所致，如肝、脑、肺肿瘤推挤压迫，可致邻近正常组织萎缩。去神经性萎缩（十版病理学P6）（C错）因运动神经元或者轴突损害所致，如脑或脊髓神经损伤可致肌肉萎缩。损伤性萎缩（十版病理学P6）（D错）可因慢性炎症所致，如慢性胃炎时胃黏膜萎缩和慢性肠炎时小肠黏膜绒毛萎缩，也可因细胞凋亡所致，如阿尔茨海默病的大脑萎缩。","","N"],["2020-N30",2,"第3节 血栓形成","血栓形成的概念",2020,30,"A","","在下列病变中，被称为血栓的是",[["A","活体中血管内的血凝块"],["B","活体中关节腔内的血凝块"],["C","活体中组织间的血凝块"],["D","活体中腹膜腔内的血凝块"]],"A","在活体的心脏和血管内血液发生凝固（A对）或血液中某些有形成分凝集形成固体质块的过程，称为血栓形成。","","N"],["2020-N31",0,"第4节 细胞不可逆性损伤（细胞死亡）","凝固性坏死",2020,31,"A","","肾贫血性梗死的组织坏死类型属于",[["A","凝固性坏死"],["B","液化性坏死"],["C","溶解性坏死"],["D","纤维素样坏死"]],"A","肾贫血性梗死的病理组织分型是凝固性坏死（A对）。凝固性坏死指坏死组织呈灰白、干燥的凝固状，尚保留有原组织的细胞轮廓的坏死类型，凝固性坏死可发生于除脑以外的所有组织，但多见于脾、肾和心等实质器官的缺血性坏死。液化性坏死（B错）见于细菌或某些感染引起的脓肿、缺血缺氧引起的脑软化，以及由细胞水肿发展而来的溶解性坏死（C错）等。纤维素样坏死（D错）是结缔组织及小血管壁常见的坏死形式，常见于某些变态反应性疾病，如风湿病、结节性多动脉炎、新月体性肾小球肾炎，以及急进型高血压和胃溃疡底部小血管等。","","N"],["2020-N32",5,"第5节 肿瘤的分级和分期","肿瘤分期",2020,32,"A","","下列情况中，与肿瘤分期有关的是",[["A","癌细胞分化程度差"],["B","癌细胞分泌黏液"],["C","癌细胞核分裂象明显增多"],["D","癌细胞浸润的深度"]],"D","肿瘤的“分期”是指恶性肿瘤的生长范围和播散程度。肿瘤体积越大，生长范围和播散程度越广，患者预后越差。对肿瘤进行分期，需要考虑以下因素：原发肿瘤的大小，浸润深度（D对），浸润范围，邻近器官受累情况，局部和远处淋巴结转移情况，远处转移等。肿瘤细胞分化程度（A错）、肿瘤细胞核分裂象（C错）为肿瘤细胞分级的依据。","","N"],["2020-N33",4,"第3节 器官和骨髓移植排斥反应","细胞型排斥反应",2020,33,"A","","下列淋巴细胞中，与急性细胞型排斥反应密切相关的是",[["A","CD3+细胞"],["B","CD20+细胞"],["C","CD30+细胞"],["D","CD68+细胞"]],"A","急性细胞型排斥反应常发生在移植后数月，是以T细胞介导的细胞免疫为主的急性排斥反应。T细胞介导的细胞免疫与CD3分子（A对）密切相关，后者可将TCR（T细胞抗原受体）识别抗原所产生的活化信号转导至T细胞内。","","N"],["2020-N34",7,"第1节 动脉粥样硬化","心肌梗死",2020,34,"A","","急性透壁性心肌梗死患者3周后死亡，解剖时梗死灶内的主要发现是",[["A","心肌细胞出现核固缩"],["B","心肌细胞出现核碎裂"],["C","梗死灶周围肉芽组织形成"],["D","大片纤维疤痕（应为“瘢痕”）形成"]],"C","急性透壁性心肌梗死是典型的心肌梗死类型，其病理变化是一个动态的演变过程，在梗死6小时内，基本无肉眼可见的变化，6小时后，坏死灶心肌组织呈苍白色，8～9小时后呈土黄色，光镜下心肌纤维早期呈凝固型坏死，如核碎裂（B 错）、核消失（A 错）、肌质均匀红染或呈不规则粗颗粒状，间质水肿，漏出性出血及不同程度的中性粒细胞浸润，3 ～7天时，在梗死灶周边开始肉芽组织增生，梗死区开始机化，间质水肿，常见出血，7天～2周边缘区开始出现肉芽组织，或肉芽组织向梗死灶内长入，呈红色，3周后，在新生的肉芽组织中，出现较多的纤维母细胞和胶原纤维，肉芽组织开始机化，6周后，坏死的心肌已逐渐被形成的瘢痕组织所替代（中华外科病理学P180）。对心肌修复过程的大致了解，有助于患者确定合适的下床活动时间。本例患者急性透壁性心肌梗死3周后死亡，解剖时梗死灶的主要表现应为梗死灶周围肉芽组织形成（C对），此时肉芽组织刚开始机化，未出现大片纤维疤痕形成（D错）。","","N"],["2020-N35",7,"第5节 感染性心内膜炎","亚急性感染性心内膜炎",2020,35,"A","","风湿性心脏瓣膜病并发亚急性感染性心内膜炎的主要病原体是",[["A","A群溶血性链球菌"],["B","草绿色链球菌"],["C","金黄色葡萄球菌"],["D","肺炎链球菌"]],"B","风湿性瓣膜病主要与A群溶血性链球菌感染（A错）相关，而并发亚急性心内膜炎，主要是草绿色链球菌（B对）多见。急性感染性心内膜炎（十版病理学P157）以金黄色葡萄球菌（C错）最为多见，少数为肺炎球菌（D错）、A 族链球菌、流感杆菌和淋球菌等。","","N"],["2020-N36",8,"第8节 呼吸系统常见肿瘤","EB病毒",2020,36,"A","","与EB病毒感染密切相关的肿瘤是",[["A","肺鳞癌"],["B","宫颈鳞癌"],["C","胃腺癌"],["D","鼻咽癌"]],"D","EB（Epstein-Barr）病毒是Epstein和Barr两位科学家于1964年首次在Burkitt非洲儿童淋巴瘤细胞内发现的一种疱疹病毒。EB病毒主要感染人类口咽部的上皮细胞和B淋巴细胞，该病毒是多种恶性肿瘤的致病病因之一，包括鼻咽癌（D对）、Burkitt淋巴瘤（十版病理学P233）、NK/T 细胞淋巴瘤（十版病理学P236）、霍奇金淋巴瘤（十版病理学P239）等。","","N"],["2020-N37",11,"第2节 肾小管间质性肾炎","慢性肾盂肾炎病理变化",2020,37,"A","","慢性肾盂肾炎可见的病理学改变是",[["A","肾小球囊壁层新月体形成"],["B","肾间质内出现较多的小脓肿"],["C","肾小球囊壁纤维化"],["D","肾小球毛细血管袢与囊壁粘连"]],"C","慢性肾盂肾炎为肾小管间质的慢性炎症。病变特点是慢性间质性炎症、纤维化和瘢痕形成，早期肾小球很少受累，但肾小球囊壁可发生纤维化（C对），后期部分肾小球发生玻璃样变和纤维化。肾小球囊壁层新月体形成（A错）见于急进性肾小球肾炎（十版病理学P255）。肾间质内出现较多小脓肿（B错）多见于急性肾盂肾炎（十版病理学P263）和慢性肾盂肾炎急性发作（十版病理学P264）。肾小球毛细血管袢与囊壁粘连（D错）可见于局灶性节段性肾小球硬化（十版病理学P259）。","","N"],["2020-N38",12,"第1节 子宫颈疾病","子宫颈鳞状细胞癌",2020,38,"A","","在子宫颈活检组织中，见异型上皮细胞累及全层并突破基底膜向下生长3mm，应诊断为",[["A","子宫颈原位癌"],["B","子宫颈原位癌累及腺体"],["C","子宫颈早期浸润癌"],["D","子宫颈浸润癌"]],"C","在子宫颈活检组织中，见异型上皮细胞累及全层并突破基底膜向下生长3mm，可诊断为子宫颈早期浸润癌（C对），因为子宫颈早期浸润癌的诊断标准为癌细胞突破基底膜，向固有膜间质内浸润但浸润深度不超过基底膜下5mm。子宫颈浸润癌（D错）是指癌细胞突破基底膜，向固有膜间质内浸润，且浸润深度超过基底膜下5mm或浸润宽度超过7mm。子宫颈原位癌（A错）是指异型增生的细胞累及子宫颈黏膜上皮全层，但病变局限于上皮内，未突破基膜。原位癌累及腺体（B错）是指原位癌的细胞由表面沿基底膜通过宫颈腺口蔓延至子宫颈腺体内，取代部分或全部腺上皮，但仍未突破腺体的基底膜的情况，仍然属于原位癌范畴。","","N"],["2020-N39",16,"第10节 寄生虫病","急性虫卵结节",2020,39,"A","","急性血吸虫病由虫卵引起的早期基本病理变化是",[["A","嗜酸性脓肿"],["B","假结核结节"],["C","钙化虫卵"],["D","肝纤维化"]],"A","急性血吸虫病虫卵结节引起的早期基本病理变化是嗜酸性脓肿（A对）。假结核结节（B错）、钙化虫卵（C错）及肝纤维化（D错）见于慢性虫卵结节。","","N"],["2020-N40",13,"第2节 甲状腺疾病","乳头状癌",2020,40,"A","","甲状腺肿块活检，镜下见肿瘤细胞呈滤泡状生长，细胞核呈典型毛玻璃样改变，核重叠，有核沟。该肿瘤应诊断为",[["A","小滤泡型腺瘤"],["B","滤泡癌"],["C","髓样癌"],["D","乳头状癌"]],"D","根据细胞核呈典型毛玻璃样改变的镜下特点，可将此病例诊断为乳头状癌（D对）。小滤泡型腺瘤（A错）、滤泡癌（B错）和髓样癌（C错）镜下均可见癌细胞呈滤泡状排列，但癌细胞核不会呈典型毛玻璃样改变。","","N"],["2020-N41",16,"","",2020,41,"A","","男性，23岁。4天前东南亚旅游归来后突发寒战、高热，体温达40.1℃，持续约2小时左右，未经特殊处理自行退热，体温降至36.2℃，伴大汗，自觉轻度乏力，无其他不适。1天前再次发热，症状同4天前而来院。查体：心肺未见异常，腹软，脾肋下可触及，血化验：WBC2.2×10⁹/L。最可能的诊断是",[["A","败血症"],["B","伤寒"],["C","疟疾"],["D","肾综合征出血热"]],"C","青年男性患者，有疟疾高发地区旅游史，4天前突发寒战高热，体温40.1℃，持续约2小时左右，未经处理自行退热，体温降至36.2℃，伴大汗，自觉轻度乏力，无其他不适（间歇热，同时是疟疾发作的典型临床表现），1天前再次发热，症状同4天前来院检查（疟疾两次发作之间有间歇期），查体心肺未见异常，腹软，脾脏肋下可触及（反复发作导致红细胞大量破坏，引起肝脾肿大），实验室检查：血常规 WBC2.2×10⁹/L（正常值3.5～9.5×10⁹/L，疟疾时白细胞可减少），根据患者既往史、临床表现体征和实验室检查，该患者最可能的诊断是疟疾（C对）。败血症（A错）白细胞计数升高明显，体温特征常为弛张热（败血症热型），体温常在39℃以上，波动幅度大，24小时内波动范围超过2℃，但都在正常水平以上。伤寒（B错）是由伤寒杆菌引起的一种急性肠道传染病。临床特征为持续发热、表情淡漠、相对缓脉、玫瑰皮疹、肝脾肿大和白细胞少等。有时可出现肠出血、肠穿孔等严重并发症，体温特征常为稽留热，即体温恒定地维持在39～40℃以上的高水平，达数天或数周，24小时内体温波动范围不超过1℃。肾综合征出血热（D错）热型以稽留热和弛张热多见，少数表现为不规则，是由汉坦病毒属的各型病毒引起，鼠类为其主要传染源，本病的主要病理变化是全身小血管和毛细血管广泛性损害，临床上以发热、低血压休克、充血出血和肾损害为主要表现。","","N"],["2020-N124",3,"第1节 炎症概述","炎症的全身反应",2020,124,"B","","急性细菌性炎症的早期主要渗出细胞是",[["A","中性粒细胞"],["B","巨噬细胞"],["C","嗜酸性粒细胞"],["D","淋巴细胞"]],"A","多数细菌感染引起中性粒细胞（A对）增加，寄生虫感染和过敏反应引起嗜酸性粒细胞（C错）增加，一些病毒感染选择性地引起单核巨噬细胞（B错）和淋巴细胞（D错）比例增加，如单核细胞增多症、腮腺炎和风疹等。","","N"],["2020-N125",3,"第1节 炎症概述","炎症的全身反应",2020,125,"B","","寄生虫感染性炎症的早期主要渗出细胞是",[["A","中性粒细胞"],["B","淋巴细胞"],["C","嗜酸性粒细胞"],["D","巨噬细胞"]],"C","多数细菌感染引起中性粒细胞（A错）增加，寄生虫感染和过敏反应引起嗜酸性粒细胞（C对）增加，一些病毒感染选择性地引起单核巨噬细胞（D错）和淋巴细胞（B错）比例增加，如单核细胞增多症、腮腺炎和风疹等。","","N"],["2020-N126",10,"第2节 淋巴组织肿瘤","前体B细胞的概述",2020,126,"B","","儿童淋巴细胞肿瘤中，常以白血病形式发病的肿瘤是",[["A","前体B细胞肿瘤"],["B","前体T细胞肿瘤"],["C","成熟B细胞肿瘤"],["D","成熟T细胞肿瘤"]],"A","前体淋巴细胞肿瘤，即急性淋巴母细胞白血病／淋巴瘤（ALL），是不成熟的前体淋巴细胞（又称淋巴母细胞）来源的一类高度侵袭性肿瘤，包括B淋巴母细胞白血病／淋巴瘤（B-ALL）、T淋巴母细胞白血病／淋巴瘤（T- ALL）两种类型。B-ALL患者多为儿童，常表现为白血病（A对），一般有广泛的骨髓累及和外周血白细胞数量增加。T-ALL患者多为青少年（B错），表现为局部包块，常累及胸腺。在儿童淋巴细胞瘤中，成熟B淋巴细胞来源的多为Burkitt淋巴瘤，即常以淋巴瘤形式发病（C错）。成熟T淋巴细胞来源的淋巴瘤多见于中老年患者（D错）。","","N"],["2020-N127",10,"第2节 淋巴组织肿瘤","T细胞淋巴瘤的概述",2020,127,"B","","儿童淋巴细胞肿瘤中，常以淋巴瘤形式发病的肿瘤是",[["A","前体B细胞肿瘤"],["B","前体T细胞肿瘤"],["C","成熟B细胞肿瘤"],["D","成熟T细胞肿瘤"]],"B","前体T细胞肿瘤（B对）多见于青少年，也可见于儿童，表现为局部包块，常累及胸腺。前体B淋巴细胞肿瘤（B-ALL）（A错）患者多为儿童，但发病形式主要为白血病。成熟T淋巴细胞（D错）来源的淋巴瘤多见于中老年。成熟B细胞肿瘤根据起源不同分为若干类型，大多数类型见于中老年，个别类型见于儿童（和青少年），发生在儿童时常以淋巴瘤的形式发病（Burkitt 淋巴瘤），故C选项也可选。本题的参考答案为B。","","N"],["2020-N148",0,"第3节 细胞可逆性损伤","脂肪变的病理变化",2020,148,"X","","下列病变中，属于脂肪变性的有",[["A","心肌细胞间出现脂肪细胞"],["B","肾小管上皮细胞中出现脂滴"],["C","心肌细胞中出现脂滴"],["D","肝细胞水肿，内含大量红染细颗粒状物"]],"BC","甘油三酯蓄积于非脂肪细胞的细胞质中，称为脂肪变，肾小管上皮细胞内出现脂滴（B对）和心肌细胞中出现脂滴（C对）均属于脂肪变性。心肌细胞间出现脂肪细胞（A错）称为心肌脂肪浸润，并非心肌细胞脂肪变性。肝细胞水肿，内含大量红染细颗粒状物质（D错）属于细胞水肿，而不属于脂肪变性。","","N"],["2020-N149",5,"第1节 肿瘤的概念","概念",2020,149,"X","","下列情况中，属于肿瘤增生特点的有",[["A","增生与机体不协调"],["B","增生多为多克隆性"],["C","增生具有相对的自主性"],["D","增生具有无限增殖的潜能"]],"ACD","肿瘤是机体的细胞异常增殖形成的新生物，常表现为机体局部的异常组织团块（肿块），肿瘤形成是在各种致瘤因素的作用下，细胞生长调控发生严重紊乱的结果，这种导致肿瘤形成的细胞增生称为肿瘤性增生（增殖）。肿瘤性增生与非肿瘤性增生有重要区别：①肿瘤性增生与机体不协调（A对），对机体有害。②肿瘤性增生一般是单克隆的（B错），即由单个细胞反复分裂繁殖产生。③肿瘤细胞的形态、代谢和功能均有异常，不同程度地失去了分化成熟的能力。④肿瘤细胞生长旺盛，失去控制，具有相对自主性（C对）和无限增殖的潜能（D对）。","","N"],["2020-N150",8,"第2节 慢性阻塞性肺疾病","慢性支气管炎的病理变化",2020,150,"X","","在慢性支气管炎中常见的病变有",[["A","柱状上皮纤毛脱落"],["B","支气管上皮鳞状化生"],["C","支气管管壁软骨变性、萎缩"],["D","支气管腺体黏液腺化生"]],"ABCD","慢性支气管炎是发生于支气管黏膜及其周围组织的慢性非特异性炎性疾病，早期病变多局限于较大的支气管，随病情进展逐渐累及较小的支气管及细支气管。主要病变表现为：①呼吸道黏液-纤毛排送系统受损，纤毛柱状上皮变性、坏死脱落（A对），再生的上皮杯状细胞增多，并发生鳞状上皮化生（B对）；②黏膜下腺体增生肥大和浆液性上皮发生黏液腺化生（D对），导致黏液分泌增多；③管壁充血水肿，淋巴细胞、浆细胞浸润；④管壁平滑肌断裂、萎缩（喘息型者：平滑肌束增生、肥大）（C对），软骨可变性、萎缩或骨化。","","N"],["2020-N151",9,"第6节 病毒性肝炎","亚急性重型肝炎的病理变化",2020,151,"X","","亚急性重型肝炎的病理特点有",[["A","肝细胞亚大块坏死"],["B","肝细胞再生结节形成"],["C","残存肝细胞出现明显异型"],["D","网状纤维支架塌陷"]],"ABD","亚急性重型肝炎病程较长（数周至数月），多数由急性重型肝炎迁延而来。镜下特点为既有肝细胞的亚大块坏死（A对），又有结节状肝细胞再生（B对）。坏死区网状纤维支架塌陷（D对）和胶原化（无细胞硬化），因而使残存的肝细胞再生时不能沿原有支架排列，呈结节状。肝细胞出现明显异型性多见于分化程度较低的肝细胞癌（C错）。","","N"],["2020-N152",9,"第12节 消化系统常见肿瘤","中晚期胃癌（进展期胃癌）的概述",2020,152,"X","","下列病变中，属于胃癌晚期的有",[["A","癌细胞浸润至黏膜下层"],["B","癌细胞转移到局部淋巴结"],["C","癌细胞转移到双侧卵巢"],["D","癌细胞转移到左锁骨上淋巴结"]],"CD","消化道管壁由内至外依次可分为黏膜层、黏膜下层、肌层和浆膜层共四层，黏膜层又可分为黏膜上皮层（含基底膜）、黏膜固有层和黏膜肌层三个部分。早期胃癌指癌组织浸润仅限于黏膜层或黏膜下层（A错），无论有无淋巴结转移（即早期胃癌也可有局部淋巴结转移）（B错）。胃癌晚期癌细胞的转移途径包括：①淋巴道转移：晚期可经胸导管转移至左锁骨上淋巴结（D对）；②血道转移：常经门静脉转移至肝，也可转移到肺、脑及骨等器官；③种植性转移：胃癌特别是胃黏液癌癌细胞浸润至胃浆膜表面时可脱落至腹腔，种植于腹腔及盆腔器官的浆膜上，常在双侧卵巢（C对）形成转移性黏液癌，称克鲁根勃瘤。","","N"],["2020-N153",11,"第1节 肾小球疾病","急进性肾小球肾炎发病机制",2020,153,"X","","在肾炎肾穿刺活检切片中，发现颗粒型的免疫荧光，该患者的肾脏疾病可能的类型有",[["A","肺出血肾炎综合征"],["B","链球菌感染后性肾炎"],["C","狼疮性肾炎"],["D","IgA肾病"]],"BCD","肺出血性肾炎综合征（A错）为Ⅰ型急进性肾小球肾炎的特殊类型，Ⅰ型急进性肾小球肾炎为抗肾小球基膜抗体引起的肾炎，免疫荧光检查显示特征性的线性荧光。链球菌感染后性肾炎（B对）、狼疮性肾炎（C对）和IgA肾病（D对）为不同原因引起的免疫复合物性肾炎，免疫荧光检查显示颗粒状荧光，以上免疫复合物性肾炎可发展形成Ⅱ型急进性肾小球肾炎。","","N"],["2021-N29",0,"第1节 适应","化生的概念",2021,29,"A","","关于化生的描述，错误的是",[["A","由成熟细胞转变所致"],["B","可增强局部抵御刺激的能力"],["C","通常发生在同源性细胞之间"],["D","可发生在上皮组织或间叶组织"]],"A","化生并不是由原来的成熟细胞直接转变所致（A错，为本题正确答案），而是该处的干细胞或结缔组织中的未分化间充质细胞发生转分化的结果，化生的生物学意义利弊兼有，一方面可增强局部抵御外界刺激的能力（B对），另一方面也可能引起细胞恶变。化生通常发生在同源性细胞之间（C对），如上皮细胞之间或间叶细胞之间（D对），一般是由特异性较低的细胞类型来取代特异性较高的细胞类型。","","N"],["2021-N30",0,"第4节 细胞不可逆性损伤（细胞死亡）","纤维素样坏死",2021,30,"A","","细小动脉管壁常发生的坏死类型是",[["A","凝固性坏死"],["B","液化性坏死"],["C","脂肪坏死"],["D","纤维素样坏死"]],"D","细小动脉管壁常发生的坏死类型是纤维素样坏死（D对），纤维素样坏死旧称纤维素样变性，是结缔组织及小血管壁常见的坏死形式。凝固性坏死（十版病理学P20）（A错）多见于心、肝、肾和脾等实质器官，常因缺血缺氧、细菌毒素、化学腐蚀剂作用引起；液化性坏死（十版病理学P20）（B错）见于细菌或某些真菌感染引起的脓肿、缺血缺氧引起的脑软化，以及由细胞水肿发展而来的溶解性坏死等；脂肪坏死（十版病理学P20）（C错）见于急性胰腺炎（细胞释放胰酶分解脂肪酸）和乳房创伤（脂肪细胞破裂）等情况。","","N"],["2021-N31",10,"第2节 淋巴组织肿瘤","结外边缘区黏膜相关淋巴组织淋巴瘤概述",2021,31,"A","","与黏膜相关淋巴组织淋巴瘤发生关系最密切的细菌是",[["A","金黄色葡萄球菌"],["B","草绿色链球菌"],["C","幽门螺杆菌"],["D","大肠埃希菌"]],"C","黏膜相关淋巴组织淋巴瘤（MALT淋巴瘤）多发生于胃肠道，与幽门螺杆菌（C对）的感染密切相关，黏膜内幽门螺杆菌的克隆增殖，使与黏膜上皮相关的淋巴组织产生免疫应答及局部炎症，并从无到有，发生免疫反应性淋巴增殖，由良性到恶性，产生异常克隆而导致淋巴瘤。","","N"],["2021-N32",9,"第6节 病毒性肝炎","大块及亚大块坏死",2021,32,"A","","急性重型肝炎中残留有少量肝细胞，其主要部位在",[["A","中央静脉周围"],["B","小叶周边"],["C","全小叶随机分布"],["D","残留网状支架旁"]],"B","急性重型肝炎镜下以肝细胞严重而广泛坏死（大块坏死）为特征，肝细胞坏死多从肝小叶中央开始并迅速向四周扩展，仅小叶周边（B对）部残留少许变性的肝细胞。","","N"],["2021-N33",4,"","",2021,33,"A","","女，45岁，自觉双手指关节疼痛2年余，近半年感觉关节僵硬，血清学检查显示类风湿因子阳性，该患者关节病理检查最可能出现的是",[["A","大量嗜酸性粒细胞浸润"],["B","肉芽肿性炎"],["C","非化脓性增生性滑膜炎"],["D","浆液渗出性炎"]],"C","女性患者45岁，关节僵硬，类风湿因子阳性，符合类风湿关节炎（RA）的临床表现和病理特点。类风湿关节炎是以多发性和对称性增生性滑膜炎（C对）为主要表现的慢性全身性自身免疫病，其镜下表现为滑膜细胞肥大增生及大量淋巴细胞、巨噬细胞和浆细胞等慢性炎症细胞浸润，为非化脓性炎症。","","N"],["2021-N34",9,"第12节 消化系统常见肿瘤","胃癌的概述",2021,34,"A","","胃癌的好发部位是",[["A","胃体前壁"],["B","胃体后壁"],["C","胃窦部"],["D","胃底"]],"C","胃癌是由胃黏膜上皮和腺上皮发生的恶性肿瘤，好发于胃窦部（C对）小弯侧。好发部位为胃体(AB错）及胃底（D错）的是A型慢性萎缩性胃炎（十版病理学P196）和慢性肥厚性胃炎（十版病理学P197）。","","N"],["2021-N35",2,"第1节 充血和淤血","肺淤血",2021,35,"A","","下列关于心衰细胞的描述，正确的是",[["A","心力衰竭时某些形态特殊的心肌细胞"],["B","肺内巨噬细胞吞噬炭沫形成的细胞"],["C","肺内巨噬细胞吞噬含铁血黄素形成的细胞"],["D","肺内巨噬细胞吞噬脂质形成的细胞"]],"C","心衰细胞常见于左心衰引起的慢性肺淤血，肺淤血时，部分巨噬细胞吞噬红细胞并将其分解，在胞浆内形成含铁血黄素（C对），这种巨噬细胞被称为心衰细胞。","","N"],["2021-N36",2,"第3节 血栓形成","透明血栓",2021,36,"A","","透明血栓的主要成分是",[["A","纤维蛋白"],["B","血小板"],["C","红细胞"],["D","白细胞"]],"A","透明血栓主要由嗜酸性同质性的纤维蛋白（A对）构成，又称为纤维素性血栓，最常见于 DIC。主要成分为血小板（B错）的是白色血栓（十版病理学P47）。主要成分为红细胞（C错）的是红色血栓（十版病理学P48）。","","N"],["2021-N37",8,"第4节 支气管扩张症","支气管扩张症的病理变化",2021,37,"A","","导致支气管扩张的主要病变基础是",[["A","支气管纤毛柱状上皮的鳞状上皮化生"],["B","支气管壁的黏液腺大量增生"],["C","支气管壁结构破坏"],["D","肺组织纤维化"]],"C","支气管扩张症多继发于慢性支气管炎、麻疹和百日咳后的支气管肺炎及肺结核病等。因反复感染，特别是化脓性炎症常导致管壁平滑肌、弹力纤维和软骨等支撑结构破坏（C对）；同时受支气管壁外周肺组织慢性炎症所形成的纤维瘢痕组织的牵拉及咳嗽时支气管腔内压的增加，最终导致支气管壁持久性扩张。","","N"],["2021-N38",11,"第1节 肾小球疾病","急性弥漫性增生性肾小球肾炎病理变化",2021,38,"A","","电镜下，驼峰状致密物沉积在肾小球毛细血管基膜表面的是哪一种肾小球疾病",[["A","急进性肾小球肾炎"],["B","急性弥漫性增生性肾小球肾炎"],["C","系膜增生性肾小球肾炎"],["D","膜增生性肾小球肾炎"]],"B","急性弥漫性增生性肾小球肾炎（B对）电镜检查显示电子密度较高的沉积物，通常呈驼峰状，多位于脏层上皮细胞和肾小球基膜之间，也可位于内皮细胞下，基膜内或细胞区。急进性肾小球肾炎（十版病理学P255）（A错）分三型，Ⅰ型和Ⅲ型无电子致密物沉积，Ⅱ型系膜区和内皮下有电子致密物沉积。系膜增生性肾小球肾炎（十版病理学P258）（C错），部分病例系膜区见有电子致密物沉积。膜增生性肾小球肾炎（十版病理学P257）（D错）分两型，Ⅰ型和Ⅱ型电镜下均可见电子致密物沉积，其中Ⅱ型又称致密沉积物病，可见大量块状电子密度极高的沉积物在基膜致密层呈带状沉积。","","N"],["2021-N39",12,"第3节 滋养层细胞疾病","绒毛膜癌病理变化",2021,39,"A","","绒毛膜癌的组织学特点",[["A","肿瘤本身无间质血管"],["B","肿瘤组织出血坏死不明显"],["C","癌细胞形成绒毛结构"],["D","由分化不良的细胞滋养细胞构成"]],"A","绒毛膜癌肿瘤自身无间质血管（A对），依靠侵袭宿主血管获取营养，故癌组织和周围正常组织有明显出血坏死（B错），有时癌细胞大多坏死，仅在边缘部查见少数残存的癌细胞。绒毛膜癌瘤组织由分化不良的似细胞滋养层和似合体细胞滋养层两种瘤细胞组成（D错），细胞异型性明显，核分裂相易见。绒毛膜癌细胞不形成绒毛（C错）和水泡状结构。","","N"],["2021-N40",13,"第2节 甲状腺疾病","髓样癌",2021,40,"A","","间质内有淀粉样物质沉积的甲状腺肿瘤是",[["A","未分化癌"],["B","髓样癌"],["C","滤泡状癌"],["D","乳头状癌"]],"B","间质内有淀粉样物质沉积的甲状腺肿瘤是髓样癌（B对），淀粉样物质的形成可能与降钙素的分泌有关。未分化癌（A错）光镜下，癌细胞大小、形态不一，核分裂象多。滤泡癌（C错）光镜下，可见不同分化程度的滤泡，分化极好的滤泡癌很难与腺瘤区别，分化差的呈实性巢片状，瘤细胞呈显著异型性，滤泡少且含胶质量少。乳头状癌（D错）光镜下乳头分支多，乳头中心有纤维血管间质，间质内常见呈同心圆状的钙化小体，即砂粒体，有浸润，有助于诊断。","","N"],["2021-N124",8,"第1节 呼吸道和肺炎症性疾病","小叶性肺炎的病理变化",2021,124,"B","","属于纤维素性炎的是",[["A","大叶性肺炎"],["B","小叶性肺炎"],["C","支原体肺炎"],["D","病毒性肺炎"]],"A","属于纤维素性炎的是大叶性肺炎（A对）。小叶性肺炎（十版病理学P174）（B错）为化脓性炎。支原体肺炎（C错）和病毒性肺炎（D错）为间质性炎。","","N"],["2021-N125",8,"第1节 呼吸道和肺炎症性疾病","小叶性肺炎的病理变化",2021,125,"B","","属于化脓性炎的是",[["A","大叶性肺炎"],["B","小叶性肺炎"],["C","支原体肺炎"],["D","病毒性肺炎"]],"B","属于化脓性炎的是小叶性肺炎（B对）。大叶性肺炎（A错）为纤维素性炎。支原体肺炎（C错）和病毒性肺炎（D错）为间质性炎。","","N"],["2021-N126",16,"第2节 结核病","浸润型肺结核",2021,126,"B","","最常见的肺结核类型是",[["A","局灶型肺结核"],["B","浸润型肺结核"],["C","慢性纤维空洞型肺结核"],["D","干酪性肺炎"]],"B","肺结核分为原发性和继发性肺结核病两大类。原发性肺结核病是第一次感染结核杆菌所引起的肺结核病，多发生于儿童，但也偶见于未感染过结核杆菌的青少年或成人。继发性肺结核病是指再次感染结核杆菌所引起的肺结核病，多见于成人，继发性肺结核病根据病变特点和临床经过又可分为局灶型肺结核（A错）、浸润型肺结核、慢性纤维空洞型肺结核（C错）、干酪性肺炎（D错）、结核球、结核性胸膜炎等不同类型，其中以浸润型肺结核（B对）最为常见。","","N"],["2021-N127",16,"第2节 结核病","干酪性肺炎",2021,127,"B","","病情危重，中毒症状明显的肺结核类型是",[["A","局灶型肺结核"],["B","浸润型肺结核"],["C","慢性纤维空洞型肺结核"],["D","干酪性肺炎"]],"D","干酪性肺炎可由浸润型肺结核恶化进展而来，也可由急、慢性空洞内的细菌经支气管播散所致，多发生在机体免疫力和体质衰弱，又受到大量结核分枝杆菌感染的病人，此型结核病病情危重，中毒症状明显，病死率较高。","","N"],["2021-N148",3,"第2节 急性炎症","化脓性炎",2021,148,"X","","下列属于化脓性炎的疾病有",[["A","阿米巴肝脓肿"],["B","疖"],["C","流行性脑脊髓膜炎"],["D","流行性乙型脑炎"]],"BC","疖（B对）是毛囊、皮脂腺及其周围组织的脓肿，属于化脓性炎。流行性脑脊髓膜炎（C对）是由脑膜炎双球菌感染引起的脑脊髓膜的急性化脓性炎。阿米巴肝脓肿（A错）和流行性乙型脑炎（D错）均属于变质性炎。","","N"],["2021-N149",3,"第3节 慢性炎症","肉芽肿性炎的常见类型",2021,149,"X","","下列属于肉芽肿性病变的是",[["A","砂粒体"],["B","结核结节"],["C","风湿小体"],["D","伤寒小结"]],"BCD","肉芽肿性病变以炎症局部巨噬细胞及其衍生细胞增生形成境界清楚的结节状病灶（即肉芽肿）为特征，是一种特殊类型的慢性炎症。结核结节（B对）又称结核性肉芽肿，由上皮样细胞（吞噬有结核杆菌的巨噬细胞）、朗汉斯巨细胞（上皮样细胞融合而成）、外周局部集聚的淋巴细胞和少量反应性增生的成纤维细胞构成。风湿小体（C对）为风湿病增生期形成的特征性肉芽肿性病变，由聚集于纤维素样坏死灶内的成群风湿细胞（由增生的巨噬细胞吞噬纤维素样坏死物质后转变而来）及少量的淋巴细胞和浆细胞构成。伤寒小结（D对）又称伤寒肉芽肿，由聚集的伤寒细胞（吞噬有伤寒杆菌、红细胞和细胞碎片的巨噬细胞）组成。砂粒体（A错）是甲状腺乳头状癌乳头纤维血管间质内的钙化物质，不属于肉芽肿性病变。","","N"],["2021-N150",5,"第9节 癌前病变和原位癌","癌前病变",2021,150,"X","","下列属于癌前病变的是",[["A","黏膜白斑"],["B","慢性非萎缩性胃炎"],["C","慢性溃疡性结肠炎"],["D","大肠绒毛状腺瘤"]],"ACD","某些病变虽然本身不是恶性肿瘤，但具有发展为恶性肿瘤的潜能，患者发生相应恶性肿瘤的风险增加，这些病变称为癌前病变。黏膜白斑（A对）、慢性溃疡性结肠炎（C对）和大肠绒毛状腺瘤（D对）均属于癌前病变。慢性非萎缩性胃炎（十版病理学P196）（B错）又称慢性浅表性胃炎或慢性单纯性胃炎，不属于癌前病变，属于癌前病变的是慢性萎缩性胃炎（伴肠腺化生及异型增生时可能导致癌变）。","","N"],["2021-N151",13,"第2节 甲状腺疾病","乳头状癌",2021,151,"X","","下列关于甲状腺乳头状癌正确的是",[["A","肿瘤细胞核内可见假包涵体"],["B","患者预后与局部淋巴结转移有关"],["C","肿瘤间质可见淀粉样组织沉积"],["D","肿瘤细胞核呈毛玻璃样"]],"AD","甲状腺乳头状癌光镜下乳头分支多，乳头中心有纤维血管间质，间质内常见呈同心圆状的钙化小体，即砂粒体，有浸润，有助于诊断。乳头上皮常呈单层，癌细胞核染色质少，常呈透明毛玻璃样（D对）， 无核仁，有核沟，核内假包涵体（A对），核相互重叠。 甲状腺乳头状癌局部淋巴结转移较早，但预后好、恶性程度低，淋巴结转移与预后并无明显关联（B错）。细胞间质可见淀粉样组织沉积（C错）为甲状腺髓样癌的特征性表现。","","N"],["2021-N152",9,"第8节 肝硬化","门脉高压症的概述(1)",2021,152,"X","","下列由于门静脉高压导致的病变有",[["A","脾淤血肿大"],["B","胃底静脉曲张"],["C","蜘蛛痣"],["D","胃肠道淤血水肿"]],"ABD","肝硬化晚期因严重的肝实质破坏和肝脏结构及血管的改建，导致门静脉高压症和肝功能障碍。门静脉压力升高后，患者出现一系列症状和体征，主要有：（1）慢性淤血性脾大（A对）；（2）腹水；（3）侧支循环形成，如门静脉血经胃冠状静脉、食管静脉丛、奇静脉入上腔静脉引起胃底静脉曲张（B对）；（4）胃肠道淤血水肿（D对）。蜘蛛痣（C错）因肝功能障碍（对雌激素灭活作用减弱），导致体内雌激素水平升高、小动脉末梢扩张所致，与门静脉高压无关。","","N"],["2021-N153",0,"第3节 细胞可逆性损伤","玻璃样变的病理变化",2021,153,"X","","下列属于玻璃样变性的有",[["A","Aschoff小体"],["B","Rusell小体"],["C","Mallory小体"],["D","Apoptosis小体"]],"BC","细胞内或间质中出现半透明状蛋白质蓄积，称为玻璃样变性。玻璃样变是一组形态学上物理性状相同，但其化学成分、发生机制各异的病变。根据病变部位，玻璃样变可分为细胞内玻璃样变、纤维结缔组织玻璃样变和细小动脉壁玻璃样变。细胞内玻璃样变通常为均质红染的圆形小体，位于细胞质内。如肾小管上皮细胞具有吞饮作用的小泡，重吸收原尿中的蛋白质，与溶酶体融合，形成玻璃样小滴；浆细胞胞质粗面内质网中免疫球蛋白蓄积，形成Rusell小体（B对）； 酒精性肝病时，肝细胞胞质中细胞中间丝前角蛋白变性，形成 Mallory小体（C对）。Aschoff小体（A错）即风湿小体，是风湿病特征性的肉芽肿性病变，不属于玻璃样变性。Apoptosis小体（D错）即凋亡小体，是细胞凋亡的重要形态学标志，不属于玻璃样变性。","","N"],["2022-N29",2,"第3节 血栓形成","透明血栓",2022,29,"A","","弥散性血管内凝血时发生的血栓是",[["A","透明血栓"],["B","混合血栓"],["C","红色血栓"],["D","白色血栓"]],"A","弥漫性毛细血管内凝血（DIC）的血栓为透明血栓（A对），透明血栓主要由嗜酸性同质性的纤维蛋白构成，又称为纤维素性血栓。混合血栓（B错）多见于静脉内延续性血栓的体部，亦见于心腔内、动脉粥样硬化溃疡部位或动脉瘤内（由于血栓底部与心壁或血管壁相连，称为附壁血栓）。红色血栓（C错）主要见于静脉内，当混合血栓逐渐增大并阻塞血管腔时，血栓下游局部血流停止，血液发生凝固，成为静脉内延续性血栓的尾部。白色血栓（D错）常位于血流较快的心瓣膜、心腔内和动脉内，如急性风湿性心内膜炎二尖瓣闭锁缘上形成的血栓；在静脉性血栓中，白色血栓位于延续性血栓的起始部（血栓的头部）。","","N"],["2022-N30",5,"第5节 肿瘤的分级和分期","肿瘤分期",2022,30,"A","","肿瘤分期的依据是",[["A","肿瘤的生长范围和播散程度"],["B","肿瘤细胞的核分裂象"],["C","肿瘤的分化程度"],["D","肿瘤细胞的异型性"]],"A","肿瘤的“分期”是指恶性肿瘤的生长范围和播散程度（A对），肿瘤的分期与原发肿瘤的大小，浸润深度，浸润范围，邻近器官受累情况，局部和远处淋巴结转移情况，远处转移等有关。肿瘤细胞核分裂象的多少（B错）、肿瘤细胞的分化程度（C错）、肿瘤细胞的异型性（D错）均与肿瘤“分级”有关。","","N"],["2022-N31",8,"第1节 呼吸道和肺炎症性疾病","肺肉质变",2022,31,"A","","下列易并发肺肉质变（机化性肺炎）的肺部疾病是",[["A","由化脓菌引起的小叶性肺炎"],["B","由病毒引起的间质性肺炎"],["C","由肺炎链球菌引起的大叶性肺炎"],["D","由肺炎支原体引起的间质性肺炎"]],"C","大叶性肺炎是主要由肺炎球菌引起的发生于肺泡的纤维素性炎症。大叶性肺炎时，若病灶中中性粒细胞渗出过少，则释放的蛋白酶量不足以溶解渗出物中的纤维素，大量未能被溶解吸收的纤维素即被肉芽组织取代而机化，称肺肉质变（C对）。化脓性肺炎（A错）和间质性肺炎（BD错）不会发生肺肉质变。","","N"],["2022-N32",12,"第5节 前列腺疾病","前列腺癌临床病理联系",2022,32,"A","","前列腺癌血道转移最常见的部位",[["A","肝"],["B","肾"],["C","骨"],["D","肺"]],"C","前列腺癌的转移途径包括淋巴转移、血道转移及直接侵犯等，最常见的转移部位是经血道转移至骨（C对），尤以脊椎骨最常见，其次为股骨近端、盆骨和肋骨。男性肿瘤骨转移应首先想到前列腺癌转移的可能。","","N"],["2022-N33",5,"第3节 肿瘤的命名与分类","肿瘤的分类",2022,33,"A","","下列肿瘤中，不属于恶性肿瘤的是",[["A","骨母细胞瘤"],["B","髓母细胞瘤"],["C","肝母细胞瘤"],["D","神经母细胞瘤"]],"A","有些肿瘤的形态类似发育过程中的某种幼稚细胞或组织，称为母细胞瘤。良性的包括骨母细胞瘤（A对）；恶性者如神经母细胞瘤（D错）、髓母细胞瘤（B错）和肝母细胞瘤（C错）。","","N"],["2022-N34",1,"第2节 纤维性修复","纤维化",2022,34,"A","","组织损伤时，完成纤维性修复的最重要细胞是",[["A","纤维细胞"],["B","血管内皮细胞"],["C","成纤维细胞"],["D","巨噬细胞"]],"C","纤维性修复又称瘢痕修复，是指由纤维结缔组织（瘢痕组织）来进行损伤修复的方式，多出现于在细胞、组织损伤过重或有感染，不能完全用再生方式加以修复时。纤维修复首先通过肉芽组织增生、溶解、吸收损伤局部的坏死组织及其异物，以后肉芽组织转化成以胶原纤维为主的瘢痕组织。在纤维性修复过程中，成纤维细胞的作用最重要，因其可产生基质及胶原，对肉芽组织转变为成熟的纤维结缔组织至关重要（C对）。","","N"],["2022-N35",16,"第4节 细菌性痢疾","中毒性细菌性痢疾",2022,35,"A","","中毒性细菌性痢疾的肠道病理变化特点是",[["A","假膜性肠炎"],["B","滤泡性肠炎"],["C","溃疡性肠炎"],["D","出血性肠炎"]],"B","中毒性细菌性痢疾肠道病变一般为卡他性炎，有时肠壁集合和孤立淋巴小结滤泡增生肿大，而呈滤泡性肠炎（B对）改变。假膜性肠炎（A错）和溃疡性肠炎（C错）为急性细菌性痢疾的病理特点。","","N"],["2022-N36",10,"第2节 淋巴组织肿瘤","浆细胞肿瘤及其相关疾病的概述",2022,36,"A","","肿瘤细胞由不成熟浆细胞构成，应首先考虑为",[["A","霍奇金淋巴瘤"],["B","滤泡型淋巴瘤"],["C","伯基特淋巴瘤"],["D","骨髓瘤"]],"D","骨髓瘤组织学表现多为分化不成熟的浆细胞大量增生形成片状浸润病灶，肿瘤性浆细胞取代正常骨髓组织，故肿瘤细胞由不成熟浆细胞构成，首先考虑骨髓瘤（D对）。霍奇金淋巴瘤（十版病理学P239）（A错）的肿瘤细胞由 R-S细胞及其变异型细胞组成。滤泡状淋巴瘤（十版病理学P232）（B错）的肿瘤细胞常呈明显的滤泡样生长方式，肿瘤性滤泡主要由中心细胞和中心母细胞以不同比例组成。伯基特淋巴瘤（十版病理学P233）（C错）的肿瘤细胞由弥漫性的中等大小、淋巴样细胞组成，瘤细胞间有散在的巨噬细胞吞噬碎片，形成所谓满天星图像。","","N"],["2022-N37",5,"第11节 环境致瘤因素","人乳头状瘤病毒",2022,37,"A","","高危型HPV感染可以导致宫颈癌的重要机制是",[["A","病毒编码E2和E3基因"],["B","病毒编码E4和E5基因"],["C","病毒编码E6和E7基因"],["D","病毒编码E7和E8基因"]],"C","人乳头瘤病毒（HPV）的感染可能是子宫颈癌致病的主要因素，尤其是HPV-16、18、31、33、58等与子宫颈癌的发生密切相关，为高危型。高危型HPV的E6和E7基因（C对）是病毒癌基因，和宫颈上皮细胞的基因组整合后，可编码使肿瘤抑制基因p53和视网膜母细胞瘤基因 (RB) 封闭和失活的蛋白，改变细胞周期和DNA修复，诱导基因组不稳定性最终导致细胞永生化和恶性转化。","","N"],["2022-N38",13,"第2节 甲状腺疾病","滤泡癌",2022,38,"A","","甲状腺滤泡状癌区别于腺瘤的要点是",[["A","腺泡结构异型"],["B","细胞异型"],["C","包膜侵犯"],["D","肿瘤切面出血"]],"C","甲状腺滤泡状癌在光镜下，可见不同分化程度的滤泡，分化极好的滤泡癌很难与腺瘤区别，需对肿瘤及包膜多处取材、切片，尤其是否有包膜（C对）和血管侵犯加以鉴别。","","N"],["2022-N39",9,"第12节 消化系统常见肿瘤","胃癌的淋巴道转移",2022,39,"A","","Virchow淋巴结穿刺标本中发现癌细胞，最可能的原发灶是",[["A","大肠"],["B","胃"],["C","肝"],["D","肺"]],"B","Virchow淋巴结是以德国著名的病理学家Rudolf Virchow命名的淋巴结，位于左锁骨上窝，接受来自腹腔的淋巴管引流。当患者的胸、腹、盆部的肿瘤，尤其是食管腹段癌和胃癌时，癌细胞栓子可经胸导管、左颈淋巴干逆流至左锁骨上淋巴结，Virchow淋巴结穿刺标本中发现癌细胞，最可能的原发灶是胃（B对）。","","N"],["2022-N40",8,"第5节 肺尘埃沉着病","Ⅰ期硅肺",2022,40,"A","","Ⅰ期肺硅沉着的病变特点是",[["A","病变主要在肺门淋巴结"],["B","胸膜明显增厚"],["C","结节性病变散在分布于双肺"],["D","肺重量增加"]],"A","肺硅沉着病（硅肺）分为三期：①Ⅰ期硅肺：主要表现为肺门淋巴结肿大（A对），肺组织内硅结节较少，主要分布于双肺中、下近肺门处（C错）。肺的重量、体积和硬度无明显改变（D错）。胸膜可有硅结节形成，但增厚不明显（B错）。②Ⅱ期硅肺：硅结节数量增多，体积增大，伴有较明显的纤维化。结节性病变散布于双肺。肺的重量和硬度增加，体积增大，胸膜也增厚。③Ⅲ期硅肺（重症硅肺）：硅结节密度增大并与肺纤维化融合成团块，病灶周肺组织通常有肺气肿或肺不张。肺门淋巴结肿大，密度高，可见蛋壳样钙化，切开时阻力大，有砂砾感，大团块病灶的中央可见硅肺空洞。肺重量和硬度明显增加，新鲜肺标本可竖立,入水可下沉。","","N"],["2022-N124",0,"第3节 细胞可逆性损伤","细胞水肿的病理变化",2022,124,"B","","肝细胞气球样变性是",[["A","水样变性"],["B","脂肪变性"],["C","玻璃样变性"],["D","淀粉样变性"]],"A","肝细胞受损后水分增多引起肝细胞胀大、胞浆疏松化，进一步发展肝细胞胀大如球形，胞浆几乎透明，称为气球样变。肝细胞气球样变的本质为细胞水肿或称水变性（A对）。","","N"],["2022-N125",0,"第3节 细胞可逆性损伤","细小动脉壁玻璃样变",2022,125,"B","","原发性高血压细动脉发生的病变是",[["A","水样变性"],["B","脂肪变性"],["C","玻璃样变性"],["D","淀粉样变性"]],"C","细动脉硬化是高血压病的主要病变特征，表现为细小动脉玻璃样变性（C对）。高血压时，由于细动脉长期痉挛，加之血管内皮细胞受长期的高血压刺激，使内皮细胞及基底膜受损，内皮细胞间隙扩大，通透性增强，血浆蛋白渗入血管壁中。同时平滑肌细胞分泌大量细胞外基质，平滑肌细胞因缺氧而变性、坏死，遂使血管壁逐渐由血浆蛋白、细胞外基质和坏死平滑肌细胞产生的修复性胶原纤维及蛋白多糖所代替，正常管壁结构消失，逐渐凝固成红染无结构均质的玻璃样物质，致细动脉壁增厚，管腔缩小甚至闭塞。","","N"],["2022-N126",11,"第1节 肾小球疾病","急性弥漫性增生性肾小球肾炎病理变化",2022,126,"B","","急性弥漫性增生性肾小球肾炎的肉眼观可为",[["A","蚤咬肾"],["B","大白肾"],["C","固缩肾"],["D","瘢痕肾"]],"A","急性弥漫增生性肾小球肾炎肉眼观可见表面充血或散在粟粒大小的出血点，故称为大红肾或蚤咬肾（A对）。大白肾（十版病理学P256）（B错）见于膜性肾小球病。固缩肾（十版病理学P260）（C错）见于慢性肾小球肾炎。瘢痕肾（十版病理学P264）（D错）见于慢性肾盂肾炎。","","N"],["2022-N127",11,"第2节 肾小管间质性肾炎","慢性肾盂肾炎临床病理联系",2022,127,"B","","慢性肾盂肾炎的肉眼观可为",[["A","蚤咬肾"],["B","大白肾"],["C","固缩肾"],["D","瘢痕肾"]],"D","慢性肾盂肾炎大体改变的特征是一侧或双侧肾脏体积缩小，出现不规则的瘢痕（D对）。蚤咬肾（十版病理学P254）（A错）见于急性弥漫增生性肾小球肾炎。大白肾（十版病理学P256）（B错）见于膜性肾小球病。固缩肾（十版病理学P260）（C错）见于慢性肾小球肾炎。","","N"],["2022-N148",3,"第2节 急性炎症","纤维蛋白性炎",2022,148,"X","","属于假膜性炎的病变或疾病有",[["A","绒毛心"],["B","细菌性痢疾"],["C","大叶性肺炎"],["D","白喉"]],"BD","纤维素性炎是以渗出物中含有大量纤维素为特征的渗出性炎症。纤维素性炎易发生于黏膜、浆膜和肺组织，其中黏膜发生的纤维素性炎，渗出的纤维素、中性粒细胞和坏死黏膜组织以及病原菌等可在黏膜表面形成一层灰白色膜状物，称为“假膜”，故又称假膜性炎。细菌性痢疾（B对）和白喉（D对）发生的纤维素性炎均属于假膜性炎。绒毛心（A错）和大叶性肺炎（C错）分别属于浆膜和肺组织发生的纤维素性炎，无“假膜”形成，不属于假膜性炎。","","N"],["2022-N149",4,"第2节 免疫缺陷病","原发性免疫缺陷病",2022,149,"X","","属于原发性免疫缺陷的疾病有",[["A","原发性丙种球蛋白缺乏症"],["B","黏膜皮肤念珠菌病"],["C","毛细血管扩张性共济失调症"],["D","艾滋病"]],"ABC","免疫缺陷病是一组因免疫系统发育不全或遭受损害引起免疫功能缺陷而导致的疾病，可分为原发性免疫缺陷病和继发性免疫缺陷病两种。原发性免疫缺陷病，又称先天性免疫缺陷病，与遗传有关，多发生于婴幼儿。原发性免疫缺陷病少见，临床表现出反复感染，严重威胁生命。按免疫缺陷性质的不同，可分为三大类：①体液免疫缺陷为主：如原发性丙种球蛋白缺乏症（A对）、孤立性IgA缺乏症、普通变异型免疫缺陷病；②细胞免疫缺陷为主：如DiGeorge综合征、Nezelof综合征、黏膜皮肤念珠菌病（B对）；③两者兼有的联合性免疫缺陷：如重症联合性免疫缺陷病、Wiskott-Aldrich综合征、毛细血管扩张性共济失调症（C对）。此外，补体缺陷、吞噬细胞功能缺陷等非特异性免疫缺陷也属于此类疾病。艾滋病（D错）是发病率日增且死亡率极高的获得性免疫缺陷综合征，属于继发性免疫缺陷病。","","N"],["2022-N150",9,"第3节 消化性溃疡病","消化性溃疡病的病理变化",2022,150,"X","","消化性溃疡发生游离性穿孔的常见部位有",[["A","胃小弯"],["B","十二指肠球部前壁"],["C","胃大弯"],["D","十二指肠球部后壁"]],"AB","急性穿孔是胃十二指肠溃疡的常见并发症。穿孔发生于游离面时称为游离性穿孔，此时，胃与十二指肠内容物流入腹腔，引起急性腹膜炎。游离性穿孔的常见部位为球部前壁（B对）和胃小弯（A对）。","","N"],["2022-N151",10,"第2节 淋巴组织肿瘤","成熟B细胞肿瘤的概述",2022,151,"X","","属于B细胞淋巴瘤免疫标记的有",[["A","CD2"],["B","CD3"],["C","CD10"],["D","CD19"]],"CD","属于B细胞淋巴瘤免疫标记的有CD19（D对）、CD20、CD79a、CD10（C对）等。CD2（A错）、CD3（B错）、CD4、CD7和CD8等属于T细胞淋巴瘤的标记。","","N"],["2022-N152",16,"第2节 结核病","结核病基本病理变化",2022,152,"X","","典型的结核结节病变中有",[["A","干酪样坏死"],["B","朗汉斯巨细胞"],["C","上皮样细胞"],["D","淋巴细胞"]],"ABCD","当细菌量少，毒力较低或人体免疫反应较强时，结核病则发生以增生为主的变化，形成具有诊断价值的结核结节，又称结核性肉芽肿。典型的结核结节病变由上皮样细胞（C对），朗汉斯巨细胞（B对）加上外周局部集聚的淋巴细胞（D对）和少量反应性增生的成纤维细胞构成，中央有干酪样坏死（A对）。","","N"],["2022-N153",9,"第12节 消化系统常见肿瘤","肝炎病毒",2022,153,"X","","与肝细胞癌发生有关的肝炎病毒有",[["A","HAV"],["B","HBV"],["C","HCV"],["D","HEV"]],"BC","肝细胞癌发生于肝细胞，占原发性肝癌的90%以上。病因尚不清楚，相关因素有肝炎病毒、肝硬化、酒精、真菌及其毒素等。其中有关肝炎病毒的资料已表明，HBV（B对）、HCV（C对）与肝癌关系密切。","","N"],["2023-N29",0,"第3节 细胞可逆性损伤","含铁血黄素",2023,29,"A","","在巨噬细胞内形成的色素是",[["A","脂褐素"],["B","黑色素"],["C","胆红素"],["D","含铁血黄素"]],"D","脂褐素、黑色素、胆红素、含铁血黄素属于正常人体的内源性色素。含铁血黄素（D对）是巨噬细胞吞噬、降解红细胞血红蛋白所产生的铁蛋白微粒聚集体，由Fe³⁺与蛋白质结合而成，巨噬细胞破裂后，含铁血黄素也可见于细胞外。脂褐素（A错） 是细胞自噬溶酶体内未被消化的细胞器碎片残体，可见于附睾管上皮细胞、睾丸间质细胞和神经节细胞胞质内；在老年人和营养耗竭性患者，萎缩的心肌细胞及肝细胞核周围出现大量脂褐素，是细胞以往受到自由基脂质过氧化损伤的标志，故又有消耗性色素之称。黑色素（B错） 是黑色素细胞质中的黑褐色细颗粒，由酪氨酸氧化经左旋多巴聚合而产生，也可聚集于皮肤基底部的角质细胞及真皮的巨噬细胞内，但并不在巨噬细胞内形成。胆红素（C错）由血液中衰老的红细胞、骨髓幼稚红细胞和含亚铁血红素的蛋白质经单核巨噬细胞破坏转变而来，此为游离胆红素（非结合胆红素），游离胆红素被运输到肝细胞的光面内质网，与葡萄糖醛酸结合后形成结合胆红素，病理性色素沉着中的胆红素一般指的是胆汁中的结合胆红素，该题C选项存在争议。","","N"],["2023-N30",0,"第4节 细胞不可逆性损伤（细胞死亡）","机化与包裹",2023,30,"A","","容易发生机化的病变是",[["A","肺脓肿"],["B","脑梗死灶"],["C","Barrett食管"],["D","宫颈管鳞状上皮化生"]],"A","机化为坏死的结局之一，是由新生肉芽组织长入并取代坏死组织、血栓、脓液、异物等的过程。肺脓肿（A对）的结局一般为完全吸收或仅剩少量纤维瘢痕，但急性肺脓肿治疗不彻底或支气管引流不畅时，容易导致炎症迁延转为慢性肺脓肿，脓腔壁成纤维细胞增生，肉芽组织使脓腔壁增厚，即肉芽组织取代了坏死组织和脓液。脑梗死（B错）一般为液化性坏死，梗死灶的脑组织坏死、变软、液化，以后形成囊状，或被增生的星形胶质细胞和胶质纤维所代替，最后形成胶质瘢痕（十版病理学P30），该过程不属于机化。Barrett食管（C错）是指食管远端出现柱状上皮化生（鳞状上皮被柱状上皮取代），是大部分食管腺癌的癌前病变（十版病理学P194）。在宫颈炎症等因素的刺激下，宫颈正常的腺上皮向鳞状上皮转化，形成宫颈管鳞状上皮化生（D错），与Barrett食管同样属于慢性炎症刺激下的化生，而非肉芽组织对组织损伤的修复。","","N"],["2023-N31",2,"第3节 血栓形成","混合血栓",2023,31,"A","","发生于左心房球状血栓的类型是",[["A","红色血栓"],["B","白色血栓"],["C","透明血栓"],["D","混合血栓"]],"D","混合血栓（D对）可发生于左心房内，由于心房的收缩和舒张，使其呈球状。红色血栓（A错）主要见于静脉延续性血栓的尾部。白色血栓（B错）常位于血流较快的心瓣膜、心腔内、动脉内和静脉延续性血栓的起始部。透明血栓（微血栓）（C错）常发生于微循环的血管内，主要在毛细血管内。","","N"],["2023-N32",8,"第8节 呼吸系统常见肿瘤","转移",2023,32,"A","","男性，62岁。体检时发现右锁骨上淋巴结肿大，无压痛。淋巴结切除送检，病理诊断：淋巴结内可见腺癌浸润。肿瘤原发部位最可能是",[["A","食管"],["B","胃"],["C","肝"],["D","肺"]],"D","恶性肿瘤细胞可侵入淋巴管，随淋巴发生淋巴结转移。肺癌可向右侧锁骨上或腋窝淋巴结转移，若先发现右锁骨上淋巴结腺癌转移，需要考虑其是否来源于肺腺癌（D对）；而胃癌多向左侧锁骨上淋巴结转移（Virchow淋巴结），因此处是胸导管进颈静脉的入口，常为胃癌（B错）、食管癌（A错）转移的标志。肝癌（C错）转移更常见于左侧锁骨上淋巴结。","","N"],["2023-N33",11,"第1节 肾小球疾病","微小病变性肾小球病病理变化",2023,33,"A","","在微小病变性肾小球病中，肾小球的主要光镜特点是",[["A","局灶性节段性玻璃样变和硬化"],["B","系膜细胞增生，系膜基质增厚"],["C","新月体形成"],["D","基本正常"]],"D","微小病变性肾小球病的病变特点是弥漫性肾小球脏层上皮细胞足突消失，光镜下肾小球基本正常（D对）。光镜下局灶性节段性玻璃样变和硬化（A错）主要见于局灶性节段性肾小球硬化（十版病理学P259）。系膜细胞增生，系膜基质增厚（B错）可见于系膜增生性肾小球肾炎（十版病理学P258）和膜增生性肾小球肾炎（十版病理学P258）。新月体形成（C错）主要见于快速进行性肾小球肾炎（急进性肾小球肾炎）（十版病理学P255）。","","N"],["2023-N34",9,"第8节 肝硬化","慢性淤血性脾大",2023,34,"A","","与肝功能不全无直接关系的临床表现是",[["A","出血倾向"],["B","黄疸"],["C","脾大"],["D","蜘蛛痣"]],"C","肝硬化晚期可因严重的肝实质破坏和肝脏结构及血管的改建，导致门静脉高压症和肝功能不全（肝功能障碍）。门脉高压症的症状和体征主要包括：（1）慢性淤血性脾大（C错，为本题正确答案）；（2）腹水；（3）侧支循环形成；（4）胃肠淤血、水肿。肝功能不全的症状及体征主要包括 ：（1）蛋白质合成障碍；（2）出血倾向（A对）；（3）胆色素代谢障碍，在临床上常表现为肝细胞性黄疸（B对）；（4）对激素的灭活作用减弱，导致体内雌激素水平升高，小动脉末梢扩张，形成蜘蛛痣（D对）；（5）肝性脑病。","","N"],["2023-N35",5,"第3节 肿瘤的命名与分类","肿瘤的分类",2023,35,"A","","下列肿瘤中，不属于恶性的是",[["A","神经母细胞瘤"],["B","髓母细胞瘤"],["C","肾母细胞瘤"],["D","骨母细胞瘤"]],"D","有些肿瘤的形态类似发育过程中的某种幼稚细胞或组织，称为‘母细胞瘤’，良性者如骨母细胞瘤（D错，为本题正确答案）、软骨母细胞瘤、脂肪母细胞瘤、肌母细胞瘤等；恶性者如视网膜母细胞瘤、神经母细胞瘤（A对）、髓母细胞瘤（B对）、肝母细胞瘤和肾母细胞瘤（C对）等。","","N"],["2023-N36",9,"第2节 胃炎","慢性萎缩性胃炎",2023,36,"A","","胃体黏膜活检可见大量假幽门腺化生，病理诊断是",[["A","慢性浅表性胃炎"],["B","慢性萎缩性胃炎"],["C","慢性肥厚性胃炎"],["D","疣状胃炎"]],"B","假幽门腺化生为胃体部或胃底部的腺体壁细胞和主细胞消失，被类似幽门腺的黏液分泌细胞所取代，为腺上皮化生的一种，较少见，常见于慢性萎缩性胃炎（B对）的病理变化。慢性浅表性胃炎（A错）主要表现为黏膜浅层固有膜内淋巴细胞、浆细胞等慢性炎细胞浸润，但腺体保持完整，无萎缩性改变。慢性肥厚性胃炎（巨大肥厚性胃炎）（C错）镜下可见腺体肥大增生，腺管延长，增生的腺体可穿过黏膜肌层，不伴有化生。疣状胃炎（D错）是一种有特征性病理变化的胃炎，镜下可见病灶中心凹陷部胃黏膜上皮变性坏死并脱落，伴有急性炎性渗出物覆盖。","","N"],["2023-N37",13,"第2节 甲状腺疾病","髓样癌",2023,37,"A","","可伴有低钙血症表现的甲状腺癌是",[["A","乳头状癌"],["B","滤泡癌"],["C","髓样癌"],["D","未分化癌"]],"C","甲状腺癌主要包括乳头状癌、滤泡状癌、髓样癌、未分化癌四种组织学类型，各有特点。髓样癌是甲状腺滤泡旁细胞发生的恶性肿瘤，属于APUD瘤，肿瘤分泌降钙素，产生严重腹泻和低钙血症（C对），有的还同时分泌其他多种激素和物质。乳头状癌（A错）是原发性甲状腺癌中最常见的类型，肿瘤生长缓慢，恶性程度较低。滤泡癌（B错）是甲状腺向滤泡分化形成的恶性肿瘤，易血道转移，比乳头状癌预后差。未分化癌（D错）生长快，早期即可发生浸润和转移，恶性程度高，预后差。","","N"],["2023-N38",16,"第2节 结核病","骨结核",2023,38,"A","","累及骨旁软组织形成“冷脓肿”的疾病是",[["A","骨肉瘤"],["B","骨结核"],["C","骨髓瘤"],["D","骨髓炎"]],"B","骨结核（B对）多侵犯脊椎骨、指骨及长骨骨骺，病变可发展为干酪样坏死型或增生型，干酪样坏死型坏死物液化后在骨旁形成结核性“脓肿”，由于局部并无红、热、痛，故又称“冷脓肿”。骨肉瘤（A错）的肿瘤组织向周围软组织浸润发展时，可沿着肿瘤微血管形成肿瘤性骨小梁，在X线上呈现为“日光射线”形态。骨髓瘤（C错）为起源于骨髓网织细胞的恶性肿瘤，肿瘤在骨髓内弥漫性浸润，破坏区周围可形成椎旁软组织肿块，但很少跨越椎间盘水平，所形成的并非冷脓肿。骨髓炎（D错）形成的脓肿穿破骨膜后成为周围软组织脓肿，伴有红、热、痛，不属于冷脓肿。","","N"],["2023-N39",12,"第1节 子宫颈疾病","慢性子宫颈炎",2023,39,"A","","子宫颈息肉的病变性质是",[["A","良性肿瘤"],["B","癌前病变"],["C","原位癌"],["D","炎性病变"]],"D","子宫颈息肉常见于慢性子宫颈炎，由子宫颈黏膜上皮、腺体和间质结缔组织局限性增生形成，极少发生癌变，其增生包括实质和间质，属于炎性病变（D对）。","","N"],["2023-N40",12,"第4节 卵巢肿瘤","浆液性肿瘤",2023,40,"A","","关于卵巢交界性浆液性囊腺瘤的叙述，正确的是",[["A","由两个胚层组织构成"],["B","由两种不同的上皮组织构成"],["C","生物学行为介于良性与恶性之间"],["D","由上皮组织及间叶组织构成"]],"C","某些组织类型的肿瘤，除了有典型的良性肿瘤和典型的恶性肿瘤之分，还存在一些组织形态和生物学行为介于两者之间（C对）的肿瘤，称为交界性肿瘤，如卵巢交界性浆液性乳头状囊腺瘤。由两个胚层组织构成（A错）可见于畸胎瘤（十版病理学P280）。由两种不同的上皮组织构成（B错）可见于肺的腺鳞癌（十版病理学P93）。由上皮组织及间叶组织构成（D错）可见于癌肉瘤（十版病理学P93）。","","N"],["2023-N124",7,"第1节 动脉粥样硬化","脂纹",2023,124,"B","","可见于动脉粥样硬化的细胞是",[["A","Aschoff细胞"],["B","心衰细胞"],["C","多核巨细胞"],["D","泡沫细胞"]],"D","动脉粥样硬化以血管内膜形成粥瘤或纤维斑块为特征，内皮细胞损伤后脂蛋白过量沉积于内膜，血液中的巨噬细胞和中膜的平滑肌细胞迁入内膜下，摄取发生氧化的脂质，形成泡沫细胞（D对）。Aschoff细胞（A错）为风湿病的特征性病理变化，由增生的巨噬细胞吞噬纤维素样坏死物质转变而来。心衰细胞（B错）见于慢性肺淤血，为肺泡腔内吞噬含铁血黄素颗粒的巨噬细胞。多核巨细胞（C错）见于慢性肉芽肿性炎，由多个巨噬细胞吞噬较大异物时融合演变而成。","","N"],["2023-N125",3,"第3节 慢性炎症","肉芽肿的组成成分和形态特点",2023,125,"B","","可见于手术缝线周围的细胞是",[["A","Aschoff细胞"],["B","心衰细胞"],["C","多核巨细胞"],["D","泡沫细胞"]],"C","手术缝线可作为刺激物引起异物性肉芽肿，其主要细胞成分是上皮样细胞和多核巨细胞（C对），具有诊断意义。Aschoff细胞（A错）为风湿病的特征性病理变化，由增生的巨噬细胞吞噬纤维素样坏死物质转变而来。心衰细胞（B错）见于慢性肺淤血，为肺泡腔内吞噬含铁血黄素颗粒的巨噬细胞。泡沫细胞（D错）见于动脉粥样硬化，由巨噬细胞或平滑肌细胞吞噬大量脂质成分转变而来。","","N"],["2023-N126",10,"第2节 淋巴组织肿瘤","伯基特淋巴瘤概述",2023,126,"B","","与Burkitt淋巴瘤相关的病毒是",[["A","HBV"],["B","CMV"],["C","HPV"],["D","EBV"]],"D","Burkitt淋巴瘤是淋巴滤泡生发中心细胞或生发中心后B细胞起源的高度侵袭性肿瘤，多见于非洲赤道附近地区的地方性Burkitt淋巴瘤是其中一种临床亚型，其发病与EBV（EB病毒）（D对）感染密切相关，除此之外，EBV还是鼻咽癌（十版病理学P187）的高危致病因素。HBV（乙型肝炎病毒）（A错）与乙型肝炎及肝炎后肝硬化的发病相关。CMV（巨细胞病毒）感染（B错）是艾滋病患者最常见的机会感染的病原体之一。HPV（人乳头状瘤病毒）（C错）与宫颈癌和尖锐湿疣发病密切相关。","","N"],["2023-N127",4,"第2节 免疫缺陷病","机会性感染",2023,127,"B","","艾滋病患者容易感染的病毒是",[["A","HBV"],["B","CMV"],["C","HPV"],["D","EBV"]],"B","艾滋病是由于机体感染人类免疫缺陷病毒（HIV）而引发的免疫功能缺陷性疾病，未经治疗的感染者在疾病晚期易并发各种机会性感染和恶性肿瘤。艾滋病患者常见的机会感染的病毒是CMV（巨细胞病毒）（B对），由于传播途径、免疫缺陷等原因，艾滋病患者感染HBV（乙肝病毒）（A）、HPV（人乳头瘤病毒）（C）和EBV（EB病毒）（D）的风险也比普通人更高。","","N"],["2023-N148",3,"第1节 炎症概述","炎症的全身反应",2023,148,"X","","可见大量嗜酸性粒细胞浸润的病变有",[["A","过敏性鼻炎"],["B","血吸虫感染"],["C","小叶性肺炎"],["D","病毒性肝炎"]],"AB","致炎因子的不同，渗出的白细胞也不同，葡萄球菌和链球菌感染以中性粒细胞浸润为主（C错），病毒感染以淋巴细胞浸润为主（D错），寄生虫感染（B对）和过敏反应（A对）中则以嗜酸性粒细胞浸润为主。","","N"],["2023-N149",3,"第2节 急性炎症","化脓性炎",2023,149,"X","","属于化脓性炎的疾病有",[["A","急性肾盂肾炎"],["B","伤寒"],["C","流行性脑脊髓膜炎"],["D","亚急性甲状腺炎"]],"AC","根据炎症的基本病变性质进行分类，可分为变质性炎、渗出性炎和增生性炎。任何炎症都在一定程度上包含变质、渗出、增生这三种基本病变，但往往以一种病变为主，以变质为主时称为变质性炎；以渗出为主时称为渗出性炎；以增生为主时称为增生性炎。渗出性炎还可以根据渗出物的主要成分和病变特点，进一步分为浆液性炎、纤维素性炎、化脓性炎、出血性炎等。急性肾盂肾炎（A对）和流行性脑脊髓膜炎（C对）属于化脓性炎。伤寒（B错）和亚急性甲状腺炎（D错）属于增生性炎。","","N"],["2023-N150",9,"第6节 病毒性肝炎","桥接坏死",2023,150,"X","","属于肝细胞桥接坏死的有",[["A","门管区-门管区连续的肝细胞坏死带"],["B","门管区-小叶中央静脉连续的肝细胞坏死带"],["C","肝细胞坏死占肝小叶的大部分"],["D","小叶中央静脉-小叶中央静脉连续的肝细胞坏死带"]],"ABD","肝细胞桥接坏死指的是中央静脉与门管区之间（B对），两个门管区之间（A对），或两个中央静脉之间出现的互相连接的坏死带（D对），常见于较重的慢性肝炎。肝细胞坏死占肝小叶的大部分（C错）为肝细胞亚大块坏死。","","N"],["2023-N151",8,"第6节 慢性肺源性心脏病","心脏病变",2023,151,"X","","慢性肺源性心脏病的主要病理特点有",[["A","肺动脉圆锥显著膨隆"],["B","左心室壁增厚"],["C","右心室内乳头肌和肉柱显著增粗"],["D","左心室扩张"]],"AC","慢性肺源性心脏病，简称肺心病，是因慢性肺疾病、肺血管及胸廓的病变引起肺循环阻力增加，肺动脉压升高而导致以右心室壁肥厚、心腔扩张，甚至发生右心衰竭的心脏病。其心脏病变，以右心的病变为主，右心室壁肥厚（B错），右心室腔扩张（D错），扩大的右心室占据心尖部，外观钝圆；右心室前壁肺动脉圆锥显著膨隆（A对），右心室内乳头肌和肉柱显著增粗（C对），室上嵴增厚。","","N"],["2023-N152",7,"第8节 心肌炎","病毒性心肌炎的病理变化",2023,152,"X","","可引起心肌坏死的病变有",[["A","病毒性心肌炎"],["B","主动脉粥样硬化"],["C","肺动脉瓣狭窄"],["D","扩张性心肌病"]],"AD","病毒性心肌炎（A对）是嗜心肌性病毒感染引起的心肌非特异性间质性炎症病变，病毒可直接或通过T细胞介导的免疫反应间接引起心肌细胞的损伤，损伤严重时可导致心肌断裂、坏死等。扩张性心肌病（充血性心肌病）（D对）是以左心室、右心室或双心室腔扩大，收缩功能障碍等为特征的心肌病变，心肌细胞常发生空泡变、小灶性肌溶解，严重时也可发生心肌坏死。主动脉粥样硬化（B错）是以主动脉壁增厚、变硬和弹性减退为特征的动脉疾病，以腹主动脉病变最为严重，其次为胸主动脉、主动脉弓和升主动脉，由于主动脉管腔大，一般不引起明显症状，严重者可形成动脉瘤，破裂可引起致命性大出血。肺动脉瓣狭窄（PS）是指右室流出道梗阻的一组先天性心脏病，肺动脉瓣狭窄本身不累及心脏，不会引起心肌坏死；但常导致右心室继发性肥厚，当肥厚到一定程度时，心肌因缺乏血供，可发生坏死，故C选项不严谨，存在争议。当年官方给出的参考答案为AD。","","N"],["2023-N153",9,"第12节 消化系统常见肿瘤","伴有肠黏膜增生的慢性肠疾病",2023,153,"X","","与大肠癌发生有关的病变有",[["A","家族性腺瘤性息肉病"],["B","溃疡性结肠炎"],["C","幼年性息肉病"],["D","绒毛状腺瘤"]],"ABCD","家族性腺瘤性息肉病（A对）与遗传因素有关，如不予治疗，将不可避免地出现癌变，而慢性溃疡性结肠炎（B对）、幼年性息肉病（C对）及绒毛状腺瘤（D对）均为伴有肠黏膜增生的慢性肠疾病，与大肠癌的发生密切相关。","","N"],["2024-N29",0,"第1节 适应","萎缩的概念",2024,29,"A","","下列选项中，最符合萎缩本质的是",[["A","细胞器减少"],["B","脂褐素减少"],["C","间质细胞减少"],["D","自噬泡减少"]],"A","萎缩是指已发育正常的细胞、组织或器官的体积均匀性缩小，伴有功能下降，是细胞适应的一种类型。萎缩细胞电镜下见细胞器减少（A对）、退化，可伴有实质细胞数量的减少（C错），自噬小体增多（D错），心肌细胞和肝细胞等萎缩细胞胞质中出现脂褐素（B错）。萎缩的本质在于细胞为了适应不利的环境条件，通过减少细胞器数量来降低自身的代谢活动和能量需求。这包括线粒体、内质网、高尔基体等细胞器的减少，这样的变化有助于细胞在资源有限的情况下维持生存，是萎缩过程中的一种典型特征。","","N"],["2024-N30",0,"第3节 细胞可逆性损伤","脂肪变的病理变化",2024,30,"A","","下列形态学改变中，符合心肌脂肪变性的是",[["A","心脏体积增大，外观为黄色"],["B","心肌细胞内出现串珠状脂滴"],["C","心肌细胞核受挤压偏位"],["D","病变发生在心外膜下"]],"B","心肌细胞的脂肪变性是指甘油三酯蓄积于心肌的细胞质中，光镜下可见心肌细胞内串珠状脂滴（B对）。脂肪变性的器官一般体积增大，呈淡黄色，但对于心脏而言，黄色的脂肪变性心肌与暗红色的正常心肌相间，形成特征性的黄红色斑纹（虎斑心）（A错）。心肌细胞核受挤压偏位（C错）为心肌脂肪浸润的表现，当心肌细胞内出现脂滴时，大者可充满整个细胞而将细胞核挤向一侧，本题答案C可能存在争议。心肌脂肪变性常累及左心室内膜下和乳头肌部位，而非心外膜下（D错）。","","N"],["2024-N31",2,"第1节 充血和淤血","肺淤血",2024,31,"A","","慢性肺淤血时，肺泡腔中的心衰细胞来源是",[["A","中性粒细胞"],["B","红细胞"],["C","巨噬细胞"],["D","淋巴细胞"]],"C","心衰细胞常见于左心衰引起的慢性肺淤血，肺淤血时，部分巨噬细胞吞噬红细胞并将其分解，在胞浆内形成含铁血黄素，这种巨噬细胞（C对）被称为心衰细胞。","","N"],["2024-N32",5,"第5节 肿瘤的分级和分期","肿瘤分期",2024,32,"A","","某患者胃镜活检病理报告诊断为低分化腺癌，该肿瘤分期是",[["A","Ⅰ期胃癌"],["B","Ⅱ期胃癌"],["C","Ⅲ期胃癌"],["D","目前不能确定"]],"D","恶性肿瘤的“分级”是描述其恶性程度的指标，主要根据肿瘤的分化程度、异型性、核分裂象的数目等进行分级。低分化腺癌是指肿瘤的分化程度，属于肿瘤的分级。而肿瘤的“分期”（Ⅰ期、Ⅱ期、Ⅲ期等）是指恶性肿瘤的生长范围和播散程度，与原发肿瘤的大小、浸润深度、浸润范围、邻近器官受累情况、局部和远处淋巴结转移情况、远处转移等相关，本题中并未给出相关信息，无法确定肿瘤的分期情况（D对）。","","N"],["2024-N33",4,"第2节 免疫缺陷病","HIV感染CD4⁺T细胞",2024,33,"A","","HIV感染的主要细胞是",[["A","辅助性T淋巴细胞"],["B","细胞毒性T淋巴细胞"],["C","B淋巴细胞"],["D","中性粒细胞"]],"A","HIV（人类免疫缺陷病毒）可以感染的细胞主要包括：①CD4⁺T淋巴细胞。②巨噬细胞。③树突状细胞。其中CD4⁺T淋巴细胞是感染的主要细胞（A对）。细胞毒性T淋巴细胞，主要为CD8⁺T细胞（B错）。","","N"],["2024-N34",7,"第1节 动脉粥样硬化","脂纹",2024,34,"A","","在动脉粥样硬化发生的过程中，最早出现在动脉内膜中的病变是",[["A","泡沫细胞聚集"],["B","胶原纤维沉积"],["C","胆固醇结晶"],["D","钙盐沉积"]],"A","动脉粥样硬化的基本病理变化包括脂纹、纤维斑块、粥样斑块和继发性病变。脂纹是动脉粥样硬化肉眼可见的最早病变，光镜下，病灶处的内膜中有大量泡沫细胞聚集（A对）。纤维斑块由脂纹发展而来，病灶内出现胶原纤维沉积（B错），可见由大量的胶原纤维、蛋白聚糖及散在的平滑肌细胞组成的纤维帽。粥样斑块（粥瘤）是动脉粥样硬化的典型病变，光镜下可见纤维帽之下含有的大量不定形的坏死崩解产物、胆固醇结晶（C错）、钙盐沉积（D错），斑块底部和边缘出现肉芽组织，少量淋巴细胞和泡沫细胞。继发性病变包括斑块内出血、斑块破裂、血栓形成、钙化、动脉瘤、血管腔狭窄等。","","N"],["2024-N35",7,"第4节 风湿病","风湿性心肌炎",2024,35,"A","","风湿性心肌炎病理特征性细胞的来源是",[["A","中性粒细胞"],["B","浆细胞"],["C","巨噬细胞"],["D","肥大细胞"]],"C","风湿性心肌炎病变为风湿病引起的心脏病变的一种，主要累及心肌间质结缔组织，常表现为灶状间质性心肌炎、间质水肿，在间质血管附近可见Aschoff小体和少量的淋巴细胞浸润。其病理特征性细胞为风湿（Aschoff）细胞，为增生的巨噬细胞（C对）吞噬纤维素样坏死物质转变而来。","","N"],["2024-N36",11,"第1节 肾小球疾病","微小病变性肾小球病病理变化",2024,36,"A","","在微小病变性肾小球病中，其HE切片在光镜下的病理特征性改变是",[["A","肾小球出现微小的细胞变性坏死灶"],["B","肾小管内出现大量的透明管型"],["C","肾小球内出现节段性的系膜细胞增生"],["D","肾小管上皮细胞内脂质沉积"]],"D","微小病变性肾病又称脂性肾病，其病理检查可见：常规光镜下肾小球基本正常，肾小管上皮细胞内有脂质沉积（D对）。肾小球内出现节段性的系膜细胞增生为IgA肾病的病理表现（十版病理学P260）（C错）。肾小球出现微小的细胞变性坏死灶（A错）可见于多种肾脏疾病，特别是那些涉及肾小球炎症或损伤的疾病，例如急性肾小球肾炎、快速进展性肾小球肾炎等。肾小管内出现大量透明管型（B错）也可见于多种肾脏疾病，尤其是那些影响肾小管功能或导致蛋白质漏出的疾病，例如慢性肾病、急性肾小管坏死等。","","N"],["2024-N37",10,"第2节 淋巴组织肿瘤","霍奇金淋巴瘤病理改变的概述",2024,37,"A","","霍奇金淋巴瘤中的特征性R-S细胞的起源细胞是",[["A","巨噬细胞"],["B","树突状细胞"],["C","B淋巴细胞"],["D","T淋巴细胞"]],"C","霍奇金淋巴瘤的特征细胞为R-S细胞，其为Sternberg（1889）和Reed（1902）首先描述，直径15～45µm，瘤细胞胞质丰富，略嗜酸或嗜碱性，核圆形或椭圆形，双核或多核；核膜厚，核内有一大而醒目的、直径与红细胞相当的、包涵体样的嗜酸性核仁，核仁周围有空晕。目前的研究结果证实R-S细胞具有生发中心或生发中心后B淋巴细胞的特征，起源于B淋巴细胞（C对）。","","N"],["2024-N38",9,"第12节 消化系统常见肿瘤","中晚期胃癌（进展期胃癌）的概述",2024,38,"A","","“革囊胃”所对应的胃癌大体类型是",[["A","息肉型"],["B","蕈伞型"],["C","溃疡型"],["D","弥漫浸润型"]],"D","中晚期胃癌肉眼形态可分三型：息肉型（蕈伞型）、溃疡型和浸润型（包括局限浸润型和弥漫浸润型）。弥漫浸润型（D对）可导致胃壁普遍增厚，变硬，胃腔变小，状如皮革，称之为“革囊胃”。","","N"],["2024-N39",3,"第2节 急性炎症","纤维蛋白性炎",2024,39,"A","","假膜性炎的本质是",[["A","化脓性炎"],["B","纤维素性炎"],["C","肉芽肿性炎"],["D","增生性炎"]],"B","纤维素性炎（B对）易发生于黏膜、浆膜和肺组织，当黏膜发生的纤维素性炎时，渗出的纤维素、中性粒细胞和坏死黏膜组织以及病原菌等可在黏膜表面形成一层灰白色膜状物，称为“假膜”，故又称为假膜性炎。","","N"],["2024-N40",0,"第1节 适应","化生的类型",2024,40,"A","","在下列化生中，不会发生的情况是",[["A","支气管纤毛柱状上皮细胞被鳞状上皮细胞取代"],["B","食管鳞状上皮细胞被肠上皮细胞取代"],["C","胃上皮细胞被大肠上皮细胞取代"],["D","肠腺上皮细胞被软骨细胞取代"]],"D","一种分化成熟的细胞类型被另一种分化成熟的细胞类型所取代的过程，称为化生，化生通常发生于同源性细胞之间，即上皮细胞之间或间叶细胞之间，肠腺上皮细胞属于上皮细胞，软骨细胞属于间叶细胞，故肠腺上皮细胞不能化生为软骨细胞（D错，为本题正确答案）。","","N"],["2024-N124",2,"第4节 栓塞","血栓栓塞",2024,124,"B","","股骨骨折两周后突然发生栓塞，最可能的原因是",[["A","血栓栓塞"],["B","空气栓塞"],["C","脂肪栓塞"],["D","氮气栓塞"]],"A","股骨骨折后的治疗需要制动，如果患者卧床两周血流变慢甚至停滞，易形成下肢深静脉血栓，患者起床时肌肉挤压可致血栓脱落，引起致命的肺动脉血栓栓塞（A对）。脂肪栓塞（C错）常发生在骨折后的1～3天，由骨髓内脂肪细胞破裂释放的脂滴入血所致。","","N"],["2024-N125",2,"第4节 栓塞","减压病",2024,125,"B","","潜水员上浮过快发生的栓塞，最可能的原因是",[["A","血栓栓塞"],["B","空气栓塞"],["C","脂肪栓塞"],["D","氮气栓塞"]],"D","潜水员上浮时发生的栓塞是氮气栓塞（D对），因为深度潜水时，人处于高气压环境下，吸入的气体可大量溶解在血液和组织中，当人体从高气压环境迅速进入常压或低气压环境时，原来溶于血液、组织液和脂肪组织的气体（包括氧气、二氧化碳和氮气）迅速游离形成气泡，氧和二氧化碳可再溶于体液内被吸收，但氮气在体液内溶解迟缓，故在血液和组织内形成很多微气泡或融合成大气泡，引起气体栓塞，故又称为氮气栓塞。","","N"],["2024-N126",11,"第1节 肾小球疾病","急性弥漫性增生性肾小球肾炎病理变化",2024,126,"B","","免疫荧光为颗粒状沉积的肾炎是",[["A","微小病变性肾小球病"],["B","急性弥漫性增生性肾小球肾炎"],["C","Ⅰ型快速进行性肾小球肾炎"],["D","急性肾盂肾炎"]],"B","急性弥漫性增生性肾小球肾炎（B对）的病变主要由免疫复合物沉积于肾小球引起，免疫荧光检查显示肾小球内有颗粒状IgG、IgM和C3沉积。微小病变性肾小球病（A错）内无免疫复合物沉积，免疫荧光检查无免疫球蛋白或补体沉积。Ⅰ型快速进行性肾小球肾炎（C错）为抗肾小球基膜抗体引起的肾炎，免疫荧光检查显示线性荧光。急性肾盂肾炎（D错）主要由细菌感染引起，与免疫机制所引起的疾病不同，免疫荧光检查不能发现明显异常。","","N"],["2024-N127",11,"第1节 肾小球疾病","急进性肾小球肾炎病理变化",2024,127,"B","","免疫荧光为线状分布的肾炎是",[["A","微小病变性肾小球病"],["B","急性弥漫性增生性肾小球肾炎"],["C","Ⅰ型快速进行性肾小球肾炎"],["D","急性肾盂肾炎"]],"C","根据免疫学和病理学检查结果，急进性肾小球肾炎分为三个类型，免疫荧光检查Ⅰ型（C对）表现为线性荧光，Ⅱ型为颗粒状荧光，Ⅲ型检查结果为阴性。微小病变性肾小球病（A错）内无免疫复合物沉积，免疫荧光检查无免疫球蛋白或补体沉积。急性弥漫性增生性肾小球肾炎（B错）的病变主要由免疫复合物沉积于肾小球引起，免疫荧光检查显示肾小球内有颗粒状IgG、IgM和C3沉积。急性肾盂肾炎（D错）主要由细菌感染引起，与免疫机制所引起的疾病不同，免疫荧光检查不能发现明显异常。","","N"],["2024-N149",3,"第1节 炎症概述","渗出",2024,149,"X","","炎性渗出液的作用有",[["A","稀释毒素"],["B","杀灭病原体"],["C","限制细菌扩散"],["D","预防粘连形成"]],"ABC","炎症局部组织血管内的液体成分、纤维素等蛋白质和各种炎症细胞通过血管壁进入组织间隙、体腔、体表和黏膜表面的过程叫渗出。通常情况下炎性渗出液对机体具有积极意义：①稀释和中和毒素（A对），减轻毒素对局部组织的损伤作用；②为局部浸润的白细胞带来营养物质，运走代谢产物；③渗出液中所含的抗体和补体有利于消灭病原体（B对）；④渗出液中的纤维素交织成网，不仅可限制病原微生物的扩散（C对），还有利于白细胞吞噬消灭病原体，在炎症后期的纤维素网架可成为修复的支架，并有利于成纤维细胞产生胶原纤维；⑤渗出液中的白细胞吞噬和杀灭病原微生物，清除坏死组织；⑥炎症局部的病原微生物和毒素随渗出液的淋巴回流而到达局部淋巴结，刺激细胞免疫和体液免疫的产生。然而，如果渗出液中的纤维素吸收不良可能会形成机化造成粘连，而不是预防粘连形成（D错）。","","N"],["2024-N150",16,"第3节 伤寒","伤寒病理变化概述",2024,150,"X","","以肉芽肿为基本病变的疾病有",[["A","结核病"],["B","伤寒"],["C","阿米巴病"],["D","细菌性痢疾"]],"AB","依据炎症的基本病变性质进行分类，可以将炎症分为变质性炎、渗出性炎和增生性炎。肉芽肿性炎（十版病理学P76）以炎症局部巨噬细胞及其衍生细胞（上皮样细胞、多核巨细胞）增生形成境界清楚的结节状病灶（即肉芽肿）为特征，是一种特殊类型的增生性炎症。根据病因不同，肉芽肿性炎可以分为感染性肉芽肿、异物性肉芽肿和原因不明性肉芽肿等三种基本类型，结核球（A对）和伤寒（B对）小结均属于感染性肉芽肿。阿米巴病（十版病理学P358）（C错）的基本病变为组织溶解液化为主的变质性炎。细菌性痢疾（D错）属于以纤维素性渗出为主的渗出性炎。","","N"],["2024-N151",12,"第3节 滋养层细胞疾病","葡萄胎病理变化",2024,151,"X","","关于完全性葡萄胎的叙述，正确的有",[["A","均为男性遗传起源"],["B","核型为二倍体"],["C","可以有胎儿存在"],["D","水肿的绒毛间质内血管增生"]],"AB","葡萄胎分为完全性葡萄胎和部分性葡萄胎。对于完全性葡萄胎而言，可能是父方的单倍体精子23X在丢失了所有的母方染色体的空卵中自我复制形成纯合子46XX，也可能是空卵在受精时和两个精子结合形成46XY，这两种情况均为男性遗传起源（A对），无论是46XX还是46XY，核型均为二倍体（B对）。在完全性葡萄胎中，由于滋养细胞的异常增生和绒毛的水肿，不会有胎儿发育（C错），这与部分性葡萄胎不同，后者可能伴有不完全的胎儿发育或正常绒毛的存在。对于葡萄胎而言，其镜下显示绒毛间质内血管消失，或见少量无功能的毛细血管（D错），内无红细胞。","","N"],["2024-N152",13,"第2节 甲状腺疾病","弥漫性毒性甲状腺肿病理变化光镜下",2024,152,"X","","弥漫性毒性甲状腺肿的病理改变有",[["A","滤泡上皮细胞增生呈高柱状"],["B","滤泡周围的胶质中有大量吸收空泡"],["C","间质中有大量淋巴细胞浸润"],["D","增生的细胞胞核呈毛玻璃样改变"]],"ABC","弥漫性毒性甲状腺肿是指血中甲状腺素过多，作用于全身各组织所引起的临床综合征，临床上统称为甲状腺功能亢进症。光镜下表现为：①滤泡上皮增生呈高柱状（A对），有的呈乳头样增生，并有小滤泡形成；②滤泡腔内胶质稀薄，滤泡周边胶质出现许多大小不一的上皮细胞的吸收空泡（B对）；③间质血管丰富、充血，淋巴组织增生（C对）。增生的细胞核呈毛玻璃样改变（D错）为甲状腺乳头状癌的特点。","","N"],["2024-N153",9,"第6节 病毒性肝炎","病毒性肝炎的发病机制",2024,153,"X","","属于RNA病毒的肝炎病毒有",[["A","HAV"],["B","HBV"],["C","HCV"],["D","HEV"]],"ACD","肝炎病毒是指引起病毒性肝炎的病原体。人类肝炎病毒有甲型（HAV）（A对）、乙型（HBV）、丙型（HCV）（C对）、丁型（HDV）、戊型（HEV）（D对）和庚型（HGV）病毒之分。其中，除了HBV（B错）是DNA病毒之外，其余均为RNA病毒。","","N"],["2025-N29",9,"第7节 酒精性肝病和非酒精性脂肪性肝病","酒精性肝炎",2025,29,"A","","酒精性肝炎的肝细胞胞浆中可见Mallory小体，其组成成分是",[["A","变性的内质网"],["B","变性的线粒体"],["C","过氧化物酶体"],["D","中间丝前角蛋白"]],"D","酒精性肝炎常出现三种病变：肝细胞脂肪变性、Mallory小体形成和灶状肝细胞坏死伴以中性粒细胞为主的炎症细胞浸润。Mallory小体代表一种细胞损伤形式，为变性肝细胞质内的嗜酸性包涵体，电镜显示其由缠绕的中间丝前角蛋白（D对）构成。内质网是细胞内重要的细胞器，主要参与蛋白质的合成、加工及物质转运，变性的内质网（A错）不是Mallory小体的构成成分。线粒体作为细胞内的能量工厂，负责产生ATP为细胞供能，变性的线粒体（B错）亦非Mallory小体的成分。过氧化物酶体（C错）与过氧化物的代谢相关，在酒精性肝炎的发病过程中可能参与氧化应激反应，其并非Mallory小体的组成成分。","","N"],["2025-N30",16,"第2节 结核病","结核病基本病理变化",2025,30,"A","","肺结核结节的上皮样细胞起源的细胞是",[["A","鳞状上皮细胞"],["B","肺泡上皮细胞"],["C","淋巴细胞"],["D","巨噬细胞"]],"D","肺结核结节又称结核性肉芽肿，发生于细菌量少，毒力较低或人体免疫反应较强时的以增生为主的病变，主要由上皮样细胞、朗汉斯巨细胞和外周局部集聚的淋巴细胞和少量反应性增生的成纤维细胞构成，其中上皮样细胞由吞噬结核分枝杆菌的巨噬细胞（D对）转变而来。鳞状上皮细胞（A错）主要存在于皮肤、口腔、食管等部位的表层，不是肺结核结节的上皮样细胞起源的细胞。肺泡上皮细胞（B错）构成肺泡，分为Ⅰ型肺泡上皮细胞和Ⅱ型肺泡上皮细胞，不是肺结核结节的上皮样细胞起源的细胞。淋巴细胞（C错）是免疫系统的重要组成部分，并在肺结核的免疫反应中发挥作用，但并不直接转化为上皮样细胞。","","N"],["2025-N31",3,"第2节 急性炎症","纤维蛋白性炎",2025,31,"A","","类风湿小结中央的坏死类型是",[["A","凝固性坏死"],["B","液化性坏死"],["C","纤维素样坏死"],["D","干酪样坏死"]],"C","类风湿小结是类风湿关节炎的特征性病理变化，其中央坏死类型为纤维素样坏死（C对），周围有呈栅栏状或放射状排列的上皮样细胞，外围为肉芽组织。纤维素样坏死是结缔组织及小血管壁常见的坏死形式，多发生于某些变态反应性疾病，如风湿病、结节性多动脉炎、新月体性肾小球肾炎，以及急进型高血压和胃溃疡底部小血管等。凝固性坏死（A错）发生于蛋白质变性凝固且溶酶体酶水解作用较弱时，坏死区呈灰黄、干燥、质实的状态，多见于心、肝、肾和脾等实质器官。液化性坏死（B错）是由于坏死组织中可凝固的蛋白质少，或坏死细胞自身及浸润的中性粒细胞等释放大量水解酶，或组织富含水分和磷脂，导致细胞组织坏死后易发生溶解液化，多见于脑、脊髓、胰腺和乳房等处。干酪样坏死（D错）是坏死更为彻底的特殊类型凝固性坏死，主要由结核杆菌引起，其坏死灶内含脂质较多，坏死区呈黄色，整体质地松软、细腻，类似干酪，多见于结核病。","","N"],["2025-N32",0,"第4节 细胞不可逆性损伤（细胞死亡）","凋亡的形态学和生物化学特征",2025,32,"A","","凋亡细胞的形态特征是",[["A","细胞固缩，细胞膜完整，膜可发泡成芽，形成凋亡小体"],["B","细胞肿胀，细胞膜及细胞核溶解破坏，细胞自溶"],["C","细胞肿胀，细胞膜完整，细胞器膜溶解破坏，形成凋亡小体"],["D","细胞固缩，细胞器膜溶解消失，核碎裂，形成凋亡小体"]],"A","凋亡是活体内局部组织中单个细胞程序性细胞死亡，在生理性或轻微病理性刺激因子诱导下发生，凋亡的形态学特征主要表现为细胞固缩，细胞膜完整，膜发泡成芽，形成凋亡小体（A对）。坏死是以酶溶性变化为特点的活体内局部组织中细胞的死亡，在病理性刺激因子诱导发生，如严重缺氧、感染、中毒等，可见细胞肿胀（BC错）、核染色质絮状或边集、细胞膜及细胞器膜发生溶解破坏（D错）、溶酶体酶释放使细胞自溶等。","","N"],["2025-N33",2,"第3节 血栓形成","混合血栓",2025,33,"A","","发生于动脉瘤内的血栓多见的类型是",[["A","白色血栓"],["B","红色血栓"],["C","混合血栓"],["D","透明血栓"]],"C","动脉瘤内血栓多见的类型是混合血栓（C对）。混合血栓也称为层状血栓，肉眼观察时呈灰白色和红褐色层状交替结构，由白色和红色血栓交错而成，常发生于血流缓慢的静脉或动脉瘤内。在动脉瘤中，由于血流速度和方向的变化，可形成涡流，这一现象导致血小板沉积和红细胞堆积交替出现，进而形成混合血栓。白色血栓（A错）主要由血小板和少量的纤维蛋白组成，通常出现在血流较快的部位或血栓形成初期，急性风湿性心内膜炎时可发生在二尖瓣闭锁缘上，在动脉瘤内不易单独形成。红色血栓（B错）主要由红细胞和纤维蛋白组成，多见于血流较慢的静脉内。透明血栓（D错）主要由纤维蛋白构成，常发生于微循环的血管内，如毛细血管，在动脉瘤中由于血管直径较大而不易形成。","","N"],["2025-N34",3,"第2节 急性炎症","白细胞游出",2025,34,"A","","炎症时的白细胞游出，通常发生的部位是",[["A","毛细血管"],["B","细动脉"],["C","淋巴管"],["D","毛细血管后小静脉"]],"D","白细胞游出指白细胞在炎症病灶产生的化学趋化因子介导下，穿过血管壁进入周围组织的过程，通常发生的部位是毛细血管后小静脉（D对），因为毛细血管后小静脉血管壁较薄且具有一定的通透性，便于白细胞穿过并进入周围组织。毛细血管（A错）是白细胞经过的地方，不是白细胞游出的部位。细动脉（B错）的主要职责是输送血液至毛细血管，不是白细胞游出的部位。淋巴管（C错）主要承担淋巴液的运输，与白细胞游出无关。","","N"],["2025-N35",8,"第8节 呼吸系统常见肿瘤","神经内分泌癌",2025,35,"A","","男性，70岁。体检发现左肺门处直径约3cm大小的不规则肿物。支气管镜活检组织的病理学特点：肿瘤细胞呈片状、条索状排列，呈浸润性生长；肿瘤细胞体积小，胞质少，似裸核，异型性明显，核分裂象多。该肿瘤最可能的病理诊断是",[["A","浸润性腺癌"],["B","鳞状细胞癌"],["C","小细胞癌"],["D","腺鳞癌"]],"C","老年男性，体检发现左侧肺门有一个直径为3cm的肿物（提示中央型肺癌），支气管镜病理检查示：肿瘤呈片状、条索状排列，浸润性生长，细胞小，胞质少，近似裸核，核分裂象多，核仁显著（符合小细胞癌的病理表现）。根据患者的检查结果，诊断考虑为中央型肺癌，病理类型为小细胞癌（C对）。小细胞癌是肺癌中分化最低、恶性度最高的一种，多为中央型，常发生于大支气管，向肺实质浸润生长，形成巨块，镜下癌细胞小，常呈圆形或卵圆形，似淋巴细胞，但体积较大；也可呈梭形或燕麦形，胞质少，似裸核，癌细胞呈弥漫分布或呈片状、条索状排列，称燕麦细胞癌。浸润性腺癌（A错）按分化程度，可分为高、中、低分化三类，高分化腺癌主要表现为癌细胞沿肺泡壁、肺泡管壁，有时也沿细支气管管壁呈贴壁样生长，中分化腺癌以腺管状、乳头状生长为主，低分化腺癌常无腺样结构，呈实心条索状，分泌现象少见，细胞异型性明显。鳞状细胞癌（B错）为肺癌中常见的类型，其中80%～85%为中央型肺癌，组织学上鳞状细胞癌可分为角化型、非角化型和基底细胞样型，角化型癌巢中有角化珠形成，常可见细胞间桥，非角化型无角化珠形成，细胞间桥也很难见到，基底细胞样型癌细胞较小，质少，似基底细胞样的形态，且癌巢周边的癌细胞呈栅栏状排列。腺鳞癌（D错）是混合性肿瘤，同时包含腺癌和鳞状细胞癌的成分，较少见。","","N"],["2025-N36",9,"第6节 病毒性肝炎","碎片状坏死",2025,36,"A","","慢性肝炎时，肝小叶周边部界板肝细胞可发生灶状坏死和崩解，使肝界板受到破坏，这种坏死的名称是",[["A","点状坏死"],["B","碎片状坏死"],["C","桥接坏死"],["D","亚大块坏死"]],"B","慢性肝炎时，肝小叶界板周围肝细胞出现的灶状、碎片状坏死，并突破界板，这种病理学类型称之为碎片状坏死（B对），也称为界面性肝炎。点状坏死（A错）指单个或数个肝细胞的坏死，常见于急性普通型肝炎。桥接坏死（C错）指中央静脉与门管区之间，两个门管区之间，或两个中央静脉之间出现的互相连接的坏死带，常见于较重的慢性肝炎。亚大块坏死（D错）指肝细胞坏死占肝小叶大部分，常见于重型肝炎。","","N"],["2025-N37",9,"第12节 消化系统常见肿瘤","胃癌的种植性转移",2025,37,"A","","下列胃癌类型中，属于低黏附性癌的是",[["A","管状腺癌"],["B","印戒细胞癌"],["C","乳头状腺癌"],["D","腺鳞癌"]],"B","管状腺癌（A错）是一种腺上皮的恶性肿瘤，其癌细胞排列成腺管状结构，具有较高粘附性，因此并不属于低黏附性癌。印戒细胞癌（B对）是一种特殊的黏液分泌型腺癌，其细胞之间粘附性低，容易在胃壁内弥漫浸润性生长，属于低黏附性癌。乳头状腺癌（C错）的癌细胞排列成乳头状结构，具有高粘附性，不属于低黏附性癌。腺鳞癌（D错）同时具有腺癌和鳞癌成分，其细胞特性和粘附性与单纯的腺癌或鳞癌不同，也不属于低黏附性癌。","","N"],["2025-N38",0,"第4节 细胞不可逆性损伤（细胞死亡）","液化性坏死",2025,38,"A","","金黄色葡萄球菌感染性脓肿的坏死类型是",[["A","干酪样坏死"],["B","凝固性坏死"],["C","湿性坏疽"],["D","液化性坏死"]],"D","金黄色葡萄球菌感染性脓肿的坏死类型是液化性坏死（D对）。液化性坏死为坏死组织中可凝固的蛋白质少，或坏死细胞自身及浸润的中性粒细胞等释放大量水解酶，或组织富含水分和磷脂，导致细胞组织坏死后易发生溶解液化。金黄色葡萄球菌产生的毒素使局部组织坏死，继而大量中性粒细胞浸润，中性粒细胞坏死形成脓细胞，并释放蛋白溶解酶溶解液化坏死组织。干酪样坏死（A错）是坏死更为彻底的特殊类型凝固性坏死，坏死灶内含有抑制水解酶活性的物质，主要见于由结核杆菌引起的坏死。凝固性坏死（B错）指蛋白质变性凝固且溶酶体酶水解作用较弱时的坏死状态，多见于心肌、肝、脾、肾等实质器官。湿性坏疽（C错）多为继发于血液循环障碍引起的缺血坏死，并继发腐败菌感染，多发生于与外界相通的内脏，也可发生于四肢。","","N"],["2025-N39",10,"第2节 淋巴组织肿瘤","淋巴细胞的分化与淋巴瘤",2025,39,"A","","淋巴瘤的最重要病理学特征是",[["A","细胞大小一致"],["B","单克隆性增生"],["C","大量分裂象"],["D","核仁显著"]],"B","淋巴瘤是起源于淋巴造血系统的恶性肿瘤，可分为霍奇金淋巴瘤和非霍奇金淋巴瘤。淋巴瘤细胞在病理上常展现出异型性，细胞大小不一致（A错）。淋巴瘤的基本病理特征之一是单克隆增殖（B对），肿瘤性祖细胞产生的所有子细胞具有相同的抗原受体基因构型和序列，并合成相同类型的抗原受体蛋白。淋巴瘤细胞增殖活跃，分裂象多见，并非其特异性病理特征，因为其他类型的恶性肿瘤也可能出现分裂象（C错）。核仁显著（D错）是霍奇金淋巴瘤的主要特征，非霍奇金淋巴瘤可有小核仁，而霍奇金淋巴瘤占所有淋巴瘤的10%～20%，所以核仁显著不是淋巴瘤的病理特征。","","N"],["2025-N40",12,"第3节 滋养层细胞疾病","绒毛膜癌病理变化",2025,40,"A","","关于绒毛膜癌病理学特点的叙述，正确的是",[["A","肉眼观，肿瘤呈灰白色、质硬"],["B","由分化不良的两种滋养层细胞组成"],["C","肿瘤血管丰富，出血、坏死明显"],["D","部分癌细胞形成绒毛和水泡状结构"]],"B","绒毛膜癌简称绒癌，是源自妊娠绒毛滋养层上皮的高度侵袭性恶性肿瘤，其病理学特征是由两种分化不良的滋养层细胞（似细胞滋养层和似合体滋养层瘤细胞）组成（B对）。绒毛膜癌自身无间质血管（C错），依靠侵袭宿主血管获取营养，故癌组织和周围正常组织有明显出血坏死，由于明显出血坏死，癌结节质软，暗红或紫蓝色（A错）。绒毛膜癌的癌细胞不形成绒毛和水泡结构（D错），这是与葡萄胎和恶性葡萄胎的重要区别之处。","","N"],["2025-N124",0,"第3节 细胞可逆性损伤","玻璃样变的病理变化",2025,124,"B","","瘢痕组织容易发生的变性是",[["A","淀粉样变"],["B","脂肪变"],["C","玻璃样变"],["D","黏液样变"]],"C","瘢痕组织的常见变性是玻璃样变（C对），在瘢痕组织中，胶原蛋白交联、变性、融合，胶原纤维增粗变宽，其间少有血管和纤维细胞。淀粉样变（A错）指细胞间质内淀粉样蛋白质和黏多糖复合物蓄积，可见于霍奇金病、多发性骨髓瘤、甲状腺髓样癌等肿瘤的间质内。脂肪变（B错）指甘油三酯蓄积于非脂肪细胞的细胞质中，多发生于肝细胞、心肌细胞、肾小管上皮细胞和骨骼肌细胞等。黏液样变（D错）指细胞间质内黏多糖（葡萄糖胺聚糖、透明质酸等）和蛋白质的蓄积常，见于间叶组织肿瘤、动脉粥样硬化斑块、风湿病灶和营养不良的骨髓和脂肪组织等。","","N"],["2025-N125",0,"第3节 细胞可逆性损伤","细小动脉壁玻璃样变",2025,125,"B","","高血压患者肾小球入球小动脉容易发生的变性是",[["A","淀粉样变"],["B","脂肪变"],["C","玻璃样变"],["D","黏液样变"]],"C","高血压患者肾小球入球小动脉常见的变性是玻璃样变（C对），因血浆蛋白质渗入和基底膜代谢物质沉积，使细小动脉管壁增厚，管腔狭窄。淀粉样变（A错）指细胞间质内淀粉样蛋白质和黏多糖复合物蓄积，可见于霍奇金病、多发性骨髓瘤、甲状腺髓样癌等肿瘤的间质内。脂肪变（B错）指甘油三酯蓄积于非脂肪细胞的细胞质中，多发生于肝细胞、心肌细胞、肾小管上皮细胞和骨骼肌细胞等。黏液样变（D错）指细胞间质内黏多糖（葡萄糖胺聚糖、透明质酸等）和蛋白质的蓄积常，见于间叶组织肿瘤、动脉粥样硬化斑块、风湿病灶和营养不良的骨髓和脂肪组织等。","","N"],["2025-N126",11,"第1节 肾小球疾病","局灶性节段性肾小球硬化病理变化",2025,126,"B","","以肾小球毛细血管丛部分玻璃样变和硬化为基本病变的疾病是",[["A","系膜增生性肾小球肾炎"],["B","局灶性节段性肾小球硬化"],["C","微小病变性肾小球病"],["D","膜性肾小球病"]],"B","局灶性节段性肾小球硬化（B对）时，由于肾小球毛细血管丛局部通透性明显增高，血浆蛋白和脂质在细胞外基质内沉积，激活系膜细胞，导致节段性的玻璃样变和硬化。系膜增生性肾小球肾炎（A错）的病变特点是弥漫性系膜细胞增生及系膜基质增多。微小病变性肾小球病（C错）的病变特点是弥漫性肾小球脏层上皮细胞足突消失，光镜下肾小球基本正常，肾小管上皮细胞内有脂质沉积。膜性肾小球病（D错）的病变特点是肾小球毛细血管壁弥漫性增厚，上皮细胞肿胀，足突消失，基膜与上皮之间有大量电子致密沉积物，形成钉状突起。","","N"],["2025-N127",11,"第1节 肾小球疾病","微小病变性肾小球病病理变化",2025,127,"B","","光镜下肾小球基本正常，以肾小管上皮细胞内脂质沉积为基本病变的疾病是",[["A","系膜增生性肾小球肾炎"],["B","局灶性节段性肾小球硬化"],["C","微小病变性肾小球病"],["D","膜性肾小球病"]],"C","微小病变性肾小球病（C对）的病变特点是弥漫性肾小球脏层上皮细胞足突消失，光镜下肾小球基本正常，肾小管上皮细胞内有脂质沉积。系膜增生性肾小球肾炎（A错）的病变特点是弥漫性系膜细胞增生及系膜基质增多。局灶性节段性肾小球硬化（B错）时，由于肾小球毛细血管丛局部通透性明显增高，血浆蛋白和脂质在细胞外基质内沉积，激活系膜细胞，导致节段性的玻璃样变和硬化。膜性肾小球病（D错）的病变特点是肾小球毛细血管壁弥漫性增厚，上皮细胞肿胀，足突消失，基膜与上皮之间有大量电子致密沉积物，形成钉状突起。","","N"],["2025-N148",0,"第1节 适应","内分泌性萎缩",2025,148,"X","","属于内分泌性萎缩的有",[["A","老年女性，乳腺萎缩"],["B","阿尔茨海默病患者的大脑萎缩"],["C","脊髓神经损伤而导致的肌肉萎缩"],["D","垂体缺血坏死时，肾上腺皮质萎缩"]],"AD","内分泌性萎缩指内分泌腺功能下降引起靶器官细胞萎缩。老年女性乳腺萎缩（A对）是由于体内雌激素水平下降导致的，因为雌激素对乳腺组织具有维持其结构和功能的作用，而随着年龄增长，卵巢功能减退，雌激素分泌减少，便会引起乳腺组织的萎缩。垂体缺血坏死时，肾上腺皮质萎缩（D对）是由于垂体缺血坏死时分泌的促激素减少，会影响到靶器官肾上腺皮质的功能和结构，导致其发生萎缩。阿尔茨海默病患者的大脑萎缩（B错）是由于大量神经细胞凋亡所致，属于老化性萎缩。脊髓神经损伤而导致的肌肉萎缩（C错）是由于神经对肌肉运动调节丧失，加之活动减少和骨骼肌细胞分解代谢加速，属于去神经性萎缩。","","N"],["2025-N149",10,"第2节 淋巴组织肿瘤","伯基特淋巴瘤概述",2025,149,"X","","与Epstein-Barr病毒感染密切相关的疾病有",[["A","Burkitt淋巴瘤"],["B","鼻咽癌"],["C","霍奇金淋巴瘤"],["D","尖锐湿疣"]],"ABC","与EB病毒感染密切相关的疾病包括伯基特淋巴瘤（A对）、鼻咽癌（B对）和霍奇金淋巴瘤（C对）。伯基特淋巴瘤是一种侵袭性高、增殖迅速的恶性淋巴造血系统肿瘤，与EB病毒感染密切相关，病毒持续感染导致免疫系统的异常反应，进而形成肿瘤。鼻咽癌是鼻咽部上皮组织发生的恶性肿瘤，其发病与EB病毒感染关系密切，但EB病毒使上皮细胞发生癌变的机制尚不清楚。霍奇金淋巴瘤是起源于淋巴结和淋巴组织的血液系统恶性肿瘤，其发病机制涉及EB病毒感染，EB病毒可导致B细胞增殖并转化为前体淋巴细胞，这些细胞在某些情况下可能发生突变，形成恶性肿瘤。尖锐湿疣（D错）是一种由人乳头状瘤病毒引起的性传播疾病，与EB病毒感染无明确相关性。","","N"],["2025-N150",1,"第1节 再生","永久性细胞",2025,150,"X","","属于永久性细胞的有",[["A","神经元"],["B","心肌细胞"],["C","成骨细胞"],["D","平滑肌细胞"]],"AB","永久性细胞又称非分裂细胞，是一种遭受破坏则成为永久性缺失的细胞。神经元（A对）是高度分化的细胞，一旦成熟就不再分裂，它们没有再生能力，因此被归类为永久性细胞。心肌细胞（B对）在成年人中也不具有分裂能力，一旦受损，无法通过细胞分裂来修复，所以也被视为永久性细胞。成骨细胞（C错）虽然分化程度较高，但仍保留了一定的分裂增殖能力，因此不属于永久性细胞。平滑肌细胞（D错）具有一定的分裂增殖潜能，特别是在某些生理或病理条件下，所以也不被归类为永久性细胞。","","N"],["2025-N151",2,"第5节 梗死","出血性梗死",2025,151,"X","","容易发生出血性梗死的器官有",[["A","肺"],["B","脾"],["C","肾"],["D","肠"]],"AD","出血性梗死是含血量多，颜色呈暗红的梗死类型，发生出血性梗死的条件是严重淤血和组织疏松，所以可以发生出血性梗死的器官是肺（A对）和肠（D对）。肺是一个拥有双重血液循环的器官，由肺动脉和支气管动脉共同供血，加之其组织结构相对疏松，当肺淤血时，肺静脉和毛细血管内压增高，影响了肺动脉分支阻塞后建立有效的肺动脉和支气管动脉侧支循环，因此容易发生出血性梗死。肠同样具备双重血供，由肠系膜上动脉和肠系膜下动脉供血，且其组织结构也相对疏松，当发生肠系膜动脉栓塞、肠套叠等情况时，使得肠也容易发生出血性梗死。脾（B错）和肾（C错）组织结构较致密、侧支循环不充分，多发生贫血性梗死。","","N"],["2025-N152",7,"第1节 动脉粥样硬化","心肌梗死",2025,152,"X","","新鲜心肌梗死区域的病理变化有",[["A","心肌细胞核固缩、碎裂、溶解消失"],["B","心肌细胞胞质均质红染，大量收缩带形成"],["C","心肌细胞间大量中性粒细胞浸润"],["D","梗死灶内肉芽肿形成"]],"ABC","心肌梗死是冠状动脉供血中断，致供血区持续缺血而导致的较大范围的心肌坏死，多属于贫血性梗死，新鲜心肌梗死区域的病理变化有：心肌细胞核固缩、碎裂、溶解消失（A对），心肌细胞胞质均质红染，大量收缩带形成（B对）以及间质水肿，心肌细胞间质大量中性粒细胞浸润（C对）。梗死区肉芽肿形成（D错）通常出现在心肌梗死后期，在心肌梗死后1～2周发生，不属于新鲜心肌梗死区域的病理变化。","","N"],["2025-N153",13,"第2节 甲状腺疾病","结节期",2025,153,"X","","结节性甲状腺肿的病理学特点有",[["A","甲状腺呈不对称结节状肿大，结节大小不等"],["B","结节边界比较清楚，常有完整包膜"],["C","切面常见出血、坏死、囊性变"],["D","部分滤泡上皮增生，部分滤泡上皮复旧或萎缩"]],"ACD","结节性甲状腺肿是弥漫性非毒性甲状腺肿的结节期，其病理学特点包括：由于滤泡上皮局灶性增生、复旧或萎缩不一致，甲状腺不对称结节状肿大，且结节大小不等（A对）；有的结节边界较为清楚，常无完整的包膜（B错）；结节切面常会出现出血、坏死、囊性变（C对）、钙化和瘢痕形成，这是因为结节内部血供不足导致部分组织坏死以及囊腔形成；光镜下，部分滤泡上皮呈柱状或乳头样增生，小滤泡形成，部分上皮复旧或萎缩，胶质贮积（D对）。","","N"],["2026-N29",0,"第4节 细胞不可逆性损伤（细胞死亡）","液化性坏死",2026,29,"A","","脓肿病变组织的坏死类型是",[["A","凝固性坏死"],["B","液化性坏死"],["C","纤维蛋白样坏死"],["D","脂肪坏死"]],"B","脓肿是局限性化脓性炎症，由金黄色葡萄球菌等化脓菌感染后，病灶内大量中性粒细胞浸润，中性粒细胞崩解后释放大量蛋白水解酶，可将局部组织的蛋白质、细胞间质溶解液化，形成脓液，属于典型的液化性坏死（B对）。凝固性坏死（A错）多见于于心、肝、肾和脾等实质器官，常由缺血缺氧、细菌毒素、化学腐蚀剂作用引起蛋白质变性凝固，且溶酶体酶水解作用较弱，坏死区呈灰黄、干燥、质实状态。纤维蛋白样坏死（C错）病变部位形成细丝状、颗粒状或小条块状无结构物质，常见于某些超敏反应性疾病，如风湿病、结节性多动脉炎、新月体性肾小球肾炎。脂肪坏死（D错）主要见于急性胰腺炎，由于细胞释放胰酶分解脂肪酸所致。","","N"],["2026-N30",0,"第4节 细胞不可逆性损伤（细胞死亡）","凋亡的形态学和生物化学特征",2026,30,"A","","下列关于凋亡，叙述正确的是",[["A","意外事故性细胞死亡"],["B","由严重病理刺激因子导致"],["C","无新蛋白生成"],["D","不引起周围炎症反应"]],"D","凋亡是活体内局部组织中单个细胞程序性细胞死亡的表现形式，生理性或轻微病理性刺激因子诱导其发生（B错），不会引起周围组织炎症反应（D对）和修复再生，其生化特征为耗能的主动过程，依赖ATP，有新蛋白合成（C错）。意外事故性细胞死亡（A错）指外环境极端的生物性、物理性、化学性或机械性损伤引起细胞质膜的损伤而导致的瞬间的、不可控的细胞死亡，大多表现为坏死。","","N"],["2026-N31",2,"第1节 充血和淤血","肺淤血",2026,31,"A","","易引发肺褐色硬化的病变是",[["A","大叶性肺炎"],["B","小叶性肺炎"],["C","间质性肺炎"],["D","慢性肺淤血"]],"D","易引起肺褐色硬化的是慢性肺淤血（D对）时，肺静脉回流受阻，血液淤积于肺组织，长期淤血会刺激肺泡壁毛细血管扩张、充血、肺泡间隔变厚和纤维化，肺组织质地变硬，同时含铁血黄素沉积使肺组织呈棕褐色，最终形成肺褐色硬化。大叶性肺炎（A错）通常是由细菌感染引起的急性肺泡内渗出性炎症。小叶性肺炎（B错）属于化脓性炎症，病灶多发且以细支气管为中心，易形成脓肿。间质性肺炎（C错）主要累及肺间质，病灶实变不明显，常呈节段性分布。","","N"],["2026-N32",2,"第5节 梗死","局部组织对缺血的敏感程度",2026,32,"A","","对缺血耐受性最强的细胞是",[["A","神经元细胞"],["B","心肌细胞"],["C","平滑肌细胞"],["D","纤维细胞"]],"D","对缺血耐受性最强的是纤维结缔组织、骨骼肌，纤维细胞（D对）属于纤维结缔组织，代谢水平低、能量需求少，能长时间耐受无氧环境。少突胶质细胞和神经细胞（A错）高度依赖有氧代谢供能，对缺血最为敏感，3～4分钟的缺血即引起梗死。心肌细胞（B错）对缺血也很敏感，缺血20～30分钟就会死亡。平滑肌细胞（C错）代谢需求较低，具有一定耐受能力，但非最强。","","N"],["2026-N33",3,"第3节 慢性炎症","异物性肉芽肿",2026,33,"A","","隆乳术的填充物引起的炎症类型是",[["A","浆液性炎"],["B","纤维蛋白性炎"],["C","肉芽肿性炎"],["D","化脓性炎"]],"C","隆乳术的填充物如硅胶植入物作为异物植入体内，可激发特异性炎症反应，即异物性肉芽肿，属于肉芽肿性炎的一种（C对），其特征为以异物为中心，周围为数量不等的巨噬细胞、异物多核巨细胞、淋巴细胞和成纤维细胞等，形成结节状病灶。浆液性炎（A错）常发生于黏膜、浆膜、滑膜、皮肤和疏松结缔组织等，以浆液渗出为其特征。纤维蛋白性炎（B错）易发生于黏膜、浆膜和肺组织，以纤维蛋白原渗出为主，继而形成纤维蛋白。化脓性炎（D错）分为表面化脓和积脓、蜂窝织炎和脓肿等，以中性粒细胞渗出、不同程度组织坏死和脓液形成为特点。","","N"],["2026-N34",7,"第7节 心肌病","肥厚型心肌病的病理变化",2026,34,"A","","肥厚型心肌病的肉眼病理变化特点是",[["A","心室肥厚，室间隔厚度大于左心室游离壁厚度"],["B","心室肥厚，室间隔厚度小于左心室游离壁厚度"],["C","心房肥厚，房间隔厚度小于左心房游离壁厚度"],["D","心房肥厚，房间隔厚度大于左心房游离壁厚度"]],"A","肥厚型心肌病的肉眼病理变化特点是心肌非对称性肥厚，即两侧心室壁肥厚、室间隔厚度大于左心室壁的游离侧，二者之比＞1.30（A对B错）。肥厚型心肌病的原发损伤部位是心室，而非心房，心房肥厚多是后期心室舒张功能障碍、血液淤积导致的继发性改变（CD错）。","","N"],["2026-N35",8,"第1节 呼吸道和肺炎症性疾病","支原体肺炎",2026,35,"A","","支原体肺炎的病理特点",[["A","常累及一叶肺组织，病变组织呈暗红色，实变不明显"],["B","常累及一侧肺组织，病变组织呈暗红色，实变明显"],["C","常累及一侧肺组织，病变组织呈灰白色，实变不明显"],["D","常累及双侧肺组织，病变组织呈灰白色，实变明显"]],"A","支原体肺炎的病变常累及一叶肺组织，以下叶多见，偶可波及双肺。病变主要发生于肺间质，故病灶实变不明显，常呈节段性分布。肉眼观呈暗红色，切面可有少量红色泡沫状液体溢出，气管或支气管管腔可有黏液性渗出物，胸膜一般不被累及（A对）。实变主要为大叶性肺炎的特征（BD错）。灰白色提示纤维化或陈旧性病变（C错）。","","N"],["2026-N36",9,"第6节 病毒性肝炎","碎片状坏死",2026,36,"A","","肝细胞碎片状坏死的病理特点是",[["A","肝小叶任何部位的肝细胞灶状坏死"],["B","肝小叶周边界板肝细胞灶状坏死"],["C","肝小叶中央静脉周围的肝细胞灶状坏死"],["D","两个中央静脉之间出现的坏死带"]],"B","肝细胞碎片状坏死的病理特点是肝小叶周边界板肝细胞的灶性坏死（B对AC错）、崩解，使肝界板受到破坏。肝细胞坏死周围的界板有炎症细胞浸润，故也称界面性肝炎，常见于慢性肝炎。两个中央静脉之间出现的坏死带（D错）属于桥接坏死的病理特点，常见于较重的慢性肝炎。","","N"],["2026-N37",13,"第2节 甲状腺疾病","弥漫性毒性甲状腺肿病理变化光镜下",2026,37,"A","","弥漫性毒性甲状腺肿的主要组织学特征是",[["A","滤泡上皮增生，胶质稀薄，间质淋巴组织增生"],["B","滤泡上皮呈局灶性增生或萎缩性改变，间质纤维化"],["C","部分滤泡被破坏，胶质外溢，肉芽肿形成"],["D","甲状腺间质有大量淋巴细胞和嗜酸性粒细胞浸润"]],"A","弥漫性毒性甲状腺肿（Graves病）是一种自身免疫性疾病，主要组织学特征包括滤泡上皮增生、胶质稀薄以及间质淋巴组织增生（A对）。由于血中存在与TSH受体结合的抗体，具有类似TSH的作用，使刺激滤泡上皮细胞增生，呈高柱状，有的呈乳头样增生；滤泡腔内胶质稀薄，滤泡周边胶质出现许多大小不一的上皮细胞的吸收空泡；间质血管丰富、充血，淋巴组织增生（D错）。滤泡上皮呈局灶性增生或萎缩性改变伴间质纤维化（B错）为慢性淋巴细胞性甲状腺炎（桥本甲状腺炎）表现。部分滤泡被破坏、胶质外溢和肉芽肿形成（C错）是亚急性甲状腺炎的典型表现。","","N"],["2026-N38",8,"第8节 呼吸系统常见肿瘤","神经内分泌癌",2026,38,"A","","小细胞肺癌呈阴性表达的免疫组化标志物是",[["A","神经元特异性烯醇化酶（NSE）"],["B","嗜铬粒蛋白A（CgA）"],["C","突触素（Syn）"],["D","结蛋白（Desmin）"]],"D","肺小细胞癌免疫组织化学染色显示癌细胞对神经内分泌标记如神经元特异性烯醇化酶（NSE）（A错）、嗜铬粒蛋白A（CgA）（B错）、突触素（Syn）（C错）及人自然杀伤细胞相关抗原（Leu7）等呈阳性反应，角蛋白（CK）亦可显示阳性。故呈阴性表达的免疫组化标志物是结蛋白（Desmin）（D对），结蛋白（Desmin）是肌细胞、平滑肌瘤、平滑肌肉瘤、横纹肌肉瘤的免疫组织化学染色常用标志物。","","N"],["2026-N39",13,"第5节 胰岛疾病","胰岛病变",2026,39,"A","","2型糖尿病常见的胰岛病理变化是",[["A","淀粉样变性"],["B","玻璃样变性"],["C","黏液样变性"],["D","脂肪变性"]],"A","2型糖尿病（非胰岛素依赖型糖尿病）早期病变不明显，后期B细胞减少，常见的胰岛病理变化是淀粉样变性（A对）。胰岛素依赖型糖尿病早期为非特异性胰岛炎，继而纤维组织增生、玻璃样变（B错）。糖尿病时，胰岛一般不出现黏液样变性（C错）、脂肪变性（D错）。","","N"],["2026-N40",16,"第4节 细菌性痢疾","急性细菌性痢疾",2026,40,"A","","急性细菌性痢疾的肠道病变通常表现为",[["A","肉芽肿性炎"],["B","纤维蛋白性炎"],["C","化脓性炎"],["D","出血性炎"]],"B","细菌性痢疾以大量纤维蛋白渗出形成假膜为特征（B对），急性细菌性痢疾的典型病变过程为初期的急性卡他性炎，随后特征性假膜性炎和溃疡形成，最后愈合。肉芽肿性炎（A错）以炎症局部巨噬细胞及其衍生细胞增生形成境界清楚的结节状病灶（即肉芽肿）为特征，是一种特殊类型的慢性炎症，多见于结核病、麻风、梅毒等。化脓性炎（C错）以中性粒细胞渗出，并伴有不同程度的组织坏死和脓液形成为其特点，多由化脓菌（如葡萄球菌、链球菌、脑膜炎双球菌、大肠埃希菌）感染所致。出血性炎（D错）是指炎症病灶的血管损伤严重，渗出物中含有大量红细胞，常见于流行性出血热、钩端螺旋体病和鼠疫等。","","N"],["2026-N124",5,"第8节 常见肿瘤举例","基底细胞癌",2026,124,"B","","好发于老年人头面部，很少发生转移的恶性肿瘤",[["A","黑色素瘤"],["B","鳞状细胞癌"],["C","基底细胞癌"],["D","淋巴瘤"]],"C","好发于老年人头面部，很少发生转移的恶性肿瘤是基底细胞癌（C对），多为日光暴露所致，生长缓慢，临床上表现为低度恶性的生物学行为。黑色素瘤（A错）可发生于皮肤，但极易早期发生淋巴结和血行转移，预后差。鳞状细胞癌（B错）可发生于头面部，但相比基底细胞癌，转移风险更高。淋巴瘤（D错）属于淋巴造血系统肿瘤，常累及全身淋巴结而非特定头面部皮肤，转移多见。","","N"],["2026-N125",5,"第8节 常见肿瘤举例","鳞状细胞癌",2026,125,"B","","肿瘤细胞间可见细胞间桥的恶性肿瘤是",[["A","黑色素瘤"],["B","鳞状细胞癌"],["C","基底细胞癌"],["D","淋巴瘤"]],"B","细胞间桥是鳞状上皮细胞的典型连接结构，通常在鳞状细胞癌中可见（B对）。黑色素瘤（A错）起源于黑色素细胞，无细胞间桥形成。基底细胞癌（C错）源自表皮基底细胞，一般无细胞间桥。淋巴瘤（D错）为淋巴组织起源的恶性肿瘤，不涉及细胞间桥结构。","","N"],["2026-N126",11,"第1节 肾小球疾病","膜性肾小球病病理变化",2026,126,"B","","膜性肾小球疾病的组织学特点是",[["A","弥漫性肾小球系膜细胞、内皮细胞增生"],["B","弥漫性肾小球系膜基膜增厚，钉状突起"],["C","肾小球系膜细胞增生，基膜增厚"],["D","光镜下肾小球无明显变化，脂质沉积"]],"B","膜性肾小球病的组织学特点是弥漫性肾小球基膜增厚，钉突形成（B对），由于免疫复合物在肾小球基膜与上皮之间沉积，导致基膜反应性增厚和钉状突起形成。弥漫性肾小球系膜细胞、内皮细胞增生（A错）为急性弥漫性增生性肾小球肾炎的病理改变。肾小球系膜细胞增生，系膜基质增多（C错）常见于系膜增生性肾小球肾炎。光镜下肾小球无明显变化，肾小管脂质沉积（D错）见于微小病变肾病，其中脂质沉积在肾小管上皮细胞。","","N"],["2026-N127",11,"第1节 肾小球疾病","急性弥漫性增生性肾小球肾炎病理变化",2026,127,"B","","急性弥漫性增生性肾小球肾炎的组织学特点是",[["A","弥漫性肾小球系膜细胞、内皮细胞增生"],["B","弥漫性肾小球系膜基膜增厚，钉状突起"],["C","肾小球系膜细胞增生，基膜增厚"],["D","光镜下肾小球无明显变化，脂质沉积"]],"A","急性弥漫性增生性肾小球肾炎的组织学特征主要为弥漫性肾小球系膜细胞和内皮细胞增生（A对），可伴中性粒细胞和巨噬细胞浸润。弥漫性肾小球基膜增厚，钉突形成（B错）是膜性肾小球疾病的组织学特点。肾小球系膜细胞增生，系膜基质增多（C错）常见于系膜增生性肾小球肾炎。光镜下肾小球无明显变化，肾小管脂质沉积（D错）常见于微小病变肾病，其中脂质沉积在肾小管上皮细胞。","","N"],["2026-N148",3,"第2节 急性炎症","血管通透性增加",2026,148,"X","","参与炎症反应的机体成分有",[["A","血浆蛋白"],["B","血管内皮细胞"],["C","细胞外基质"],["D","成纤维细胞"]],"ABCD","血浆蛋白（A对）包括补体系统（如C3、C5）、凝血因子（如纤维蛋白原）、免疫球蛋白等，参与病原体清除、炎症介质激活及纤维蛋白网形成，限制病原体扩散。血管内皮细胞（B对）受炎症介质刺激后表达黏附分子，促进白细胞黏附和渗出；同时释放一氧化氮、前列腺素等，调节血管通透性和血流。细胞外基质（C对）由胶原蛋白、蛋白聚糖等组成，炎症时被基质金属蛋白酶降解，为白细胞迁移提供通道；后期作为修复支架，促进组织再生。成纤维细胞（D对）在炎症后期增殖并合成胶原蛋白，参与组织修复和瘢痕形成；此外还可以释放生长因子，促进血管新生和炎症。","","N"],["2026-N149",5,"第8节 常见肿瘤举例","间叶组织恶性肿瘤",2026,149,"X","","关于肉瘤的叙述，正确的有",[["A","表现出向某种间叶组织分化的特征"],["B","大体特点为质软、色灰红、鱼肉状"],["C","镜下特点为间质和实质分界不清"],["D","多经淋巴道转移"]],"ABC","肉瘤是起源于间叶组织的恶性肿瘤，表现出向某种间叶组织分化的特征（A对）；肉瘤体积常较大，切面多呈鱼肉状，且质软、色灰红（B对），与癌的硬质外观不同。镜下，肉瘤细胞大多不成巢，弥漫生长，与间质分界不清（C对）。间质的结缔组织一般较少，但血管常较丰富，肉瘤多先发生血行转移（D错）。","","N"],["2026-N150",4,"第1节 自身免疫病","免疫耐受的丧失",2026,150,"X","","诱导自身免疫耐受丧失的机制有",[["A","活化诱导的细胞死亡功能丧失"],["B","共同抗原诱发交叉反应"],["C","T细胞“免疫不应答”功能丧失"],["D","Treg细胞与Th细胞功能失衡"]],"ABCD","免疫耐受指机体对某种特定的抗原不产生免疫应答。免疫耐受丧失的机制有：①T细胞“免疫不应答”功能丧失（C对）：抗原特异性T细胞的激活需要主要组织相容性复合体和协同刺激分子，如果刺激分子异常持续存在或调节失常，使这些本应处于不应答状态的T细胞被异常激活，就会引发自身免疫反应。②活化诱导的细胞死亡功能丧失（A对）：正常情况下，T细胞活化后会促进其自身凋亡，如果T细胞激活时不能诱导细胞凋亡，自身反应性T细胞不能被有效清除，会在体内持续存在并攻击自身组织。③Treg细胞与Th细胞功能失衡（D对）：如果Treg数量减少或功能缺陷，或Th细胞亚群过度活化、促炎因子分泌过多，就会打破平衡，导致免疫系统对自身抗原的攻击失去控制。④共同抗原诱发交叉反应（B对）指某些外来抗原（如病原体）与自身抗原在分子结构上相似，免疫系统在清除外来入侵者时产生的免疫效应（抗体或T细胞）可错误地识别并结合自身抗原，引发交叉反应性攻击，这种分子模拟机制是打破自身耐受的经典途径之一。","","N"],["2026-N151",9,"第2节 胃炎","慢性胃炎",2026,151,"X","","关于B型慢性萎缩性胃炎的叙述，正确的有",[["A","与幽门螺旋杆菌感染密切相关"],["B","好发于胃窦部"],["C","胃内G细胞增生明显"],["D","胃酸分泌中度降低或正常"]],"ABD","B型慢性萎缩性胃炎主要与幽门螺旋杆菌感染密切相关（A对），通常好发于胃窦部（B对），因为幽门螺旋杆菌偏好定植于胃窦黏膜，引发局部炎症和萎缩。胃酸分泌常中度降低或正常（D对），这是由于感染导致胃黏膜功能受损但尚未完全丧失酸分泌能力。胃内G细胞增生不明显（C错），因为幽门螺旋杆菌感染不刺激G细胞增生，这与免疫相关的A型胃炎中反馈性增生不同。","","N"],["2026-N152",10,"第2节 淋巴组织肿瘤","非霍奇金淋巴瘤的概述",2026,152,"X","","成熟B细胞淋巴瘤有",[["A","滤泡性淋巴瘤"],["B","弥漫性大B细胞淋巴瘤，非特殊类型"],["C","结外边缘区黏膜相关淋巴组织淋巴瘤"],["D","ALK阳性间变性大细胞淋巴瘤"]],"ABC","成熟B细胞淋巴瘤依据WHO分类包括多种亚型。滤泡性淋巴瘤源自生发中心B细胞，属于成熟B细胞淋巴瘤（A对）。弥漫性大B细胞淋巴瘤的非特殊亚型是常见的成熟B细胞淋巴瘤（B对）。结外边缘区黏膜相关淋巴组织淋巴瘤（MALT淋巴瘤）是一种边缘区淋巴瘤，源自成熟B细胞（C对）。ALK阳性间变性大细胞淋巴瘤（D错）属于T细胞/组织细胞来源淋巴瘤，表达ALK蛋白，与B细胞淋巴瘤无关。","","N"],["2026-N153",12,"第4节 卵巢肿瘤","成熟性畸胎瘤",2026,153,"X","","关于成熟性畸胎瘤的叙述正确的有",[["A","多数肿瘤由2～3个胚层的成熟组织构成"],["B","卵巢皮样囊种为多胚层畸胎瘤"],["C","卵巢甲状腺肿为单胚层畸胎瘤"],["D","不会发生恶变"]],"AC","成熟性畸胎瘤是一种良性生殖细胞肿瘤。多数肿瘤由2～3个胚层（包括外胚层、中胚层和内胚层）的成熟组织构成（A对）。卵巢皮样囊肿是以表皮和附件组成的单胚层畸胎瘤（B错）。同时，卵巢甲状腺肿作为特定亚型，仅由甲状腺组织（单一胚层）组成，属于单胚层畸胎瘤（C对）。成熟性畸胎瘤有1%可能发生恶性变（D错），多发生在老年女性。","","N"]];
